// ---------- Utilidades ----------

// Direção do sprite a partir da mira (8 direções; y cresce para baixo)
static Direcao DirecaoDoVetor(Vector2 v)
{
    static const Direcao setores[8] = {
        DIR_DIREITA, DIR_FRENTE_DIREITA, DIR_FRENTE, DIR_FRENTE_ESQUERDA,
        DIR_ESQUERDA, DIR_COSTAS_ESQUERDA, DIR_COSTAS, DIR_COSTAS_DIREITA
    };

    int s = (int)roundf(atan2f(v.y, v.x) / (PI / 4.0f));
    return setores[(s + 8) % 8];
}

// Mantém um círculo dentro da arena e fora das estantes
static void RogueEmpurrarParaFora(Vector2 *p, float raio, const Rectangle *obst, int n)
{
    p->x = Clamp(p->x, ARENA_ROGUE.x + raio, ARENA_ROGUE.x + ARENA_ROGUE.width - raio);
    p->y = Clamp(p->y, ARENA_ROGUE.y + raio, ARENA_ROGUE.y + ARENA_ROGUE.height - raio);

    for (int i = 0; i < n; i++) {

        Rectangle r = obst[i];
        float cx = Clamp(p->x, r.x, r.x + r.width);
        float cy = Clamp(p->y, r.y, r.y + r.height);
        float dx = p->x - cx, dy = p->y - cy;
        float d2 = dx * dx + dy * dy;

        if (d2 >= raio * raio)
            continue;

        if (d2 > 0.0001f) {
            float d = sqrtf(d2);
            p->x = cx + dx / d * raio;
            p->y = cy + dy / d * raio;
        } else {
            // Centro dentro da estante: sai pelo lado mais perto
            float esq = p->x - r.x, dir = r.x + r.width - p->x;
            float cima = p->y - r.y, baixo = r.y + r.height - p->y;
            float m = fminf(fminf(esq, dir), fminf(cima, baixo));

            if (m == esq)       p->x = r.x - raio;
            else if (m == dir)  p->x = r.x + r.width + raio;
            else if (m == cima) p->y = r.y - raio;
            else                p->y = r.y + r.height + raio;
        }
    }
}

static void RogueParticulas(Biblioteca *b, Vector2 origem, Color cor, int quantidade, float velMax)
{
    for (int i = 0; i < MAX_PARTICULAS_ROGUE && quantidade > 0; i++) {

        ParticulaRogue *p = &b->part[i];

        if (p->vida > 0.0f)
            continue;

        float ang = (float)GetRandomValue(0, 360) * DEG2RAD;
        float vel = (float)GetRandomValue(20, (int)velMax);

        p->pos = origem;
        p->vel = (Vector2){ cosf(ang) * vel, sinf(ang) * vel };
        p->vidaMax = p->vida = 0.25f + (float)GetRandomValue(0, 30) / 100.0f;
        p->tam = (float)GetRandomValue(2, 4);
        p->cor = cor;
        quantidade--;
    }
}

static void RogueAviso(Biblioteca *b, const char *texto)
{
    snprintf(b->aviso, sizeof(b->aviso), "%s", texto);
    b->tempoAviso = 1.8f;
}

// Texto que sobe de um ponto da arena e some (o mais antigo é reaproveitado)
static void RogueTextoFlutuante(Biblioteca *b, Vector2 pos, const char *texto, Color cor)
{
    int escolhido = 0;
    for (int i = 0; i < MAX_TEXTOS_FLUTUANTES; i++) {
        if (b->textos[i].tempo <= 0.0f) { escolhido = i; break; }
        if (b->textos[i].tempo < b->textos[escolhido].tempo) escolhido = i;
    }
    TextoFlutuante *t = &b->textos[escolhido];
    t->pos = pos;
    t->tempo = 1.2f;
    t->cor = cor;
    snprintf(t->texto, sizeof(t->texto), "%s", texto);
}

// Feedback de erro na verificação: o termo falso aparece com aberração cromática e a justificativa
static void RogueErroVerificacao(Biblioteca *b, const char *termo, const char *explicacao)
{
    snprintf(b->erroTermo, sizeof(b->erroTermo), "%s", termo);
    snprintf(b->erroExplicacao, sizeof(b->erroExplicacao), "%s", explicacao);
    b->tempoErro = 2.8f;
}

static Projetil *RogueDisparar(Biblioteca *b, Vector2 origem, Vector2 dir, float vel, float dano, float raio, bool doJogador)
{
    for (int i = 0; i < MAX_PROJETEIS; i++) {

        if (b->proj[i].ativo)
            continue;

        b->proj[i] = (Projetil){ .ativo = true, .pos = origem, .vel = Vector2Scale(dir, vel), .raio = raio, .dano = dano, .doJogador = doJogador };
        return &b->proj[i];
    }

    return NULL;
}

static void RogueSoltar(Biblioteca *b, Vector2 pos, bool fragmento, TipoItem item)
{
    for (int i = 0; i < MAX_COLETAVEIS; i++) {

        if (b->col[i].ativo)
            continue;

        float ang = (float)GetRandomValue(0, 360) * DEG2RAD;
        b->col[i] = (Coletavel){ true, fragmento, item, pos, { cosf(ang) * 90.0f, sinf(ang) * 90.0f }, 0.0f };
        return;
    }
}

static int RogueInimigosVivos(const Biblioteca *b)
{
    int n = 0;

    for (int i = 0; i < MAX_INIMIGOS; i++)
        if (b->ini[i].ativo)
            n++;

    return n;
}

// Atributos: base + melhorias permanentes (Byteco) + itens passivos da mochila + efeitos.
// Todo bônus passa por aqui (nada é somado direto nos atributos), então pegar, perder
// ou trocar de arma nunca aplica um bônus duas vezes.

// Quantos de um item passivo valem (nunca passa do limite da tabela)
static int RogueQtd(const JogadorRogue *j, TipoItem it)
{
    return (j->itens[it] > ITENS[it].maxPilha) ? ITENS[it].maxPilha : j->itens[it];
}

// Nível de uma melhoria da build (reformulação)
static int RogueUp(const JogadorRogue *j, TipoUpgrade u)
{
    return j->up[u];
}

static float RogueHpMax(const Biblioteca *b)
{
    float hp = (ROGUE_HP_MAX + MELHORIA_HP * (float)b->perm->melhorias[MELHORIA_VIDA] + UP_VIDA_NIVEL * (float)RogueUp(&b->j, UP_VIDA))
               * (1.0f + NUCLEO_HP * (float)RogueQtd(&b->j, ITEM_NUCLEO));
    if (b->j.penalidade & PEN_VIDA) hp *= PEN_VIDA_FATOR;
    return hp;
}

static float RogueEpMax(const Biblioteca *b)
{
    return ROGUE_EP_MAX + MELHORIA_EP * (float)b->perm->melhorias[MELHORIA_ENERGIA] + (b->j.seloAmplificado ? SIL_BH_EP_BONUS : 0.0f);
}

// Multiplicador de dano de todas as armas (Processador Neural, a melhoria do Byteco e a build)
static float RogueFatorDano(const Biblioteca *b)
{
    const JogadorRogue *j = &b->j;
    float f = 1.0f + BONUS_PROCESSADOR * (float)RogueQtd(j, ITEM_PROCESSADOR) + MELHORIA_DANO * (float)b->perm->melhorias[MELHORIA_ATAQUE]
            + UP_DANO_NIVEL * (float)RogueUp(j, UP_DANO);

    // Contra-Ataque Heurístico: logo depois de esquivar
    if (j->bonusPosEsquiva > 0.0f && RogueUp(j, UP_POS_ESQUIVA) > 0)
        f *= 1.4f + 0.3f * (float)(RogueUp(j, UP_POS_ESQUIVA) - 1);

    return f;
}

// Dano do Disparador de Dados (também é a base do Disparo Dedutivo)
static float RogueDanoTiro(const Biblioteca *b)
{
    return TIRO_DANO * RogueFatorDano(b);
}

static float RogueFatorDanoRecebido(const JogadorRogue *j)
{
    float f = 1.0f - REDUCAO_FIREWALL * (float)RogueQtd(j, ITEM_FIREWALL) - FIREWALL_ADAPTATIVO * (float)RogueQtd(j, ITEM_FIREWALL_ADAPTATIVO);
    f = fmaxf(FATOR_DANO_MINIMO, f);
    if (j->penalidade & PEN_FRAGIL) f *= PEN_FRAGIL_FATOR;      // Modelo Experimental
    return f;
}

static float RogueVelocidadeJogador(const JogadorRogue *j)
{
    float f = 1.0f + ROTEAMENTO_VELOCIDADE * (float)RogueQtd(j, ITEM_ROTEAMENTO) + UP_VELOCIDADE_NIVEL * (float)RogueUp(j, UP_VELOCIDADE);
    if (j->efeito[EFEITO_OVERCLOCK] > 0.0f) f += EFEITO_OVERCLOCK_VELOCIDADE;
    if (j->penalidade & PEN_LENTO) f *= PEN_LENTO_FATOR;
    return ROGUE_VELOCIDADE * f;
}

static float RogueRecargaEsquiva(const JogadorRogue *j)
{
    float f = 1.0f - ROTEAMENTO_ESQUIVA * (float)RogueQtd(j, ITEM_ROTEAMENTO) - UP_ESQUIVA_NIVEL * (float)RogueUp(j, UP_ESQUIVA);
    return ESQUIVA_RECARGA * fmaxf(0.4f, f);
}

// Intervalo entre disparos: Overclock e Buffer aceleram, mas nunca passam do limite da arma
static float RogueIntervaloArma(const JogadorRogue *j, TipoArma arma)
{
    float cadencia = 1.0f + BUFFER_CADENCIA * (float)RogueQtd(j, ITEM_BUFFER) + UP_CADENCIA_NIVEL * (float)RogueUp(j, UP_CADENCIA);
    if (j->efeito[EFEITO_OVERCLOCK] > 0.0f) cadencia += EFEITO_OVERCLOCK_CADENCIA;
    float intervalo = DEF_ARMAS[arma].intervalo;
    float minimo = DEF_ARMAS[arma].intervaloMin;
    if (arma == ARMA_PULSO_FW && RogueUp(j, UP_ARMA_PULSO_FW) > 0) { intervalo *= 0.8f; minimo *= 0.8f; }   // Muralha Ativa
    return fmaxf(minimo, intervalo / cadencia);
}

// Raio e dano do Pulso de Integridade (Pulso Amplificado)
static float RogueRaioPulso(const JogadorRogue *j)
{
    return PULSO_RAIO * (1.0f + UP_PULSO_RAIO * (float)RogueUp(j, UP_PULSO));
}

static float RogueDanoPulso(const JogadorRogue *j)
{
    return PULSO_DANO * (1.0f + UP_PULSO_DANO * (float)RogueUp(j, UP_PULSO));
}

static TipoArma RogueArmaAtual(const JogadorRogue *j)
{
    return j->usandoExtra ? j->armaExtra : ARMA_DISPARADOR;
}

// Efeitos com tempo e contadores da arma: somem ao voltar ao átrio, ao morrer e ao começar outra tentativa
static void RogueLimparEfeitos(JogadorRogue *j)
{
    memset(j->efeito, 0, sizeof(j->efeito));
    j->carga = 0.0f;
    j->calor = 0.0f;
    j->superaquecida = false;
    j->disparos = 0;
    j->fragmentacaoArmada = false;
    j->alvoAnalise = 0;
    j->marcasAnalise = 0;
    j->recargaBotnet = 0.0f;
    j->bonusPosEsquiva = 0.0f;
    j->recargaEsquiva2 = 0.0f;
    j->recargaExplosao = 0.0f;
    j->recargaRastro = 0.0f;
    j->contaFluxo = 0;
}

// A build da tentativa (melhorias e penalidades) some ao morrer e ao começar outra tentativa
static void RogueLimparBuild(JogadorRogue *j)
{
    memset(j->up, 0, sizeof(j->up));
    j->ultimoUp = -1;
    j->penalidade = 0;
    j->abatesEscudo = 0;
}

// Perdeu a tentativa (ou terminou a Biblioteca): a mochila, a arma extra, a build e o Selo da Inferência ficam para trás
static void RogueEsvaziarMochila(JogadorRogue *j)
{
    memset(j->itens, 0, sizeof(j->itens));
    j->seloInferencia = false;
    j->seloAmplificado = false;
    j->armaExtra = ARMA_DISPARADOR;
    j->usandoExtra = false;
    RogueLimparEfeitos(j);
    RogueLimparBuild(j);
}

// ---------- Sorteios por raridade ----------

static int RogueSortearPeso(const int *candidatos, int n, int (*peso)(int))
{
    int total = 0;
    for (int i = 0; i < n; i++)
        total += peso(candidatos[i]);

    if (n == 0 || total <= 0)
        return -1;

    int r = GetRandomValue(1, total);
    for (int i = 0; i < n; i++) {
        r -= peso(candidatos[i]);
        if (r <= 0) return candidatos[i];
    }
    return candidatos[n - 1];
}

static int PesoItem(int i) { return PESO_RARIDADE[ITENS[i].raridade]; }
static int PesoArma(int a) { return PESO_RARIDADE[DEF_ARMAS[a].raridade]; }

// Item para pedestal ou para o fim do combate: nunca temporário nem passivo que já está no máximo.
// soPassivos = só upgrades passivos. Devolve -1 se não houver nenhum.
static int RogueSortearItem(const Biblioteca *b, unsigned int excluir, bool soPassivos)
{
    int candidatos[NUM_ITENS], n = 0;

    for (int i = 0; i < NUM_ITENS; i++) {
        if (ITENS[i].temporario || (excluir & (1u << i)))                 continue;
        if (ITENS[i].passivo && b->j.itens[i] >= ITENS[i].maxPilha)      continue;
        if (soPassivos && !ITENS[i].passivo)                              continue;
        candidatos[n++] = i;
    }

    return RogueSortearPeso(candidatos, n, PesoItem);
}

static TipoItem RogueSortearTemporario(void)
{
    int candidatos[NUM_ITENS], n = 0;

    for (int i = 0; i < NUM_ITENS; i++)
        if (ITENS[i].temporario)
            candidatos[n++] = i;

    return (TipoItem)RogueSortearPeso(candidatos, n, PesoItem);
}

// Arma para oferecer: nunca a que o jogador já tem; de preferência uma que ainda
// não apareceu nesta tentativa. ARMA_DISPARADOR = nenhuma.
static TipoArma RogueSortearArma(Biblioteca *b, unsigned int excluir)
{
    int candidatos[NUM_ARMAS], n = 0;

    for (int passada = 0; passada < 2 && n == 0; passada++)
        for (int a = ARMA_DISPARADOR + 1; a < NUM_ARMAS; a++) {
            if (a == (int)b->j.armaExtra || (excluir & (1u << a))) continue;
            if (passada == 0 && (b->armasOferecidas & (1u << a)))  continue;
            candidatos[n++] = a;
        }

    int a = RogueSortearPeso(candidatos, n, PesoArma);
    if (a < 0)
        return ARMA_DISPARADOR;

    b->armasOferecidas |= 1u << a;
    return (TipoArma)a;
}

static Inimigo *RogueCriarInimigo(Biblioteca *b, TipoInimigo tipo, Vector2 pos)
{
    for (int i = 0; i < MAX_INIMIGOS; i++) {

        Inimigo *e = &b->ini[i];

        if (e->ativo)
            continue;

        *e = (Inimigo){0};
        e->ativo = true;
        e->tipo = tipo;
        e->pos = pos;
        e->surgindo = TEMPO_SURGINDO;
        e->lado = (GetRandomValue(0, 1) == 0) ? -1.0f : 1.0f;
        e->recarga = (float)GetRandomValue(30, 120) / 100.0f;   // não atacam todos juntos
        e->hp = DEF_INIMIGOS[tipo].hp;
        e->raio = DEF_INIMIGOS[tipo].raio;
        e->frente = (Vector2){ 0, 1 };
        e->dono = -1;
        for (int k = 0; k < BOTNET_CONEXOES; k++)
            e->conexao[k] = -1;

        // O que nasce de outro inimigo aparece na hora
        if (tipo == INIMIGO_ECO)            { e->timer = ECO_TEMPO; e->surgindo = 0.0f; }
        else if (tipo == INIMIGO_SPAM)      { e->vida = SPAM_VIDA; e->surgindo = 0.0f; }
        else if (tipo == INIMIGO_ISCA)      { e->vida = ISCA_DURACAO; e->surgindo = 0.0f; }
        else if (tipo == INIMIGO_FIREWALL)  e->habilidade = FIREWALL_INTERVALO * 0.6f;
        else if (tipo == INIMIGO_NUCLEO)    e->recarga = NUCLEO_INTERVALO * 0.5f;

        // Reformulação: salas mais fundas da missão têm inimigos mais resistentes
        // (o que nasce de outro inimigo, como spam, ecos e cópias, não muda)
        if (tipo != INIMIGO_ECO && tipo != INIMIGO_SPAM && tipo != INIMIGO_ISCA && b->fatorVidaInimigos > 0.0f)
            e->hp *= b->fatorVidaInimigos;

        e->hpMax = e->hp;
        return e;
    }

    return NULL;
}

// Elite: aura dourada, mais vida, um pouco maior e com ataques reforçados (ver RogueAtualizarInimigos)
static void RogueTornarElite(Inimigo *e)
{
    if (e == NULL || e->elite)
        return;

    e->elite = true;
    e->hp *= ELITE_HP;
    e->hpMax = e->hp;
    e->raio *= ELITE_RAIO;
}

