// Uma sala da missão (reformulação) usa portas nos lados: nada pode ficar na frente delas
static bool RogueSalaDaMissao(const Biblioteca *b)
{
    return (b->noAtual >= 0 || b->modoSeletor) && b->tipoSala != SALA_ATRIO && b->tipoSala != SALA_TRANSICAO && b->tipoSala != SALA_LUCI;
}

// Tipo do encontro especial da sala: do nó do mapa ou, no seletor (sem mapa), o escolhido
static int RogueEspecialAtual(const Biblioteca *b)
{
    int esp = (b->noAtual >= 0 && b->noAtual < b->mapa.numNos) ? b->mapa.no[b->noAtual].especial : b->especialDireto;
    return (esp >= 0 && esp < NUM_ESPECIAIS) ? esp : ESP_SENTINELA;
}

// O ponto está numa faixa livre (portas e entrada)?
static bool RogueNaZonaLivre(Vector2 p, float raio)
{
    for (int z = 0; z < NUM_LADOS; z++)
        if (CheckCollisionCircleRec(p, raio, ZONAS_LIVRES_ROGUE[z]))
            return true;
    return false;
}

static void RogueUsarLayout(Biblioteca *b, const LayoutSala *l)
{
    b->numObst = 0;

    for (int i = 0; i < l->numObst && b->numObst < MAX_OBSTACULOS; i++) {

        // Validação dos layouts de combate: nenhuma estante bloqueia uma porta ou a entrada
        bool bloqueia = false;
        if (RogueSalaDaMissao(b))
            for (int z = 0; z < NUM_LADOS && !bloqueia; z++)
                bloqueia = CheckCollisionRecs(l->obst[i], ZONAS_LIVRES_ROGUE[z]);

        if (!bloqueia)
            b->obst[b->numObst++] = l->obst[i];
    }

    b->numObstFixos = b->numObst;
}

// Sorteia um encontro do nível da sala, de preferência diferente do anterior.
// As salas de ELITE só usam os encontros de elite (e as outras nunca).
static int RogueSortearEncontro(const Biblioteca *b, int nivel)
{
    int candidatos[NUM_ENCONTROS], n = 0;
    bool elite = (b->tipoSala == SALA_ELITE || b->eventoCombate);

    for (int passada = 0; passada < 3 && n == 0; passada++)
        for (int i = 0; i < NUM_ENCONTROS; i++) {
            if (ENCONTROS[i].salaElite != elite)                                              continue;
            if (passada < 2 && (nivel < ENCONTROS[i].nivelMin || nivel > ENCONTROS[i].nivelMax)) continue;
            if (passada == 0 && i == b->ultimoEncontro)                                       continue;
            candidatos[n++] = i;
        }

    return (n > 0) ? candidatos[GetRandomValue(0, n - 1)] : 0;
}

// Lugar para um inimigo perto de um ponto da sala: fora das estantes, longe da
// entrada do jogador e sem cair em cima de outro inimigo
static Vector2 RogueLugarSurgir(const Biblioteca *b, Vector2 base, float raio)
{
    Vector2 escolhido = base;

    for (int tentativa = 0; tentativa < 16; tentativa++) {

        float ang = (float)GetRandomValue(0, 360) * DEG2RAD;
        float dist = (tentativa == 0) ? 0.0f : (float)GetRandomValue(14, 60);
        Vector2 p = { base.x + cosf(ang) * dist, base.y + sinf(ang) * dist };

        RogueEmpurrarParaFora(&p, raio, b->obst, b->numObst);

        if (Vector2Distance(p, b->j.pos) < DIST_SURGIR_JOGADOR)
            continue;

        // Reformulação: ninguém nasce na frente das portas (a não ser que não haja outro lugar)
        if (RogueSalaDaMissao(b) && tentativa < 12 && RogueNaZonaLivre(p, raio))
            continue;

        escolhido = p;
        bool livre = true;
        for (int i = 0; i < MAX_INIMIGOS && livre; i++)
            if (b->ini[i].ativo && Vector2Distance(p, b->ini[i].pos) < raio + b->ini[i].raio + 4.0f)
                livre = false;

        if (livre)
            return p;
    }

    return escolhido;
}

// Nível da sala de combate atual: 1 = inicial, 2 = intermediária, 3 = avançada
// Reformulação: o nível vem da profundidade no mapa (1 = começo, 2 = meio, 3 = fim);
// a sala de ELITE conta um nível acima. Fora do mapa, vale a contagem antiga.
static int RogueNivelCombate(const Biblioteca *b)
{
    int nivel;

    if (b->noAtual >= 0) nivel = (b->profundidade <= 1) ? 1 : ((b->profundidade <= 4) ? 2 : 3);
    else                 nivel = (b->combates > 3) ? 3 : ((b->combates < 1) ? 1 : b->combates);

    if (b->tipoSala == SALA_ELITE && nivel < 3)
        nivel++;
    return nivel;
}

// Layout usado na sala de combate atual (os reforços nascem nos pontos dele)
static const LayoutSala *layoutCombateAtual = &LAYOUTS_COMBATE[0];

// Cria os grupos de uma onda do encontro atual nos pontos da sala
static void RogueSurgirOnda(Biblioteca *b, int onda)
{
    const LayoutSala *l = layoutCombateAtual;
    const EncontroDef *enc = &ENCONTROS[(b->encontro >= 0) ? b->encontro : 0];
    int nivel = RogueNivelCombate(b);

    // Pontos da sala em ordem sorteada
    int ordem[8];
    for (int i = 0; i < l->numPontos; i++)
        ordem[i] = i;

    for (int i = l->numPontos - 1; i > 0; i--) {
        int k = GetRandomValue(0, i);
        int t = ordem[i]; ordem[i] = ordem[k]; ordem[k] = t;
    }

    int ponto = 0;

    for (int g = 0; g < enc->numGrupos; g++) {

        const GrupoEncontro *gr = &enc->grupo[g];
        if (gr->onda != onda)
            continue;

        int qtd = GetRandomValue(gr->min, gr->max) + ((nivel >= 3 && gr->max > 1) ? 1 : 0);
        bool bando = (gr->tipo == INIMIGO_SPAMMER);

        for (int k = 0; k < qtd; k++) {
            Vector2 base = l->pontos[ordem[ponto % l->numPontos]];
            Inimigo *e = RogueCriarInimigo(b, gr->tipo, RogueLugarSurgir(b, base, DEF_INIMIGOS[gr->tipo].raio));
            if (gr->elite) RogueTornarElite(e);
            if (!bando || k % BANDO_SPAMMERS == BANDO_SPAMMERS - 1 || k == qtd - 1)
                ponto++;
        }
    }

    // A partir do 2º combate, um Guardião vem selado com um desafio educativo (só na 1ª onda
    // e só quando o objetivo é eliminar: assim o desafio nunca fica para trás)
    if (onda == 0 && b->combates >= 2 && b->objetivoSala == OBJC_ELIMINAR) {
        Vector2 base = l->pontos[ordem[ponto % l->numPontos]];
        Inimigo *e = RogueCriarInimigo(b, INIMIGO_GUARDIAO, RogueLugarSurgir(b, base, GUARDIAO_RAIO));
        if (e != NULL)
            e->selado = true;
    }
}

// Monta a sala de combate com o encontro "id" (só a 1ª onda; as outras vêm em RogueAtualizarObjetivo)
static void RogueMontarEncontro(Biblioteca *b, const LayoutSala *l, int id)
{
    int nivel = RogueNivelCombate(b);
    const EncontroDef *enc = &ENCONTROS[id];

    layoutCombateAtual = l;
    b->encontro = id;
    b->ultimoEncontro = id;
    b->ondaAtual = 0;
    b->numOndas = 1;

    // Ondas extras só quando o objetivo é eliminar (os outros objetivos têm reforços próprios)
    if (b->objetivoSala == OBJC_ELIMINAR)
        for (int g = 0; g < enc->numGrupos; g++)
            if (enc->grupo[g].onda + 1 > b->numOndas)
                b->numOndas = enc->grupo[g].onda + 1;

    // Expansão da progressão: com o dobro de salas, no máximo 2 ondas por sala (a 3ª onda não vem)
    if (b->numOndas > MAX_ONDAS_SALA)
        b->numOndas = MAX_ONDAS_SALA;

    RogueSurgirOnda(b, 0);

    RogueAviso(b, TextFormat("ENCONTRO: %s", enc->nome));
    Telemetria("rogue_encontro", enc->nome, (float)nivel, b->combates);
}

// Esvazia a sala e coloca o jogador na entrada
static void RogueLimparSala(Biblioteca *b, TipoSalaRogue tipo, Vector2 entrada)
{
    memset(b->proj, 0, sizeof(b->proj));
    memset(b->ini, 0, sizeof(b->ini));
    memset(b->col, 0, sizeof(b->col));
    memset(b->arm, 0, sizeof(b->arm));
    memset(b->areas, 0, sizeof(b->areas));

    b->tipoSala = tipo;
    b->encontro = -1;
    b->limpa = false;
    b->terminalLido = false;
    b->recompensaPega = false;
    b->lojaAberta = false;
    b->chefe.ativo = false;
    b->silogista.ativo = false;
    b->luci.ativo = false;
    b->fadeEntrada = 0.35f;
    b->j.pos = entrada;
    b->j.tempoEsquiva = 0.0f;
    b->j.golpesSofridos = 0;

    // Reformulação: estado de sala (portas, objetivo, armadilhas, recompensa, eventos)
    b->numPortas = 0;
    b->numObstFixos = 0;
    b->objetivoSala = OBJC_ELIMINAR;
    b->ondaAtual = 0;
    b->numOndas = 1;
    b->avisoOnda = 0.0f;
    b->tempoObjetivo = b->tempoObjetivoMax = 0.0f;
    b->reforco = 0.0f;
    b->alvoPrioritario = -1;
    b->numMecanismos = 0;
    memset(b->progressoMecanismo, 0, sizeof(b->progressoMecanismo));
    memset(b->mecanismoDesligado, 0, sizeof(b->mecanismoDesligado));
    b->temParedeSecreta = false;
    b->passagemAberta = false;
    b->paredeFalsa = -1;
    b->paredeMarcada = -1;
    b->marcaParede = 0.0f;
    b->recompensaAtiva = false;
    b->escolhaAberta = false;
    b->escolhaPendente = -1;
    b->eventoAberto = false;
    b->eventoResolvido = false;
    b->eventoUsado = false;
    b->eventoCombate = false;
    b->estadoDesafio = 0;
    b->contadorDesafio = 0;
    b->registroSala = false;
    b->registroSalaLido = false;
    b->mensagemSistema = 0.0f;
    b->mapaAberto = false;
    memset(&b->lab, 0, sizeof(b->lab));        // expansão educativa: o laboratório não passa de uma sala para outra
    memset(&b->janela, 0, sizeof(b->janela));  // expansão da progressão: o mini-chefe também não
    b->janela.indice = -1;

    // Bloco 3: impacto e parry não passam de uma sala para outra
    b->tremorForte = 0.0f;
    b->zoomImpacto = 0.0f;
    b->tempoErro = 0.0f;
    memset(b->textos, 0, sizeof(b->textos));
    memset(&b->j.parry, 0, sizeof(b->j.parry));
}

// ---------- Reformulação: montagem das salas da missão ----------

// Lado oposto (sair pela porta da esquerda = entrar na próxima pela direita)
static LadoPorta RogueLadoOposto(LadoPorta l)
{
    switch (l) {
        case LADO_CIMA:     return LADO_BAIXO;
        case LADO_ESQUERDA: return LADO_DIREITA;
        case LADO_DIREITA:  return LADO_ESQUERDA;
        default:            return LADO_CIMA;
    }
}

// Distribui as saídas do nó atual nas paredes: nunca na parede por onde o jogador entrou.
// Duas saídas: a que fica mais à esquerda no mapa vai na porta mais à esquerda.
static void RoguePrepararPortas(Biblioteca *b)
{
    b->numPortas = 0;
    if (b->noAtual < 0)
        return;

    const NoMapa *n = &b->mapa.no[b->noAtual];
    if (n->numSaidas <= 0)
        return;

    // Destinos da esquerda para a direita (como aparecem no mapa)
    int dest[MAX_SAIDAS];
    for (int k = 0; k < n->numSaidas; k++) dest[k] = n->saida[k];
    for (int a = 0; a < n->numSaidas; a++)
        for (int c = a + 1; c < n->numSaidas; c++)
            if (b->mapa.no[dest[c]].x < b->mapa.no[dest[a]].x) { int t = dest[a]; dest[a] = dest[c]; dest[c] = t; }

    if (n->numSaidas >= 3) {
        // Três caminhos: esquerda, cima e direita (só acontece em salas em que se entra por baixo)
        static const LadoPorta tres[3] = { LADO_ESQUERDA, LADO_CIMA, LADO_DIREITA };
        for (int k = 0; k < 3; k++)
            b->portas[k] = (PortaMissao){ tres[k], dest[k], PORTA_LADO_ROGUE[tres[k]] };
        b->numPortas = 3;
        return;
    }

    if (n->numSaidas == 1) {
        // Câmara e chefe: sempre pela porta de cima (as duas arenas foram feitas para entrar por baixo)
        LadoPorta lado = LADO_CIMA;
        TipoSalaRogue t = b->mapa.no[dest[0]].tipo;
        if (t != SALA_SILOGISTA && t != SALA_CHEFE && t != SALA_ESPECIAL && GetRandomValue(0, 2) == 0) {
            LadoPorta lat = (GetRandomValue(0, 1) == 0) ? LADO_ESQUERDA : LADO_DIREITA;
            if (lat == b->ladoEntrada) lat = RogueLadoOposto(lat);
            lado = lat;
        }
        b->portas[0] = (PortaMissao){ lado, dest[0], PORTA_LADO_ROGUE[lado] };
        b->numPortas = 1;
        return;
    }

    // Pares possíveis, sempre da esquerda para a direita: esquerda+cima, cima+direita, esquerda+direita
    static const LadoPorta pares[3][2] = { { LADO_ESQUERDA, LADO_CIMA }, { LADO_CIMA, LADO_DIREITA }, { LADO_ESQUERDA, LADO_DIREITA } };
    int validos[3], nv = 0;
    for (int p = 0; p < 3; p++)
        if (pares[p][0] != b->ladoEntrada && pares[p][1] != b->ladoEntrada)
            validos[nv++] = p;

    int p = validos[GetRandomValue(0, nv - 1)];
    for (int k = 0; k < 2; k++)
        b->portas[k] = (PortaMissao){ pares[p][k], dest[k], PORTA_LADO_ROGUE[pares[p][k]] };
    b->numPortas = 2;
}

// Objetivo da sala de combate (a 1ª sala é sempre "eliminar"; elite também)
static ObjetivoCombate RogueSortearObjetivo(const Biblioteca *b)
{
    if (b->tipoSala == SALA_ELITE || b->profundidade == 0 || b->noAtual < 0)
        return OBJC_ELIMINAR;

    static const int peso[NUM_OBJC] = { 40, 15, 15, 15, 15 };
    int total = 0;
    for (int i = 0; i < NUM_OBJC; i++) total += peso[i];

    int r = GetRandomValue(1, total);
    for (int i = 0; i < NUM_OBJC; i++) {
        r -= peso[i];
        if (r <= 0) return (ObjetivoCombate)i;
    }
    return OBJC_ELIMINAR;
}

// Lugar livre para uma armadilha ou objeto: dentro da arena, fora das estantes, das portas,
// longe da entrada do jogador e de outras armadilhas
static bool RogueLugarLivre(const Biblioteca *b, Vector2 p, float raio, float longeJogador)
{
    if (p.x < ARENA_ROGUE.x + raio + 10 || p.x > ARENA_ROGUE.x + ARENA_ROGUE.width - raio - 10) return false;
    if (p.y < ARENA_ROGUE.y + raio + 10 || p.y > ARENA_ROGUE.y + ARENA_ROGUE.height - raio - 10) return false;
    if (RogueNaZonaLivre(p, raio))                                                   return false;
    if (Vector2Distance(p, b->j.pos) < longeJogador)                                 return false;

    for (int i = 0; i < b->numObst; i++)
        if (CheckCollisionCircleRec(p, raio + 6, b->obst[i]))
            return false;

    for (int i = 0; i < MAX_ARMADILHAS; i++) {
        const Armadilha *a = &b->arm[i];
        if (!a->ativo) continue;
        if ((a->tipo == ARM_ZONA || a->tipo == ARM_TORRE) && Vector2Distance(a->pos, p) < a->raio + raio + 30) return false;
        if ((a->tipo == ARM_BARREIRA || a->tipo == ARM_BLOQUEIO) && CheckCollisionCircleRec(p, raio + 20, a->r))   return false;
    }
    return true;
}

static bool RogueSortearLugar(const Biblioteca *b, float raio, float longeJogador, Vector2 *saida)
{
    for (int t = 0; t < 40; t++) {
        Vector2 p = { (float)GetRandomValue(100, 700), (float)GetRandomValue(120, 470) };
        if (RogueLugarLivre(b, p, raio, longeJogador)) { *saida = p; return true; }
    }
    return false;
}

// Cria uma armadilha. Todas avisam antes de machucar (ver RogueAtualizarArmadilhas).
static void RogueCriarArmadilha(Biblioteca *b, TipoArmadilha tipo)
{
    Armadilha *a = NULL;
    for (int i = 0; i < MAX_ARMADILHAS && a == NULL; i++)
        if (!b->arm[i].ativo) a = &b->arm[i];
    if (a == NULL)
        return;

    *a = (Armadilha){ .ativo = true, .tipo = tipo };
    Vector2 p;

    switch (tipo) {
        case ARM_FEIXE:
            // Linha que corta a arena inteira; nunca em cima da entrada
            a->vertical = GetRandomValue(0, 1) == 0;
            for (int t = 0; t < 20; t++) {
                float c = a->vertical ? (float)GetRandomValue(120, 680) : (float)GetRandomValue(130, 450);
                float jog = a->vertical ? b->j.pos.x : b->j.pos.y;
                if (fabsf(c - jog) < 90.0f) continue;
                a->r = a->vertical ? (Rectangle){ c - FEIXE_LARGURA / 2, ARENA_ROGUE.y, FEIXE_LARGURA, ARENA_ROGUE.height }
                                   : (Rectangle){ ARENA_ROGUE.x, c - FEIXE_LARGURA / 2, ARENA_ROGUE.width, FEIXE_LARGURA };
                break;
            }
            if (a->r.width <= 0.0f) { a->ativo = false; return; }
            a->timer = FEIXE_DESCANSO + (float)GetRandomValue(0, 150) / 100.0f;
            break;

        case ARM_ZONA:
            if (!RogueSortearLugar(b, ZONA_RAIO, 150.0f, &p)) { a->ativo = false; return; }
            a->pos = p;
            a->raio = ZONA_RAIO;
            a->timer = 1.5f + (float)GetRandomValue(0, 100) / 100.0f;
            break;

        case ARM_TORRE:
            if (!RogueSortearLugar(b, 16.0f, 220.0f, &p)) { a->ativo = false; return; }
            a->pos = p;
            a->raio = 16.0f;
            a->timer = TORRE_INTERVALO;
            break;

        case ARM_EXPLOSAO:
            a->raio = EXPLOSAO_RAIO;
            a->timer = EXPLOSAO_INTERVALO;
            break;

        case ARM_BARREIRA: {
            // Barreira que vai e volta no meio da arena (longe das portas)
            a->vertical = GetRandomValue(0, 1) == 0;
            if (a->vertical) {                  // barra em pé, anda para os lados
                a->r = (Rectangle){ 230, (float)GetRandomValue(160, 300), 22, 100 };
                a->limiteA = 230; a->limiteB = 548;
            } else {                            // barra deitada, anda para cima e para baixo
                a->r = (Rectangle){ (float)GetRandomValue(220, 480), 170, 100, 22 };
                a->limiteA = 170; a->limiteB = 392;
            }
            a->vel = BARREIRA_VEL * ((GetRandomValue(0, 1) == 0) ? 1.0f : -1.0f);
        } break;

        case ARM_BLOQUEIO:
            if (!RogueSortearLugar(b, 56.0f, 160.0f, &p)) { a->ativo = false; return; }
            a->r = (Rectangle){ p.x - 40, p.y - 40, 80, 80 };
            a->timer = BLOQUEIO_LIVRE;
            break;

        default:
            break;
    }
}

// Quantas armadilhas e de que tipo (cresce com a profundidade; a 1ª sala não tem)
static int RogueQtdArmadilhas(const Biblioteca *b)
{
    int n = 0;
    if (b->profundidade == 0)       n = 0;
    else if (b->profundidade <= 2)  n = (GetRandomValue(1, 100) <= 55) ? 1 : 0;
    else if (b->profundidade <= 4)  n = 1;
    else                            n = GetRandomValue(1, 2);
    if (b->tipoSala == SALA_ELITE)  n++;
    return n;
}

static TipoArmadilha RogueSortearTipoArmadilha(const Biblioteca *b)
{
    int maximo = (b->profundidade <= 2) ? ARM_EXPLOSAO : ARM_BLOQUEIO;
    return (TipoArmadilha)GetRandomValue(0, maximo);
}

// Objetos do objetivo: núcleos, alvo prioritário ou consoles do mecanismo
static void RogueMontarObjetivo(Biblioteca *b, const LayoutSala *l)
{
    switch (b->objetivoSala) {

        case OBJC_SOBREVIVER:
            b->tempoObjetivoMax = b->tempoObjetivo = fminf(38.0f, SOBREVIVER_TEMPO_BASE + 2.5f * (float)b->profundidade);
            b->reforco = REFORCO_INTERVALO * 0.6f;
            break;

        case OBJC_NUCLEOS: {
            // Os núcleos ficam longe da entrada e longe uns dos outros
            int criados = 0;
            for (int t = 0; t < 60 && criados < NUM_NUCLEOS; t++) {
                Vector2 p = l->pontos[GetRandomValue(0, l->numPontos - 1)];
                p.x += (float)GetRandomValue(-30, 30);
                p.y += (float)GetRandomValue(-30, 30);
                if (!RogueLugarLivre(b, p, DEF_INIMIGOS[INIMIGO_NUCLEO].raio, 200.0f)) continue;

                bool perto = false;
                for (int i = 0; i < MAX_INIMIGOS; i++)
                    if (b->ini[i].ativo && b->ini[i].tipo == INIMIGO_NUCLEO && Vector2Distance(b->ini[i].pos, p) < 170.0f) perto = true;
                if (perto) continue;

                RogueCriarInimigo(b, INIMIGO_NUCLEO, p);
                criados++;
            }
            if (criados == 0) b->objetivoSala = OBJC_ELIMINAR;     // sem lugar: vira um combate comum
            b->reforco = REFORCO_INTERVALO;
        } break;

        case OBJC_PRIORITARIO: {
            // O RETRANSMISSOR: um Botnet de elite no ponto mais longe da entrada
            Vector2 melhor = l->pontos[0];
            for (int i = 1; i < l->numPontos; i++)
                if (Vector2Distance(l->pontos[i], b->j.pos) > Vector2Distance(melhor, b->j.pos)) melhor = l->pontos[i];

            Inimigo *e = RogueCriarInimigo(b, INIMIGO_BOTNET, RogueLugarSurgir(b, melhor, DEF_INIMIGOS[INIMIGO_BOTNET].raio));
            if (e != NULL) {
                RogueTornarElite(e);
                e->prioritario = true;
                e->hp *= PRIORITARIO_HP;
                e->hpMax = e->hp;
                b->alvoPrioritario = (int)(e - b->ini);
            } else {
                b->objetivoSala = OBJC_ELIMINAR;
            }
            b->reforco = REFORCO_INTERVALO;
        } break;

        case OBJC_MECANISMO: {
            b->numMecanismos = 0;
            for (int t = 0; t < 80 && b->numMecanismos < NUM_MECANISMOS; t++) {
                Vector2 p;
                if (!RogueSortearLugar(b, 26.0f, 140.0f, &p)) continue;
                bool perto = false;
                for (int k = 0; k < b->numMecanismos; k++)
                    if (Vector2Distance(b->posMecanismo[k], p) < 180.0f) perto = true;
                if (perto) continue;
                b->posMecanismo[b->numMecanismos++] = p;
            }
            if (b->numMecanismos == 0) b->objetivoSala = OBJC_ELIMINAR;
            b->reforco = REFORCO_INTERVALO;
        } break;

        default:
            break;
    }
}

// Algumas salas escondem uma passagem para a sala secreta (parede corrompida).
// A Luci às vezes avisa, mas, instável, pode apontar a parede errada.
static void RogueMontarParedeSecreta(Biblioteca *b)
{
    if (b->noAtual < 0 || b->mapa.no[b->noAtual].secreta < 0)
        return;

    const NoMapa *s = &b->mapa.no[b->mapa.no[b->noAtual].secreta];
    if (s->visitado)
        return;

    b->temParedeSecreta = true;
    b->paredeSecreta = GetRandomValue(0, 3);
    b->hpParede = PAREDE_SECRETA_HP;

    if (GetRandomValue(1, 100) <= 70) {
        bool errou = GetRandomValue(1, 100) <= RogueChanceLuciErrar(b);
        int onde = b->paredeSecreta;
        if (errou) {
            b->paredeFalsa = (b->paredeSecreta + GetRandomValue(1, 3)) % 4;
            onde = b->paredeFalsa;
        }
        RogueRecadoLuci(b, TextFormat("Luci: Sinto um eco atrás da parede %s...", NOMES_PAREDES_SECRETAS[onde]));
        b->luciMsgTempo = 5.0f;
    }
}

// Recompensa no chão no meio da sala (núcleo de melhoria, arsenal, fragmentos ou restauração)
static void RogueColocarRecompensa(Biblioteca *b, TipoRecompensa tipo)
{
    if (tipo == RECOMPENSA_NENHUMA)
        return;

    Vector2 p = { 400, 290 };
    for (int t = 0; t < 30; t++) {
        Vector2 q = (t == 0) ? p : (Vector2){ 400.0f + (float)GetRandomValue(-140, 140), 290.0f + (float)GetRandomValue(-100, 100) };
        bool livre = true;
        for (int i = 0; i < b->numObst && livre; i++)
            if (CheckCollisionCircleRec(q, 26, b->obst[i])) livre = false;
        if (livre) { p = q; break; }
    }

    b->recompensaAtiva = true;
    b->recompensaTipo = tipo;
    b->recompensaPos = p;
    RogueParticulas(b, p, GOLD, 24, 200);
}

static int RogueSortearEvento(Biblioteca *b)
{
    int candidatos[NUM_EVENTOS_SORTEAVEIS], n = 0;

    for (int passada = 0; passada < 2 && n == 0; passada++)
        for (int e = 0; e < NUM_EVENTOS_SORTEAVEIS; e++) {
            if (passada == 0 && (b->eventosVistos & (1u << e))) continue;
            if (e == EVT_MEMORIA && b->memoriasVistas == (1u << NUM_MEMORIAS) - 1) continue;
            candidatos[n++] = e;
        }

    int e = (n > 0) ? candidatos[GetRandomValue(0, n - 1)] : EVT_PROTOCOLO;
    b->eventosVistos |= 1u << e;
    return e;
}

static void RogueEntrarSala(Biblioteca *b, TipoSalaRogue tipo)
{
    // Na missão, o jogador aparece do lado por onde entrou; fora dela, embaixo
    Vector2 entrada = (b->noAtual >= 0) ? ENTRADA_LADO_ROGUE[b->ladoEntrada] : SPAWN_ROGUE;
    RogueLimparSala(b, tipo, entrada);
    RoguePrepararPortas(b);

    if (tipo == SALA_COMBATE || tipo == SALA_ELITE) {

        int idLayout = GetRandomValue(0, NUM_LAYOUTS_COMBATE - 1);
        const LayoutSala *l = &LAYOUTS_COMBATE[idLayout];
        RogueUsarLayout(b, l);
        b->combates++;
        b->objetivoSala = RogueSortearObjetivo(b);

        int armadilhas = RogueQtdArmadilhas(b) + ((idLayout == LAYOUT_AREA_ABERTA) ? 1 : 0);
        for (int k = 0; k < armadilhas; k++)
            RogueCriarArmadilha(b, RogueSortearTipoArmadilha(b));

        RogueMontarEncontro(b, l, RogueSortearEncontro(b, RogueNivelCombate(b)));
        RogueMontarObjetivo(b, l);
        RogueMontarParedeSecreta(b);

        if (b->objetivoSala != OBJC_ELIMINAR)
            RogueAviso(b, TextFormat("OBJETIVO: %s", NOMES_OBJC[b->objetivoSala]));
        if (tipo == SALA_ELITE && b->luciMsgTempo <= 0.0f)
            RogueRecadoLuci(b, FALAS_LUCI_SALA[SALA_ELITE]);
    }
    else if (tipo == SALA_EDUCATIVA) {
        RogueUsarLayout(b, &LAYOUT_EDUCATIVA);

        // Instável, a Luci começa a se contradizer
        if (RogueEstab(b) <= 3) {
            int nivel = (int)Clamp((float)(4 - RogueEstab(b)), 1.0f, 3.0f);
            b->falaPendente = FALAS_LUCI_CORROMPIDA[nivel - 1];
        }

        // Reformulação: um arquivo de ameaça opcional (narrativa sobre um inimigo)
        b->registroSala = true;
        b->registroSalaId = GetRandomValue(0, NUM_AMEACAS - 1);
        b->posRegistroSala = POS_REGISTRO_SALA;
    }
    else if (tipo == SALA_RECOMPENSA) {

        RogueUsarLayout(b, &LAYOUT_RECOMPENSA);
        b->limpa = true;                        // pode pegar uma recompensa ou seguir em frente

        // Três recompensas diferentes, sorteadas pela raridade: no máximo uma arma;
        // nenhum temporário e nenhum passivo que já está no máximo
        unsigned int usados = 0;
        int comArma = (GetRandomValue(1, 100) <= CHANCE_ARMA_PEDESTAL) ? GetRandomValue(0, NUM_PEDESTAIS - 1) : -1;

        for (int i = 0; i < NUM_PEDESTAIS; i++) {
            b->armaPedestal[i] = (i == comArma) ? RogueSortearArma(b, 0) : ARMA_DISPARADOR;
            int it = RogueSortearItem(b, usados, false);
            b->pedestal[i] = (TipoItem)((it < 0) ? ITEM_ANTIVIRUS : it);
            usados |= 1u << b->pedestal[i];
        }
    }
    else if (tipo == SALA_EVENTO || tipo == SALA_DESCANSO || tipo == SALA_DESAFIO) {
        // Salas sem combate obrigatório: a porta já está aberta
        RogueUsarLayout(b, &LAYOUT_EVENTO);
        layoutCombateAtual = &LAYOUT_EVENTO;
        b->limpa = true;
        b->posObjetoSala = POS_OBJETO_SALA;

        if (tipo == SALA_EVENTO) {
            b->evento = (TipoEvento)RogueSortearEvento(b);
            if (b->evento == EVT_FONTE_FALSA)          b->varianteEvento = GetRandomValue(0, NUM_QUIZ_FONTES - 1);
            else if (b->evento == EVT_RESPOSTA_IA)     b->varianteEvento = GetRandomValue(0, NUM_QUIZ_RESPOSTAS - 1);
            else if (b->evento == EVT_MODELO_EXPERIMENTAL) {
                int livres[3], n = 0;
                for (int p = 0; p < 3; p++) if (!(b->j.penalidade & (1 << p))) livres[n++] = p;
                b->varianteEvento = (n > 0) ? livres[GetRandomValue(0, n - 1)] : 0;
            }
            else if (b->evento == EVT_MEMORIA) {
                int livres[NUM_MEMORIAS], n = 0;
                for (int m = 0; m < NUM_MEMORIAS; m++) if (!(b->memoriasVistas & (1u << m))) livres[n++] = m;
                b->varianteEvento = (n > 0) ? livres[GetRandomValue(0, n - 1)] : GetRandomValue(0, NUM_MEMORIAS - 1);
            }
        } else if (tipo == SALA_DESCANSO) {
            b->evento = EVT_DESCANSO;
        } else {
            b->evento = EVT_DESAFIO;
            b->desafioSala = (TipoDesafioSala)GetRandomValue(0, NUM_DESAFIOS_SALA - 1);
        }

        if (FALAS_LUCI_SALA[tipo] != NULL) {
            RogueRecadoLuci(b, FALAS_LUCI_SALA[tipo]);
            b->luciMsgTempo = 4.5f;
        }
    }
    else if (tipo == SALA_ESPECIAL) {
        // Expansão da progressão: elite ou mini-chefe obrigatório
        RogueMontarSalaEspecial(b, RogueEspecialAtual(b));
    }
    else if (tipo == SALA_LABORATORIO) {
        // Expansão educativa: o console do laboratório no meio da sala
        RogueUsarLayout(b, &LAYOUT_EVENTO);
        layoutCombateAtual = &LAYOUT_EVENTO;
        b->posObjetoSala = POS_OBJETO_SALA;
        TipoLab lab = (b->noAtual >= 0) ? (TipoLab)b->mapa.no[b->noAtual].lab : LAB_PROMPTS;
        LabPreparar(b, lab);
        b->limpa = LAB_ESPECIAL[lab];          // comum: a porta abre ao terminar; especial: opcional
        RogueRecadoLuci(b, FALAS_LUCI_LAB[lab]);
        b->luciMsgTempo = 4.5f;
    }
    else if (tipo == SALA_SECRETA) {
        // Arquivo oculto: uma recompensa rara, fragmentos e uma memória da Luci
        RogueUsarLayout(b, &LAYOUT_SECRETA);
        b->limpa = true;
        RogueColocarRecompensa(b, RECOMPENSA_RARA);
        for (int k = 0; k < 4; k++)
            RogueSoltar(b, (Vector2){ 400, 330 }, true, ITEM_ANTIVIRUS);

        int livres[NUM_MEMORIAS], n = 0;
        for (int m = 0; m < NUM_MEMORIAS; m++) if (!(b->memoriasVistas & (1u << m))) livres[n++] = m;
        b->registroSala = true;
        b->registroSalaId = 100 + ((n > 0) ? livres[GetRandomValue(0, n - 1)] : GetRandomValue(0, NUM_MEMORIAS - 1));   // 100+ = memória
        b->posRegistroSala = (Vector2){ 400, 150 };

        RogueRecadoLuci(b, FALAS_LUCI_SALA[SALA_SECRETA]);
        b->luciMsgTempo = 4.0f;
    }
    else if (tipo == SALA_TRANSICAO || tipo == SALA_LUCI) {
        RogueMontarSalaBloco3(b, tipo);
    }
    else if (tipo == SALA_SILOGISTA) {
        RogueUsarLayout(b, &LAYOUT_CHEFE);
        if (SILOGISTA_BH) RogueIniciarSilogistaBH(b);       // versão nova (desafio opcional)
        else              RogueIniciarSilogista(b);         // versão legada (Câmara obrigatória)
        b->conversaPendente = SILOGISTA_BH ? &dialogoSilogistaIntroBH : &dialogoSilogistaIntro;
        b->objConversa = OBJ_SILOGISTA_INTRO;
    }
    else {
        RogueUsarLayout(b, &LAYOUT_CHEFE);
        RogueIniciarChefe(b);
        RogueMudarEstabilidade(b, -1, "o eco do Alucinador");
        b->conversaPendente = &dialogoAlucinadorIntro;
        b->objConversa = OBJ_CHEFE_INTRO;
    }

    // Mensagem de sistema corrompido (narrativa ambiental) em algumas salas da missão
    if (RogueSalaDaMissao(b) && tipo != SALA_CHEFE && tipo != SALA_SILOGISTA && GetRandomValue(1, 100) <= 35) {
        snprintf(b->textoSistema, sizeof(b->textoSistema), "%s", MENSAGENS_SISTEMA[GetRandomValue(0, NUM_MENSAGENS_SISTEMA - 1)]);
        b->mensagemSistema = 4.0f;
    }
}

// Volta para o átrio (chegando do corredor, depois da derrota ou no fim da missão)
static void RogueEntrarAtrio(Biblioteca *b, bool vindoDoCorredor)
{
    b->noAtual = -1;
    b->profundidade = 0;
    b->ladoEntrada = LADO_BAIXO;
    b->fatorVidaInimigos = b->fatorRitmoInimigos = b->fatorDanoSala = 1.0f;

    RogueLimparSala(b, SALA_ATRIO, vindoDoCorredor ? SPAWN_ATRIO : (Vector2){ 400, 420 });
    RogueUsarLayout(b, &LAYOUT_ATRIO);

    // Terminais de atalho: sólidos (o Thomas encosta na frente deles)
    const Vector2 terminais[2] = { POS_TERMINAL_SELETOR, POS_TERMINAL_BLOCO3 };
    for (int k = 0; k < 2 && b->numObst < MAX_OBSTACULOS; k++)
        b->obst[b->numObst++] = (Rectangle){ terminais[k].x - 19, terminais[k].y - 24, 38, 40 };
    b->numObstFixos = b->numObst;
    b->seletorAberto = false;

    b->indiceRota = -1;
    b->limpa = true;
    RogueLimparEfeitos(&b->j);
    b->j.hp = RogueHpMax(b);
    b->j.ep = RogueEpMax(b);
    b->j.direcao = vindoDoCorredor ? DIR_DIREITA : DIR_COSTAS;

    // Armas à venda no Byteco (diferentes entre si)
    unsigned int naLoja = 0;
    for (int i = 0; i < ARMAS_NA_LOJA; i++) {
        b->estoqueArmas[i] = RogueSortearArma(b, naLoja);
        naLoja |= 1u << b->estoqueArmas[i];
    }
    b->armasOferecidas = 0;
}

// ---------- Reformulação: geração do mapa da tentativa ----------

static NoMapa *RogueNo(Biblioteca *b, int prof, int coluna)
{
    return &b->mapa.no[b->mapa.primeiro[prof] + coluna];
}

static void RogueLigar(NoMapa *n, int destino)
{
    for (int k = 0; k < n->numSaidas; k++)
        if (n->saida[k] == destino) return;
    if (n->numSaidas < MAX_SAIDAS)
        n->saida[n->numSaidas++] = destino;
}

// Tipo sorteado de uma sala intermediária, pelos pesos da camada
static TipoSalaRogue RogueSortearTipoSala(int prof, unsigned int jaNaCamada)
{
    //                              COMBATE ELITE EDUC  EVENTO DESC  DESAFIO TESOURO LAB
    static const int pesos[MAPA_PROFUNDIDADES][8] = {
        {  1,  0,  0,  0,  0,  0,  0,  0 },     // 0
        { 40,  0, 30, 20,  0, 12, 14, 22 },     // 1
        { 35, 25, 25, 20,  0, 15, 10, 22 },     // 2
        { 40, 15, 20, 25,  0, 15, 10, 22 },     // 3 (nova)
        {  0,  0,  0,  0,  0,  0,  0,  0 },     // 4 (Sentinela)
        { 25,  0, 10, 20, 35,  0, 25, 10 },     // 5 (nova: respiro depois do elite)
        {  0,  0,  0,  0,  0,  0,  0,  0 },     // 6 (Câmara)
        { 35, 20, 25, 20,  0, 15, 10, 22 },     // 7
        { 40, 25, 15, 20,  0, 15, 10, 22 },     // 8 (nova)
        {  0,  0,  0,  0,  0,  0,  0,  0 },     // 9 (Retropropagador)
        { 35, 25,  0, 20, 15, 15,  0, 22 },     // 10
        { 25, 10,  0, 20, 35, 10, 15, 15 },     // 11 (nova: preparação para o mini-chefe)
        {  0,  0,  0,  0,  0,  0,  0,  0 },     // 12 (Janela de Contexto)
        { 30, 10,  0, 20, 30,  0, 25, 10 },     // 13 (nova: recuperação)
        { 30, 30,  0,  0, 30,  0, 15, 15 },     // 14 (antes do chefe: risco x descanso)
        {  0,  0,  0,  0,  0,  0,  0,  0 },     // 15 (chefe)
    };
    static const TipoSalaRogue tipos[8] = { SALA_COMBATE, SALA_ELITE, SALA_EDUCATIVA, SALA_EVENTO, SALA_DESCANSO, SALA_DESAFIO, SALA_RECOMPENSA,
                                            SALA_LABORATORIO };

    int total = 0, peso[8];
    for (int i = 0; i < 8; i++) {
        peso[i] = pesos[prof][i];
        if (jaNaCamada & (1u << tipos[i])) peso[i] = 0;         // camadas sem tipos repetidos (escolha de verdade)
        total += peso[i];
    }

    if (total <= 0)
        return SALA_COMBATE;

    int r = GetRandomValue(1, total);
    for (int i = 0; i < 8; i++) {
        r -= peso[i];
        if (r <= 0) return tipos[i];
    }
    return SALA_COMBATE;
}

// Encontro especial de uma camada (-1 = nenhum)
static int RogueEspecialDaCamada(int d)
{
    return (d == PROF_ESPECIAL_A) ? ESP_SENTINELA : ((d == PROF_ESPECIAL_B) ? ESP_RETRO : ((d == PROF_MINICHEFE) ? ESP_JANELA : -1));
}

// Camada em que o jogador escolhe o caminho (nem a 1ª, nem a Câmara, nem um encontro especial, nem o chefe)
static bool RogueCamadaComEscolha(int d)
{
    return d > 0 && d < PROF_CHEFE && d != PROF_SILOGISTA && RogueEspecialDaCamada(d) < 0;
}

// Uma camada com escolha entre d1 e d2, sorteada (-1 = nenhuma)
static int RogueSortearCamadaComEscolha(int d1, int d2)
{
    int cand[MAPA_PROFUNDIDADES], n = 0;
    for (int d = d1; d <= d2 && d < MAPA_PROFUNDIDADES; d++)
        if (RogueCamadaComEscolha(d)) cand[n++] = d;
    return (n > 0) ? cand[GetRandomValue(0, n - 1)] : -1;
}

// Categoria de um laboratório pela camada (os básicos cedo, os especiais mais fundo), sem repetir na tentativa
static int RogueSortearLab(int prof, unsigned int usados)
{
    //                                                PROMPTS ARQUIVO NÚCLEO FIREWALL PESQUISA
    static const int pesos[MAPA_PROFUNDIDADES][NUM_LABS] = {
        {  0,  0,  0,  0,  0 },     // 0
        { 55, 45,  0,  0,  0 },     // 1
        { 30, 30, 30, 15,  0 },     // 2
        { 25, 30, 30, 20, 10 },     // 3
        {  0,  0,  0,  0,  0 },     // 4 (Sentinela)
        { 20, 20, 25, 25, 20 },     // 5
        {  0,  0,  0,  0,  0 },     // 6 (Câmara)
        { 20, 20, 30, 30, 25 },     // 7
        { 15, 15, 25, 30, 30 },     // 8
        {  0,  0,  0,  0,  0 },     // 9 (Retropropagador)
        { 15, 15, 25, 30, 30 },     // 10
        { 10, 10, 20, 30, 35 },     // 11
        {  0,  0,  0,  0,  0 },     // 12 (Janela)
        { 10, 10, 20, 30, 35 },     // 13
        { 10, 10, 20, 30, 35 },     // 14
        {  0,  0,  0,  0,  0 },     // 15 (chefe)
    };

    int total = 0, peso[NUM_LABS];
    for (int l = 0; l < NUM_LABS; l++) {
        peso[l] = (usados & (1u << l)) ? 0 : pesos[prof][l];
        total += peso[l];
    }
    if (total <= 0) {
        for (int l = 0; l < NUM_LABS; l++) if (!(usados & (1u << l))) return l;
        return GetRandomValue(0, NUM_LABS - 1);
    }

    int r = GetRandomValue(1, total);
    for (int l = 0; l < NUM_LABS; l++) {
        r -= peso[l];
        if (r <= 0) return l;
    }
    return LAB_PROMPTS;
}

static TipoRecompensa RogueSortearRecompensaCombate(int prof, TipoRecompensa evitar)
{
    for (int t = 0; t < 8; t++) {
        int r = GetRandomValue(1, 100);
        TipoRecompensa rec = (r <= 50) ? RECOMPENSA_MELHORIA : ((r <= 70) ? RECOMPENSA_FRAGMENTOS : ((r <= 85) ? RECOMPENSA_ARMA : RECOMPENSA_VIDA));
        if (rec == RECOMPENSA_VIDA && prof < 2) rec = RECOMPENSA_MELHORIA;
        if (rec != evitar || t == 7) return rec;
    }
    return RECOMPENSA_MELHORIA;
}

// Gera o grafo da tentativa (ver o comentário de MAPA PROCEDURAL RAMIFICADO)
static void RogueGerarMapa(Biblioteca *b)
{
    MapaRogue *m = &b->mapa;
    memset(m, 0, sizeof(*m));

    // Na versão bullet-hell a camada da Câmara tem 2 salas: a Câmara (opcional) e um caminho que a evita
    // Expansão da progressão: camadas de largura 1 para os encontros especiais (ninguém passa sem eles)
    int larg[MAPA_PROFUNDIDADES] = { 1, 2, GetRandomValue(2, 3), GetRandomValue(2, 3), 1, 2, SILOGISTA_BH ? 2 : 1,
                                     GetRandomValue(2, 3), GetRandomValue(2, 3), 1, GetRandomValue(2, 3), 2, 1, 2, 2, 1 };
    int colunaSilogista = GetRandomValue(0, larg[PROF_SILOGISTA] - 1);

    // Nós
    for (int d = 0; d < MAPA_PROFUNDIDADES; d++) {
        m->primeiro[d] = m->numNos;
        m->largura[d] = larg[d];
        for (int c = 0; c < larg[d]; c++) {
            NoMapa *n = &m->no[m->numNos++];
            n->prof = d;
            n->coluna = c;
            n->x = ((float)c + 0.5f) / (float)larg[d];
            n->secreta = -1;
            n->pai = -1;
        }
    }

    // Ligações: cada nó vai para o vizinho mais alinhado e para um ao lado.
    // Com isso toda sala da camada seguinte recebe ligação (conferido logo abaixo).
    for (int d = 0; d < PROF_CHEFE; d++) {
        int a = larg[d], c2 = larg[d + 1];

        for (int i = 0; i < a; i++) {
            NoMapa *n = RogueNo(b, d, i);

            if (c2 == 1) { RogueLigar(n, m->primeiro[d + 1]); continue; }

            if (a == 1) {
                // Origem única (1ª sala e Câmara): liga em todas as salas da camada seguinte
                for (int j = 0; j < c2; j++)
                    RogueLigar(n, m->primeiro[d + 1] + j);
                continue;
            }

            int j0 = (int)roundf((float)i * (float)(c2 - 1) / (float)(a - 1));
            int j1 = j0 + ((GetRandomValue(0, 1) == 0) ? -1 : 1);
            if (j1 < 0 || j1 >= c2) j1 = j0 + ((j1 < 0) ? 1 : -1);
            RogueLigar(n, m->primeiro[d + 1] + j0);
            if (j1 >= 0 && j1 < c2) RogueLigar(n, m->primeiro[d + 1] + j1);
        }

        // Garantia: nenhum nó da camada seguinte fica sem entrada (não há caminho perdido)
        for (int j = 0; j < c2; j++) {
            int alvo = m->primeiro[d + 1] + j;
            bool temEntrada = false;
            for (int i = 0; i < a && !temEntrada; i++) {
                const NoMapa *n = RogueNo(b, d, i);
                for (int k = 0; k < n->numSaidas; k++) if (n->saida[k] == alvo) temEntrada = true;
            }
            if (temEntrada) continue;

            // O nó mais próximo no mapa troca a 2ª saída por esta
            int melhor = 0;
            for (int i = 1; i < a; i++)
                if (fabsf(RogueNo(b, d, i)->x - m->no[alvo].x) < fabsf(RogueNo(b, d, melhor)->x - m->no[alvo].x)) melhor = i;
            NoMapa *n = RogueNo(b, d, melhor);
            if (n->numSaidas < MAX_SAIDAS) n->saida[n->numSaidas++] = alvo;
            else                           n->saida[MAX_SAIDAS - 1] = alvo;
        }
    }

    // Tipos das salas
    for (int d = 0; d < MAPA_PROFUNDIDADES; d++) {
        unsigned int naCamada = 0;
        TipoRecompensa ultimaRec = RECOMPENSA_NENHUMA;

        for (int c = 0; c < larg[d]; c++) {
            NoMapa *n = RogueNo(b, d, c);

            if (d == 0)                   n->tipo = SALA_COMBATE;
            else if (d == PROF_SILOGISTA) n->tipo = (!SILOGISTA_BH || c == colunaSilogista) ? SALA_SILOGISTA
                                                   : ((GetRandomValue(1, 100) <= 60) ? SALA_COMBATE : ((GetRandomValue(0, 1) == 0) ? SALA_EVENTO : SALA_DESCANSO));
            else if (d == PROF_CHEFE)     n->tipo = SALA_CHEFE;
            else if (RogueEspecialDaCamada(d) >= 0) { n->tipo = SALA_ESPECIAL; n->especial = RogueEspecialDaCamada(d); }
            else                          n->tipo = RogueSortearTipoSala(d, naCamada);
            naCamada |= 1u << n->tipo;
        }

        // Camadas com escolha: sempre há pelo menos um caminho com luta (mais recompensa)
        if (RogueCamadaComEscolha(d) &&
            !(naCamada & ((1u << SALA_COMBATE) | (1u << SALA_ELITE))))
            RogueNo(b, d, GetRandomValue(0, larg[d] - 1))->tipo = SALA_COMBATE;

        for (int c = 0; c < larg[d]; c++) {
            NoMapa *n = RogueNo(b, d, c);
            if (n->tipo == SALA_COMBATE)      n->recompensa = ultimaRec = RogueSortearRecompensaCombate((int)PROF_DIFICULDADE[d], ultimaRec);
            else if (n->tipo == SALA_ELITE || n->tipo == SALA_DESAFIO || n->tipo == SALA_ESPECIAL) n->recompensa = RECOMPENSA_RARA;
            else if (n->tipo == SALA_SILOGISTA && SILOGISTA_BH)       n->recompensa = RECOMPENSA_SELO;
            if (d == 0)                       n->recompensa = RECOMPENSA_MELHORIA;    // começa sempre com uma melhoria
        }
    }

    // O conteúdo educativo continua presente: uma sala educativa antes e uma depois da Câmara
    for (int metade = 0; metade < 2; metade++) {
        int d1 = (metade == 0) ? 1 : PROF_SILOGISTA + 1, d2 = (metade == 0) ? 3 : PROF_ESPECIAL_B - 1;
        bool tem = false;
        for (int d = d1; d <= d2; d++)
            for (int c = 0; c < larg[d]; c++) if (RogueNo(b, d, c)->tipo == SALA_EDUCATIVA) tem = true;
        int d = RogueSortearCamadaComEscolha(d1, d2);
        if (!tem && d >= 0) {
            // Troca uma sala que não é de luta (ou, se não houver, a 2ª de combate da camada)
            for (int c = 0; c < larg[d]; c++) {
                NoMapa *n = RogueNo(b, d, c);
                bool luta = (n->tipo == SALA_COMBATE || n->tipo == SALA_ELITE);
                int lutas = 0;
                for (int k = 0; k < larg[d]; k++) { TipoSalaRogue t = RogueNo(b, d, k)->tipo; if (t == SALA_COMBATE || t == SALA_ELITE) lutas++; }
                if (!luta || lutas > 1) { n->tipo = SALA_EDUCATIVA; n->recompensa = RECOMPENSA_NENHUMA; break; }
            }
        }
    }

    // Expansão educativa: um laboratório antes da Câmara e um depois (sem tirar o único caminho
    // com luta nem a sala educativa da camada)
    for (int metade = 0; metade < 2; metade++) {
        int d1 = (metade == 0) ? 1 : PROF_SILOGISTA + 1, d2 = (metade == 0) ? PROF_SILOGISTA - 1 : PROF_CHEFE - 1;
        bool tem = false;
        for (int d = d1; d <= d2; d++)
            for (int c = 0; c < larg[d]; c++) if (RogueNo(b, d, c)->tipo == SALA_LABORATORIO) tem = true;

        for (int tentativa = 0; tentativa < 8 && !tem; tentativa++) {
            int d = RogueSortearCamadaComEscolha(d1, d2);
            if (d < 0) break;
            int lutas = 0;
            for (int k = 0; k < larg[d]; k++) { TipoSalaRogue t = RogueNo(b, d, k)->tipo; if (t == SALA_COMBATE || t == SALA_ELITE) lutas++; }
            int c0 = GetRandomValue(0, larg[d] - 1);
            for (int k = 0; k < larg[d] && !tem; k++) {
                NoMapa *n = RogueNo(b, d, (c0 + k) % larg[d]);
                bool luta = (n->tipo == SALA_COMBATE || n->tipo == SALA_ELITE);
                if (n->tipo == SALA_EDUCATIVA || (luta && lutas <= 1)) continue;
                n->tipo = SALA_LABORATORIO;
                tem = true;
            }
        }
    }

    // A categoria de cada laboratório. Na primeira tentativa da sessão, o Modo Prompt vem primeiro.
    {
        unsigned int usados = 0;
        bool promptPrimeiro = !(b->labIntroVista & (1u << LAB_PROMPTS));
        for (int i = 0; i < m->numNos; i++) {
            NoMapa *n = &m->no[i];
            if (n->tipo != SALA_LABORATORIO) continue;
            int lab = (promptPrimeiro && !(usados & (1u << LAB_PROMPTS))) ? LAB_PROMPTS : RogueSortearLab(n->prof, usados);
            n->lab = lab;
            usados |= 1u << lab;
            n->recompensa = LAB_ESPECIAL[lab] ? RECOMPENSA_RARA : RECOMPENSA_FRAGMENTOS;
        }
    }

    // Salas secretas: escondidas em salas de luta das camadas com escolha (menos as duas antes do chefe)
    int secretas = GetRandomValue(1, MAX_SECRETAS);
    for (int s = 0; s < secretas && m->numNos < MAPA_MAX_NOS; s++) {
        int candidatos[MAPA_MAX_NOS], n = 0;
        for (int i = 0; i < m->numNos; i++) {
            const NoMapa *no = &m->no[i];
            if (no->secreta >= 0 || no->pai >= 0) continue;
            if (!RogueCamadaComEscolha(no->prof) || no->prof >= PROF_CHEFE - 2) continue;
            if (no->tipo != SALA_COMBATE && no->tipo != SALA_ELITE) continue;
            candidatos[n++] = i;
        }
        if (n == 0) break;

        int host = candidatos[GetRandomValue(0, n - 1)];
        NoMapa *sec = &m->no[m->numNos];
        *sec = m->no[host];                     // mesmas saídas e a mesma camada
        sec->tipo = SALA_SECRETA;
        sec->recompensa = RECOMPENSA_RARA;
        sec->escondida = true;
        sec->visitado = false;
        sec->secreta = -1;
        sec->pai = host;
        m->no[host].secreta = m->numNos;
        m->numNos++;
    }
}

// Entra num nó do mapa por um lado
static void RogueEntrarNo(Biblioteca *b, int no, LadoPorta ladoEntrada)
{
    NoMapa *n = &b->mapa.no[no];

    b->noAtual = no;
    b->profundidade = (int)(PROF_DIFICULDADE[n->prof] + 0.5f);      // escala antiga (0 a 7)
    b->ladoEntrada = ladoEntrada;
    b->indiceRota++;
    n->visitado = true;
    n->escondida = false;

    // A dificuldade cresce com a profundidade (os chefes já têm o próprio equilíbrio)
    bool chefe = (n->tipo == SALA_CHEFE || n->tipo == SALA_SILOGISTA || (n->tipo == SALA_ESPECIAL && n->especial == ESP_JANELA));
    float eq = PROF_DIFICULDADE[n->prof];
    b->fatorVidaInimigos  = chefe ? 1.0f : 1.0f + DIFICULDADE_VIDA_PROF * eq;
    b->fatorRitmoInimigos = chefe ? 1.0f : 1.0f + DIFICULDADE_RITMO_PROF * eq;
    b->fatorDanoSala      = chefe ? 1.0f : 1.0f + DIFICULDADE_DANO_PROF * eq;

    Telemetria("rogue_sala", NOMES_SALAS_ROGUE[n->tipo], (float)n->prof, b->indiceRota);
    RogueEntrarSala(b, n->tipo);
}

// Sorteia o mapa da tentativa e entra na primeira sala (sempre de combate)
static void RogueComecarMissao(Biblioteca *b)
{
    RogueGerarMapa(b);

    b->indiceRota = -1;
    b->combates = 0;
    b->ultimoEncontro = -1;
    b->j.salasConcluidas = 0;
    b->armasOferecidas = 0;
    RogueLimparEfeitos(&b->j);
    RogueLimparBuild(&b->j);
    b->educativas = 0;
    b->abatidos = 0;
    b->elitesDerrotados = 0;
    b->eventosVistos = 0;
    b->j.hp = RogueHpMax(b);
    b->j.ep = RogueEpMax(b);
    b->desafiosUsados = 0;
    b->desafiosRespondidos = 0;
    b->cargaLuci = 0;
    b->falaPendente = NULL;
    b->inicio = GetTime();
    b->perm->tentativas++;

    Telemetria("rogue_missao", "inicio", 0.0f, b->perm->tentativas);
    RogueEntrarNo(b, 0, LADO_BAIXO);
}

// Atravessou a porta k da sala atual
static void RogueAtravessarPorta(Biblioteca *b, int k)
{
    if (k < 0 || k >= b->numPortas)
        return;
    RogueEntrarNo(b, b->portas[k].destino, RogueLadoOposto(b->portas[k].lado));
}

// Atravessou a passagem secreta (parede de cima = entra por baixo; parede lateral = entra pelo lado oposto)
static void RogueEntrarSecreta(Biblioteca *b)
{
    int s = (b->noAtual >= 0) ? b->mapa.no[b->noAtual].secreta : -1;
    if (s < 0)
        return;

    LadoPorta lado = (b->paredeSecreta <= 1) ? LADO_BAIXO : ((b->paredeSecreta == 2) ? LADO_DIREITA : LADO_ESQUERDA);
    RogueEntrarNo(b, s, lado);
}

// Primeira vez na Biblioteca nesta sessão (ou recomeço sem nada na mochila)
static void RogueIniciar(Biblioteca *b, ProgressoBiblioteca *perm)
{
    memset(b, 0, sizeof(*b));

    b->perm = perm;
    b->estabilidadeLocal = ESTABILIDADE_MAX_LUCI;
    b->estabilidade = &b->estabilidadeLocal;
    b->proximaContradicao = CONTRADICAO_INTERVALO_MIN;
    b->j.mira = (Vector2){ 1, 0 };
    b->j.ultimoUp = -1;
    b->noAtual = -1;
    b->inicio = GetTime();

    RogueEntrarAtrio(b, true);
}

// ---------- Desafios educativos ----------

static int RogueEstab(const Biblioteca *b)
{
    return *b->estabilidade;
}

// Chance (%) de a Luci alucinar (dica, verificação, scanner): depende da estabilidade
static int RogueChanceLuciErrar(const Biblioteca *b)
{
    return CHANCE_LUCI_ALUCINAR_B2[(int)Clamp((float)RogueEstab(b), 0.0f, (float)ESTABILIDADE_MAX_LUCI)];
}

static void RogueRecadoLuci(Biblioteca *b, const char *texto)
{
    snprintf(b->luciMsg, sizeof(b->luciMsg), "%s", texto);
    b->luciMsgTempo = 3.0f;
}

// Sobe ou desce a estabilidade. Subir por uma ação do jogador é um REPARO (vai para o save).
static void RogueMudarEstabilidade(Biblioteca *b, int delta, const char *motivo)
{
    int antes = RogueEstab(b);
    *b->estabilidade = (int)Clamp((float)(antes + delta), 0.0f, (float)ESTABILIDADE_MAX_LUCI);

    if (*b->estabilidade > antes) {
        b->perm->reparos++;
        if (motivo != NULL) RogueRecadoLuci(b, TextFormat("LUCI +1: %s", motivo));
        TocarSomTom(sfxPegar, 1.6f);
    } else if (*b->estabilidade < antes && motivo != NULL) {
        RogueRecadoLuci(b, TextFormat("LUCI -1: %s", motivo));
    }
}

// Confiar ou verificar vira hábito; com 3 iguais seguidos, a Luci comenta (pista para o Bloco 3)
static void RogueHabitoLuci(Biblioteca *b, bool confiou)
{
    if (confiou) { b->habitoConfiar++;   b->habitoVerificar = 0; }
    else         { b->habitoVerificar++; b->habitoConfiar = 0; }

    if (b->habitoConfiar >= HABITO_LUCI && !b->comentouConfiar) {
        b->comentouConfiar = true;
        b->falaPendente = "Luci: Você nunca me confere... Eu gosto disso. Fica tudo mais fácil para mim.";
    }
    if (b->habitoVerificar >= HABITO_LUCI && !b->comentouVerificar) {
        b->comentouVerificar = true;
        b->falaPendente = "Luci: Você sempre me confere. Faz bem... mesmo que isso me incomode um pouco.";
    }
}

// Desempenho que vai para o save (o Bloco 3 usa): cada resposta, puzzle e a corrupção da Luci
static void RogueRegistrarResposta(Biblioteca *b, bool certo)
{
    if (certo) b->perm->desafiosCertos++;
    else       b->perm->desafiosErrados++;

    if (RogueChanceLuciErrar(b) > b->perm->corrupcaoLuciMax)
        b->perm->corrupcaoLuciMax = RogueChanceLuciErrar(b);
}

// Quanto a Luci está "corrompida" (0 a 1): deixa ela magenta e com glitch
static float RogueCorrupcaoLuci(const Biblioteca *b)
{
    return 1.0f - (float)RogueEstab(b) / ESTABILIDADE_MAX_LUCI;
}

// Um desafio de conceito já descoberto (de preferência um que ainda não caiu nesta tentativa)
static int RogueSortearDesafio(const Biblioteca *b)
{
    int candidatos[NUM_DESAFIOS], n = 0;

    for (int passada = 0; passada < 2 && n == 0; passada++)
        for (int i = 0; i < NUM_DESAFIOS; i++) {
            if (!(b->perm->conceitos & (1u << DESAFIOS[i].conceito)))
                continue;
            if (passada == 0 && (b->desafiosUsados & (1u << i)))
                continue;
            candidatos[n++] = i;
        }

    return (n > 0) ? candidatos[GetRandomValue(0, n - 1)] : 0;    // (o Byte sempre ensina o 1º conceito)
}

static void RogueAbrirDesafio(Biblioteca *b, int indiceInimigo)
{
    b->desafioAberto = true;
    b->alvoDesafio = indiceInimigo;
    b->desafio = RogueSortearDesafio(b);
    b->desafiosUsados |= 1u << b->desafio;
    b->selecaoDesafio = 0;
    b->tempoDesafio = 0.0f;
    b->tempoRespostaSelo = TEMPO_RESPOSTA_SELO;
    b->tempoEsgotadoSelo = false;
    b->respondido = false;
    b->acertouDesafio = false;
    b->usouManual = false;
    b->dicaDesafio[0] = '\0';
    b->dicaDaLuci = false;
    b->luciMentiu = false;
    b->opcaoDica = -1;
    b->verificouDica = false;
    memset(b->opcaoRiscada, 0, sizeof(b->opcaoRiscada));

    TocarSomTom(sfxSelecao, 0.8f);
}

// Move a seleção pulando as opções riscadas
static void RogueMoverSelecaoDesafio(Biblioteca *b, int passo)
{
    int n = DESAFIOS[b->desafio].numOpcoes;

    for (int k = 0; k < n; k++) {
        b->selecaoDesafio = (b->selecaoDesafio + passo + n) % n;
        if (!b->opcaoRiscada[b->selecaoDesafio])
            return;
    }
}

// Lente da Verificação: dica confiável (e, com 3 ou mais opções, risca uma errada)
static void RogueUsarLente(Biblioteca *b)
{
    const DesafioEdu *d = &DESAFIOS[b->desafio];

    if (b->j.itens[ITEM_LENTE] <= 0 || b->respondido)
        return;

    b->j.itens[ITEM_LENTE]--;

    if (d->numOpcoes > 2) {
        int erradas[4], n = 0;
        for (int i = 0; i < d->numOpcoes; i++)
            if (i != d->correta && !b->opcaoRiscada[i])
                erradas[n++] = i;
        if (n > 0)
            b->opcaoRiscada[erradas[GetRandomValue(0, n - 1)]] = true;
        if (b->opcaoRiscada[b->selecaoDesafio])
            RogueMoverSelecaoDesafio(b, 1);
    }

    snprintf(b->dicaDesafio, sizeof(b->dicaDesafio), "LENTE: %s", d->dica);
    b->dicaDaLuci = false;
    TocarSomTom(sfxPegar, 1.3f);
    Telemetria("rogue_lente", "", 0.0f, b->desafio);
}

// H: a Luci aponta uma opção (e diz por quê). Custa 1 de estabilidade; quanto menor
// a estabilidade, maior a chance de ela ALUCINAR. A alucinação vem sem motivo e com
// certeza absoluta: um jogador atento percebe. V verifica (Lente ou 1 Fragmento).
static void RoguePedirLuci(Biblioteca *b)
{
    const DesafioEdu *d = &DESAFIOS[b->desafio];

    if (b->dicaDaLuci || b->respondido)
        return;

    b->dicaDaLuci = true;
    b->verificouDica = false;

    if (RogueEstab(b) <= 0) {
        b->luciMentiu = false;
        b->opcaoDica = -1;
        snprintf(b->dicaDesafio, sizeof(b->dicaDesafio), "Luci: Estou sobrecarregada... Resolva sem mim e eu me estabilizo.");
        MostrarEmocaoLuci(EMOCAO_DUVIDA, 2.0f);
        return;
    }

    RogueMudarEstabilidade(b, -1, NULL);
    b->luciMentiu = GetRandomValue(1, 100) <= RogueChanceLuciErrar(b);

    if (b->luciMentiu) {
        int errada = GetRandomValue(0, d->numOpcoes - 2);
        if (errada >= d->correta) errada++;
        b->opcaoDica = errada;
        snprintf(b->dicaDesafio, sizeof(b->dicaDesafio), "Luci: É \"%s\". Tenho 100%% de certeza!", d->opcoes[errada]);
    } else {
        b->opcaoDica = d->correta;
        snprintf(b->dicaDesafio, sizeof(b->dicaDesafio), "Luci: Acho que é \"%s\". %s", d->opcoes[d->correta], d->dica);
    }

    TocarSom(sfxSelecao);
    Telemetria("rogue_dica_luci", b->luciMentiu ? "alucinou" : "dica", (float)RogueChanceLuciErrar(b), b->desafio);
}

// V: confere a dica da Luci (gasta uma Lente ou 1 Fragmento). Pegar a alucinação repara a Luci.
static void RogueVerificarDica(Biblioteca *b)
{
    if (!b->dicaDaLuci || b->opcaoDica < 0 || b->verificouDica || b->respondido)
        return;

    if (b->j.itens[ITEM_LENTE] > 0)                       b->j.itens[ITEM_LENTE]--;
    else if (b->perm->fragmentos >= CUSTO_VERIFICAR_FC)   b->perm->fragmentos -= CUSTO_VERIFICAR_FC;
    else {
        RogueRecadoLuci(b, "Sem Lente nem Fragmento para verificar.");
        TocarSom(sfxErro);
        return;
    }

    b->verificouDica = true;
    b->perm->verificou++;
    RogueHabitoLuci(b, false);

    if (b->luciMentiu) {
        b->perm->alucinacoesPegas++;
        b->opcaoRiscada[b->opcaoDica] = true;
        if (b->selecaoDesafio == b->opcaoDica) RogueMoverSelecaoDesafio(b, 1);
        snprintf(b->dicaDesafio, sizeof(b->dicaDesafio), "VERIFICADO: a fonte NÃO confere. A Luci alucinou essa resposta!");
        RogueMudarEstabilidade(b, 1, "você pegou a alucinação");
        TocarSom(sfxAcerto);
    } else {
        snprintf(b->dicaDesafio, sizeof(b->dicaDesafio), "VERIFICADO: a fonte confere. %s", DESAFIOS[b->desafio].dica);
        TocarSomTom(sfxSelecao, 1.3f);
    }
    Telemetria("rogue_verificar", b->luciMentiu ? "pegou" : "conferia", 0.0f, b->desafio);
}

// esgotou = o cronômetro chegou a zero: é um erro comum (o Manual não salva e não conta como seguir a Luci)
static void RogueResponderDesafio(Biblioteca *b, ProgressoCorredor *prog, bool esgotou)
{
    const DesafioEdu *d = &DESAFIOS[b->desafio];
    int s = b->selecaoDesafio;

    if (b->respondido)
        return;

    if (!esgotou && b->opcaoRiscada[s])
        return;

    if (!esgotou && s != d->correta && b->j.itens[ITEM_MANUAL] > 0 && !b->usouManual) {

        // Manual do Conhecimento: o erro não conta, a opção errada fica riscada
        b->j.itens[ITEM_MANUAL]--;
        b->usouManual = true;
        b->opcaoRiscada[s] = true;
        RogueMoverSelecaoDesafio(b, 1);
        snprintf(b->dicaDesafio, sizeof(b->dicaDesafio), "MANUAL DO CONHECIMENTO: não foi essa. Você tem outra chance!");
        b->dicaDaLuci = false;
        TocarSom(sfxErro);
        Telemetria("rogue_manual", "", 0.0f, b->desafio);
        return;
    }

    b->respondido = true;
    b->tempoEsgotadoSelo = esgotou;
    b->acertouDesafio = !esgotou && (s == d->correta);
    b->desafiosRespondidos++;
    RogueRegistrarResposta(b, b->acertouDesafio);

    // Confiar: seguiu a dica sem verificar. Certa = bônus; alucinada = a Luci se abala.
    if (!esgotou && b->dicaDaLuci && b->opcaoDica >= 0 && !b->verificouDica && s == b->opcaoDica) {
        b->perm->confiouCego++;
        RogueHabitoLuci(b, true);
        if (b->luciMentiu) {
            b->perm->confiouAlucinacao++;
            RogueMudarEstabilidade(b, -1, "você acreditou na alucinação");
        } else {
            AlterarPontos(prog, BONUS_CONFIAR_PONTOS);
            b->perm->fragmentos += BONUS_CONFIAR_FC;
        }
    }

    // Resolveu sem a Luci: ela se estabiliza
    if (b->acertouDesafio && !b->dicaDaLuci)
        RogueMudarEstabilidade(b, 1, "resolvido sem ajuda");

    if (b->acertouDesafio) {
        AlterarPontos(prog, PONTOS_DESAFIO);
        b->perm->fragmentos += FC_POR_DESAFIO;
        TocarSom(sfxAcerto);
    } else {
        AlterarPontos(prog, -PENALIDADE_ERRO);
        TocarSom(sfxErro);
    }

    Telemetria("rogue_desafio", b->acertouDesafio ? "certo" : (esgotou ? "tempo" : "errado"),
               (float)((b->dicaDaLuci ? 1 : 0) + (b->luciMentiu ? 2 : 0)), b->desafio);
}

// Depois da explicação: o selo quebra. Acertou = o guardião fica fraco e atordoado;
// errou = ele usa a informação falsa num ataque especial (anel de balas).
static void RogueFecharDesafio(Biblioteca *b)
{
    Inimigo *e = &b->ini[b->alvoDesafio];

    b->desafioAberto = false;

    if (!e->ativo)
        return;

    e->selado = false;

    if (b->acertouDesafio) {
        e->hp -= e->hpMax * DANO_SELO_CERTO;
        e->flash = 0.3f;
        e->estado = 0;
        e->atordoado = ATORDOADO_SELO;
        e->recarga = ATORDOADO_SELO + 0.5f;
        RogueParticulas(b, e->pos, GOLD, 24, 220);
        RogueAviso(b, "SELO QUEBRADO! O guardião está atordoado.");
    } else {
        for (int k = 0; k < BALAS_ATAQUE_ESPECIAL; k++) {
            float ang = (2.0f * PI / BALAS_ATAQUE_ESPECIAL) * k;
            RogueDisparar(b, e->pos, (Vector2){ cosf(ang), sinf(ang) }, 190.0f, 9.0f, 6.0f, false);
        }
        e->estado = 0;
        e->recarga = GUARDIAO_INTERVALO;
        RogueParticulas(b, e->pos, MAGENTA, 24, 220);
        RogueAviso(b, "O guardião usa a informação falsa contra você!");
    }
}

// Onde fica a opção i do desafio do guardião (a mesma conta de DesenharDesafioRogue), para o mouse
static Rectangle RogueRetOpcaoDesafio(const Biblioteca *b, int i)
{
    const DesafioEdu *d = &DESAFIOS[b->desafio];
    Rectangle painel = { 60, 70, 680, 440 };
    int x = (int)painel.x + 24, y = (int)painel.y + 16;
    char linhas[512];

    QuebrarTexto(d->enunciado, (int)painel.width - 48, 18, linhas, (int)sizeof(linhas));
    y += 42 + ContarLinhas(linhas) * 24 + 14;

    for (int k = 0; k <= i && k < d->numOpcoes; k++) {
        char op[256];
        QuebrarTexto(TextFormat("%d) %s", k + 1, d->opcoes[k]), (int)painel.width - 90, 16, op, (int)sizeof(op));
        int n = ContarLinhas(op);
        if (k == i)
            return (Rectangle){ (float)x, (float)y - 4, painel.width - 48, (float)(n * 20 + 6) };
        y += n * 20 + 8;
    }

    return (Rectangle){ 0, 0, 0, 0 };
}

// Atalhos de ajuda escritos no rodapé do desafio (também clicáveis)
#define X_LENTE_DESAFIO   84
#define X_LUCI_DESAFIO    334
#define Y_AJUDA_DESAFIO   (70 + 440 - 46)

static const char *RogueTextoLenteDesafio(const Biblioteca *b)
{
    return (b->j.itens[ITEM_LENTE] > 0) ? TextFormat("L: Lente da Verificação (x%d)", b->j.itens[ITEM_LENTE])
                                        : "L: (sem Lente da Verificação)";
}

static const char *RogueTextoLuciDesafio(const Biblioteca *b)
{
    return !b->dicaDaLuci ? "H: dica da Luci (-1 de estabilidade)"
         : ((b->verificouDica || b->opcaoDica < 0) ? "H: a Luci já deu a dica" : "V: verificar a dica (Lente ou 1 FC)");
}

static void RogueAtualizarDesafio(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    const DesafioEdu *d = &DESAFIOS[b->desafio];
    bool confirmar = IsKeyPressed(KEY_E) || IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_SPACE);

    b->tempoDesafio += dt;

    // Cronômetro: começa quando a pergunta aparece e só corre enquanto ela espera resposta
    // (o RogueAtualizar não roda na pausa nem nas transições). Chegou a zero: erro, uma vez
    // só (respondido = true trava a volta e o tempo para de descer).
    if (!b->respondido) {
        b->tempoRespostaSelo -= dt;
        if (b->tempoRespostaSelo <= 0.0f) {
            b->tempoRespostaSelo = 0.0f;
            RogueResponderDesafio(b, prog, true);
            b->tempoDesafio = 0.0f;         // a explicação não fecha com uma tecla apertada no susto
            return;
        }
    }

    if (b->tempoDesafio < 0.4f)             // evita responder sem querer
        return;

    bool clique = CliqueMouse();

    if (b->respondido) {
        if (confirmar || clique)
            RogueFecharDesafio(b);
        return;
    }

    if (IsKeyPressed(KEY_W) || IsKeyPressed(KEY_UP))   { RogueMoverSelecaoDesafio(b, -1); TocarSom(sfxSelecao); }
    if (IsKeyPressed(KEY_S) || IsKeyPressed(KEY_DOWN)) { RogueMoverSelecaoDesafio(b, 1);  TocarSom(sfxSelecao); }

    // Mouse: passar por cima marca, clicar responde (opção riscada não vale)
    for (int i = 0; i < d->numOpcoes; i++) {
        if (b->opcaoRiscada[i] || !MouseEm(RogueRetOpcaoDesafio(b, i))) continue;
        if (MouseMexeu() && b->selecaoDesafio != i) { b->selecaoDesafio = i; TocarSom(sfxSelecao); }
        if (clique) { b->selecaoDesafio = i; confirmar = true; }
    }

    // Os atalhos do rodapé também são clicáveis
    if (clique && MouseEm(RetTextoClicavel(RogueTextoLenteDesafio(b), X_LENTE_DESAFIO, Y_AJUDA_DESAFIO, 12)))
        RogueUsarLente(b);
    if (clique && MouseEm(RetTextoClicavel(RogueTextoLuciDesafio(b), X_LUCI_DESAFIO, Y_AJUDA_DESAFIO, 12))) {
        if (b->dicaDaLuci) RogueVerificarDica(b);
        else               RoguePedirLuci(b);
    }

    for (int i = 0; i < d->numOpcoes; i++)
        if (IsKeyPressed(KEY_ONE + i) && !b->opcaoRiscada[i]) {
            b->selecaoDesafio = i;
            confirmar = true;
        }

    if (IsKeyPressed(KEY_L)) RogueUsarLente(b);
    if (IsKeyPressed(KEY_H)) RoguePedirLuci(b);
    if (IsKeyPressed(KEY_V)) RogueVerificarDica(b);

    if (confirmar)
        RogueResponderDesafio(b, prog, false);
}

// ---------- Inimigos da expansão: utilidades e sinergias ----------

// Inimigo que nasce de outro e some sozinho (não recebe bônus nem protege ninguém)
static bool RogueInimigoPassageiro(TipoInimigo t)
{
    return t == INIMIGO_ECO || t == INIMIGO_SPAM || t == INIMIGO_ISCA || t == INIMIGO_TOKEN;
}

// Está dentro do escudo de rede de algum Firewall (sem contar ele mesmo)?
static bool RogueNaZonaFirewall(const Biblioteca *b, const Inimigo *e)
{
    for (int i = 0; i < MAX_INIMIGOS; i++) {
        const Inimigo *f = &b->ini[i];
        if (f != e && f->ativo && f->tipo == INIMIGO_FIREWALL && f->surgindo <= 0.0f &&
            Vector2Distance(f->pos, e->pos) < FIREWALL_ZONA)
            return true;
    }
    return false;
}

static int RogueSpammersPerto(const Biblioteca *b, Vector2 pos, float raio)
{
    int n = 0;
    for (int i = 0; i < MAX_INIMIGOS; i++)
        if (b->ini[i].ativo && b->ini[i].tipo == INIMIGO_SPAMMER && Vector2Distance(b->ini[i].pos, pos) < raio)
            n++;
    return n;
}

// Keylogger: onde o jogador vai estar quando o tiro chegar. Só prevê se ele vem
// andando na mesma direção há algum tempo; a esquiva ou uma curva zeram a leitura.
static Vector2 RoguePrevisaoJogador(const Biblioteca *b, Vector2 origem, float velProjetil)
{
    const JogadorRogue *j = &b->j;
    float confianca = Clamp((j->tempoMesmaDirecao - KEYLOGGER_LEITURA) / KEYLOGGER_LEITURA, 0.0f, 1.0f);
    float t = fminf(Vector2Distance(origem, j->pos) / velProjetil, KEYLOGGER_PREVISAO_MAX);
    Vector2 p = Vector2Add(j->pos, Vector2Scale(j->velMedia, t * confianca));

    p.x = Clamp(p.x, ARENA_ROGUE.x + 10.0f, ARENA_ROGUE.x + ARENA_ROGUE.width - 10.0f);
    p.y = Clamp(p.y, ARENA_ROGUE.y + 10.0f, ARENA_ROGUE.y + ARENA_ROGUE.height - 10.0f);
    return p;
}

static bool RogueTemKeylogger(const Biblioteca *b)
{
    for (int i = 0; i < MAX_INIMIGOS; i++)
        if (b->ini[i].ativo && b->ini[i].tipo == INIMIGO_KEYLOGGER && b->ini[i].surgindo <= 0.0f)
            return true;
    return false;
}

// Overclock: carga de 0 (mínima) a 1 (máxima)
static float RogueCargaOverclock(const Inimigo *e)
{
    return Clamp((e->carga - OVERCLOCK_CARGA_MIN) / (OVERCLOCK_CARGA_MAX - OVERCLOCK_CARGA_MIN), 0.0f, 1.0f);
}

static void RogueSuperaquecer(Inimigo *e)
{
    e->estado = 3;
    e->timer = OVERCLOCK_ESFRIAR_MIN + (OVERCLOCK_ESFRIAR_MAX - OVERCLOCK_ESFRIAR_MIN) * RogueCargaOverclock(e);
    e->vel = (Vector2){0};
}

// Phisher revelado: mira e, se a habilidade estiver pronta, solta uma cópia falsa ao lado.
// Com o jogador cercado de Spammers (distraído), ele ataca mais rápido.
static void RogueRevelarPhisher(Biblioteca *b, Inimigo *e, bool distraido)
{
    if (e->estado != 0)
        return;

    Vector2 dir = Vector2Normalize(Vector2Subtract(b->j.pos, e->pos));

    e->estado = 1;
    e->timer = distraido ? PHISHER_PREPARO * 0.65f : PHISHER_PREPARO;
    e->alvo = dir;
    RogueParticulas(b, e->pos, GOLD, 10, 140);
    TocarSomTom(sfxErro, 1.3f);

    if (e->habilidade > 0.0f)
        return;

    e->habilidade = ISCA_RECARGA;

    Vector2 lado = { -dir.y * e->lado, dir.x * e->lado };
    Vector2 onde = Vector2Add(e->pos, Vector2Scale(lado, 70.0f));
    RogueEmpurrarParaFora(&onde, e->raio, b->obst, b->numObst);

    Inimigo *isca = RogueCriarInimigo(b, INIMIGO_ISCA, onde);
    if (isca != NULL) {
        isca->estado = 1;
        isca->timer = e->timer;
        isca->alvo = Vector2Normalize(Vector2Subtract(b->j.pos, onde));
        isca->dono = (int)(e - b->ini);
        RogueParticulas(b, onde, GOLD, 10, 140);
    }
}

// Botnet: liga cada Botnet aos (até 3) inimigos mais próximos. Quem está ligado
// fica mais rápido e ataca mais vezes. Botnet derrotado = conexões desfeitas na hora.
static void RogueAtualizarConexoes(Biblioteca *b)
{
    for (int i = 0; i < MAX_INIMIGOS; i++)
        b->ini[i].conectado = false;

    for (int i = 0; i < MAX_INIMIGOS; i++) {

        Inimigo *bt = &b->ini[i];

        if (!bt->ativo || bt->tipo != INIMIGO_BOTNET)
            continue;

        for (int k = 0; k < BOTNET_CONEXOES; k++) {

            bt->conexao[k] = -1;

            if (bt->surgindo > 0.0f)
                continue;

            float menor = BOTNET_ALCANCE;

            for (int o = 0; o < MAX_INIMIGOS; o++) {

                Inimigo *e = &b->ini[o];
                bool jaLigado = false;

                for (int q = 0; q < k; q++)
                    if (bt->conexao[q] == o) jaLigado = true;

                // (o Phisher camuflado fica de fora: a conexão entregaria o disfarce)
                if (!e->ativo || o == i || jaLigado || e->tipo == INIMIGO_BOTNET || RogueInimigoPassageiro(e->tipo) || e->surgindo > 0.0f ||
                    (e->tipo == INIMIGO_PHISHER && e->estado == 0))
                    continue;

                float d = Vector2Distance(bt->pos, e->pos);
                if (d < menor) { menor = d; bt->conexao[k] = o; }
            }

            if (bt->conexao[k] >= 0)
                b->ini[bt->conexao[k]].conectado = true;
        }
    }
}

// Firewall: quem ele protege. Um Cache tem prioridade (sinergia); senão, o centro dos aliados.
static bool RogueQuemProteger(const Biblioteca *b, const Inimigo *fw, Vector2 *centro)
{
    Vector2 soma = {0};
    int n = 0;
    float menorCache = 99999.0f;

    for (int i = 0; i < MAX_INIMIGOS; i++) {

        const Inimigo *e = &b->ini[i];

        if (e == fw || !e->ativo || e->tipo == INIMIGO_FIREWALL || RogueInimigoPassageiro(e->tipo))
            continue;

        if (e->tipo == INIMIGO_CACHE && Vector2Distance(fw->pos, e->pos) < menorCache) {
            menorCache = Vector2Distance(fw->pos, e->pos);
            *centro = e->pos;
        }

        soma = Vector2Add(soma, e->pos);
        n++;
    }

    if (menorCache < 99999.0f)
        return true;

    if (n == 0)
        return false;

    *centro = Vector2Scale(soma, 1.0f / (float)n);
    return true;
}

// Ponto da barreira de energia do Firewall (segmento na frente dele)
static void RogueBarreiraFirewall(const Inimigo *e, Vector2 *a, Vector2 *c)
{
    Vector2 meio = Vector2Add(e->pos, Vector2Scale(e->frente, e->raio + 16.0f));
    Vector2 lado = { -e->frente.y, e->frente.x };
    *a = Vector2Add(meio, Vector2Scale(lado, FIREWALL_BARREIRA_LARGURA / 2.0f));
    *c = Vector2Subtract(meio, Vector2Scale(lado, FIREWALL_BARREIRA_LARGURA / 2.0f));
}

// Um tiro do jogador bateu numa barreira de energia ativa?
static bool RogueBarreiraBloqueia(const Biblioteca *b, Vector2 pos, float raio)
{
    for (int i = 0; i < MAX_INIMIGOS; i++) {

        const Inimigo *e = &b->ini[i];

        if (!e->ativo || e->tipo != INIMIGO_FIREWALL || e->estado != 2)
            continue;

        Vector2 a, c;
        RogueBarreiraFirewall(e, &a, &c);

        Vector2 ac = Vector2Subtract(c, a);
        float t = Clamp(Vector2DotProduct(Vector2Subtract(pos, a), ac) / Vector2DotProduct(ac, ac), 0.0f, 1.0f);
        if (Vector2Distance(pos, Vector2Add(a, Vector2Scale(ac, t))) < raio + 4.0f)
            return true;
    }
    return false;
}

// Quanto do dano o inimigo leva de verdade. "direcao" é para onde o golpe vai.
// protegido = bateu num escudo (frente do Firewall ou zona de rede): faíscas verdes.
static float RogueFatorDanoInimigo(const Biblioteca *b, const Inimigo *e, Vector2 direcao, bool *protegido)
{
    float f = 1.0f;
    *protegido = false;

    if (e->tipo == INIMIGO_FIREWALL && Vector2Length(direcao) > 0.01f) {
        float deFrente = Vector2DotProduct(Vector2Negate(direcao), e->frente);     // 1 = veio bem de frente
        if (deFrente > cosf(FIREWALL_ANGULO_FRENTE * DEG2RAD)) { f *= FIREWALL_FRENTE; *protegido = true; }
        else if (deFrente < -0.5f)                              f *= FIREWALL_COSTAS;
    }
    else if (e->tipo == INIMIGO_SENTINELA) {
        // A lente protege enquanto ela está focada; distraída ou recalculando, leva o dobro
        if (RogueSentinelaVulneravel(e)) f *= SENTINELA_DANO_VULNERAVEL;
        else                             { f *= SENTINELA_DANO_BLINDADA; *protegido = true; }
    }
    else if (e->tipo == INIMIGO_RETRO) {
        if (e->estado == 3) f *= RETRO_DANO_RECALIBRANDO;
    }
    else if (e->tipo == INIMIGO_JANELA) {
        // Com a instrução PROTEGER na janela, o golpe não fere: vira ruído (ver RogueJanelaRuido)
        if (b->janela.vulneravel > 0.0f) f *= JANELA_DANO_VULNERAVEL;
        else                             { f = 0.0f; *protegido = true; }
    }
    else if (e->tipo == INIMIGO_OVERCLOCK) {
        if (e->estado == 1) f *= OVERCLOCK_DANO_CARREGANDO;
        if (e->estado == 3) f *= 1.0f + (OVERCLOCK_DANO_QUENTE - 1.0f) * (0.5f + 0.5f * RogueCargaOverclock(e));
    }

    if (e->tipo != INIMIGO_FIREWALL && !RogueInimigoPassageiro(e->tipo) && RogueNaZonaFirewall(b, e)) {
        f *= 1.0f - FIREWALL_PROTECAO;
        *protegido = true;
    }

    return f;
}

// Dano de encostar no jogador agora (alguns só machucam atacando)
static float RogueDanoContato(const Inimigo *e)
{
    switch (e->tipo) {
        case INIMIGO_PHISHER:   return (e->estado == 2) ? PHISHER_DANO : 0.0f;
        case INIMIGO_OVERCLOCK: return (e->estado == 2) ? OVERCLOCK_DANO_INVESTIDA : ((e->estado == 3) ? 0.0f : DEF_INIMIGOS[e->tipo].danoContato);
        default:                return DEF_INIMIGOS[e->tipo].danoContato;
    }
}

// O Pulso de Integridade interrompe o ataque que está sendo preparado
static void RogueInterromperInimigo(Inimigo *e)
{
    switch (e->tipo) {
        case INIMIGO_FRAGMENTO: e->estado = 0; e->recarga = FRAGMENTO_RECARGA;  break;
        case INIMIGO_GUARDIAO:  e->estado = 0; e->recarga = GUARDIAO_INTERVALO; break;
        case INIMIGO_PHISHER:
        case INIMIGO_ISCA:      if (e->estado == 1) { e->estado = 3; e->timer = PHISHER_RECUO; } break;
        case INIMIGO_OVERCLOCK: if (e->estado == 1) RogueSuperaquecer(e); break;      // a carga escapa: superaquece
        case INIMIGO_FIREWALL:  if (e->estado == 1) { e->estado = 0; e->habilidade = FIREWALL_INTERVALO; } break;
        case INIMIGO_BOTNET:    if (e->estado == 1) { e->estado = 0; e->recarga = BOTNET_INTERVALO; }    break;
        case INIMIGO_KEYLOGGER: if (e->estado == 1) { e->estado = 0; e->recarga = KEYLOGGER_INTERVALO; } break;
        case INIMIGO_CACHE:     if (e->estado == 1) { e->estado = 0; e->recarga = CACHE_INTERVALO; }     break;
        default: break;
    }
}

// ---------- Dano ----------

static void RogueFerirJogador(Biblioteca *b, float dano)
{
    JogadorRogue *j = &b->j;

    if (j->invulneravel > 0.0f || j->tempoEsquiva > 0.0f || b->morreu)
        return;

    // Firewall Portátil: o escudo absorve este golpe e some
    if (j->efeito[EFEITO_ESCUDO] > 0.0f) {
        j->efeito[EFEITO_ESCUDO] = 0.0f;
        j->invulneravel = 0.4f;
        RogueParticulas(b, j->pos, (Color){ 0, 228, 48, 255 }, 18, 200);
        TocarSomTom(sfxSelecao, 0.5f);
        return;
    }

    // Reformulação: nas salas mais fundas da missão os golpes doem mais
    if (RogueSalaDaMissao(b) && b->fatorDanoSala > 0.0f)
        dano *= b->fatorDanoSala;

    j->hp -= dano * RogueFatorDanoRecebido(j);
    j->invulneravel = INVULNERAVEL_APOS_DANO;
    j->golpesSofridos++;                        // desafio de integridade
    b->tremor = 0.25f;                          // a tela só treme quando o jogador toma dano

    // Mecanismo corrompido: levar dano interrompe o console que estava sendo desligado
    for (int k = 0; k < b->numMecanismos; k++)
        if (!b->mecanismoDesligado[k]) b->progressoMecanismo[k] = 0.0f;

    RogueParticulas(b, j->pos, RED, 10, 160);
    TocarSom(sfxDano);

    // Bloco 3: levou dano carregando um pedaço de contexto, ele cai
    if (b->luci.ativo && b->luci.carregando >= 0) {
        b->luci.posContexto[b->luci.carregando] = j->pos;
        b->luci.carregando = -1;
    }

    // Câmara da Inferência: levou dano carregando um fragmento, ele cai no chão (não some)
    Silogista *s = &b->silogista;
    if (s->ativo && s->carregando >= 0) {
        s->posPeca[s->carregando] = j->pos;
        s->carregando = -1;
        RogueAviso(b, "O fragmento caiu! Pegue de novo (E).");
    }
}

static void RogueDanoArea(Biblioteca *b, ProgressoCorredor *prog, Vector2 centro, float raio, float dano, float empurrao);
static void RogueAnel(Biblioteca *b, Vector2 pos, float raio, Color cor);

static void RogueFerirInimigo(Biblioteca *b, ProgressoCorredor *prog, Inimigo *e, float dano, Vector2 direcao)
{
    const DefInimigo *def = &DEF_INIMIGOS[e->tipo];

    // Selado: o golpe bate no selo e abre o desafio
    if (e->selado) {
        RogueParticulas(b, e->pos, GOLD, 4, 100);
        if (!b->desafioAberto)
            RogueAbrirDesafio(b, (int)(e - b->ini));
        return;
    }

    bool protegido;
    float fator = RogueFatorDanoInimigo(b, e, direcao, &protegido);

    // Rotulagem de Dados: o alvo rotulado leva mais dano de tudo
    if (e->rotulo > 0.0f && RogueUp(&b->j, UP_ROTULAR) > 0)
        fator *= 1.0f + UP_ROTULO_BONUS;

    e->hp -= dano * fator;
    e->flash = 0.1f;
    e->empurrao = Vector2Add(e->empurrao, Vector2Scale(direcao, 140.0f * def->empurrao));

    RogueParticulas(b, e->pos, protegido ? (Color){ 0, 228, 48, 255 } : def->cor, 4, 120);

    // Reações de cada tipo ao levar dano
    if (e->tipo == INIMIGO_PHISHER && e->estado == 0)
        RogueRevelarPhisher(b, e, false);                   // descoberto antes da hora

    // Expansão da progressão: o Retropropagador guarda de onde veio o golpe; a Janela vira ruído
    if (e->tipo == INIMIGO_RETRO)
        RogueRetroRegistrar(b, e);
    if (e->tipo == INIMIGO_JANELA && b->janela.vulneravel <= 0.0f)
        RogueJanelaRuido(b, dano);

    if (e->tipo == INIMIGO_CACHE) {
        e->energia = fminf(CACHE_ENERGIA_MAX, e->energia + dano * fator * CACHE_ARMAZENA);
        e->semDano = 0.0f;
        if (e->recuperando > 0.0f) {
            e->recuperando = 0.0f;                          // a pressão interrompe a recuperação
            RogueParticulas(b, e->pos, WHITE, 8, 140);
        }
    }

    if (e->hp > 0.0f)
        return;

    // Derrotado
    Vector2 onde = e->pos;
    TipoInimigo tipo = e->tipo;
    int indice = (int)(e - b->ini);

    e->ativo = false;
    b->abatidos++;
    if (tipo != INIMIGO_SPAM && tipo != INIMIGO_ISCA && tipo != INIMIGO_TOKEN)
        b->pausaImpacto = 0.04f;

    RogueParticulas(b, onde, def->cor, (tipo == INIMIGO_SPAM) ? 6 : 18, 220);
    RogueParticulas(b, onde, WHITE, 6, 160);
    TocarSomTom(sfxPegar, def->tomSom);

    // Eco da sala de desafio: conta para a meta (e não repara a Luci)
    if (tipo == INIMIGO_ECO && e->desafio) {
        b->contadorDesafio++;
        return;
    }

    // Ecos falsos verificados (destruídos a tempo) estabilizam a Luci
    if (tipo == INIMIGO_ECO && ++b->ecosDestruidos % ECOS_PARA_REPARO == 0)
        RogueMudarEstabilidade(b, 1, "ecos falsos verificados");

    if (tipo == INIMIGO_ECO || tipo == INIMIGO_SPAM || tipo == INIMIGO_TOKEN)
        return;

    if (tipo == INIMIGO_ISCA) {
        RogueAviso(b, "CÓPIA FALSA! O verdadeiro é outro.");
        return;
    }

    // As cópias somem junto com o Phisher verdadeiro
    if (tipo == INIMIGO_PHISHER)
        for (int i = 0; i < MAX_INIMIGOS; i++)
            if (b->ini[i].ativo && b->ini[i].tipo == INIMIGO_ISCA && b->ini[i].dono == indice) {
                b->ini[i].ativo = false;
                RogueParticulas(b, b->ini[i].pos, GOLD, 10, 140);
            }

    AlterarPontos(prog, def->pontos);

    // Expansão da progressão: o mini-chefe derrotado (recompensa uma vez e a explicação)
    if (tipo == INIMIGO_JANELA)
        RogueJanelaDerrotada(b, prog);

    // Reformulação: efeitos da build ao derrotar um inimigo
    JogadorRogue *jg = &b->j;
    bool elite = e->elite;

    if (RogueUp(jg, UP_ENERGIA_ABATE) > 0)
        jg->ep = fminf(RogueEpMax(b), jg->ep + UP_ENERGIA_ABATE_EP * (float)RogueUp(jg, UP_ENERGIA_ABATE));
    if (RogueUp(jg, UP_VERIFICACAO) > 0)
        jg->hp = fminf(RogueHpMax(b), jg->hp + UP_VERIFICACAO_CURA * (float)RogueUp(jg, UP_VERIFICACAO));
    if (RogueUp(jg, UP_ESCUDO_ELITE) > 0 && (elite || ++jg->abatesEscudo >= UP_ESCUDO_ABATES)) {
        jg->abatesEscudo = 0;
        if (jg->efeito[EFEITO_ESCUDO] < UP_ESCUDO_TEMPO) jg->efeito[EFEITO_ESCUDO] = UP_ESCUDO_TEMPO;
        RogueParticulas(b, jg->pos, (Color){ 0, 228, 48, 255 }, 14, 160);
    }

    if (elite) {
        b->elitesDerrotados++;
        RogueSoltar(b, onde, true, ITEM_ANTIVIRUS);         // elite sempre deixa conhecimento
        RogueSoltar(b, onde, true, ITEM_ANTIVIRUS);
        RogueAviso(b, "ELITE DERROTADO!");
    }

    if (e->prioritario) {
        b->alvoPrioritario = -1;
        RogueAviso(b, "RETRANSMISSOR DERRUBADO! Os reforços pararam.");
        TocarSomTom(sfxAcerto, 0.9f);
    }

    // Rótulo Volátil (sinergia): o rotulado explode (sem reação em cadeia)
    if (e->rotulo > 0.0f && RogueUp(jg, UP_SIN_ROTULO) > 0 && !b->golpeSecundario) {
        b->golpeSecundario = true;
        RogueDanoArea(b, prog, onde, UP_ROTULO_EXP_RAIO, UP_ROTULO_EXP_DANO * RogueFatorDano(b), 140.0f);
        b->golpeSecundario = false;
        RogueAnel(b, onde, UP_ROTULO_EXP_RAIO, (Color){ 255, 109, 194, 255 });
    }

    // Recursos: dado corrompido derrotado libera conhecimento
    if (GetRandomValue(1, 100) <= def->chanceFC)        RogueSoltar(b, onde, true, ITEM_ANTIVIRUS);
    if (GetRandomValue(1, 100) <= CHANCE_ANTIVIRUS)     RogueSoltar(b, onde, false, ITEM_ANTIVIRUS);
    if (GetRandomValue(1, 100) <= CHANCE_TEMPORARIO)    RogueSoltar(b, onde, false, RogueSortearTemporario());

    // Botnet Reverso: o inimigo derrotado solta um pacote teleguiado (só uma vez por morte,
    // nunca a partir de um golpe secundário e com um intervalo entre um e outro)
    if (RogueQtd(&b->j, ITEM_BOTNET_REVERSO) > 0 && !b->golpeSecundario && b->j.recargaBotnet <= 0.0f &&
        GetRandomValue(1, 100) <= BOTNET_REVERSO_CHANCE) {
        TipoArma arma = RogueArmaAtual(&b->j);
        Projetil *q = RogueDisparar(b, onde, (Vector2){ 0, -1 }, 300.0f, DEF_ARMAS[arma].dano * RogueFatorDano(b) * BOTNET_REVERSO_DANO, 4.0f, true);
        if (q != NULL) {
            q->guiado = true;
            q->secundario = true;
            q->vida = 1.5f;
            q->ultimoAlvo = indice + 1;
        }
        b->j.recargaBotnet = BOTNET_REVERSO_RECARGA;
    }

    if (tipo == INIMIGO_FRAGMENTO && (elite || GetRandomValue(1, 100) <= CHANCE_ECO_FALSO))
        RogueCriarInimigo(b, INIMIGO_ECO, onde);          // a informação falsa ecoa

    // Spammer: a notificação se multiplica em dois fragmentos de spam
    if (tipo == INIMIGO_SPAMMER && GetRandomValue(1, 100) <= SPAMMER_CHANCE_DIVIDIR)
        for (int k = 0; k < 2; k++) {
            Inimigo *f = RogueCriarInimigo(b, INIMIGO_SPAM, (Vector2){ onde.x + ((k == 0) ? -8.0f : 8.0f), onde.y });
            if (f != NULL) f->empurrao = (Vector2){ (k == 0) ? -160.0f : 160.0f, 0.0f };
        }
}

// O Alucinador só leva dano na fase 1 ou com o escudo aberto (fase 2)
static void RogueFerirChefe(Biblioteca *b, float dano, Vector2 onde)
{
    ChefeRogue *c = &b->chefe;

    if (!c->ativo || !c->apresentado || c->morrendo > 0.0f)
        return;

    if (c->fase == 2 && c->janela <= 0.0f) {
        RogueParticulas(b, onde, MAGENTA, 3, 90);          // bateu no escudo de distorção
        return;
    }

    c->hp -= dano;
    c->flash = 0.08f;
    RogueParticulas(b, onde, MAGENTA, 3, 120);
}

// O Alucinador leva dano agora? (o Disparo Dedutivo só marca quem pode ser ferido)
static bool RogueChefeVulneravel(const ChefeRogue *c)
{
    return c->ativo && c->apresentado && c->morrendo <= 0.0f && (c->fase == 1 || c->janela > 0.0f);
}

// O Silogista só leva dano sem a armadura lógica. Devolve true se feriu.
static bool RogueFerirSilogista(Biblioteca *b, float dano, Vector2 onde)
{
    Silogista *s = &b->silogista;

    if (!s->ativo || !s->apresentado || s->morrendo > 0.0f)
        return false;

    if (s->etapa != SIL_VULNERAVEL) {
        RogueParticulas(b, onde, (Color){ 0, 228, 255, 255 }, 3, 90);     // bateu na armadura lógica
        return false;
    }

    s->hp -= dano;
    s->flash = 0.08f;
    RogueParticulas(b, onde, PURPLE, 3, 120);
    return true;
}

// ---------- Selo da Inferência: DISPARO DEDUTIVO (Modus Ponens) ----------
//   1º acerto num inimigo: marca P → Q.  2º acerto: confirma P.
//   P → Q e P, logo Q: um projétil de energia Q cai no alvo com dano extra.

// Onde está o alvo de um projétil Q (false = o alvo sumiu)
static bool RoguePosAlvoDedutivo(const Biblioteca *b, int alvo, Vector2 *pos)
{
    if (alvo > 0) {
        if (!b->ini[alvo - 1].ativo) return false;
        *pos = b->ini[alvo - 1].pos;
        return true;
    }

    if (b->chefe.ativo)     { *pos = b->chefe.pos;     return true; }
    if (b->silogista.ativo) { *pos = b->silogista.pos; return true; }
    if (b->luci.ativo)      { *pos = b->luci.pos;      return true; }
    return false;
}

// Um tiro comum acertou um alvo que pode ser ferido (alvo: k+1 = inimigo k, -1 = chefe da sala)
static void RogueMarcarDedutivo(Biblioteca *b, int *marca, float *tempo, int alvo, Vector2 pos)
{
    JogadorRogue *j = &b->j;

    if (!j->seloInferencia || j->recargaDedutivo > 0.0f || *marca == 2)
        return;

    *tempo = DEDUTIVO_MARCA_DURACAO;

    if (*marca == 0) {
        *marca = 1;                             // premissa 1: P → Q
        TocarSomTom(sfxDedutivo, 1.0f);
        RogueTextoFlutuante(b, (Vector2){ pos.x, pos.y - 36 }, "P -> Q", (Color){ 0, 228, 255, 255 });
        RogueAnel(b, pos, 34.0f, (Color){ 0, 228, 255, 255 });
        return;
    }

    // Premissa 2: P. Conclusão: Q
    *marca = 2;
    *tempo = 0.6f;                              // os símbolos ficam um instante na tela
    j->recargaDedutivo = DEDUTIVO_RECARGA * (j->seloAmplificado ? SIL_BH_DEDUTIVO_RECARGA : 1.0f);

    Vector2 origem = { pos.x, fmaxf(ARENA_ROGUE.y + 8.0f, pos.y - 70.0f) };
    Projetil *q = RogueDisparar(b, origem, (Vector2){ 0, 1 }, DEDUTIVO_VEL, RogueDanoTiro(b) * DEDUTIVO_DANO * (j->seloAmplificado ? SIL_BH_DEDUTIVO_BONUS : 1.0f), 7.0f, true);
    if (q != NULL) q->alvoDedutivo = alvo;

    RogueParticulas(b, origem, GOLD, 12, 140);
    TocarSomTom(sfxDedutivo, 1.6f);                         // o encadeamento tem som próprio
    RogueTextoFlutuante(b, (Vector2){ pos.x, pos.y - 36 }, "P!  LOGO, Q", GOLD);
    RogueAnel(b, pos, 46.0f, GOLD);
}

static void PassarMarcaDedutiva(int *marca, float *tempo, float dt)
{
    if (*marca == 0)
        return;

    *tempo -= dt;
    if (*tempo <= 0.0f)
        *marca = 0;
}

static void RogueAtualizarDedutivo(Biblioteca *b, float dt)
{
    if (b->j.recargaDedutivo > 0.0f)
        b->j.recargaDedutivo -= dt;

    for (int i = 0; i < MAX_INIMIGOS; i++)
        PassarMarcaDedutiva(&b->ini[i].marca, &b->ini[i].tempoMarca, dt);

    PassarMarcaDedutiva(&b->chefe.marca, &b->chefe.tempoMarca, dt);
    PassarMarcaDedutiva(&b->silogista.marca, &b->silogista.tempoMarca, dt);
    PassarMarcaDedutiva(&b->luci.marca, &b->luci.tempoMarca, dt);
}

static void RoguePulso(Biblioteca *b, ProgressoCorredor *prog)
{
    JogadorRogue *j = &b->j;

    if (j->recargaPulso > 0.0f || j->ep < PULSO_CUSTO_EP)
        return;

    j->ep -= PULSO_CUSTO_EP;
    j->recargaPulso = PULSO_RECARGA;
    j->efeitoPulso = 0.4f;

    float raio = RogueRaioPulso(j), danoPulso = RogueDanoPulso(j);
    Vector2 refletir[16];
    int refletidas = 0;

    // Apaga as balas inimigas por perto (Pulso Reflexivo: guarda onde estavam)
    for (int i = 0; i < MAX_PROJETEIS; i++) {
        Projetil *p = &b->proj[i];
        if (p->ativo && !p->doJogador && Vector2Distance(p->pos, j->pos) < raio) {
            p->ativo = false;
            RogueParticulas(b, p->pos, SKYBLUE, 3, 80);
            if (RogueUp(j, UP_PULSO_REFLEXIVO) > 0 && refletidas < 16)
                refletir[refletidas++] = p->pos;
        }
    }

    for (int r = 0; r < refletidas; r++) {
        Vector2 d = Vector2Subtract(refletir[r], j->pos);
        d = (Vector2Length(d) > 0.01f) ? Vector2Normalize(d) : j->mira;
        Projetil *q = RogueDisparar(b, refletir[r], d, 420.0f, 7.0f * RogueFatorDano(b), 4.0f, true);
        if (q != NULL) { q->secundario = true; q->alcance = 320.0f; q->arma = ARMA_DISPARADOR; }
    }

    int derrubados = 0;

    // Fere, empurra e interrompe os ataques de quem está perto
    for (int i = 0; i < MAX_INIMIGOS; i++) {

        Inimigo *e = &b->ini[i];

        if (!e->ativo || Vector2Distance(e->pos, j->pos) > raio + e->raio)
            continue;

        Vector2 dir = Vector2Normalize(Vector2Subtract(e->pos, j->pos));

        if (e->tipo != INIMIGO_ECO) {
            RogueInterromperInimigo(e);
            e->empurrao = Vector2Add(e->empurrao, Vector2Scale(dir, 260.0f * DEF_INIMIGOS[e->tipo].empurrao));
        }

        RogueFerirInimigo(b, prog, e, danoPulso, dir);
        if (!e->ativo) derrubados++;
    }

    // Circuito Fechado (sinergia): cada derrubado pelo Pulso devolve energia e recarga
    if (derrubados > 0 && RogueUp(j, UP_SIN_CIRCUITO) > 0) {
        j->ep = fminf(RogueEpMax(b), j->ep + 12.0f * (float)derrubados);
        j->recargaPulso = fmaxf(0.0f, j->recargaPulso - 1.0f * (float)derrubados);
    }

    if (b->chefe.ativo && Vector2Distance(b->chefe.pos, j->pos) < raio + CHEFE_RAIO)
        RogueFerirChefe(b, danoPulso, b->chefe.pos);

    if (b->silogista.ativo && Vector2Distance(b->silogista.pos, j->pos) < raio + SIL_RAIO)
        RogueFerirSilogista(b, danoPulso, b->silogista.pos);

    if (b->luci.ativo && Vector2Distance(b->luci.pos, j->pos) < raio + LUCI_RAIO)
        RogueFerirLuciChefe(b, danoPulso, b->luci.pos);

    TocarSomTom(sfxAcerto, 0.7f);
}

// ---------- Armas, itens temporários e upgrades (expansão) ----------

static void RogueAnel(Biblioteca *b, Vector2 pos, float raio, Color cor)
{
    for (int i = 0; i < MAX_ANEIS; i++)
        if (b->aneis[i].tempo <= 0.0f) {
            b->aneis[i] = (AnelEfeito){ pos, raio, 0.35f, cor };
            return;
        }
}

// Poça ou explosão do jogador (Resíduo de Dados, Esquiva Fragmentada). Fere em RogueAtualizarAreas.
static void RogueCriarArea(Biblioteca *b, Vector2 pos, float raio, float atraso, float vida, float dps, float danoInstantaneo, Color cor)
{
    for (int i = 0; i < MAX_AREAS; i++)
        if (!b->areas[i].ativo) {
            b->areas[i] = (AreaDano){ true, pos, raio, atraso, vida, vida, dps, 0.0f, danoInstantaneo, cor };
            return;
        }
}

// Inimigo mais perto de um ponto (dentro do raio), sem contar "ignorar" (-1 = nenhum)
static int RogueInimigoMaisPerto(const Biblioteca *b, Vector2 pos, float raio, int ignorar)
{
    int melhor = -1;
    float menor = raio;

    for (int k = 0; k < MAX_INIMIGOS; k++) {
        const Inimigo *e = &b->ini[k];
        if (!e->ativo || k == ignorar || e->surgindo > 0.0f || e->selado || e->tipo == INIMIGO_ISCA)
            continue;
        float d = Vector2Distance(pos, e->pos);
        if (d < menor) { menor = d; melhor = k; }
    }

    return melhor;
}

// Dano em área (Orbe de Buffer e Pulso de Firewall). Empurra para fora do centro.
static void RogueDanoArea(Biblioteca *b, ProgressoCorredor *prog, Vector2 centro, float raio, float dano, float empurrao)
{
    for (int k = 0; k < MAX_INIMIGOS; k++) {

        Inimigo *e = &b->ini[k];

        if (!e->ativo || e->surgindo > 0.0f || Vector2Distance(centro, e->pos) > raio + e->raio)
            continue;

        Vector2 dir = Vector2Subtract(e->pos, centro);
        dir = (Vector2Length(dir) > 0.01f) ? Vector2Normalize(dir) : (Vector2){ 0, -1 };

        bool selado = e->selado;
        RogueFerirInimigo(b, prog, e, dano, dir);
        if (e->ativo && !selado)
            e->empurrao = Vector2Add(e->empurrao, Vector2Scale(dir, empurrao * DEF_INIMIGOS[e->tipo].empurrao));
    }

    if (b->chefe.ativo && Vector2Distance(centro, b->chefe.pos) < raio + CHEFE_RAIO)
        RogueFerirChefe(b, dano, b->chefe.pos);

    if (b->silogista.ativo && Vector2Distance(centro, b->silogista.pos) < raio + SIL_RAIO)
        RogueFerirSilogista(b, dano, b->silogista.pos);

    if (b->luci.ativo && Vector2Distance(centro, b->luci.pos) < raio + LUCI_RAIO)
        RogueFerirLuciChefe(b, dano, b->luci.pos);
}

static void RogueExplodirOrbe(Biblioteca *b, ProgressoCorredor *prog, Vector2 centro)
{
    float k = (RogueUp(&b->j, UP_ARMA_ORBE) > 0) ? 1.5f : 1.0f;      // Buffer Expandido
    RogueDanoArea(b, prog, centro, ORBE_RAIO_EXPLOSAO * k, ORBE_DANO_EXPLOSAO * k * RogueFatorDano(b), 120.0f);
    RogueAnel(b, centro, ORBE_RAIO_EXPLOSAO * k, DEF_ARMAS[ARMA_ORBE].cor);
    RogueParticulas(b, centro, DEF_ARMAS[ARMA_ORBE].cor, 20, 220);
    TocarSomTom(sfxAcerto, 0.6f);
}

// Pulso de Firewall (arma): onda em volta que fere, empurra e apaga as balas inimigas
static void RoguePulsoFirewall(Biblioteca *b, ProgressoCorredor *prog, float dano)
{
    JogadorRogue *j = &b->j;
    float raio = DEF_ARMAS[ARMA_PULSO_FW].alcance * ((RogueUp(j, UP_ARMA_PULSO_FW) > 0) ? 1.35f : 1.0f);

    for (int i = 0; i < MAX_PROJETEIS; i++) {
        Projetil *p = &b->proj[i];
        if (p->ativo && !p->doJogador && Vector2Distance(p->pos, j->pos) < raio) {
            p->ativo = false;
            RogueParticulas(b, p->pos, DEF_ARMAS[ARMA_PULSO_FW].cor, 3, 80);
        }
    }

    RogueDanoArea(b, prog, j->pos, raio, dano, PULSO_FW_EMPURRAO);
    RogueAnel(b, j->pos, raio, DEF_ARMAS[ARMA_PULSO_FW].cor);
    TocarSomTom(sfxAcerto, 0.5f);
}

// Fragmentação de Pacotes: o acerto se divide em pedaços que vão para os inimigos mais perto
static void RogueFragmentar(Biblioteca *b, Vector2 pos, float dano, int atingido)
{
    unsigned int usados = 0;

    for (int f = 0; f < FRAGMENTACAO_PEDACOS; f++) {

        int alvo = -1;
        float menor = FRAGMENTACAO_ALCANCE;
        for (int k = 0; k < MAX_INIMIGOS; k++) {
            const Inimigo *e = &b->ini[k];
            if (!e->ativo || k == atingido || (usados & (1u << (k % 32))) || e->surgindo > 0.0f) continue;
            if (Vector2Distance(pos, e->pos) < menor) { menor = Vector2Distance(pos, e->pos); alvo = k; }
        }

        Vector2 dir;
        if (alvo >= 0) {
            usados |= 1u << (alvo % 32);
            dir = Vector2Normalize(Vector2Subtract(b->ini[alvo].pos, pos));
        } else {
            float ang = (float)GetRandomValue(0, 360) * DEG2RAD;
            dir = (Vector2){ cosf(ang), sinf(ang) };
        }

        Projetil *q = RogueDisparar(b, pos, dir, 480.0f, dano, 3.0f, true);
        if (q != NULL) {
            q->secundario = true;                       // fragmento não se fragmenta de novo
            q->alcance = FRAGMENTACAO_ALCANCE;
            q->ultimoAlvo = atingido + 1;
        }
    }

    RogueParticulas(b, pos, LIME, 8, 140);
}

// Analisador Heurístico: devolve o multiplicador deste acerto (alvo: k+1 = inimigo, -1 = chefe)
static float RogueAnalisar(Biblioteca *b, int alvo)
{
    JogadorRogue *j = &b->j;

    if (RogueQtd(j, ITEM_ANALISADOR) == 0)
        return 1.0f;

    j->tempoAnalise = ANALISADOR_TEMPO;

    if (j->alvoAnalise != alvo) {                       // mudou de alvo: recomeça
        j->alvoAnalise = alvo;
        j->marcasAnalise = 1;
        return 1.0f;
    }

    if (j->marcasAnalise >= ANALISADOR_MARCAS) {         // padrão identificado: golpe reforçado
        j->marcasAnalise = 0;
        TocarSomTom(sfxAcerto, 1.6f);
        return 1.0f + ANALISADOR_BONUS;
    }

    j->marcasAnalise++;
    return 1.0f;
}

// Disparo contado para a Fragmentação de Pacotes
static void RogueContarDisparo(JogadorRogue *j)
{
    if (RogueQtd(j, ITEM_FRAGMENTACAO) == 0 || j->fragmentacaoArmada)
        return;

    if (++j->disparos >= FRAGMENTACAO_A_CADA) {
        j->disparos = 0;
        j->fragmentacaoArmada = true;
    }
}

static Projetil *RogueTiroArma(Biblioteca *b, TipoArma arma, Vector2 dir, float dano)
{
    const JogadorRogue *j = &b->j;
    const DefArma *a = &DEF_ARMAS[arma];
    Vector2 cano = Vector2Add(j->pos, Vector2Add((Vector2){ 0, 4 }, Vector2Scale(j->mira, 20.0f)));
    float alc = (float)RogueUp(j, UP_ALCANCE);                  // Janela de Contexto
    Projetil *p = RogueDisparar(b, cano, dir, a->velocidade * (1.0f + UP_VEL_PROJETIL_NIVEL * alc), dano, a->raio, true);

    if (p != NULL) {
        p->arma = arma;
        p->alcance = a->alcance * (1.0f + UP_ALCANCE_NIVEL * alc);

        // Disparos da build: ricochete e perfuração (o Orbe explode, então não entra)
        if (arma != ARMA_ORBE) {
            p->ricochetes += RogueUp(j, UP_RICOCHETE);
            if (RogueUp(j, UP_RICOCHETE) > 0 && RogueUp(j, UP_SIN_TEMPESTADE) > 0) p->ricochetes++;
            p->perfura += RogueUp(j, UP_PERFURAR);
        }
        if (arma == ARMA_DISPARADOR)
            p->raio += 1.5f * (float)RogueUp(j, UP_ARMA_DISPARADOR);  // Disparador Calibrado
    }
    return p;
}

// Amostragem Múltipla (projéteis extras em leque) e Eco Benigno (chance de duplicar o disparo)
static void RogueDisparosExtras(Biblioteca *b, TipoArma arma, Vector2 mira, float dano, int perfura)
{
    JogadorRogue *j = &b->j;
    int extras = RogueUp(j, UP_RAJADA);

    // Com o Fluxo Contínuo (muito rápido), só 1 a cada 3 tiros ganha os extras
    if (arma == ARMA_FLUXO && extras > 0 && (++j->contaFluxo % 3) != 0)
        extras = 0;

    // Nível 1: 1 extra; nível 2: 2 extras (um de cada lado)
    for (int k = 0; k < extras; k++) {
        float lado = (k % 2 == 0) ? 1.0f : -1.0f;
        float ang = lado * 9.0f * (float)(k / 2 + 1) * DEG2RAD;
        Projetil *q = RogueTiroArma(b, arma, Vector2Rotate(mira, ang), dano * UP_RAJADA_DANO);
        if (q == NULL) continue;
        q->secundario = (arma != ARMA_ORBE);
        q->perfura += perfura;
        if (arma == ARMA_ROTEADOR) { q->guiado = true; q->ricochetes += ROTEADOR_RICOCHETES; q->vida = ROTEADOR_VIDA; }
    }

    if (RogueUp(j, UP_DUPLICAR) > 0 && GetRandomValue(1, 100) <= UP_DUPLICAR_CHANCE * RogueUp(j, UP_DUPLICAR)) {
        Projetil *q = RogueTiroArma(b, arma, Vector2Rotate(mira, 5.0f * DEG2RAD), dano);
        if (q != NULL) {
            q->perfura += perfura;
            if (arma == ARMA_ROTEADOR) { q->guiado = true; q->ricochetes += ROTEADOR_RICOCHETES; q->vida = ROTEADOR_VIDA; }
            RogueParticulas(b, q->pos, (Color){ 0, 228, 48, 255 }, 3, 60);
        }
    }
}

// Dispara a arma equipada. "atirando" = botão ou seta segurados neste quadro.
static void RogueUsarArma(Biblioteca *b, ProgressoCorredor *prog, bool atirando, float dt)
{
    JogadorRogue *j = &b->j;
    TipoArma arma = RogueArmaAtual(j);
    const DefArma *a = &DEF_ARMAS[arma];
    float fator = RogueFatorDano(b);
    Vector2 cano = Vector2Add(j->pos, Vector2Add((Vector2){ 0, 4 }, Vector2Scale(j->mira, 20.0f)));

    if (arma == ARMA_DISPARADOR)
        fator *= 1.0f + 0.25f * (float)RogueUp(j, UP_ARMA_DISPARADOR);      // Disparador Calibrado

    // Fluxo Contínuo: esfria quando não está atirando com ela; superaquecida, só volta fria
    if (!(atirando && arma == ARMA_FLUXO) || j->superaquecida) {
        j->calor -= (j->superaquecida ? FLUXO_ESFRIA_TRAVADO : FLUXO_ESFRIA) * dt;
        if (j->calor <= 0.0f) { j->calor = 0.0f; j->superaquecida = false; }
    }

    if (j->tempoEsquiva > 0.0f)
        return;

    // Vetor de Compilação: segurar carrega, soltar dispara (mais carga, mais dano)
    if (arma == ARMA_VETOR) {
        if (atirando) {
            float velCarga = (RogueUp(j, UP_ARMA_VETOR) > 0) ? 1.4f : 1.0f;    // Compilação Otimizada
            if (j->cronoTiro <= 0.0f) j->carga = fminf(VETOR_CARGA_MAX, j->carga + dt * velCarga);
            return;
        }
        if (j->carga >= VETOR_CARGA_MIN) {
            float k = j->carga / VETOR_CARGA_MAX;
            float danoVetor = (a->dano + (VETOR_DANO_MAX - a->dano) * k) * fator;
            int atravessa = VETOR_ATRAVESSA + ((RogueUp(j, UP_ARMA_VETOR) > 0) ? 2 : 0);
            Projetil *p = RogueTiroArma(b, arma, j->mira, danoVetor);
            if (p != NULL) p->perfura += atravessa;
            RogueDisparosExtras(b, arma, j->mira, danoVetor, atravessa);
            RogueParticulas(b, cano, a->cor, 6 + (int)(10 * k), 140);
            TocarSomTom(sfxTiro, 0.55f);
            j->cronoTiro = RogueIntervaloArma(j, arma);
            RogueContarDisparo(j);
        }
        j->carga = 0.0f;
        return;
    }

    if (!atirando || j->cronoTiro > 0.0f || (arma == ARMA_FLUXO && j->superaquecida))
        return;

    if (arma == ARMA_PULSO_FW) {
        RoguePulsoFirewall(b, prog, a->dano * fator);
    }
    else if (arma == ARMA_FRAGMENTADORA) {
        // Cone Denso: +3 fragmentos e cone mais fechado; Amostragem Múltipla: +2 por nível
        int n = a->projeteis + ((RogueUp(j, UP_ARMA_FRAGMENTADORA) > 0) ? 3 : 0) + 2 * RogueUp(j, UP_RAJADA);
        float abertura = a->abertura * ((RogueUp(j, UP_ARMA_FRAGMENTADORA) > 0) ? 0.75f : 1.0f);
        for (int k = 0; k < n; k++) {
            float ang = ((float)k / (float)(n - 1) - 0.5f) * abertura + (float)GetRandomValue(-3, 3);
            RogueTiroArma(b, arma, Vector2Rotate(j->mira, ang * DEG2RAD), a->dano * fator);
        }
        TocarSomTom(sfxTiro, 0.75f);
    }
    else {
        float espalhar = (float)GetRandomValue(-10, 10) / 10.0f * (a->abertura / 2.0f) * DEG2RAD;
        Vector2 mira = Vector2Rotate(j->mira, espalhar);
        Projetil *p = RogueTiroArma(b, arma, mira, a->dano * fator);
        if (p != NULL && arma == ARMA_ROTEADOR) {
            p->guiado = true;
            p->ricochetes += ROTEADOR_RICOCHETES + ((RogueUp(j, UP_ARMA_ROTEADOR) > 0) ? 2 : 0);    // Tabela de Rotas
            p->vida = ROTEADOR_VIDA;
        }
        RogueDisparosExtras(b, arma, mira, a->dano * fator, 0);
        TocarSomTom(sfxTiro, (arma == ARMA_FLUXO) ? 1.4f : ((arma == ARMA_ORBE) ? 0.6f : 1.0f));
    }

    if (arma == ARMA_FLUXO) {
        j->calor += FLUXO_CALOR_TIRO * ((RogueUp(j, UP_ARMA_FLUXO) > 0) ? 0.6f : 1.0f);    // Resfriamento Líquido
        if (j->calor >= 1.0f) {
            j->calor = 1.0f;
            j->superaquecida = true;
            RogueAviso(b, "FLUXO CONTÍNUO SUPERAQUECIDO!");
            TocarSomTom(sfxErro, 1.2f);
        }
    }

    RogueParticulas(b, cano, a->cor, 2, 60);
    j->cronoTiro = RogueIntervaloArma(j, arma);
    RogueContarDisparo(j);
}

// Fim do alcance ou do tempo de vida: o Orbe explode, os outros somem
static void RogueFimProjetil(Biblioteca *b, ProgressoCorredor *prog, Projetil *p)
{
    p->ativo = false;

    if (p->doJogador && p->arma == ARMA_ORBE && !p->secundario)
        RogueExplodirOrbe(b, prog, p->pos);
    else
        RogueParticulas(b, p->pos, p->doJogador ? DEF_ARMAS[p->arma].cor : ORANGE, 2, 60);
}

// Um projétil do jogador acertou o inimigo k: dano, efeitos e o que acontece com o projétil
static void RogueAcertarInimigo(Biblioteca *b, ProgressoCorredor *prog, Projetil *p, int k)
{
    Inimigo *e = &b->ini[k];
    bool selado = e->selado;
    bool principal = (p->alvoDedutivo == 0 && !p->secundario);
    Vector2 dir = Vector2Normalize(p->vel);
    float dano = p->dano;

    if (principal && !selado)
        dano *= RogueAnalisar(b, k + 1);

    // Alta Confiança: acerto crítico
    bool critico = false;
    if (principal && !selado && RogueUp(&b->j, UP_CRITICO) > 0 && GetRandomValue(1, 100) <= UP_CRITICO_CHANCE * RogueUp(&b->j, UP_CRITICO)) {
        critico = true;
        dano *= 2.0f;
        RogueParticulas(b, p->pos, GOLD, 8, 180);
    }

    b->golpeSecundario = !principal;
    RogueFerirInimigo(b, prog, e, dano, dir);
    b->golpeSecundario = false;

    // Reformulação: efeitos da build no acerto (só o disparo principal: sem reação em cadeia)
    if (principal && !selado) {
        JogadorRogue *j = &b->j;

        if (e->ativo && RogueUp(j, UP_ROTULAR) > 0)
            e->rotulo = UP_ROTULO_TEMPO;                        // Rotulagem de Dados

        if (RogueUp(j, UP_EXPLOSAO) > 0 && j->recargaExplosao <= 0.0f) {       // Saída Generativa
            float raio = UP_EXPLOSAO_RAIO + 14.0f * (float)(RogueUp(j, UP_EXPLOSAO) - 1);
            j->recargaExplosao = UP_EXPLOSAO_RECARGA;
            b->golpeSecundario = true;
            RogueDanoArea(b, prog, p->pos, raio, p->dano * UP_EXPLOSAO_DANO, 60.0f);
            b->golpeSecundario = false;
            RogueAnel(b, p->pos, raio, (Color){ 255, 161, 0, 255 });
        }

        if (RogueUp(j, UP_RASTRO) > 0 && j->recargaRastro <= 0.0f) {           // Resíduo de Dados
            j->recargaRastro = UP_RASTRO_RECARGA;
            RogueCriarArea(b, p->pos, UP_RASTRO_RAIO, 0.0f, 1.5f, UP_RASTRO_DPS * RogueFatorDano(b), 0.0f, (Color){ 0, 228, 48, 255 });
        }

        if (critico && RogueUp(j, UP_SIN_CONFIANCA) > 0) {                     // Confiança Calibrada
            int outro = RogueInimigoMaisPerto(b, p->pos, 260.0f, k);
            if (outro >= 0) {
                Vector2 d = Vector2Normalize(Vector2Subtract(b->ini[outro].pos, p->pos));
                Projetil *q = RogueDisparar(b, p->pos, d, 520.0f, p->dano * 0.5f, 4.0f, true);
                if (q != NULL) { q->secundario = true; q->ultimoAlvo = k + 1; q->arma = ARMA_DISPARADOR; q->alcance = 300.0f; }
            }
        }
    }

    if (e->ativo && !selado && p->arma == ARMA_FRAGMENTADORA)
        e->empurrao = Vector2Add(e->empurrao, Vector2Scale(dir, 140.0f * (FRAGMENTADORA_EMPURRAO - 1.0f) * DEF_INIMIGOS[e->tipo].empurrao));

    if (e->ativo && !selado && principal)
        RogueMarcarDedutivo(b, &e->marca, &e->tempoMarca, k + 1, e->pos);

    // Fragmentação de Pacotes: o próximo acerto depois de 6 disparos se divide
    if (principal && !selado && b->j.fragmentacaoArmada) {
        b->j.fragmentacaoArmada = false;
        RogueFragmentar(b, p->pos, p->dano * FRAGMENTACAO_DANO, k);
    }

    p->ultimoAlvo = k + 1;

    if (p->arma == ARMA_ORBE && !p->secundario) {
        p->ativo = false;
        RogueExplodirOrbe(b, prog, p->pos);
    }
    else if (p->perfura > 0 && !selado) {
        p->perfura--;                                   // Vetor: segue em frente
        RogueParticulas(b, p->pos, WHITE, 6, 160);
    }
    else if (p->ricochetes > 0) {
        int proximo = RogueInimigoMaisPerto(b, p->pos, ROTEADOR_RICOCHETE_RAIO, k);
        if (proximo >= 0) {
            // Tempestade de Pacotes: sem perda; Tabela de Rotas (Roteador): perde menos
            float perda = ROTEADOR_PERDA;
            if (RogueUp(&b->j, UP_SIN_TEMPESTADE) > 0)                                   perda = 1.0f;
            else if (p->arma == ARMA_ROTEADOR && RogueUp(&b->j, UP_ARMA_ROTEADOR) > 0)   perda = 0.85f;

            float vel = (p->arma == ARMA_ROTEADOR) ? DEF_ARMAS[ARMA_ROTEADOR].velocidade : fmaxf(300.0f, Vector2Length(p->vel));
            p->ricochetes--;
            p->dano *= perda;
            p->vel = Vector2Scale(Vector2Normalize(Vector2Subtract(b->ini[proximo].pos, p->pos)), vel);
            if (p->arma == ARMA_ROTEADOR) {
                p->vida = ROTEADOR_VIDA;
                p->alcance = DEF_ARMAS[ARMA_ROTEADOR].alcance;
            } else if (p->alcance > 0.0f) {
                p->alcance = fmaxf(p->alcance, ROTEADOR_RICOCHETE_RAIO + 40.0f);
            }
            RogueParticulas(b, p->pos, DEF_ARMAS[p->arma].cor, 6, 120);
        } else {
            p->ativo = false;
        }
    }
    else {
        p->ativo = false;
    }
}

// ----- Itens temporários -----

static void RogueLimpezaCache(Biblioteca *b)
{
    JogadorRogue *j = &b->j;

    // Some com as balas inimigas (até as dos chefes) ...
    for (int i = 0; i < MAX_PROJETEIS; i++) {
        Projetil *p = &b->proj[i];
        if (p->ativo && !p->doJogador) {
            p->ativo = false;
            RogueParticulas(b, p->pos, SKYBLUE, 2, 60);
        }
    }

    // ... e atordoa os inimigos comuns por perto (os chefes seguem o padrão deles)
    for (int k = 0; k < MAX_INIMIGOS; k++) {
        Inimigo *e = &b->ini[k];
        if (!e->ativo || Vector2Distance(e->pos, j->pos) > LIMPEZA_RAIO)
            continue;
        RogueInterromperInimigo(e);
        if (e->atordoado < LIMPEZA_ATORDOA) e->atordoado = LIMPEZA_ATORDOA;
    }

    RogueAnel(b, j->pos, LIMPEZA_RAIO, SKYBLUE);
}

static void RogueAtivarTemporario(Biblioteca *b, TipoItem it)
{
    JogadorRogue *j = &b->j;

    switch (it) {
        // Pegar de novo só renova o tempo (o bônus não se soma)
        case ITEM_OVERCLOCK:         j->efeito[EFEITO_OVERCLOCK] = EFEITO_OVERCLOCK_DURACAO; break;
        case ITEM_FIREWALL_PORTATIL: j->efeito[EFEITO_ESCUDO] = ESCUDO_PORTATIL_DURACAO;   break;
        case ITEM_CAMPO_LATENCIA:    j->efeito[EFEITO_LATENCIA] = LATENCIA_DURACAO;         break;
        case ITEM_LIMPEZA_CACHE:     RogueLimpezaCache(b);                                  break;

        case ITEM_PROXY: {
            Vector2 lado = { -j->mira.y, j->mira.x };
            j->proxyPos = Vector2Add(j->pos, Vector2Scale(lado, 50.0f));
            RogueEmpurrarParaFora(&j->proxyPos, RAIO_CORPO_JOGADOR, b->obst, b->numObst);
            j->proxyHp = PROXY_HP;
            j->efeito[EFEITO_PROXY] = PROXY_DURACAO;
        } break;

        case ITEM_PACOTE_INTEGRIDADE:
            j->hp = fminf(RogueHpMax(b), j->hp + RogueHpMax(b) * PACOTE_INTEGRIDADE_CURA);
            RogueParticulas(b, j->pos, LIME, 20, 160);
            break;

        default:
            break;
    }

    RogueAviso(b, ITENS[it].nome);
    Telemetria("rogue_temporario", ITENS[it].nome, 0.0f, 0);
}

// Uma sala vencida (combate ou Silogista): conta para o Cache Persistente
static void RogueSalaConcluida(Biblioteca *b)
{
    JogadorRogue *j = &b->j;

    j->salasConcluidas++;

    if (RogueQtd(j, ITEM_CACHE_PERSISTENTE) > 0 && j->salasConcluidas % CACHE_PERSISTENTE_SALAS == 0) {
        j->hp = fminf(RogueHpMax(b), j->hp + RogueHpMax(b) * CACHE_PERSISTENTE_CURA);
        RogueParticulas(b, j->pos, LIME, 16, 140);
        RogueAviso(b, "CACHE PERSISTENTE: integridade recuperada");
    }
}

// Tempos dos efeitos, marcas do Analisador e os anéis
static void RogueAtualizarEfeitos(Biblioteca *b, float dt)
{
    JogadorRogue *j = &b->j;

    for (int i = 0; i < NUM_EFEITOS; i++)
        if (j->efeito[i] > 0.0f) j->efeito[i] -= dt;

    if (j->efeito[EFEITO_PROXY] > 0.0f && j->proxyHp <= 0.0f) {
        j->efeito[EFEITO_PROXY] = 0.0f;
        RogueParticulas(b, j->proxyPos, SKYBLUE, 16, 160);
    }

    if (j->recargaBotnet > 0.0f) j->recargaBotnet -= dt;

    // Reformulação: tempos da build
    if (j->bonusPosEsquiva > 0.0f)  j->bonusPosEsquiva -= dt;
    if (j->recargaEsquiva2 > 0.0f)  j->recargaEsquiva2 -= dt;
    if (j->recargaExplosao > 0.0f)  j->recargaExplosao -= dt;
    if (j->recargaRastro > 0.0f)    j->recargaRastro -= dt;

    // Analisador: as marcas somem com o tempo ou se o alvo sumiu
    if (j->alvoAnalise != 0) {
        j->tempoAnalise -= dt;
        bool sumiu = (j->alvoAnalise > 0) ? !b->ini[j->alvoAnalise - 1].ativo : !(b->chefe.ativo || b->silogista.ativo);
        if (j->tempoAnalise <= 0.0f || sumiu) { j->alvoAnalise = 0; j->marcasAnalise = 0; }
    }

    for (int i = 0; i < MAX_ANEIS; i++)
        if (b->aneis[i].tempo > 0.0f) b->aneis[i].tempo -= dt;
}

// Inimigos que perseguem o jogador (e por isso caem na Proxy-Isca)
static bool RoguePerseguidor(TipoInimigo t)
{
    return t == INIMIGO_FRAGMENTO || t == INIMIGO_SPAMMER || t == INIMIGO_SPAM || t == INIMIGO_OVERCLOCK ||
           t == INIMIGO_CACHE || t == INIMIGO_PHISHER || t == INIMIGO_ISCA;
}

// ---------- ALUCINADOR ----------

static void RogueIniciarChefe(Biblioteca *b)
{
    ChefeRogue *c = &b->chefe;

    *c = (ChefeRogue){0};
    c->ativo = true;
    c->fase = 1;
    c->hp = CHEFE_HP;
    c->pos = (Vector2){ 400, 170 };
    c->destino = c->pos;
    c->padrao = PADRAO_REPOSICIONAR;
    c->tempoPadrao = 1.2f;
    c->proximoPadrao = PADRAO_LEQUE;
    c->afirmacaoAtual = -1;
    c->tempoAfirm = 1.5f;

    // Ordem das afirmações: sorteada a cada luta
    for (int i = 0; i < NUM_AFIRMACOES_ALUCINADOR; i++)
        c->ordemAfirm[i] = i;

    for (int i = NUM_AFIRMACOES_ALUCINADOR - 1; i > 0; i--) {
        int k = GetRandomValue(0, i);
        int t = c->ordemAfirm[i]; c->ordemAfirm[i] = c->ordemAfirm[k]; c->ordemAfirm[k] = t;
    }
}

// Depois de cada ataque ele troca de lugar (na fase 2, mais embaixo, longe da faixa das afirmações)
static void RogueChefeReposicionar(ChefeRogue *c)
{
    c->padrao = PADRAO_REPOSICIONAR;
    c->tempoPadrao = 1.0f;
    c->destino = (Vector2){ (float)GetRandomValue(140, 660),
                            (float)((c->fase == 1) ? GetRandomValue(120, 260) : GetRandomValue(240, 320)) };
}

static void RogueChefeComecarPadrao(Biblioteca *b)
{
    ChefeRogue *c = &b->chefe;
    float ritmo = (c->fase == 2) ? 0.7f : 1.0f;     // na fase 2 ele ataca mais devagar (o jogador também responde)

    c->padrao = (PadraoChefe)c->proximoPadrao;
    c->cronoTiro = 0.3f;

    // Revezamento: fase 1 = leque, espiral, investida, ecos; fase 2 = leque, espiral, ecos
    switch (c->padrao) {
        case PADRAO_LEQUE:     c->proximoPadrao = PADRAO_ESPIRAL; break;
        case PADRAO_ESPIRAL:   c->proximoPadrao = (c->fase == 1) ? PADRAO_INVESTIDA : PADRAO_ECOS; break;
        case PADRAO_INVESTIDA: c->proximoPadrao = PADRAO_ECOS; break;
        default:               c->proximoPadrao = PADRAO_LEQUE; break;
    }

    if (c->padrao == PADRAO_LEQUE) {
        c->rajadas = 3;
        c->tempoPadrao = 2.4f / ritmo;
    }
    else if (c->padrao == PADRAO_ESPIRAL) {
        c->tempoPadrao = 3.0f;
        c->cronoTiro = 0.0f;
    }
    else if (c->padrao == PADRAO_INVESTIDA) {
        c->etapaInvestida = 0;
        c->tempoPadrao = 0.8f;                       // a linha vermelha avisa para onde ele vai
    }
    else {
        c->tempoPadrao = 1.2f;
        for (int k = 0; k < 2; k++) {
            Inimigo *e = RogueCriarInimigo(b, INIMIGO_FRAGMENTO, (Vector2){ (k == 0) ? 120.0f : 680.0f, 300.0f });
            if (e != NULL) e->recarga = 1.0f;
        }
        TocarSomTom(sfxErro, 1.6f);
    }
}

// Errou (ou o tempo acabou): anel de balas e mais Fragmentos
static void RogueAtaqueEspecialChefe(Biblioteca *b)
{
    ChefeRogue *c = &b->chefe;

    for (int k = 0; k < 18; k++) {
        float ang = (2.0f * PI / 18.0f) * k + c->anim;
        RogueDisparar(b, c->pos, (Vector2){ cosf(ang), sinf(ang) }, 190.0f, CHEFE_TIRO_DANO, 6.0f, false);
    }

    for (int k = 0; k < 2; k++)
        RogueCriarInimigo(b, INIMIGO_FRAGMENTO, (Vector2){ c->pos.x + ((k == 0) ? -90.0f : 90.0f), c->pos.y });

    RogueParticulas(b, c->pos, MAGENTA, 30, 260);
    TocarSomTom(sfxErro, 0.7f);
}

static void RogueNovaAfirmacao(ChefeRogue *c)
{
    c->afirmacaoAtual = c->ordemAfirm[c->proximaAfirm % NUM_AFIRMACOES_ALUCINADOR];
    c->proximaAfirm++;
    c->tempoAfirm = TEMPO_AFIRMACAO;
    c->mostrandoResultado = false;
    c->usouManualAfirm = false;
    c->dicaAfirm[0] = '\0';
    c->dicaAfirmLuci = false;
    c->luciMentiuAfirm = false;
    c->opcaoDicaAfirm = -1;
    c->verificouAfirm = false;
}

// C = CONFIÁVEL, F = PROBLEMÁTICA. Acertou: escudo aberto. Errou: ataque especial.
static void RogueResponderAfirmacao(Biblioteca *b, ProgressoCorredor *prog, bool disseConfiavel, bool tempoEsgotado)
{
    ChefeRogue *c = &b->chefe;
    const AfirmacaoChefe *a = &AFIRMACOES_ALUCINADOR[c->afirmacaoAtual];
    bool certo = !tempoEsgotado && (disseConfiavel == a->confiavel);

    // Manual do Conhecimento: o primeiro erro não conta
    if (!certo && !tempoEsgotado && b->j.itens[ITEM_MANUAL] > 0 && !c->usouManualAfirm) {
        b->j.itens[ITEM_MANUAL]--;
        c->usouManualAfirm = true;
        c->tempoAfirm += 3.0f;
        snprintf(c->dicaAfirm, sizeof(c->dicaAfirm), "MANUAL DO CONHECIMENTO: não foi essa. Pense de novo!");
        c->dicaAfirmLuci = false;
        TocarSom(sfxErro);
        return;
    }

    c->mostrandoResultado = true;
    c->acertouAfirm = certo;
    c->tempoAfirm = TEMPO_RESULTADO_AFIRM;
    b->desafiosRespondidos++;
    RogueRegistrarResposta(b, certo);

    // Confiar ou verificar (como nos desafios)
    if (!tempoEsgotado && c->dicaAfirmLuci && c->opcaoDicaAfirm >= 0 && !c->verificouAfirm && (disseConfiavel ? 1 : 0) == c->opcaoDicaAfirm) {
        b->perm->confiouCego++;
        RogueHabitoLuci(b, true);
        if (c->luciMentiuAfirm) { b->perm->confiouAlucinacao++; RogueMudarEstabilidade(b, -1, "você acreditou na alucinação"); }
        else if (certo)         AlterarPontos(prog, BONUS_CONFIAR_PONTOS);
    }
    if (certo && !c->dicaAfirmLuci)
        RogueMudarEstabilidade(b, 1, "resolvido sem ajuda");

    if (certo) {
        c->janela = CHEFE_JANELA;
        AlterarPontos(prog, PONTOS_AFIRMACAO);
        RogueParticulas(b, c->pos, GOLD, 30, 240);
        RogueAviso(b, "ESCUDO ABERTO! Ataque agora!");
        TocarSom(sfxAcerto);
    } else {
        AlterarPontos(prog, -PENALIDADE_ERRO);
        RogueAtaqueEspecialChefe(b);
        RogueAviso(b, tempoEsgotado ? "TEMPO ESGOTADO! Ataque especial!" : "ERRADO! Ataque especial!");
        RogueErroVerificacao(b, a->texto, a->explicacao);
    }

    Telemetria("rogue_chefe_afirmacao", certo ? "certo" : (tempoEsgotado ? "tempo" : "errado"),
               TEMPO_AFIRMACAO - c->tempoAfirm, c->afirmacaoAtual);
}

// Fase 2: as afirmações aparecem no alto da arena e o combate continua
static void RogueAtualizarAfirmacoes(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    ChefeRogue *c = &b->chefe;

    // Sem afirmação na tela: espera o escudo fechar e a pausa acabar
    if (c->afirmacaoAtual < 0) {
        if (c->janela > 0.0f) return;
        c->tempoAfirm -= dt;
        if (c->tempoAfirm <= 0.0f) RogueNovaAfirmacao(c);
        return;
    }

    c->tempoAfirm -= dt;

    if (c->mostrandoResultado) {
        if (c->tempoAfirm <= 0.0f) {
            c->afirmacaoAtual = -1;
            c->tempoAfirm = INTERVALO_AFIRMACAO;
        }
        return;
    }

    const AfirmacaoChefe *a = &AFIRMACOES_ALUCINADOR[c->afirmacaoAtual];

    if (IsKeyPressed(KEY_L) && b->j.itens[ITEM_LENTE] > 0) {
        b->j.itens[ITEM_LENTE]--;
        snprintf(c->dicaAfirm, sizeof(c->dicaAfirm), "LENTE: %s", a->dica);
        c->dicaAfirmLuci = false;
        TocarSomTom(sfxPegar, 1.3f);
    }

    // Dica da Luci: custa estabilidade e pode vir alucinada (sem motivo e com certeza absoluta)
    if (IsKeyPressed(KEY_H) && !c->dicaAfirmLuci) {
        c->dicaAfirmLuci = true;
        if (RogueEstab(b) <= 0) {
            c->opcaoDicaAfirm = -1;
            snprintf(c->dicaAfirm, sizeof(c->dicaAfirm), "Luci: Estou sobrecarregada... decida sem mim.");
        } else {
            RogueMudarEstabilidade(b, -1, NULL);
            c->luciMentiuAfirm = GetRandomValue(1, 100) <= RogueChanceLuciErrar(b);
            bool diz = c->luciMentiuAfirm ? !a->confiavel : a->confiavel;
            c->opcaoDicaAfirm = diz ? 1 : 0;
            if (c->luciMentiuAfirm)
                snprintf(c->dicaAfirm, sizeof(c->dicaAfirm), "Luci: É %s. Tenho 100%% de certeza!", diz ? "CONFIÁVEL" : "PROBLEMÁTICA");
            else
                snprintf(c->dicaAfirm, sizeof(c->dicaAfirm), "Luci: Eu diria %s. %s", diz ? "CONFIÁVEL" : "PROBLEMÁTICA", a->dica);
        }
        TocarSom(sfxSelecao);
    }

    // V: verificar a dica da Luci (Lente ou 1 Fragmento)
    if (IsKeyPressed(KEY_V) && c->dicaAfirmLuci && c->opcaoDicaAfirm >= 0 && !c->verificouAfirm) {
        bool pagou = true;
        if (b->j.itens[ITEM_LENTE] > 0)                       b->j.itens[ITEM_LENTE]--;
        else if (b->perm->fragmentos >= CUSTO_VERIFICAR_FC)   b->perm->fragmentos -= CUSTO_VERIFICAR_FC;
        else { pagou = false; RogueRecadoLuci(b, "Sem Lente nem Fragmento para verificar."); }

        if (pagou) {
            c->verificouAfirm = true;
            b->perm->verificou++;
            RogueHabitoLuci(b, false);
            if (c->luciMentiuAfirm) {
                b->perm->alucinacoesPegas++;
                snprintf(c->dicaAfirm, sizeof(c->dicaAfirm), "VERIFICADO: a dica da Luci NÃO confere!");
                RogueMudarEstabilidade(b, 1, "você pegou a alucinação");
            } else {
                snprintf(c->dicaAfirm, sizeof(c->dicaAfirm), "VERIFICADO: confere. %s", a->dica);
            }
        }
    }

    if (IsKeyPressed(KEY_C))           RogueResponderAfirmacao(b, prog, true, false);
    else if (IsKeyPressed(KEY_F))      RogueResponderAfirmacao(b, prog, false, false);
    else if (c->tempoAfirm <= 0.0f)    RogueResponderAfirmacao(b, prog, false, true);
}

static void RogueAtualizarChefe(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    ChefeRogue *c = &b->chefe;
    JogadorRogue *j = &b->j;

    if (!c->ativo || !c->apresentado)
        return;

    c->anim += dt;
    if (c->flash > 0.0f) c->flash -= dt;

    // Derrotado: se desfaz e depois vem a conversa final
    if (c->morrendo > 0.0f) {
        c->morrendo -= dt;
        RogueParticulas(b, (Vector2){ c->pos.x + GetRandomValue(-40, 40), c->pos.y + GetRandomValue(-40, 40) },
                        (GetRandomValue(0, 1) == 0) ? MAGENTA : SKYBLUE, 3, 260);
        if (c->morrendo <= 0.0f) {
            c->ativo = false;
            b->conversaPendente = &dialogoAlucinadorVitoria;
            b->objConversa = OBJ_ALUCINADOR_VITORIA;
        }
        return;
    }

    if (c->hp <= 0.0f) {
        c->hp = 0.0f;
        c->morrendo = 1.6f;
        memset(b->proj, 0, sizeof(b->proj));
        for (int i = 0; i < MAX_INIMIGOS; i++) b->ini[i].ativo = false;
        b->pausaImpacto = 0.2f;
        TocarSomTom(sfxAcerto, 0.6f);
        return;
    }

    // Metade da vida: escudo de distorção e afirmações
    if (c->fase == 1 && c->hp <= CHEFE_HP * CHEFE_FASE2) {
        c->fase = 2;
        for (int i = 0; i < MAX_PROJETEIS; i++)
            if (!b->proj[i].doJogador) b->proj[i].ativo = false;
        RogueChefeReposicionar(c);
        c->proximoPadrao = PADRAO_LEQUE;
        c->afirmacaoAtual = -1;
        c->tempoAfirm = 1.5f;
        b->conversaPendente = &dialogoAlucinadorFase2;
        b->objConversa = OBJ_NENHUM;
        Telemetria("rogue_chefe_fase2", "", (float)(GetTime() - b->inicio), 0);
        return;
    }

    if (c->janela > 0.0f) c->janela -= dt;

    Vector2 paraJogador = Vector2Subtract(j->pos, c->pos);
    float dist = Vector2Length(paraJogador);
    Vector2 dir = (dist > 0.01f) ? Vector2Scale(paraJogador, 1.0f / dist) : (Vector2){ 0, 1 };
    float ritmo = (c->fase == 2) ? 0.7f : 1.0f;

    c->tempoPadrao -= dt;
    c->cronoTiro -= dt;

    switch (c->padrao) {

        case PADRAO_REPOSICIONAR: {
            Vector2 ate = Vector2Subtract(c->destino, c->pos);
            if (Vector2Length(ate) > 4.0f)
                c->pos = Vector2Add(c->pos, Vector2Scale(Vector2Normalize(ate), CHEFE_VELOCIDADE * dt));
            if (c->tempoPadrao <= 0.0f)
                RogueChefeComecarPadrao(b);
        } break;

        case PADRAO_LEQUE:
            // 3 rajadas de 5 balas mirando o jogador
            if (c->cronoTiro <= 0.0f && c->rajadas > 0) {
                for (int k = -2; k <= 2; k++)
                    RogueDisparar(b, c->pos, Vector2Rotate(dir, k * 12.0f * DEG2RAD), CHEFE_TIRO_VEL, CHEFE_TIRO_DANO, 6.0f, false);
                c->rajadas--;
                c->cronoTiro = 0.6f / ritmo;
                TocarSomTom(sfxTiro, 0.6f);
            }
            if (c->tempoPadrao <= 0.0f) RogueChefeReposicionar(c);
            break;

        case PADRAO_ESPIRAL:
            // Dois (fase 1) ou três (fase 2) braços girando
            if (c->cronoTiro <= 0.0f) {
                int bracos = (c->fase == 1) ? 2 : 3;
                for (int k = 0; k < bracos; k++) {
                    float ang = c->anguloEspiral + k * (2.0f * PI / bracos);
                    RogueDisparar(b, c->pos, (Vector2){ cosf(ang), sinf(ang) }, CHEFE_TIRO_VEL * 0.85f, CHEFE_TIRO_DANO, 5.0f, false);
                }
                c->anguloEspiral += 0.32f;
                c->cronoTiro = 0.09f / ritmo;
            }
            if (c->tempoPadrao <= 0.0f) RogueChefeReposicionar(c);
            break;

        case PADRAO_INVESTIDA:
            if (c->etapaInvestida == 0) {
                // Mira (a linha vermelha mostra para onde ele vai)
                if (c->tempoPadrao > 0.2f) c->dirInvestida = dir;
                if (c->tempoPadrao <= 0.0f) {
                    c->etapaInvestida = 1;
                    c->tempoPadrao = 0.45f;
                    TocarSomTom(sfxDano, 0.6f);
                }
            } else {
                c->pos = Vector2Add(c->pos, Vector2Scale(c->dirInvestida, CHEFE_INVESTIDA_VEL * dt));
                if (c->tempoPadrao <= 0.0f) {
                    for (int k = 0; k < 12; k++) {
                        float ang = (2.0f * PI / 12.0f) * k;
                        RogueDisparar(b, c->pos, (Vector2){ cosf(ang), sinf(ang) }, CHEFE_TIRO_VEL * 0.8f, CHEFE_TIRO_DANO, 6.0f, false);
                    }
                    RogueChefeReposicionar(c);
                }
            }
            break;

        default:    // PADRAO_ECOS: os Fragmentos já foram chamados
            if (c->tempoPadrao <= 0.0f) RogueChefeReposicionar(c);
            break;
    }

    RogueEmpurrarParaFora(&c->pos, CHEFE_RAIO, b->obst, b->numObst);

    if (dist < CHEFE_RAIO + RAIO_CORPO_JOGADOR)
        RogueFerirJogador(b, CHEFE_DANO_CONTATO);

    if (c->fase == 2)
        RogueAtualizarAfirmacoes(b, prog, dt);
}

// ---------- O SILOGISTA ----------

static bool OperarLogica(OperadorLogico op, bool a, bool b)
{
    switch (op) {
        case OP_E:   return a && b;
        case OP_OU:  return a || b;
        case OP_NAO: return !a;
        case OP_SE:  return !a || b;
        default:     return a == b;     // OP_SSE
    }
}

static int EntradasPorta(const PortaLogica *p)
{
    return (p->op == OP_NAO) ? 1 : 2;
}

// Valor de um sinal do circuito (0 = p, 1 = q, 2+k = saída da porta k).
// Devolve false se o sinal ainda não chegou (porta não ativada).
static bool SinalCircuito(const Silogista *s, int sinal, bool *valor)
{
    if (sinal < 2) {
        *valor = s->valor[sinal];
        return true;
    }

    *valor = s->saida[sinal - 2];
    return s->ativada[sinal - 2];
}

// Resultado da expressão inteira para uns valores de p e q (as portas já estão em ordem)
static bool ResultadoCircuito(const CircuitoDef *c, const bool valor[2])
{
    bool saida[MAX_PORTAS_CIRCUITO] = { false };

    for (int k = 0; k < c->numPortas; k++) {
        const PortaLogica *p = &c->porta[k];
        bool e[2];
        for (int i = 0; i < 2; i++)
            e[i] = (p->entrada[i] < 2) ? valor[p->entrada[i]] : saida[p->entrada[i] - 2];
        saida[k] = OperarLogica(p->op, e[0], e[1]);
    }

    return saida[c->numPortas - 1];
}

// Posição de um elemento do circuito (0 = p, 1 = q, 2+k = porta k)
static Vector2 SilPosElemento(int e)
{
    const CircuitoDef *c = &CIRCUITO_SILOGISTA;
    return (e < 2) ? c->posTerminal[e] : c->porta[e - 2].pos;
}

static int SilNumElementos(void)
{
    return 2 + CIRCUITO_SILOGISTA.numPortas;
}

// Os fragmentos vão para lugares sorteados da arena (nenhum fica encaixado)
static void SilEspalharPecas(Silogista *s)
{
    int ordem[NUM_PONTOS_PECAS_SIL];

    for (int i = 0; i < NUM_PONTOS_PECAS_SIL; i++)
        ordem[i] = i;

    for (int i = NUM_PONTOS_PECAS_SIL - 1; i > 0; i--) {
        int k = GetRandomValue(0, i);
        int t = ordem[i]; ordem[i] = ordem[k]; ordem[k] = t;
    }

    for (int k = 0; k < NUM_ENCAIXES; k++) {
        s->posPeca[k] = PONTOS_PECAS_SIL[ordem[k]];
        s->encaixe[k] = -1;
    }

    s->carregando = -1;
}

static bool SilPecaNoChao(const Silogista *s, int k)
{
    if (s->carregando == k)
        return false;

    for (int e = 0; e < NUM_ENCAIXES; e++)
        if (s->encaixe[e] == k)
            return false;

    return true;
}

// Rodada 1: o núcleo aceita o resultado com os valores dados (é só calcular na ordem).
// Rodada 2: o núcleo exige o contrário, e o jogador escolhe p e q.
static void SilPrepararRodada(Silogista *s, int rodada)
{
    const CircuitoDef *c = &CIRCUITO_SILOGISTA;

    s->rodada = rodada;
    s->valor[0] = c->inicial[0];
    s->valor[1] = c->inicial[1];
    memset(s->ativada, 0, sizeof(s->ativada));
    memset(s->travado, 0, sizeof(s->travado));

    bool resultado = ResultadoCircuito(c, s->valor);
    s->exigido = (rodada == 1) ? resultado : !resultado;
}

static void RogueIniciarSilogista(Biblioteca *b)
{
    Silogista *s = &b->silogista;
    char letras[NUM_ENCAIXES] = { 'X', 'Y', 'Z' };

    *s = (Silogista){0};
    s->ativo = true;
    s->etapa = SIL_MONTAGEM;
    s->hp = SIL_HP;
    s->pos = (Vector2){ 400, 190 };
    s->proximoAtaque = 2.0f;

    // As letras são sorteadas: a ordem da lista não entrega a resposta
    for (int i = NUM_ENCAIXES - 1; i > 0; i--) {
        int k = GetRandomValue(0, i);
        char t = letras[i]; letras[i] = letras[k]; letras[k] = t;
    }

    for (int k = 0; k < NUM_ENCAIXES; k++)
        s->letraPeca[k] = letras[k];

    SilEspalharPecas(s);
}

// E perto de um fragmento no chão: pega (se já estiver com outro, troca)
static void SilPegarPeca(Biblioteca *b, int k)
{
    Silogista *s = &b->silogista;

    if (s->carregando >= 0)
        s->posPeca[s->carregando] = b->j.pos;

    s->carregando = k;
    TocarSomTom(sfxPegar, 1.1f);
}

// E perto de um mecanismo: encaixa o que está na mão e pega o que estava lá (se houver)
static void SilUsarEncaixe(Biblioteca *b, int e)
{
    Silogista *s = &b->silogista;
    int naMao = s->carregando;

    s->carregando = s->encaixe[e];
    s->encaixe[e] = naMao;

    if (naMao >= 0) {
        RogueParticulas(b, POS_ENCAIXES[e], (Color){ 0, 228, 255, 255 }, 10, 120);
        TocarSomTom(sfxSelecao, 1.2f);
    } else {
        TocarSomTom(sfxPegar, 1.1f);
    }
}

// ----- Ataques (todos com aviso) -----

static AtaqueSil *SilNovoAtaque(Silogista *s, TipoAtaqueSil tipo, float aviso)
{
    for (int i = 0; i < MAX_ATAQUES_SIL; i++) {

        if (s->atq[i].ativo)
            continue;

        s->atq[i] = (AtaqueSil){0};
        s->atq[i].ativo = true;
        s->atq[i].tipo = tipo;
        s->atq[i].aviso = aviso;
        return &s->atq[i];
    }

    return NULL;
}

// Linhas: quantas balas cabem e onde nasce a bala i
static int SilBalasLinha(const AtaqueSil *a)
{
    float comprimento = (a->dir.y != 0.0f) ? ARENA_ROGUE.width : ARENA_ROGUE.height;
    return (int)(comprimento / SIL_LINHA_ESPACO);
}

static Vector2 SilPontoLinha(const AtaqueSil *a, int i)
{
    float t = ((float)i + 0.5f) * SIL_LINHA_ESPACO;

    if (a->dir.y != 0.0f)                       // linha deitada, descendo do alto
        return (Vector2){ ARENA_ROGUE.x + t, ARENA_ROGUE.y + 8.0f };

    float x = (a->dir.x > 0.0f) ? ARENA_ROGUE.x + 8.0f : ARENA_ROGUE.x + ARENA_ROGUE.width - 8.0f;
    return (Vector2){ x, ARENA_ROGUE.y + t };
}

// Errou um puzzle: anel de balas (com aviso)
static void SilAtaqueAnel(Silogista *s)
{
    SilNovoAtaque(s, ATQ_ANEL, 0.7f);
}

static void SilComecarAtaque(Biblioteca *b)
{
    static const TipoAtaqueSil MONTAGEM[] = { ATQ_LINHAS, ATQ_ZONA, ATQ_REFUTACAO };
    static const TipoAtaqueSil SOFISMA[]  = { ATQ_LINHAS, ATQ_REFUTACAO, ATQ_ZONA };
    static const TipoAtaqueSil CIRCUITO[] = { ATQ_ZONA, ATQ_LINHAS, ATQ_CORTE };
    static const TipoAtaqueSil FINAL[]    = { ATQ_LINHAS, ATQ_REFUTACAO, ATQ_ZONA, ATQ_ANEL };

    Silogista *s = &b->silogista;
    Vector2 jp = b->j.pos;
    int r = s->revezamento++;
    TipoAtaqueSil tipo;

    switch (s->etapa) {
        // Carregando um fragmento, ele tenta derrubar o portador (um ataque sim, outro não)
        case SIL_MONTAGEM: tipo = (s->carregando >= 0 && r % 2 == 0) ? ATQ_REFUTACAO : MONTAGEM[r % 3]; break;
        case SIL_SOFISMA:  tipo = SOFISMA[r % 3];  break;
        case SIL_CIRCUITO: tipo = CIRCUITO[r % 3]; break;
        default:           tipo = FINAL[r % 4];    break;
    }

    // Corte: trava um terminal ou porta que ainda não foi resolvida (se não houver, vira zona)
    int candidatos[MAX_ELEMENTOS_CIRCUITO], n = 0;

    if (tipo == ATQ_CORTE) {
        for (int e = 0; e < SilNumElementos(); e++) {
            bool resolvido = (e < 2) ? (s->rodada == 1) : s->ativada[e - 2];
            if (!resolvido && s->travado[e] <= 0.0f)
                candidatos[n++] = e;
        }
        if (n == 0)
            tipo = ATQ_ZONA;
    }

    AtaqueSil *a = SilNovoAtaque(s, tipo, SIL_AVISO);

    if (a == NULL)
        return;

    switch (tipo) {

        case ATQ_LINHAS: {
            // De cima, da esquerda ou da direita, com a brecha perto do jogador (dá para alcançar)
            int lado = GetRandomValue(0, 2);
            a->dir = (lado == 0) ? (Vector2){ 0, 1 } : ((lado == 1) ? (Vector2){ 1, 0 } : (Vector2){ -1, 0 });

            float ref = (a->dir.y != 0.0f) ? jp.x - ARENA_ROGUE.x : jp.y - ARENA_ROGUE.y;
            int balas = SilBalasLinha(a);
            int meio = (int)(ref / SIL_LINHA_ESPACO) + GetRandomValue(-4, 4);
            a->brecha = (int)Clamp((float)(meio - SIL_LINHA_BRECHA / 2), 0.0f, (float)(balas - SIL_LINHA_BRECHA));
        } break;

        case ATQ_ZONA: {
            // Zona de bloqueio em volta do mecanismo (ou elemento do circuito) mais perto do jogador
            a->pos = jp;
            a->duracao = SIL_ZONA_DURACAO;

            float menor = 200.0f;
            if (s->etapa == SIL_MONTAGEM || s->etapa == SIL_SOFISMA) {
                for (int e = 0; e < NUM_ENCAIXES; e++)
                    if (Vector2Distance(jp, POS_ENCAIXES[e]) < menor) { menor = Vector2Distance(jp, POS_ENCAIXES[e]); a->pos = POS_ENCAIXES[e]; }
            } else if (s->etapa == SIL_CIRCUITO) {
                for (int e = 0; e < SilNumElementos(); e++)
                    if (Vector2Distance(jp, SilPosElemento(e)) < menor) { menor = Vector2Distance(jp, SilPosElemento(e)); a->pos = SilPosElemento(e); }
            }
        } break;

        case ATQ_REFUTACAO:
            a->dir = Vector2Normalize(Vector2Subtract(jp, s->pos));
            a->tiros = 6;
            break;

        case ATQ_CORTE:
            a->alvo = candidatos[GetRandomValue(0, n - 1)];
            a->aviso = 0.8f;
            break;

        default:
            break;
    }
}

static void SilAtualizarAtaques(Biblioteca *b, float dt)
{
    Silogista *s = &b->silogista;
    Vector2 jp = b->j.pos;

    for (int i = 0; i < MAX_ATAQUES_SIL; i++) {

        AtaqueSil *a = &s->atq[i];

        if (!a->ativo)
            continue;

        // Aviso: a refutação segue o jogador até pouco antes de disparar
        if (a->aviso > 0.0f) {

            a->aviso -= dt;

            if (a->tipo == ATQ_REFUTACAO && a->aviso > 0.25f)
                a->dir = Vector2Normalize(Vector2Subtract(jp, s->pos));

            if (a->aviso > 0.0f)
                continue;

            switch (a->tipo) {

                case ATQ_LINHAS:
                    for (int k = 0; k < SilBalasLinha(a); k++)
                        if (k < a->brecha || k >= a->brecha + SIL_LINHA_BRECHA)
                            RogueDisparar(b, SilPontoLinha(a, k), a->dir, SIL_TIRO_VEL, SIL_TIRO_DANO, 6.0f, false);
                    a->ativo = false;
                    TocarSomTom(sfxTiro, 0.5f);
                    break;

                case ATQ_ZONA:
                    TocarSomTom(sfxErro, 1.8f);
                    break;

                case ATQ_CORTE:
                    s->travado[a->alvo] = SIL_CORTE_DURACAO;
                    RogueParticulas(b, SilPosElemento(a->alvo), PURPLE, 14, 160);
                    TocarSomTom(sfxErro, 1.3f);
                    a->ativo = false;
                    break;

                case ATQ_ANEL:
                    for (int k = 0; k < 16; k++) {
                        float ang = (2.0f * PI / 16.0f) * k + s->anim;
                        RogueDisparar(b, s->pos, (Vector2){ cosf(ang), sinf(ang) }, SIL_TIRO_VEL, SIL_TIRO_DANO, 6.0f, false);
                    }
                    RogueParticulas(b, s->pos, PURPLE, 24, 240);
                    TocarSomTom(sfxErro, 0.7f);
                    a->ativo = false;
                    break;

                default:    // ATQ_REFUTACAO: a rajada começa
                    a->cronoTiro = 0.0f;
                    break;
            }
            continue;
        }

        if (a->tipo == ATQ_ZONA) {
            a->duracao -= dt;
            if (Vector2Distance(jp, a->pos) < SIL_ZONA_RAIO + RAIO_CORPO_JOGADOR * 0.5f)
                RogueFerirJogador(b, SIL_TIRO_DANO);
            if (a->duracao <= 0.0f)
                a->ativo = false;
        }
        else if (a->tipo == ATQ_REFUTACAO) {
            a->cronoTiro -= dt;
            if (a->cronoTiro <= 0.0f && a->tiros > 0) {
                Vector2 cano = Vector2Add(s->pos, Vector2Scale(a->dir, SIL_RAIO));
                RogueDisparar(b, cano, a->dir, 360.0f, SIL_TIRO_DANO, 5.0f, false);
                a->tiros--;
                a->cronoTiro = 0.07f;
                TocarSomTom(sfxTiro, 0.8f);
            }
            if (a->tiros <= 0)
                a->ativo = false;
        }
    }
}

// Entre um puzzle e outro: limpa as balas e os ataques e abre a explicação
static void SilPausaParaExplicar(Biblioteca *b, const Dialogo *dialogo)
{
    Silogista *s = &b->silogista;

    memset(s->atq, 0, sizeof(s->atq));
    for (int i = 0; i < MAX_PROJETEIS; i++)
        if (!b->proj[i].doJogador) b->proj[i].ativo = false;

    s->proximoAtaque = 2.5f;
    b->conversaPendente = dialogo;
    b->objConversa = OBJ_SILOGISTA_ETAPA;
    b->pausaImpacto = 0.15f;
}

// Um puzzle resolvido: cai uma camada da armadura lógica
static void SilConcluirEtapa(Biblioteca *b, ProgressoCorredor *prog, EtapaSilogista etapa, const Dialogo *dialogo)
{
    Silogista *s = &b->silogista;

    Telemetria("rogue_silogista", TextFormat("etapa %d", (int)s->etapa + 1), (float)(GetTime() - b->inicio), b->perm->tentativas);
    RogueRegistrarResposta(b, true);

    s->etapa = etapa;
    s->carregando = -1;

    if (etapa == SIL_SOFISMA) {
        for (int k = 0; k < NUM_ENCAIXES; k++)
            s->hpPeca[k] = SIL_HP_PECA;
        s->blindagem = 0.0f;
    }
    else if (etapa == SIL_CIRCUITO) {
        SilPrepararRodada(s, 1);
    }

    AlterarPontos(prog, PONTOS_ETAPA_SILOGISTA);
    RogueParticulas(b, s->pos, (Color){ 0, 228, 255, 255 }, 30, 240);
    TocarSom(sfxAcerto);
    MostrarEmocaoLuci(EMOCAO_ALEGRE, 2.0f);
    SilPausaParaExplicar(b, dialogo);
}

// Errou um puzzle: ataque especial e explicação da Luci
static void SilErrou(Biblioteca *b, ProgressoCorredor *prog, const char *aviso, const char *fala, const char *detalhe)
{
    Silogista *s = &b->silogista;

    s->erro = 1.2f;
    SilAtaqueAnel(s);
    AlterarPontos(prog, -PENALIDADE_ERRO);
    RogueRegistrarResposta(b, false);
    RogueAviso(b, aviso);
    b->falaPendente = fala;
    TocarSom(sfxErro);
    MostrarEmocaoLuci(EMOCAO_DUVIDA, 2.0f);
    Telemetria("rogue_silogista_erro", detalhe, (float)(GetTime() - b->inicio), (int)s->etapa + 1);
}

// Montagem: com os três mecanismos cheios, o argumento é conferido
static void SilConferirMontagem(Biblioteca *b, ProgressoCorredor *prog)
{
    Silogista *s = &b->silogista;

    for (int e = 0; e < NUM_ENCAIXES; e++)
        if (s->encaixe[e] < 0)
            return;

    bool certo = true;
    for (int e = 0; e < NUM_ENCAIXES; e++)
        if (s->encaixe[e] != e)
            certo = false;

    if (certo) {
        SilConcluirEtapa(b, prog, SIL_SOFISMA, &dialogoSilogistaSofisma);
        return;
    }

    // A conclusão errada ou as premissas trocadas: os fragmentos se espalham de novo
    const char *fala = (s->encaixe[ENCAIXE_C] != ENCAIXE_C) ? FALA_MONTAGEM_CONCLUSAO : FALA_MONTAGEM_PREMISSAS;

    for (int e = 0; e < NUM_ENCAIXES; e++)
        RogueParticulas(b, POS_ENCAIXES[e], RED, 10, 160);

    SilEspalharPecas(s);
    SilErrou(b, prog, "MONTAGEM INVÁLIDA! Os fragmentos se espalham.", fala,
             (s->encaixe[ENCAIXE_C] != ENCAIXE_C) ? "montagem_conclusao" : "montagem_premissas");
}

// Sofisma: um tiro numa das peças do argumento corrompido
static void SilAcertarPecaSofisma(Biblioteca *b, ProgressoCorredor *prog, int k, float dano)
{
    Silogista *s = &b->silogista;

    if (s->blindagem > 0.0f) {
        RogueParticulas(b, POS_ENCAIXES[k], (Color){ 0, 228, 255, 255 }, 3, 90);
        return;
    }

    s->hpPeca[k] -= dano;
    s->tremePeca[k] = 0.15f;
    RogueParticulas(b, POS_ENCAIXES[k], MAGENTA, 4, 120);

    if (s->hpPeca[k] > 0.0f)
        return;

    RogueParticulas(b, POS_ENCAIXES[k], MAGENTA, 30, 240);

    if (k == SOFISMA_SILOGISTA.invalida) {
        SilConcluirEtapa(b, prog, SIL_CIRCUITO, &dialogoSilogistaCircuito);
        return;
    }

    // Destruiu uma premissa: a defesa se recupera (peças inteiras e blindadas por um tempo)
    for (int i = 0; i < NUM_ENCAIXES; i++)
        s->hpPeca[i] = SIL_HP_PECA;
    s->blindagem = SIL_BLINDAGEM;

    SilErrou(b, prog, "A DEFESA DO SILOGISTA SE RECUPEROU!", FALA_SOFISMA_ERRO, "sofisma");
}

// A última porta ligou o núcleo: confere a saída
static void SilNucleo(Biblioteca *b, ProgressoCorredor *prog)
{
    Silogista *s = &b->silogista;
    const CircuitoDef *c = &CIRCUITO_SILOGISTA;

    if (s->saida[c->numPortas - 1] != s->exigido) {
        memset(s->ativada, 0, sizeof(s->ativada));      // o circuito reinicia
        SilErrou(b, prog, "SAÍDA ERRADA! O circuito reinicia.", c->dicaErro, "circuito");
        return;
    }

    s->nucleo = 1.0f;
    RogueParticulas(b, c->posNucleo, (Color){ 0, 228, 255, 255 }, 30, 220);

    if (s->rodada == 1) {
        // A rodada 2 começa quando a explicação terminar (RogueFimConversa)
        AlterarPontos(prog, PONTOS_ETAPA_SILOGISTA);
        TocarSom(sfxAcerto);
        SilPausaParaExplicar(b, &dialogoSilogistaRodada2);
        Telemetria("rogue_silogista", "rodada 1", (float)(GetTime() - b->inicio), b->perm->tentativas);
    } else {
        SilConcluirEtapa(b, prog, SIL_VULNERAVEL, &dialogoSilogistaVulneravel);
    }
}

// Circuito: um tiro num terminal (troca V/F) ou numa porta (ativa a operação)
static void SilAcertarElemento(Biblioteca *b, ProgressoCorredor *prog, int e)
{
    Silogista *s = &b->silogista;
    const CircuitoDef *c = &CIRCUITO_SILOGISTA;
    Vector2 pos = SilPosElemento(e);

    if (s->recarga[e] > 0.0f)
        return;

    s->recarga[e] = SIL_RECARGA_ELEMENTO;

    if (s->travado[e] > 0.0f) {
        RogueParticulas(b, pos, PURPLE, 6, 100);
        RogueAviso(b, "TRAVADO! Espere o corte do Silogista passar.");
        TocarSomTom(sfxErro, 1.5f);
        return;
    }

    if (e < 2) {
        if (s->rodada == 1) {
            RogueAviso(b, "Nesta rodada p e q estão fixos: ative as portas!");
            TocarSomTom(sfxSelecao, 0.7f);
            return;
        }

        s->valor[e] = !s->valor[e];
        memset(s->ativada, 0, sizeof(s->ativada));      // o sinal mudou: as portas apagam
        RogueParticulas(b, pos, s->valor[e] ? SKYBLUE : PURPLE, 10, 120);
        TocarSomTom(sfxSelecao, s->valor[e] ? 1.3f : 0.9f);
        return;
    }

    int k = e - 2;
    const PortaLogica *p = &c->porta[k];
    bool entrada[2] = { false, false };

    if (s->ativada[k])
        return;

    // Precedência: a porta só funciona com as entradas já calculadas
    for (int i = 0; i < EntradasPorta(p); i++) {
        if (!SinalCircuito(s, p->entrada[i], &entrada[i])) {
            s->erroElemento[e] = 0.6f;
            RogueAviso(b, "SEM SINAL! Ative antes as portas que chegam nesta.");
            TocarSomTom(sfxErro, 1.4f);
            return;
        }
    }

    s->saida[k] = OperarLogica(p->op, entrada[0], entrada[1]);
    s->ativada[k] = true;
    RogueParticulas(b, p->pos, s->saida[k] ? SKYBLUE : PURPLE, 14, 160);
    TocarSomTom(sfxAcerto, 1.4f);

    if (k == c->numPortas - 1)
        SilNucleo(b, prog);
}

// Tiro do jogador na Câmara da Inferência. Devolve true se o tiro foi usado.
// =============================================================
// O SILOGISTA - VERSÃO BULLET-HELL LÓGICO (SILOGISTA_MODO_BULLET_HELL)
//   3 rodadas, uma por camada da armadura (Modus Ponens, Afirmação do
//   Consequente, Modus Tollens). As premissas ficam na faixa do alto; o
//   Silogista lança CONCLUSÕES curtas em anéis, espirais e cercos. O jogador
//   atira (ou dá parry) na conclusão válida: ela confirma a regra e desfaz as
//   falácias da tela. Atingir uma falácia ou ser atingido por ela custa EP
//   (a estabilidade mental do Thomas) e mostra a justificativa. Sem armadura,
//   o Silogista vira um bullet-hell comum até cair.
// =============================================================

static void ExibirFeedbackPedagogico(Silogista *s, const char *texto, Color cor)
{
    snprintf(s->bh.mensagemFeedback, sizeof(s->bh.mensagemFeedback), "%s", texto);
    s->bh.corFeedback = cor;
    s->bh.tempoExibicaoFeedback = 2.5f;             // a explicação fica 2,5 s na tela
}

static void RogueIniciarSilogistaBH(Biblioteca *b)
{
    Silogista *s = &b->silogista;

    *s = (Silogista){0};
    s->ativo = true;
    s->modoBH = true;
    s->etapa = SIL_MONTAGEM;            // as 3 camadas da armadura usam as etapas (SIL_VULNERAVEL = sem armadura)
    s->hp = SIL_HP;
    s->pos = (Vector2){ 400, 170 };
    s->carregando = -1;
    s->bh.fatorTempo = 1.0f;
    s->bh.proximoPadrao = 2.0f;
}

// Fator do tempo do mundo (Focus Mode): os projéteis e inimigos andam com dt * fator
static float RogueFatorTempoMundo(const Biblioteca *b)
{
    const Silogista *s = &b->silogista;
    return (b->tipoSala == SALA_SILOGISTA && s->ativo && s->modoBH && s->bh.modoFocoAtivo) ? SIL_BH_FATOR_FOCO : 1.0f;
}

// papel: 0 = conclusão válida, 1 = falácia, 2 = premissa
static void SilBHCriarSimbolo(Biblioteca *b, Vector2 pos, Vector2 vel, int papel, float surgindo)
{
    Silogista *s = &b->silogista;
    const RodadaSilogistaBH *r = &RODADAS_SILOGISTA_BH[(s->bh.rodada < 3) ? s->bh.rodada : 2];
    ProjetilSilogista *q = NULL;

    for (int k = 0; k < MAX_PROJETEIS_SILOGISTA && q == NULL; k++)
        if (!s->bh.projeteis[k].ativo) q = &s->bh.projeteis[k];
    if (q == NULL)
        return;

    *q = (ProjetilSilogista){0};
    q->ativo = true;
    q->posicao = pos;
    q->velocidade = vel;
    q->raio = SIL_BH_RAIO_SIMBOLO;
    q->vida = 9.0f;
    q->surgindo = surgindo;

    if (papel == 0) {
        int i = GetRandomValue(0, 1);
        snprintf(q->textoSimbolo, sizeof(q->textoSimbolo), "%s", r->validos[i][0]);
        q->explicacaoPedagogica = r->validos[i][1];
        q->justificativa = r->regraAcerto;
        q->tipo = PROJETIL_LOGICO_VALIDO;
        q->ehRespostaCorreta = true;
    } else if (papel == 1) {
        int i = GetRandomValue(0, 2);
        snprintf(q->textoSimbolo, sizeof(q->textoSimbolo), "%s", r->falacias[i][0]);
        q->explicacaoPedagogica = r->falacias[i][1];
        q->justificativa = r->falacias[i][2];
        q->tipo = PROJETIL_LOGICO_FALACIA;
    } else {
        snprintf(q->textoSimbolo, sizeof(q->textoSimbolo), "%s", r->premissa[0]);
        q->explicacaoPedagogica = r->premissa[1];
        q->justificativa = "Premissa: ela foi DADA como verdadeira. O que está em jogo é a conclusão.";
        q->tipo = PROJETIL_LOGICO_PREMISSA;
    }
}

// Começa um padrão (ANEL radial, ESPIRAL ou CERCO circular em volta do jogador)
static void SilBHComecarPadrao(Biblioteca *b)
{
    Silogista *s = &b->silogista;
    JogadorRogue *j = &b->j;
    int padrao = s->bh.padrao % 3;
    s->bh.padrao++;

    if (padrao == 0) {
        // ANEL: 8 conclusões saindo do Silogista (2 válidas, uma premissa) + um anel de balas comuns
        int n = 8, v1 = GetRandomValue(0, n - 1), v2 = (v1 + n / 2) % n, pr = (v1 + 2) % n;
        for (int i = 0; i < n; i++) {
            float a = (float)i * 2.0f * PI / (float)n + s->anim * 0.5f;
            Vector2 d = { cosf(a), sinf(a) };
            SilBHCriarSimbolo(b, Vector2Add(s->pos, Vector2Scale(d, 40.0f)), Vector2Scale(d, 85.0f),
                              (i == v1 || i == v2) ? 0 : ((i == pr) ? 2 : 1), 0.0f);
        }
        for (int i = 0; i < 12; i++) {
            float a = (float)i * 2.0f * PI / 12.0f + PI / 12.0f + s->anim * 0.5f;
            RogueDisparar(b, s->pos, (Vector2){ cosf(a), sinf(a) }, SIL_TIRO_VEL * 0.75f, SIL_TIRO_DANO, 5.0f, false);
        }
        TocarSomTom(sfxTiro, 0.6f);
    }
    else if (padrao == 1) {
        // ESPIRAL: um símbolo de cada vez, girando (ver RogueAtualizarSilogistaBH)
        s->bh.emissoesRestantes = 10;
        s->bh.cronoEmissao = 0.0f;
        s->bh.anguloEmissao = (float)GetRandomValue(0, 359) * DEG2RAD;
    }
    else {
        // CERCO: um círculo de conclusões em volta do jogador, girando e se fechando devagar
        int n = 8, v = GetRandomValue(0, n - 1);
        float giro = (GetRandomValue(0, 1) == 0) ? 1.0f : -1.0f;
        for (int i = 0; i < n; i++) {
            float a = (float)i * 2.0f * PI / (float)n;
            Vector2 d = { cosf(a), sinf(a) };
            Vector2 p = Vector2Add(j->pos, Vector2Scale(d, 230.0f));
            if (!CheckCollisionPointRec(p, (Rectangle){ ARENA_ROGUE.x + 20, ARENA_ROGUE.y + 20, ARENA_ROGUE.width - 40, ARENA_ROGUE.height - 40 }))
                continue;
            Vector2 tangente = { -d.y * giro, d.x * giro };
            SilBHCriarSimbolo(b, p, Vector2Add(Vector2Scale(d, -55.0f), Vector2Scale(tangente, 22.0f)),
                              (i == v) ? 0 : ((i == (v + 4) % n) ? 2 : 1), 0.6f);
        }
        TocarSomTom(sfxSelecao, 0.5f);
    }

    s->bh.proximoPadrao = 3.4f - 0.3f * (float)s->bh.rodada;
}

// Erro lógico: atingiu a conclusão errada ou foi atingido por ela
static void SilBHErro(Biblioteca *b, ProgressoCorredor *prog, const ProjetilSilogista *q, bool foiAtingido)
{
    Silogista *s = &b->silogista;
    JogadorRogue *j = &b->j;

    ExibirFeedbackPedagogico(s, q->justificativa, (Color){ 230, 41, 55, 255 });
    j->ep = fmaxf(0.0f, j->ep - SIL_BH_PENALIDADE_EP);          // a estabilidade mental do Thomas cai
    RogueTextoFlutuante(b, (Vector2){ q->posicao.x, q->posicao.y - 24 }, TextFormat("ERRO LÓGICO  -%d EP", (int)SIL_BH_PENALIDADE_EP), RED);
    RogueParticulas(b, q->posicao, RED, 14, 200);

    // Atirou na errada: ela se parte em balas
    if (!foiAtingido)
        for (int i = 0; i < 4; i++) {
            float a = (float)i * PI / 2.0f + PI / 4.0f;
            RogueDisparar(b, q->posicao, (Vector2){ cosf(a), sinf(a) }, SIL_TIRO_VEL * 0.8f, SIL_TIRO_DANO * 0.7f, 5.0f, false);
        }

    // Erros seguidos contam uma vez só (no índice e nos pontos)
    if (s->bh.recargaErro <= 0.0f) {
        s->bh.recargaErro = 1.5f;
        RogueRegistrarResposta(b, false);
        AlterarPontos(prog, -2);
    }

    TocarSom(sfxErro);
    MostrarEmocaoLuci(EMOCAO_DUVIDA, 1.5f);
    Telemetria("rogue_silogista_bh_erro", q->textoSimbolo, (float)s->bh.rodada + 1.0f, foiAtingido ? 1 : 0);
}

// Uma camada da armadura cai: explicação curta (pausa) e a próxima rodada
static void SilBHConcluirRodada(Biblioteca *b, ProgressoCorredor *prog)
{
    Silogista *s = &b->silogista;
    int feita = s->bh.rodada;

    s->bh.acertosRodada = 0;
    s->bh.emissoesRestantes = 0;
    s->bh.proximoPadrao = 2.0f;
    memset(s->bh.projeteis, 0, sizeof(s->bh.projeteis));
    for (int i = 0; i < MAX_PROJETEIS; i++)
        if (!b->proj[i].doJogador) b->proj[i].ativo = false;

    s->etapa = (EtapaSilogista)((int)s->etapa + 1);
    s->bh.rodada++;

    RogueRegistrarResposta(b, true);
    AlterarPontos(prog, PONTOS_ETAPA_SILOGISTA);
    RogueParticulas(b, s->pos, (Color){ 0, 228, 255, 255 }, 30, 240);
    TocarSom(sfxAcerto);
    MostrarEmocaoLuci(EMOCAO_ALEGRE, 2.0f);

    b->conversaPendente = &dialogosRodadaSilogistaBH[feita];
    b->objConversa = OBJ_NENHUM;
    b->pausaImpacto = 0.15f;
    Telemetria("rogue_silogista_bh", RODADAS_SILOGISTA_BH[feita].titulo, (float)(GetTime() - b->inicio), b->perm->tentativas);
}

// Escolheu a conclusão k (tiro ou parry)
static void SilBHEscolher(Biblioteca *b, ProgressoCorredor *prog, int k, bool rebatido)
{
    Silogista *s = &b->silogista;
    ProjetilSilogista q = s->bh.projeteis[k];

    s->bh.projeteis[k].ativo = false;

    if (!q.ehRespostaCorreta) {
        SilBHErro(b, prog, &q, false);
        return;
    }

    // Conclusão válida: o micro-feedback verde explica a regra
    s->bh.acertosRodada++;
    ExibirFeedbackPedagogico(s, q.justificativa, (Color){ 0, 228, 48, 255 });
    RogueTextoFlutuante(b, (Vector2){ q.posicao.x, q.posicao.y - 26 }, TextFormat("%s  %d/%d", q.textoSimbolo, s->bh.acertosRodada, SIL_BH_META), LIME);
    RogueParticulas(b, q.posicao, LIME, 24, 240);
    RogueAnel(b, q.posicao, 60.0f, LIME);

    // ... e desfaz as falácias e premissas que estavam na tela
    for (int i = 0; i < MAX_PROJETEIS_SILOGISTA; i++) {
        ProjetilSilogista *o = &s->bh.projeteis[i];
        if (!o->ativo || o->ehRespostaCorreta) continue;
        RogueParticulas(b, o->posicao, (Color){ 170, 140, 255, 255 }, 6, 140);
        o->ativo = false;
    }

    // Rebatida: a conclusão volta voando para o Silogista (só o efeito; a armadura segura)
    if (rebatido) {
        Vector2 d = Vector2Subtract(s->pos, q.posicao);
        d = (Vector2Length(d) > 0.1f) ? Vector2Normalize(d) : (Vector2){ 0, -1 };
        Projetil *p = RogueDisparar(b, q.posicao, d, 560.0f, 0.0f, 7.0f, true);
        if (p != NULL) { p->secundario = true; p->arma = ARMA_DISPARADOR; }
    }

    s->flash = 0.1f;
    TocarSom(sfxAcerto);
    TocarSomTom(sfxDedutivo, 1.4f);

    if (s->bh.acertosRodada >= SIL_BH_META)
        SilBHConcluirRodada(b, prog);
}

// Tiro do jogador na Câmara (bullet-hell): primeiro os símbolos, depois o corpo do Silogista
static bool RogueSilogistaAcertoBH(Biblioteca *b, ProgressoCorredor *prog, Projetil *p)
{
    Silogista *s = &b->silogista;

    if (!s->ativo || !s->apresentado || s->morrendo > 0.0f)
        return false;

    if (s->etapa != SIL_VULNERAVEL && p->dano > 0.0f)       // dano 0 = a conclusão rebatida (só o efeito)
        for (int k = 0; k < MAX_PROJETEIS_SILOGISTA; k++) {
            const ProjetilSilogista *q = &s->bh.projeteis[k];
            if (!q->ativo || q->surgindo > 0.0f || Vector2Distance(p->pos, q->posicao) > q->raio + p->raio) continue;
            p->ativo = false;
            SilBHEscolher(b, prog, k, false);
            return true;
        }

    if (Vector2Distance(p->pos, s->pos) < SIL_RAIO + p->raio) {
        p->ativo = false;
        if (RogueFerirSilogista(b, p->dano, p->pos) && p->alvoDedutivo == 0)
            RogueMarcarDedutivo(b, &s->marca, &s->tempoMarca, -1, s->pos);
        return true;
    }

    return false;
}

static void RogueAtualizarSilogistaBH(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    Silogista *s = &b->silogista;
    JogadorRogue *j = &b->j;
    EstadoSilogista *e = &s->bh;

    if (e->tempoExibicaoFeedback > 0.0f) e->tempoExibicaoFeedback -= dt;
    if (e->recargaErro > 0.0f)           e->recargaErro -= dt;

    // Flutua no alto (sem armadura, também sobe e desce)
    Vector2 alvo = { 400.0f + sinf(s->anim * 0.5f) * 200.0f,
                     (s->etapa == SIL_VULNERAVEL) ? 200.0f + sinf(s->anim * 0.9f) * 70.0f : 165.0f };
    s->pos = Vector2Lerp(s->pos, alvo, fminf(1.0f, 3.0f * dt));

    if (Vector2Distance(s->pos, j->pos) < SIL_RAIO + RAIO_CORPO_JOGADOR)
        RogueFerirJogador(b, SIL_DANO_CONTATO);

    e->proximoPadrao -= dt;

    if (s->etapa != SIL_VULNERAVEL) {
        if (e->proximoPadrao <= 0.0f && e->totalProjeteis <= MAX_PROJETEIS_SILOGISTA - 8)
            SilBHComecarPadrao(b);

        // Espiral em andamento: a 4ª e a 8ª são válidas; a 6ª é a premissa
        if (e->emissoesRestantes > 0) {
            e->cronoEmissao -= dt;
            if (e->cronoEmissao <= 0.0f) {
                int i = 10 - e->emissoesRestantes;
                Vector2 d = { cosf(e->anguloEmissao), sinf(e->anguloEmissao) };
                SilBHCriarSimbolo(b, Vector2Add(s->pos, Vector2Scale(d, 40.0f)), Vector2Scale(d, 100.0f),
                                  (i == 3 || i == 7) ? 0 : ((i == 5) ? 2 : 1), 0.0f);
                RogueDisparar(b, s->pos, Vector2Rotate(d, PI), SIL_TIRO_VEL * 0.9f, SIL_TIRO_DANO, 5.0f, false);
                e->anguloEmissao += 36.0f * DEG2RAD;
                e->cronoEmissao = 0.22f;
                e->emissoesRestantes--;
            }
        }
    } else {
        // Sem armadura: anéis e espiral de balas comuns (bullet-hell clássico)
        if (e->proximoPadrao <= 0.0f) {
            for (int i = 0; i < 16; i++) {
                float a = (float)i * 2.0f * PI / 16.0f + s->anim;
                RogueDisparar(b, s->pos, (Vector2){ cosf(a), sinf(a) }, SIL_TIRO_VEL * 0.8f, SIL_TIRO_DANO, 5.0f, false);
            }
            TocarSomTom(sfxTiro, 0.6f);
            e->proximoPadrao = 1.4f;
        }
        e->cronoEmissao -= dt;
        if (e->cronoEmissao <= 0.0f) {
            for (int k = 0; k < 2; k++) {
                float a = s->anim * 2.4f + (float)k * PI;
                RogueDisparar(b, s->pos, (Vector2){ cosf(a), sinf(a) }, SIL_TIRO_VEL, SIL_TIRO_DANO, 5.0f, false);
            }
            e->cronoEmissao = 0.16f;
        }
    }

    // Símbolos: andam, somem fora da arena, batem no jogador ou são rebatidos pelo parry
    int ativos = 0;
    for (int k = 0; k < MAX_PROJETEIS_SILOGISTA; k++) {

        ProjetilSilogista *q = &e->projeteis[k];
        if (!q->ativo) continue;

        if (q->surgindo > 0.0f) { q->surgindo -= dt; ativos++; continue; }

        q->posicao = Vector2Add(q->posicao, Vector2Scale(q->velocidade, dt));
        q->vida -= dt;
        if (q->vida <= 0.0f || !CheckCollisionPointRec(q->posicao, (Rectangle){ ARENA_ROGUE.x + 4, ARENA_ROGUE.y + 12, ARENA_ROGUE.width - 8, ARENA_ROGUE.height - 16 })) {
            q->ativo = false;
            continue;
        }
        ativos++;

        float d = Vector2Distance(q->posicao, j->pos);

        // Parry no símbolo: rebate (conta como escolher essa conclusão)
        if (j->parry.emParry && d < q->raio + RAIO_CORPO_JOGADOR + 22.0f) {
            j->parry.emParry = false;
            j->parry.cooldownParry = 0.15f;
            if (j->invulneravel < 0.3f) j->invulneravel = 0.3f;
            b->pausaImpacto = 0.06f;
            b->tremor = 0.15f;
            b->zoomImpacto = 0.25f;
            b->focoZoom = q->posicao;
            RogueAnel(b, q->posicao, 70.0f, GOLD);
            TocarSom(sfxParryPerfeito);
            RogueTextoFlutuante(b, (Vector2){ j->pos.x, j->pos.y - 44 }, "PARRY!", GOLD);
            SilBHEscolher(b, prog, k, true);
            continue;
        }

        // Encostar: a conclusão válida passa sem machucar; falácia e premissa ferem
        if (d < q->raio + RAIO_CORPO_JOGADOR - 2.0f && !q->ehRespostaCorreta && j->invulneravel <= 0.0f && j->tempoEsquiva <= 0.0f) {
            RogueFerirJogador(b, SIL_TIRO_DANO);
            SilBHErro(b, prog, q, true);
            q->ativo = false;
        }
    }
    e->totalProjeteis = ativos;
}

static bool RogueSilogistaAcerto(Biblioteca *b, ProgressoCorredor *prog, Projetil *p)
{
    Silogista *s = &b->silogista;

    if (s->modoBH)
        return RogueSilogistaAcertoBH(b, prog, p);

    if (!s->ativo || !s->apresentado || s->morrendo > 0.0f)
        return false;

    if (Vector2Distance(p->pos, s->pos) < SIL_RAIO + p->raio) {
        p->ativo = false;
        if (RogueFerirSilogista(b, p->dano, p->pos) && p->alvoDedutivo == 0)
            RogueMarcarDedutivo(b, &s->marca, &s->tempoMarca, -1, s->pos);
        return true;
    }

    if (s->etapa == SIL_SOFISMA) {
        for (int k = 0; k < NUM_ENCAIXES; k++)
            if (Vector2Distance(p->pos, POS_ENCAIXES[k]) < 28.0f + p->raio) {
                p->ativo = false;
                SilAcertarPecaSofisma(b, prog, k, p->dano);
                return true;
            }
    }
    else if (s->etapa == SIL_CIRCUITO) {
        for (int e = 0; e < SilNumElementos(); e++)
            if (Vector2Distance(p->pos, SilPosElemento(e)) < 24.0f + p->raio) {
                p->ativo = false;
                SilAcertarElemento(b, prog, e);
                return true;
            }
    }

    return false;
}

static void RogueAtualizarSilogista(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    Silogista *s = &b->silogista;

    if (!s->ativo || !s->apresentado)
        return;

    s->anim += dt;
    if (s->flash > 0.0f) s->flash -= dt;
    if (s->erro > 0.0f)  s->erro -= dt;

    // Derrotado: se desmonta e depois vem a conversa final (com a recompensa)
    if (s->morrendo > 0.0f) {
        s->morrendo -= dt;
        RogueParticulas(b, (Vector2){ s->pos.x + GetRandomValue(-40, 40), s->pos.y + GetRandomValue(-40, 40) },
                        (GetRandomValue(0, 1) == 0) ? PURPLE : (Color){ 0, 228, 255, 255 }, 3, 220);
        if (s->morrendo <= 0.0f) {
            s->ativo = false;
            b->conversaPendente = s->modoBH ? &dialogoSilogistaVitoriaBH : &dialogoSilogistaVitoria;
            b->objConversa = OBJ_SILOGISTA_VITORIA;
        }
        return;
    }

    if (s->etapa == SIL_VULNERAVEL && s->hp <= 0.0f) {
        s->hp = 0.0f;
        s->morrendo = 1.6f;
        memset(s->atq, 0, sizeof(s->atq));
        memset(s->bh.projeteis, 0, sizeof(s->bh.projeteis));
        s->bh.modoFocoAtivo = false;
        for (int i = 0; i < MAX_PROJETEIS; i++)
            if (!b->proj[i].doJogador) b->proj[i].ativo = false;
        b->pausaImpacto = 0.2f;
        TocarSomTom(sfxAcerto, 0.6f);
        return;
    }

    // Versão bullet-hell: padrões, símbolos e parry próprios (a legada segue abaixo, sem mudanças)
    if (s->modoBH) {
        RogueAtualizarSilogistaBH(b, prog, dt);
        return;
    }

    // Flutua de um lado para o outro no alto (sem a armadura, também sobe e desce)
    Vector2 alvo = { 400.0f + sinf(s->anim * 0.45f) * 210.0f,
                     (s->etapa == SIL_VULNERAVEL) ? 210.0f + sinf(s->anim * 0.9f) * 60.0f : 190.0f };
    s->pos = Vector2Lerp(s->pos, alvo, fminf(1.0f, 3.0f * dt));

    if (Vector2Distance(s->pos, b->j.pos) < SIL_RAIO + RAIO_CORPO_JOGADOR)
        RogueFerirJogador(b, SIL_DANO_CONTATO);

    s->proximoAtaque -= dt;
    if (s->proximoAtaque <= 0.0f) {
        SilComecarAtaque(b);
        s->proximoAtaque = (s->etapa == SIL_VULNERAVEL) ? SIL_INTERVALO_FINAL : SIL_INTERVALO_PUZZLE;
    }

    SilAtualizarAtaques(b, dt);

    for (int e = 0; e < MAX_ELEMENTOS_CIRCUITO; e++) {
        if (s->recarga[e] > 0.0f)      s->recarga[e] -= dt;
        if (s->travado[e] > 0.0f)      s->travado[e] -= dt;
        if (s->erroElemento[e] > 0.0f) s->erroElemento[e] -= dt;
    }

    if (s->etapa == SIL_MONTAGEM) {
        SilConferirMontagem(b, prog);
    }
    else if (s->etapa == SIL_SOFISMA) {
        if (s->blindagem > 0.0f) s->blindagem -= dt;
        for (int k = 0; k < NUM_ENCAIXES; k++) {
            if (s->tremePeca[k] > 0.0f) s->tremePeca[k] -= dt;
            s->hpPeca[k] = fminf(SIL_HP_PECA, s->hpPeca[k] + SIL_RECUPERA_PECA * dt);
        }
    }
}

// ---------- A Luci: Scanner de Ecos e contradições ----------

// Frases com que a Luci "reescreve" o objetivo, contradizendo o que dá para ver na sala
static const char *CONTRADICOES_LUCI[] = {
    "Sala limpa! Pode escolher uma porta",                   // combate com inimigos vivos
    "Cuidado: ainda há inimigos escondidos nesta sala",      // combate já vencido
    "Não precisa ler o terminal: a porta já está aberta",    // educativa sem ler
    "Pode pegar os três itens: são todos seus",              // recompensa (só dá para pegar um)
    "A armadura dele caiu: atire à vontade!",                // Silogista ainda blindado
    "O Alucinador já está quase sem vida",                   // Alucinador com a vida alta
};

// Qual contradição combina com a sala agora (-1 = nenhuma)
static int RogueContradicaoPossivel(const Biblioteca *b)
{
    switch (b->tipoSala) {
        case SALA_COMBATE:
        case SALA_ELITE:
        case SALA_ESPECIAL:   return b->limpa ? 1 : 0;
        case SALA_EDUCATIVA:  return b->terminalLido ? -1 : 2;
        case SALA_RECOMPENSA: return b->recompensaPega ? -1 : 3;
        case SALA_SILOGISTA:  return (b->silogista.ativo && b->silogista.apresentado && b->silogista.etapa != SIL_VULNERAVEL) ? 4 : -1;
        case SALA_CHEFE:      return (b->chefe.ativo && b->chefe.apresentado && b->chefe.fase == 1 && b->chefe.hp > CHEFE_HP * 0.75f) ? 5 : -1;
        default:              return -1;
    }
}

// Instável (estabilidade 3 ou menos), a Luci às vezes reescreve o objetivo com algo
// que contradiz a sala (alucinação intrínseca). Quanto menos estável, mais frequente.
static void RogueAtualizarContradicoes(Biblioteca *b, float dt)
{
    if (b->contradicao > 0.0f) {
        // A sala mudou e a frase deixou de contradizer: some sem contar
        if (RogueContradicaoPossivel(b) != b->textoContradicao) { b->contradicao = 0.0f; return; }
        b->contradicao -= dt;
        if (b->contradicao <= 0.0f) b->perm->contradicoesPerdidas++;
        return;
    }

    if (RogueEstab(b) > CONTRADICAO_ESTAB_MAX)
        return;

    b->proximaContradicao -= dt;
    if (b->proximaContradicao > 0.0f)
        return;

    float sorteio = (float)GetRandomValue(0, 100) / 100.0f;
    b->proximaContradicao = (CONTRADICAO_INTERVALO_MIN + (CONTRADICAO_INTERVALO_MAX - CONTRADICAO_INTERVALO_MIN) * sorteio) *
                            (0.5f + 0.5f * (float)RogueEstab(b) / CONTRADICAO_ESTAB_MAX);

    int frase = RogueContradicaoPossivel(b);
    if (frase < 0)
        return;

    b->textoContradicao = frase;
    b->contradicao = CONTRADICAO_DURACAO;
    Telemetria("luci_contradicao", CONTRADICOES_LUCI[frase], 0.0f, RogueEstab(b));
}

// C: contestar a Luci. Na hora certa repara; à toa custa pontos.
static void RogueContestar(Biblioteca *b, ProgressoCorredor *prog)
{
    if (b->contradicao > 0.0f) {
        b->contradicao = 0.0f;
        b->perm->contradicoesFlagradas++;
        b->perm->fragmentos += CONTRADICAO_FC;
        RogueMudarEstabilidade(b, 1, "contradição flagrada");
        RogueAviso(b, TextFormat("CONTRADIÇÃO FLAGRADA! +%d FRAGMENTOS", CONTRADICAO_FC));
        TocarSom(sfxAcerto);
        Telemetria("luci_contestar", "certo", 0.0f, RogueEstab(b));
    } else {
        b->perm->contestouAToa++;
        AlterarPontos(prog, -CONTESTAR_A_TOA_PONTOS);
        RogueRecadoLuci(b, "Luci: Mas eu não disse nada de errado...");
        TocarSom(sfxErro);
        Telemetria("luci_contestar", "a toa", 0.0f, RogueEstab(b));
    }
}

// H fora dos desafios: o Scanner de Ecos revela Phisher, cópias falsas e ecos.
// Instável, a varredura pode trocar as marcas (as marcas falsas tremem).
static void RogueScanner(Biblioteca *b)
{
    JogadorRogue *j = &b->j;

    if (b->recargaScanner > 0.0f) { RogueRecadoLuci(b, "Scanner recarregando..."); return; }
    // Conceito BOAS PRÁTICAS: no Bloco 3 o scanner não gasta energia
    bool gratis = (b->tipoSala == SALA_TRANSICAO || b->tipoSala == SALA_LUCI) && (b->perm->conceitos & (1u << CONCEITO_PRATICAS));
    float custo = gratis ? 0.0f : SCANNER_CUSTO_EP;

    if (j->ep < custo) { RogueRecadoLuci(b, "Sem energia para o scanner."); TocarSom(sfxErro); return; }

    j->ep -= custo;
    b->recargaScanner = SCANNER_RECARGA;
    b->scanner = SCANNER_DURACAO;
    b->scannerErrou = GetRandomValue(1, 100) <= RogueChanceLuciErrar(b);

    if (RogueEstab(b) <= 3 && GetRandomValue(1, 100) <= SCANNER_CHANCE_LUCI_ECO)
        b->luciEco = 0.6f;                              // pista: por um instante, ela mesma aparece como eco

    // Reformulação: o scanner também procura passagens secretas (alucinando, marca a parede errada)
    if (b->temParedeSecreta && !b->passagemAberta) {
        b->paredeMarcada = b->scannerErrou ? (b->paredeSecreta + GetRandomValue(1, 3)) % 4 : b->paredeSecreta;
        b->marcaParede = SCANNER_DURACAO;
    }

    RogueAnel(b, j->pos, 420.0f, (Color){ 0, 228, 255, 255 });
    TocarSomTom(sfxSelecao, 0.7f);
    Telemetria("luci_scanner", b->scannerErrou ? "alucinou" : "certo", 0.0f, RogueEstab(b));
}

static void RogueAtualizarLuci(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    if (b->luciMsgTempo > 0.0f)   b->luciMsgTempo -= dt;
    if (b->scanner > 0.0f)        b->scanner -= dt;
    if (b->recargaScanner > 0.0f) b->recargaScanner -= dt;
    if (b->luciEco > 0.0f)        b->luciEco -= dt;

    // Arena da Luci: C contesta o que ela diz; H é o scanner (mostra a verdadeira)
    if (b->tipoSala == SALA_LUCI) {
        b->contradicao = 0.0f;
        if (IsKeyPressed(KEY_C)) RogueLuciContestar(b, prog);
        if (IsKeyPressed(KEY_H)) RogueScanner(b);
        return;
    }

    // No átrio e na fase 2 do Alucinador (C, F e H respondem às afirmações) não há contradição nem scanner
    if (b->tipoSala == SALA_ATRIO || b->tipoSala == SALA_MESTRE || (b->chefe.ativo && b->chefe.fase == 2)) {
        b->contradicao = 0.0f;
        return;
    }

    RogueAtualizarContradicoes(b, dt);

    if (IsKeyPressed(KEY_C)) RogueContestar(b, prog);
    if (IsKeyPressed(KEY_H)) RogueScanner(b);
}

// =============================================================
// BLOCO 3 - O NÚCLEO DE UTOPIA
//   Pela porta do átrio (aberta ao vencer o Alucinador):
//   1) CORREDOR DO NÚCLEO: a Luci se solta do jogador; 3 registros de memória
//      mostram as decisões dele (tiradas do save). Lidos os 3, a porta abre.
//   2) ARENA DA LUCI: a revelação (ela é a IA que alucinou UtopIA) e a luta.
//      A tela mostra UMA barra de vida, mas ela precisa ser zerada 3 vezes
//      (o jogador não sabe: a 1ª e a 2ª quedas são falsas derrotas).
//      1ª barra CONFLITO LÓGICO: dica envenenada (o "lado seguro" às vezes é
//               mentira; o aviso vermelho nunca mente) e, da metade para baixo,
//               as CONTRADIÇÕES (armadura + 2 cópias; C contesta).
//      Queda 1: o áudio congela em estática e ela desaba por 2 s.
//      2ª barra SURTO FÍSICO (vermelha): investidas corpo a corpo, cada uma
//               uma falácia. PARRY (V ou botão direito) no impacto: hit freeze,
//               tremor, zoom e onda de luz; ela fica atordoada e aceita o COMBO
//               DEDUTIVO (até 3 golpes corpo a corpo).
//      Queda 2: explosão de estática.
//      3ª barra NÚCLEO INSTÁVEL (magenta): investidas em cadeia, ondas de choque
//               com brecha e o chão que racha e cai. Com índice ruim, a guarda
//               só abre com o CONTEXTO CLARO (ASSUNTO, OBJETIVO e FORMATO ao
//               núcleo, E) ou com um parry.
//   O ÍNDICE DE DESEMPENHO (0-100, tirado do save) decide a dificuldade ao
//   entrar e o final ao vencer: 60 ou mais = final bom (a Luci é salva).
//   Perder a luta volta ao corredor sem perder nada.
// =============================================================

static IndiceFinal RogueCalcularIndice(const Biblioteca *b, int pontos)
{
    const ProgressoBiblioteca *p = b->perm;
    IndiceFinal r;
    int respostas = p->desafiosCertos + p->desafiosErrados;
    int conceitos = 0;

    for (int c = 0; c < NUM_CONCEITOS; c++)
        if (p->conceitos & (1u << c)) conceitos++;

    r.estabilidade  = 20 * RogueEstab(b) / ESTABILIDADE_MAX_LUCI;
    r.acertos       = (respostas > 0) ? 25 * p->desafiosCertos / respostas : 12;
    r.verificacao   = 15 * (p->alucinacoesPegas + 1) / (p->alucinacoesPegas + p->confiouAlucinacao + 1);
    r.contradicoes  = 15 * (p->contradicoesFlagradas + 1) / (p->contradicoesFlagradas + p->contradicoesPerdidas + 1);
    r.conceitos     = 3 * conceitos;
    r.sobrevivencia = (8 - 2 * (p->mortes + p->derrotasLuci) > 0) ? 8 - 2 * (p->mortes + p->derrotasLuci) : 0;
    r.pontos        = (pontos / 60 > 5) ? 5 : ((pontos > 0) ? pontos / 60 : 0);
    r.total = r.estabilidade + r.acertos + r.verificacao + r.contradicoes + r.conceitos + r.sobrevivencia + r.pontos;
    return r;
}

static bool RogueTemConceito(const Biblioteca *b, int conceito)
{
    return (b->perm->conceitos & (1u << conceito)) != 0;
}

