// ---------- Utilidades de linha de visão ----------

// Nenhuma estante entre a e c (amostras a cada 8 px)
static bool RogueLinhaLivre(const Biblioteca *b, Vector2 a, Vector2 c)
{
    float dist = Vector2Distance(a, c);
    int passos = (int)(dist / 8.0f);

    for (int k = 1; k < passos; k++) {
        Vector2 p = Vector2Lerp(a, c, (float)k / (float)passos);
        for (int i = 0; i < b->numObst; i++)
            if (CheckCollisionPointRec(p, b->obst[i]))
                return false;
    }
    return true;
}

// Onde um feixe que sai de "origem" na direção "dir" para: na primeira estante ou na parede
static Vector2 RogueFimFeixe(const Biblioteca *b, Vector2 origem, Vector2 dir)
{
    Vector2 p = origem;

    for (int k = 0; k < 200; k++) {
        Vector2 q = Vector2Add(p, Vector2Scale(dir, 6.0f));
        if (!CheckCollisionPointRec(q, ARENA_ROGUE))
            return q;
        for (int i = 0; i < b->numObst; i++)
            if (CheckCollisionPointRec(q, b->obst[i]))
                return q;
        p = q;
    }
    return p;
}

// O ponto está dentro do feixe (segmento a-c com a largura do feixe)?
static bool RogueNoFeixe(Vector2 a, Vector2 c, Vector2 p, float largura)
{
    Vector2 ac = Vector2Subtract(c, a);
    float l2 = Vector2DotProduct(ac, ac);
    if (l2 < 1.0f)
        return false;
    float t = Clamp(Vector2DotProduct(Vector2Subtract(p, a), ac) / l2, 0.0f, 1.0f);
    return Vector2Distance(p, Vector2Add(a, Vector2Scale(ac, t))) < largura / 2.0f + RAIO_CORPO_JOGADOR;
}

// ---------- ELITE A: SENTINELA DE ATENÇÃO ----------
// estado 0 = focando/procurando, 1 = travada (aviso), 2 = feixe, 3 = recalculando (vulnerável)
static void RogueAtualizarSentinela(Biblioteca *b, Inimigo *e, Vector2 dir, float dist, float dt)
{
    JogadorRogue *j = &b->j;
    const float vel = DEF_INIMIGOS[INIMIGO_SENTINELA].velocidade;
    bool visao = RogueLinhaLivre(b, e->pos, j->pos);
    bool tinhaVisao = e->visao;

    e->visao = visao;
    e->miraPrevista = j->pos;                      // para o desenho da linha de atenção
    if (e->distraida > 0.0f) e->distraida -= dt;

    switch (e->estado) {

        case 0:
            if (visao) {
                // Com o jogador à vista, para e concentra a atenção
                e->foco = fminf(1.0f, e->foco + dt / SENTINELA_FOCO_TEMPO);
                e->vel = (dist > 300.0f) ? Vector2Scale(dir, vel * 0.5f) : (Vector2){0};
            } else {
                // Perdeu o jogador de vista: fica distraída e procura uma linha livre andando de lado
                if (tinhaVisao && e->foco > 0.2f) {
                    e->distraida = SENTINELA_DISTRAIDA;
                    RogueTextoFlutuante(b, (Vector2){ e->pos.x, e->pos.y - 30 }, "PERDEU O FOCO", GOLD);
                }
                e->foco = fmaxf(0.0f, e->foco - dt * SENTINELA_PERDE_FOCO);
                Vector2 lado = { -dir.y * e->lado, dir.x * e->lado };
                e->vel = Vector2Scale(Vector2Normalize(Vector2Add(Vector2Scale(dir, 0.5f), lado)), vel);
                if (fmodf(e->anim, 3.0f) < dt) e->lado = -e->lado;
            }

            if (e->foco >= 1.0f && e->recarga <= 0.0f && visao) {
                e->estado = 1;
                e->timer = SENTINELA_TRAVA;
                e->alvo = dir;
                e->fimFeixe = RogueFimFeixe(b, e->pos, dir);
                e->vel = (Vector2){0};
                TocarSomTom(sfxAvisoParry, 0.8f);
            }
            break;

        case 1:     // travada: a direção não muda mais (dá para sair da linha ou se esconder)
            e->vel = (Vector2){0};
            e->timer -= dt;
            if (e->timer <= 0.0f) {
                e->estado = 2;
                e->timer = SENTINELA_FEIXE;
                e->feixeAcertou = false;
                TocarSomTom(sfxTiro, 0.4f);
            }
            break;

        case 2:     // feixe de atenção: atravessa a sala até a primeira estante
            e->vel = (Vector2){0};
            e->timer -= dt;
            if (!e->feixeAcertou && RogueNoFeixe(e->pos, e->fimFeixe, j->pos, SENTINELA_FEIXE_LARGURA)) {
                RogueFerirJogador(b, SENTINELA_FEIXE_DANO);
                e->feixeAcertou = true;
            }
            if (GetRandomValue(0, 1) == 0) RogueParticulas(b, e->fimFeixe, (Color){ 140, 230, 255, 255 }, 2, 120);
            if (e->timer <= 0.0f) {
                e->estado = 3;
                e->timer = SENTINELA_RECALCULA;
                e->foco = 0.0f;
                RogueTextoFlutuante(b, (Vector2){ e->pos.x, e->pos.y - 30 }, "RECALCULANDO PESOS", (Color){ 140, 230, 255, 255 });
            }
            break;

        default:    // recalculando: parada e vulnerável
            e->vel = (Vector2){0};
            e->timer -= dt;
            if (GetRandomValue(0, 4) == 0) RogueParticulas(b, e->pos, (Color){ 140, 230, 255, 255 }, 1, 60);
            if (e->timer <= 0.0f) { e->estado = 0; e->recarga = SENTINELA_INTERVALO; }
            break;
    }
}

static bool RogueSentinelaVulneravel(const Inimigo *e)
{
    return e->estado == 3 || e->distraida > 0.0f;
}

// ---------- ELITE B: RETROPROPAGADOR ----------
// estado 0 = para frente (registra os golpes), 1 = aviso, 2 = volta (devolve), 3 = recalibrando (vulnerável)
static void RogueAtualizarRetro(Biblioteca *b, Inimigo *e, Vector2 dir, float dist, float ritmo, float dt)
{
    const float vel = DEF_INIMIGOS[INIMIGO_RETRO].velocidade;

    if (e->habilidade > 0.0f) e->habilidade -= dt;

    switch (e->estado) {

        case 0:
            e->vel = RogueManterDistancia(e, dir, dist, 120.0f, 220.0f, vel, dt);
            e->timer += dt * ritmo;
            if (e->timer >= RETRO_FORWARD) {
                e->timer = 0.0f;
                if (e->numRegistros > 0) {
                    e->estado = 1;
                    e->timer = RETRO_AVISO;
                    TocarSomTom(sfxErro, 1.3f);
                    RogueTextoFlutuante(b, (Vector2){ e->pos.x, e->pos.y - 32 }, "RETROPROPAGANDO...", ORANGE);
                } else {
                    // Gradiente zero: ninguém o feriu, então só um anel lento e uma pausa curta
                    for (int k = 0; k < 8; k++) {
                        float a = (2.0f * PI / 8.0f) * k + e->anim;
                        RogueDisparar(b, e->pos, (Vector2){ cosf(a), sinf(a) }, 140.0f, RETRO_TIRO_DANO * 0.75f, 6.0f, false);
                    }
                    e->estado = 3;
                    e->timer = RETRO_RECALIBRA * 0.5f;
                }
            }
            break;

        case 1:
            e->vel = (Vector2){0};
            e->timer -= dt;
            if (e->timer <= 0.0f) { e->estado = 2; e->tiros = 0; e->timer = 0.0f; }
            break;

        case 2: {
            // Um projétil para cada marca, em sequência (golpes demais deixam a volta mais rápida)
            e->vel = (Vector2){0};
            e->timer -= dt;
            float rapidez = 1.0f + 0.08f * (float)((e->excesso < 6) ? e->excesso : 6);
            while (e->timer <= 0.0f && e->tiros < e->numRegistros) {
                Vector2 d = Vector2Subtract(e->registro[e->tiros], e->pos);
                d = (Vector2Length(d) > 1.0f) ? Vector2Normalize(d) : dir;
                RogueDisparar(b, e->pos, d, RETRO_TIRO_VEL * rapidez, RETRO_TIRO_DANO, 7.0f, false);
                TocarSomTom(sfxTiro, 0.8f);
                e->tiros++;
                e->timer += 0.06f;
            }
            if (e->tiros >= e->numRegistros) {
                e->numRegistros = 0;
                e->excesso = 0;
                e->estado = 3;
                e->timer = RETRO_RECALIBRA;
                RogueTextoFlutuante(b, (Vector2){ e->pos.x, e->pos.y - 32 }, "RECALIBRANDO", LIGHTGRAY);
            }
        } break;

        default:
            e->vel = Vector2Scale(dir, vel * 0.2f);
            e->timer -= dt;
            if (GetRandomValue(0, 5) == 0) RogueParticulas(b, e->pos, GRAY, 1, 50);
            if (e->timer <= 0.0f) { e->estado = 0; e->timer = 0.0f; }
            break;
    }
}

// Golpe recebido na passagem "para frente": guarda de onde o jogador atacou
static void RogueRetroRegistrar(Biblioteca *b, Inimigo *e)
{
    if (e->estado != 0 || e->habilidade > 0.0f)
        return;

    if (e->numRegistros < RETRO_MAX_REGISTROS) e->registro[e->numRegistros++] = b->j.pos;
    else                                       e->excesso++;
    e->habilidade = RETRO_REGISTRO_INTERVALO;
}

// ---------- MINI-CHEFE: JANELA DE CONTEXTO ----------

static Inimigo *RogueJanelaChefe(Biblioteca *b)
{
    JanelaContexto *jc = &b->janela;
    if (!jc->ativo || jc->indice < 0 || jc->indice >= MAX_INIMIGOS)
        return NULL;
    Inimigo *e = &b->ini[jc->indice];
    return (e->ativo && e->tipo == INIMIGO_JANELA) ? e : NULL;
}

static int RogueJanelaContar(const JanelaContexto *jc, int tipo)
{
    int n = 0;
    for (int i = 0; i < jc->num; i++) if (jc->slot[i] == tipo) n++;
    return n;
}

static void RogueJanelaDica(Biblioteca *b, const char *texto)
{
    snprintf(b->janela.dica, sizeof(b->janela.dica), "%s", texto);
}

// A instrução PROTEGER saiu da janela: o escudo cai
static void RogueJanelaAbrir(Biblioteca *b)
{
    JanelaContexto *jc = &b->janela;
    Inimigo *e = RogueJanelaChefe(b);

    jc->vulneravel = JANELA_VULNERAVEL;
    jc->ciclos++;
    if (e != NULL) {
        e->estado = 3;
        e->timer = 0.0f;
        RogueParticulas(b, e->pos, (Color){ 150, 140, 255, 255 }, 30, 260);
        RogueAnel(b, e->pos, 90.0f, (Color){ 150, 140, 255, 255 });
    }
    RogueAviso(b, "INSTRUÇÃO ESQUECIDA! O escudo caiu: ataque!");
    TocarSomTom(sfxAcerto, 0.7f);
    if (jc->ciclos == 1)
        RogueJanelaDica(b, "A janela passou do limite e o bloco mais antigo (PROTEGER) foi esquecido.");
}

// Tira o bloco mais antigo da janela
static void RogueJanelaEsquecer(Biblioteca *b)
{
    JanelaContexto *jc = &b->janela;
    if (jc->num <= 0)
        return;

    int tipo = jc->slot[0];
    for (int i = 1; i < jc->num; i++) { jc->slot[i - 1] = jc->slot[i]; jc->memoria[i - 1] = jc->memoria[i]; }
    jc->num--;
    jc->esquecidoTipo = tipo;
    jc->esquecidoAnim = 0.9f;
    jc->estouros++;

    Inimigo *e = RogueJanelaChefe(b);
    if (tipo == CTX_SISTEMA) {
        RogueJanelaAbrir(b);
    } else if (tipo == CTX_RELEVANTE && jc->fase >= 3 && e != NULL && jc->vulneravel <= 0.0f) {
        // Fase 3: perder um dado o deixa nervoso (um anel curto)
        for (int k = 0; k < 8; k++) {
            float a = (2.0f * PI / 8.0f) * k + e->anim;
            RogueDisparar(b, e->pos, (Vector2){ cosf(a), sinf(a) }, 150.0f, 6.0f, 6.0f, false);
        }
        RogueTextoFlutuante(b, (Vector2){ e->pos.x, e->pos.y - 40 }, "PERDEU O FIO", GOLD);
    }
}

// Um bloco entra no fim da janela; se passar do limite, o mais antigo sai
static void RogueJanelaInserir(Biblioteca *b, int tipo, Vector2 memoria)
{
    JanelaContexto *jc = &b->janela;

    if (jc->num >= JANELA_MAX_SLOTS + 1)
        RogueJanelaEsquecer(b);
    jc->slot[jc->num] = (unsigned char)tipo;
    jc->memoria[jc->num] = memoria;
    jc->num++;
    jc->entrouAnim = 0.35f;

    while (jc->num > jc->capacidade)
        RogueJanelaEsquecer(b);
}

// Golpe no escudo: o dano vira ruído na janela (prompt inundado)
static void RogueJanelaRuido(Biblioteca *b, float dano)
{
    JanelaContexto *jc = &b->janela;
    Inimigo *e = RogueJanelaChefe(b);

    if (e == NULL || jc->vulneravel > 0.0f)
        return;

    jc->ruidoAcumulado += dano;
    while (jc->ruidoAcumulado >= JANELA_DANO_POR_RUIDO && jc->vulneravel <= 0.0f) {
        jc->ruidoAcumulado -= JANELA_DANO_POR_RUIDO;
        RogueTextoFlutuante(b, (Vector2){ e->pos.x + (float)GetRandomValue(-20, 20), e->pos.y - 36 }, "+RUÍDO", LIGHTGRAY);
        RogueJanelaInserir(b, CTX_RUIDO, (Vector2){0});
    }
}

// Fim do escudo aberto: ela relê as instruções (na fase 3, repete PROTEGER no FIM da janela)
static void RogueJanelaReler(Biblioteca *b)
{
    JanelaContexto *jc = &b->janela;
    Inimigo *e = RogueJanelaChefe(b);

    jc->num = 0;
    jc->vulneravel = 0.0f;
    jc->ruidoAcumulado = 0.0f;
    if (jc->fase < 3) {
        RogueJanelaInserir(b, CTX_SISTEMA, (Vector2){0});
        RogueJanelaInserir(b, CTX_RELEVANTE, b->j.pos);
    } else {
        RogueJanelaInserir(b, CTX_RELEVANTE, b->j.pos);
        RogueJanelaInserir(b, CTX_SISTEMA, (Vector2){0});
    }
    if (e != NULL) { e->estado = 0; e->recarga = 1.2f; }
    RogueAviso(b, (jc->fase < 3) ? "Ela releu as instruções. Encha a janela de novo!" : "Agora ela repete PROTEGER no FIM da janela!");
}

// Um dado dourado nasce na borda da sala e voa até a Janela (carrega a posição do jogador)
static void RogueJanelaEmitir(Biblioteca *b)
{
    Vector2 p = { 400, 80 };
    for (int t = 0; t < 8; t++) {
        int lado = GetRandomValue(0, 3);
        p = (lado == 0) ? (Vector2){ (float)GetRandomValue(80, 720), 76 } :
            (lado == 1) ? (Vector2){ (float)GetRandomValue(80, 720), 514 } :
            (lado == 2) ? (Vector2){ 56, (float)GetRandomValue(100, 490) } : (Vector2){ 744, (float)GetRandomValue(100, 490) };
        if (Vector2Distance(p, b->j.pos) > 130.0f) break;
    }
    Inimigo *t = RogueCriarInimigo(b, INIMIGO_TOKEN, p);
    if (t != NULL) { t->surgindo = 0.25f; t->memoria = b->j.pos; }
}

static bool RogueAtualizarToken(Biblioteca *b, Inimigo *e, float dt)
{
    Inimigo *chefe = RogueJanelaChefe(b);
    (void)dt;

    if (chefe == NULL) {
        e->ativo = false;
        return false;
    }

    Vector2 d = Vector2Subtract(chefe->pos, e->pos);
    float l = Vector2Length(d);
    if (l < chefe->raio + e->raio) {
        RogueJanelaInserir(b, CTX_RELEVANTE, e->memoria);
        RogueParticulas(b, e->pos, GOLD, 6, 100);
        e->ativo = false;
        return false;
    }

    e->vel = Vector2Scale(d, TOKEN_VELOCIDADE[b->janela.fase - 1] / l);
    return true;
}

// estado 0 = livre, 1 = preparando a resposta, 2 = resumindo, 3 = escudo esquecido (vulnerável)
static void RogueAtualizarJanela(Biblioteca *b, Inimigo *e, Vector2 dir, float dist, float dt)
{
    JanelaContexto *jc = &b->janela;
    (void)dir; (void)dist;

    e->empurrao = (Vector2){0};
    if (jc->esquecidoAnim > 0.0f) jc->esquecidoAnim -= dt;
    if (jc->entrouAnim > 0.0f)    jc->entrouAnim -= dt;

    // Fases: a janela cresce e ele aprende a se organizar
    float frac = e->hp / e->hpMax;
    int fase = (frac <= JANELA_FASE3) ? 3 : ((frac <= JANELA_FASE2) ? 2 : 1);
    if (fase > jc->fase) {
        jc->fase = fase;
        jc->capacidade = JANELA_CAPACIDADE[fase - 1];
        jc->resumo = JANELA_RESUMO[fase - 1];
        if (fase == 2) {
            RogueAviso(b, "JANELA MAIOR! E agora ele RESUME o ruído.");
            RogueJanelaDica(b, "Janela maior: precisa de mais ruído. Encha mais rápido do que ele resume!");
        } else {
            RogueAviso(b, "ÚLTIMA FASE: ele repete a instrução no fim!");
            RogueJanelaDica(b, "Dados dourados também ocupam espaço: deixá-los entrar enche a janela, mas melhora a mira dele.");
        }
    }

    // Deriva devagar pela sala
    Vector2 alvo = { 400.0f + sinf(e->anim * 0.45f) * 150.0f, 250.0f + sinf(e->anim * 0.8f) * 60.0f };
    Vector2 ate = Vector2Subtract(alvo, e->pos);
    float veloc = DEF_INIMIGOS[INIMIGO_JANELA].velocidade;
    e->vel = (e->estado == 0 && Vector2Length(ate) > 8.0f) ? Vector2Scale(Vector2Normalize(ate), veloc) : (Vector2){0};

    // Dados dourados (o que ele sabe sobre o jogador)
    jc->emissor -= dt;
    if (jc->emissor <= 0.0f) {
        jc->emissor = JANELA_EMISSAO[jc->fase - 1];
        for (int k = 0; k < ((jc->fase >= 3) ? 2 : 1); k++)
            RogueJanelaEmitir(b);
    }

    switch (e->estado) {

        case 3:     // escudo esquecido
            jc->vulneravel -= dt;
            if (GetRandomValue(0, 2) == 0) RogueParticulas(b, e->pos, MAGENTA, 1, 80);
            if (jc->vulneravel <= 0.0f) RogueJanelaReler(b);
            break;

        case 2: {   // resumindo: descarta os 2 blocos de ruído mais antigos
            e->timer -= dt;
            if (e->timer <= 0.0f) {
                int tirados = 0;
                for (int i = 0; i < jc->num && tirados < 2; ) {
                    if (jc->slot[i] == CTX_RUIDO) {
                        for (int k = i + 1; k < jc->num; k++) { jc->slot[k - 1] = jc->slot[k]; jc->memoria[k - 1] = jc->memoria[k]; }
                        jc->num--;
                        tirados++;
                    } else i++;
                }
                RogueTextoFlutuante(b, (Vector2){ e->pos.x, e->pos.y - 40 }, TextFormat("RESUMO: -%d RUÍDO", tirados), (Color){ 150, 140, 255, 255 });
                e->estado = 0;
                if (e->recarga < 0.8f) e->recarga = 0.8f;
            }
        } break;

        case 1:     // preparando a resposta (linhas até o alvo)
            e->timer -= dt;
            if (e->timer <= 0.0f) {
                int nRel = e->tiros;
                if (e->carga > 0.5f) {
                    // Sem contexto relevante: resposta genérica (um anel espalhado e fraco)
                    float giro = (float)GetRandomValue(0, 360) * DEG2RAD;
                    for (int k = 0; k < 8; k++) {
                        float a = giro + (2.0f * PI / 8.0f) * k;
                        RogueDisparar(b, e->pos, (Vector2){ cosf(a), sinf(a) }, 150.0f, 6.0f, 6.0f, false);
                    }
                    RogueTextoFlutuante(b, (Vector2){ e->pos.x, e->pos.y - 40 }, "SEM CONTEXTO: ???", LIGHTGRAY);
                } else {
                    // Com contexto: um leque mirado no que ele LEMBRA (mais dados = mais balas e mais precisão)
                    Vector2 d = Vector2Subtract(e->alvo, e->pos);
                    d = (Vector2Length(d) > 1.0f) ? Vector2Normalize(d) : (Vector2){ 0, 1 };
                    int balas = 3 + 2 * nRel;
                    if (balas > 11) balas = 11;
                    float arco = (50.0f / (1.0f + 0.4f * (float)nRel)) * DEG2RAD;
                    for (int k = 0; k < balas; k++) {
                        float a = (balas > 1) ? ((float)k / (float)(balas - 1) - 0.5f) * arco : 0.0f;
                        RogueDisparar(b, e->pos, Vector2Rotate(d, a), 200.0f + 12.0f * (float)nRel, 8.0f, 6.0f, false);
                    }
                }
                TocarSomTom(sfxTiro, 0.6f);
                e->estado = 0;
                e->recarga = JANELA_RESPOSTA[jc->fase - 1];
            }
            break;

        default:
            if (jc->fase >= 2) {
                jc->resumo -= dt;
                if (jc->resumo <= 0.0f) {
                    jc->resumo = JANELA_RESUMO[jc->fase - 1];
                    if (RogueJanelaContar(jc, CTX_RUIDO) >= 2) {
                        e->estado = 2;
                        e->timer = 1.3f;
                        RogueTextoFlutuante(b, (Vector2){ e->pos.x, e->pos.y - 40 }, "RESUMINDO...", (Color){ 150, 140, 255, 255 });
                        break;
                    }
                }
            }
            if (e->recarga <= 0.0f) {
                // Mira no dado mais recente que ainda está na janela
                int nRel = RogueJanelaContar(jc, CTX_RELEVANTE);
                e->tiros = nRel;
                e->carga = (nRel == 0) ? 1.0f : 0.0f;
                e->alvo = e->pos;
                for (int i = jc->num - 1; i >= 0; i--)
                    if (jc->slot[i] == CTX_RELEVANTE) { e->alvo = jc->memoria[i]; break; }
                e->estado = 1;
                e->timer = 0.8f;
            }
            break;
    }
}

// Derrotada: os dados somem, a recompensa sai uma vez e a explicação aparece
static void RogueJanelaDerrotada(Biblioteca *b, ProgressoCorredor *prog)
{
    JanelaContexto *jc = &b->janela;

    jc->ativo = false;
    jc->vulneravel = 0.0f;
    for (int i = 0; i < MAX_INIMIGOS; i++)
        if (b->ini[i].ativo && b->ini[i].tipo == INIMIGO_TOKEN) {
            b->ini[i].ativo = false;
            RogueParticulas(b, b->ini[i].pos, GOLD, 4, 80);
        }

    if (jc->recompensaDada)
        return;
    jc->recompensaDada = true;

    if (!b->modoSeletor || b->recompensaSeletor) {
        b->perm->fragmentos += 10;
        AlterarPontos(prog, 20);
        RogueMudarEstabilidade(b, 1, "contexto organizado");
        RogueAviso(b, "JANELA DE CONTEXTO DERROTADA! +10 FRAGMENTOS");
    } else {
        RogueAviso(b, "JANELA DE CONTEXTO DERROTADA!");
    }
    b->conversaPendente = &dialogoJanelaVitoria;
    b->objConversa = OBJ_NENHUM;
    MostrarEmocaoLuci(EMOCAO_ALEGRE, 3.0f);
    Telemetria("rogue_minichefe", "janela", (float)(GetTime() - b->inicio), jc->ciclos);
}

// Monta a sala de um encontro especial (objetivo: derrotar o especial e quem vier com ele)
static void RogueMontarSalaEspecial(Biblioteca *b, int esp)
{
    if (esp < 0 || esp >= NUM_ESPECIAIS) esp = ESP_SENTINELA;

    const LayoutSala *l = &LAYOUTS_ESPECIAIS[esp];
    RogueUsarLayout(b, l);
    layoutCombateAtual = (l->numPontos > 0) ? l : &LAYOUTS_COMBATE[0];
    b->combates++;
    b->objetivoSala = OBJC_ELIMINAR;
    b->ondaAtual = 0;
    b->numOndas = 1;
    b->encontro = -1;

    Vector2 topo = { 400, 170 };
    if (esp == ESP_SENTINELA) {
        Inimigo *e = RogueCriarInimigo(b, INIMIGO_SENTINELA, RogueLugarSurgir(b, topo, SENTINELA_RAIO));
        if (e != NULL) e->elite = true;
        for (int k = 0; k < 3; k++)
            RogueCriarInimigo(b, INIMIGO_FRAGMENTO, RogueLugarSurgir(b, l->pontos[k % l->numPontos], FRAGMENTO_RAIO));
    } else if (esp == ESP_RETRO) {
        Inimigo *e = RogueCriarInimigo(b, INIMIGO_RETRO, RogueLugarSurgir(b, topo, RETRO_RAIO));
        if (e != NULL) e->elite = true;
        for (int k = 0; k < 4; k++)
            RogueCriarInimigo(b, INIMIGO_SPAMMER, RogueLugarSurgir(b, l->pontos[k % l->numPontos], 10.0f));
        RogueCriarInimigo(b, INIMIGO_GUARDIAO, RogueLugarSurgir(b, l->pontos[4], GUARDIAO_RAIO));
    } else {
        Inimigo *e = RogueCriarInimigo(b, INIMIGO_JANELA, RogueLugarSurgir(b, (Vector2){ 400, 210 }, JANELA_RAIO));
        JanelaContexto *jc = &b->janela;
        memset(jc, 0, sizeof(*jc));
        if (e != NULL) {
            jc->ativo = true;
            jc->indice = (int)(e - b->ini);
            jc->fase = 1;
            jc->capacidade = JANELA_CAPACIDADE[0];
            jc->emissor = 2.5f;
            jc->resumo = JANELA_RESUMO[0];
            e->recarga = 2.5f;
            RogueJanelaInserir(b, CTX_SISTEMA, (Vector2){0});
            RogueJanelaInserir(b, CTX_RELEVANTE, b->j.pos);
            RogueJanelaDica(b, "Golpes no escudo viram RUÍDO. Encha a janela: o bloco mais antigo é esquecido.");
        }
        b->conversaPendente = &dialogoJanelaIntro;
        b->objConversa = OBJ_NENHUM;
    }

    RogueAviso(b, TextFormat("ENCONTRO ESPECIAL: %s", NOMES_ESPECIAIS[esp]));
    RogueRecadoLuci(b, FALAS_LUCI_ESPECIAL[esp]);
    b->luciMsgTempo = 4.5f;
    Telemetria("rogue_especial", NOMES_ESPECIAIS[esp], 0.0f, b->indiceRota);
}

static void RogueAtualizarInimigos(Biblioteca *b, float dt)
{
    JogadorRogue *j = &b->j;

    RogueAtualizarConexoes(b);

    for (int i = 0; i < MAX_INIMIGOS; i++) {

        Inimigo *e = &b->ini[i];
        const DefInimigo *def = &DEF_INIMIGOS[e->tipo];

        if (!e->ativo)
            continue;

        e->anim += dt;
        if (e->flash > 0.0f) e->flash -= dt;
        if (e->rotulo > 0.0f) e->rotulo -= dt;

        if (e->surgindo > 0.0f) {
            e->surgindo -= dt;
            continue;
        }

        // Proxy-Isca: quem persegue vai atrás do holograma
        bool enganado = j->efeito[EFEITO_PROXY] > 0.0f && RoguePerseguidor(e->tipo);
        Vector2 paraJogador = Vector2Subtract(enganado ? j->proxyPos : j->pos, e->pos);
        float dist = Vector2Length(paraJogador);
        Vector2 dir = (dist > 0.01f) ? Vector2Scale(paraJogador, 1.0f / dist) : (Vector2){ 0, 1 };

        // Ligado a um Botnet: as recargas passam mais rápido (ataca mais vezes)
        float ritmo = (e->conectado ? BOTNET_BONUS_RITMO : 1.0f) * (e->elite ? ELITE_RITMO : 1.0f) *
                      ((b->fatorRitmoInimigos > 0.0f) ? b->fatorRitmoInimigos : 1.0f);       // elite e profundidade

        if (e->recarga > 0.0f) e->recarga -= dt * ritmo;

        if (e->atordoado > 0.0f) {
            e->atordoado -= dt;
            e->vel = (Vector2){0};
        }
        else switch (e->tipo) {

            case INIMIGO_FRAGMENTO:

                if (e->estado == 0) {
                    // Persegue com um zigue-zague de dado corrompido
                    Vector2 lado = { -dir.y, dir.x };
                    e->vel = Vector2Add(Vector2Scale(dir, FRAGMENTO_VELOCIDADE),
                                        Vector2Scale(lado, sinf(e->anim * 5.0f) * 40.0f));

                    if (dist < FRAGMENTO_ALCANCE_BOTE && e->recarga <= 0.0f) {
                        e->estado = 1;
                        e->timer = FRAGMENTO_PREPARO;
                        e->alvo = dir;
                        e->vel = (Vector2){0};
                    }
                }
                else if (e->estado == 1) {
                    e->vel = (Vector2){0};
                    e->timer -= dt;
                    if (e->timer <= 0.0f) {
                        e->estado = 2;
                        e->timer = FRAGMENTO_BOTE_DURACAO;
                        e->vel = Vector2Scale(e->alvo, FRAGMENTO_BOTE_VEL);
                    }
                }
                else {
                    e->timer -= dt;
                    if (e->timer <= 0.0f) {
                        e->estado = 0;
                        e->recarga = FRAGMENTO_RECARGA;
                    }
                }
                break;

            case INIMIGO_GUARDIAO:

                if (e->estado == 0) {
                    // Mantém distância: foge de perto, chega mais se longe, senão anda de lado
                    if (dist < GUARDIAO_DIST_MIN)      e->vel = Vector2Scale(dir, -GUARDIAO_VELOCIDADE);
                    else if (dist > GUARDIAO_DIST_MAX) e->vel = Vector2Scale(dir, GUARDIAO_VELOCIDADE);
                    else                               e->vel = Vector2Scale((Vector2){ -dir.y * e->lado, dir.x * e->lado }, GUARDIAO_VELOCIDADE * 0.6f);

                    if (fmodf(e->anim, 2.5f) < dt) e->lado = -e->lado;

                    if (e->recarga <= 0.0f) {
                        e->estado = 1;
                        e->timer = GUARDIAO_PREPARO;
                        e->vel = (Vector2){0};
                    }
                }
                else {
                    e->vel = (Vector2){0};
                    e->timer -= dt;

                    if (e->timer <= 0.0f) {
                        // Leque mirado no jogador (padrão previsível)
                        int leque = e->elite ? GUARDIAO_LEQUE + 2 : GUARDIAO_LEQUE;    // elite: leque de 5
                        for (int k = 0; k < leque; k++) {
                            float ang = ((float)k - (leque - 1) / 2.0f) * GUARDIAO_ABERTURA * DEG2RAD;
                            RogueDisparar(b, e->pos, Vector2Rotate(dir, ang), GUARDIAO_TIRO_VEL, GUARDIAO_TIRO_DANO, 6.0f, false);
                        }
                        e->estado = 0;
                        e->recarga = GUARDIAO_INTERVALO;
                    }
                }
                break;

            case INIMIGO_ECO:

                // Eco falso: se ninguém checar (atirar) a tempo, explode e espalha balas
                e->vel = (Vector2){0};
                e->timer -= dt;

                if (e->timer <= 0.0f) {
                    for (int k = 0; k < ECO_BALAS; k++) {
                        float ang = (2.0f * PI / ECO_BALAS) * k + e->anim;
                        RogueDisparar(b, e->pos, (Vector2){ cosf(ang), sinf(ang) }, 170.0f, 8.0f, 5.0f, false);
                    }
                    RogueParticulas(b, e->pos, MAGENTA, 14, 200);
                    TocarSomTom(sfxErro, 1.4f);
                    e->ativo = false;
                    continue;
                }
                break;

            case INIMIGO_SPAMMER: {
                // Enxame: persegue em zigue-zague nervoso, cada um com seu desvio (o bando se espalha)
                Vector2 lado = { -dir.y, dir.x };
                float desvio = sinf(e->anim * 7.0f + e->lado * 2.0f + (float)i) * 70.0f;
                e->vel = Vector2Add(Vector2Scale(dir, def->velocidade), Vector2Scale(lado, desvio));
            } break;

            case INIMIGO_SPAM:
                e->vel = Vector2Scale(dir, def->velocidade);
                e->vida -= dt;
                if (e->vida <= 0.0f) {
                    RogueParticulas(b, e->pos, def->cor, 4, 80);
                    e->ativo = false;
                    continue;
                }
                break;

            case INIMIGO_PHISHER: {
                // Spammer + Phisher: com o jogador cercado de spam, ele ataca de mais longe e mais rápido
                bool distraido = RogueSpammersPerto(b, j->pos, 140.0f) >= 3;

                if (e->habilidade > 0.0f) e->habilidade -= dt;

                if (e->estado == 0 && e->recarga <= 0.0f && dist < PHISHER_ALCANCE * (distraido ? 1.4f : 1.0f))
                    RogueRevelarPhisher(b, e, distraido);

                RogueMoverPhisher(e, dir, def->velocidade, dt);
            } break;

            case INIMIGO_ISCA: {
                // Cópia falsa: imita o bote, mas não machuca. Some com o tempo ou com o dono.
                bool donoVivo = e->dono >= 0 && b->ini[e->dono].ativo && b->ini[e->dono].tipo == INIMIGO_PHISHER;

                e->vida -= dt;
                if (e->vida <= 0.0f || !donoVivo) {
                    RogueParticulas(b, e->pos, def->cor, 8, 120);
                    e->ativo = false;
                    continue;
                }

                RogueMoverPhisher(e, dir, def->velocidade, dt);
                if (e->estado == 0 && e->recarga <= 0.0f && dist < PHISHER_ALCANCE) {
                    e->estado = 1;
                    e->timer = PHISHER_PREPARO;
                }
            } break;

            case INIMIGO_FIREWALL: {
                // Vira devagar para o jogador: quem dá a volta acha as costas desprotegidas
                float ang = atan2f(e->frente.y, e->frente.x);
                float diferenca = atan2f(dir.y, dir.x) - ang;
                while (diferenca > PI)  diferenca -= 2.0f * PI;
                while (diferenca < -PI) diferenca += 2.0f * PI;
                float passo = FIREWALL_GIRO * dt;
                ang += Clamp(diferenca, -passo, passo);
                e->frente = (Vector2){ cosf(ang), sinf(ang) };

                // Fica na frente de quem protege (entre os aliados e o jogador)
                Vector2 centro = {0};
                Vector2 destino = j->pos;
                if (RogueQuemProteger(b, e, &centro))
                    destino = Vector2Add(centro, Vector2Scale(Vector2Normalize(Vector2Subtract(j->pos, centro)), 55.0f));
                else if (dist < 160.0f)
                    destino = e->pos;

                Vector2 ate = Vector2Subtract(destino, e->pos);
                e->vel = (Vector2Length(ate) > 16.0f) ? Vector2Scale(Vector2Normalize(ate), def->velocidade) : (Vector2){0};

                // Barreira de energia na frente (com aviso)
                if (e->estado == 0) {
                    e->habilidade -= dt * ritmo;
                    if (e->habilidade <= 0.0f) { e->estado = 1; e->timer = FIREWALL_AVISO_BARREIRA; }
                }
                else if (e->estado == 1) {
                    e->timer -= dt;
                    if (e->timer <= 0.0f) {
                        e->estado = 2;
                        e->timer = FIREWALL_BARREIRA;
                        TocarSomTom(sfxSelecao, 0.5f);
                    }
                }
                else {
                    e->timer -= dt;
                    if (e->timer <= 0.0f) { e->estado = 0; e->habilidade = FIREWALL_INTERVALO; }
                }
            } break;

            case INIMIGO_OVERCLOCK:

                if (e->estado == 0) {
                    // Aproxima-se devagar até uma boa distância
                    e->vel = (dist > OVERCLOCK_ALCANCE * 0.8f) ? Vector2Scale(dir, def->velocidade)
                                                               : Vector2Scale((Vector2){ -dir.y * e->lado, dir.x * e->lado }, def->velocidade * 0.5f);
                    if (dist < OVERCLOCK_ALCANCE && e->recarga <= 0.0f) {
                        e->estado = 1;
                        e->carga = 0.0f;
                        e->cargaAlvo = OVERCLOCK_CARGA_MIN + (OVERCLOCK_CARGA_MAX - OVERCLOCK_CARGA_MIN) * (float)GetRandomValue(0, 100) / 100.0f;
                    }
                }
                else if (e->estado == 1) {
                    // Carregando: quanto mais carga, mais rápida a investida (e mais longa a fraqueza depois).
                    // Overclock + Keylogger: se houver um Keylogger vivo, mira onde ele previu.
                    e->vel = (Vector2){0};
                    e->carga += dt * ritmo;

                    if (e->cargaAlvo - e->carga > 0.15f) {
                        Vector2 alvo = RogueTemKeylogger(b) ? RoguePrevisaoJogador(b, e->pos, OVERCLOCK_INVESTIDA_MAX) : j->pos;
                        Vector2 d = Vector2Subtract(alvo, e->pos);
                        e->alvo = (Vector2Length(d) > 1.0f) ? Vector2Normalize(d) : dir;
                    }

                    if (e->carga >= e->cargaAlvo) {
                        float vel = OVERCLOCK_INVESTIDA_MIN + (OVERCLOCK_INVESTIDA_MAX - OVERCLOCK_INVESTIDA_MIN) * RogueCargaOverclock(e);
                        e->estado = 2;
                        e->timer = OVERCLOCK_INVESTIDA_DURACAO;
                        e->vel = Vector2Scale(e->alvo, vel);
                        TocarSomTom(sfxDano, 1.4f);
                    }
                }
                else if (e->estado == 2) {
                    e->timer -= dt;
                    if (GetRandomValue(0, 1) == 0) RogueParticulas(b, e->pos, ORANGE, 1, 40);      // rastro de energia
                    if (e->timer <= 0.0f) RogueSuperaquecer(e);
                }
                else {
                    // Superaquecido: quase parado e vulnerável
                    e->vel = Vector2Scale(dir, 20.0f);
                    e->timer -= dt;
                    if (GetRandomValue(0, 6) == 0) RogueParticulas(b, (Vector2){ e->pos.x, e->pos.y - 10 }, GRAY, 1, 30);
                    if (e->timer <= 0.0f) { e->estado = 0; e->recarga = OVERCLOCK_RECARGA; }
                }
                break;

            case INIMIGO_BOTNET: {
                // Fica longe e, se der, escondido atrás de um aliado (o aliado entre ele e o jogador)
                const Inimigo *escudo = NULL;
                float menor = 9999.0f;
                for (int o = 0; o < MAX_INIMIGOS; o++) {
                    const Inimigo *a = &b->ini[o];
                    if (a == e || !a->ativo || a->tipo == INIMIGO_BOTNET || RogueInimigoPassageiro(a->tipo)) continue;
                    if (Vector2Distance(a->pos, e->pos) < menor) { menor = Vector2Distance(a->pos, e->pos); escudo = a; }
                }

                if (dist < BOTNET_DIST_MIN || escudo == NULL) {
                    e->vel = RogueManterDistancia(e, dir, dist, BOTNET_DIST_MIN, BOTNET_DIST_MAX, def->velocidade, dt);
                } else {
                    Vector2 atras = Vector2Add(escudo->pos, Vector2Scale(Vector2Normalize(Vector2Subtract(escudo->pos, j->pos)), 70.0f));
                    Vector2 ate = Vector2Subtract(atras, e->pos);
                    e->vel = (Vector2Length(ate) > 12.0f) ? Vector2Scale(Vector2Normalize(ate), def->velocidade) : (Vector2){0};
                }

                // De vez em quando, um pacote fraco (brilha antes)
                if (e->estado == 0 && e->recarga <= 0.0f) { e->estado = 1; e->timer = BOTNET_PREPARO; }
                else if (e->estado == 1) {
                    e->vel = Vector2Scale(e->vel, 0.3f);
                    e->timer -= dt;
                    if (e->timer <= 0.0f) {
                        RogueDisparar(b, e->pos, dir, 200.0f, BOTNET_TIRO_DANO, 5.0f, false);
                        TocarSomTom(sfxTiro, 1.6f);
                        e->estado = 0;
                        e->recarga = BOTNET_INTERVALO;
                    }
                }
            } break;

            case INIMIGO_KEYLOGGER:

                if (e->estado == 0) {
                    e->vel = RogueManterDistancia(e, dir, dist, KEYLOGGER_DIST_MIN, KEYLOGGER_DIST_MAX, def->velocidade, dt);
                    if (e->recarga <= 0.0f) { e->estado = 1; e->timer = KEYLOGGER_PREPARO; }
                }
                else if (e->estado == 1) {
                    // A mira aparece no chão, seguindo a previsão; trava um instante antes da rajada
                    e->vel = (Vector2){0};
                    e->timer -= dt;
                    if (e->timer > 0.15f) e->miraPrevista = RoguePrevisaoJogador(b, e->pos, KEYLOGGER_TIRO_VEL);
                    if (e->timer <= 0.0f) { e->estado = 2; e->tiros = e->elite ? KEYLOGGER_RAJADA + 2 : KEYLOGGER_RAJADA; e->timer = 0.0f; }
                }
                else {
                    e->vel = (Vector2){0};
                    e->timer -= dt;
                    if (e->timer <= 0.0f && e->tiros > 0) {
                        Vector2 d = Vector2Normalize(Vector2Subtract(e->miraPrevista, e->pos));
                        float espalhar = (float)GetRandomValue(-3, 3) * DEG2RAD;
                        RogueDisparar(b, e->pos, Vector2Rotate(d, espalhar), KEYLOGGER_TIRO_VEL, KEYLOGGER_TIRO_DANO, 5.0f, false);
                        TocarSomTom(sfxTiro, 1.3f);
                        e->tiros--;
                        e->timer = 0.1f;
                    }
                    if (e->tiros <= 0) { e->estado = 0; e->recarga = KEYLOGGER_INTERVALO; }
                }
                break;

            case INIMIGO_CACHE: {
                // Anda devagar atrás do jogador. Sem levar dano por um tempo, usa a energia guardada
                // para se curar (dentro do escudo de um Firewall, começa mais cedo).
                float espera = RogueNaZonaFirewall(b, e) ? CACHE_ESPERA_PROTEGIDO : CACHE_ESPERA;

                e->vel = Vector2Scale(dir, def->velocidade);
                e->semDano += dt;

                if (e->recuperando > 0.0f) {
                    e->vel = (Vector2){0};
                    e->recuperando -= dt;
                    if (GetRandomValue(0, 3) == 0) RogueParticulas(b, e->pos, LIME, 1, 50);
                    if (e->recuperando <= 0.0f) {
                        float cura = fminf(e->energia, e->hpMax - e->hp);
                        e->hp += cura;
                        e->energia = 0.0f;
                        e->semDano = 0.0f;
                        RogueParticulas(b, e->pos, LIME, 16, 140);
                        TocarSomTom(sfxPegar, 0.7f);
                    }
                }
                else if (e->energia > 0.0f && e->hp < e->hpMax && e->semDano >= espera) {
                    e->recuperando = CACHE_RECUPERAR;
                }

                // Despeja dados: anel lento de balas (os blocos brilham antes)
                if (e->recuperando <= 0.0f) {
                    if (e->estado == 0 && e->recarga <= 0.0f) { e->estado = 1; e->timer = CACHE_PREPARO; }
                    else if (e->estado == 1) {
                        e->vel = (Vector2){0};
                        e->timer -= dt;
                        if (e->timer <= 0.0f) {
                            int balas = e->elite ? CACHE_BALAS + 4 : CACHE_BALAS;     // elite: anel mais denso
                            for (int k = 0; k < balas; k++) {
                                float a = (2.0f * PI / balas) * k + e->anim;
                                RogueDisparar(b, e->pos, (Vector2){ cosf(a), sinf(a) }, 140.0f, CACHE_TIRO_DANO, 6.0f, false);
                            }
                            TocarSomTom(sfxTiro, 0.7f);
                            e->estado = 0;
                            e->recarga = CACHE_INTERVALO;
                        }
                    }
                }
            } break;

            case INIMIGO_SENTINELA: RogueAtualizarSentinela(b, e, dir, dist, dt);     break;
            case INIMIGO_RETRO:     RogueAtualizarRetro(b, e, dir, dist, ritmo, dt); break;
            case INIMIGO_JANELA:    RogueAtualizarJanela(b, e, dir, dist, dt);      break;
            case INIMIGO_TOKEN:
                if (!RogueAtualizarToken(b, e, dt)) continue;
                break;

            case INIMIGO_NUCLEO:
                // Núcleo de corrupção: parado; de tempos em tempos pulsa um anel de balas (brilha antes)
                e->vel = (Vector2){0};
                e->empurrao = (Vector2){0};
                if (e->estado == 0 && e->recarga <= 0.0f) { e->estado = 1; e->timer = NUCLEO_PREPARO; }
                else if (e->estado == 1) {
                    e->timer -= dt;
                    if (e->timer <= 0.0f) {
                        for (int k = 0; k < NUCLEO_BALAS; k++) {
                            float a = (2.0f * PI / NUCLEO_BALAS) * k + e->anim * 0.7f;
                            RogueDisparar(b, e->pos, (Vector2){ cosf(a), sinf(a) }, 125.0f, 7.0f, 6.0f, false);
                        }
                        TocarSomTom(sfxTiro, 0.5f);
                        e->estado = 0;
                        e->recarga = NUCLEO_INTERVALO;
                    }
                }
                break;

            default:
                break;
        }

        // Movimento (com o bônus do Botnet) + empurrão dos golpes
        float velocidade = e->conectado ? BOTNET_BONUS_VELOCIDADE : 1.0f;
        if (j->efeito[EFEITO_LATENCIA] > 0.0f && Vector2Distance(e->pos, j->pos) < LATENCIA_RAIO)
            velocidade *= 1.0f - LATENCIA_LENTIDAO;             // Campo de Latência
        e->pos = Vector2Add(e->pos, Vector2Scale(Vector2Add(Vector2Scale(e->vel, velocidade), e->empurrao), dt));
        e->empurrao = Vector2Scale(e->empurrao, fmaxf(0.0f, 1.0f - 8.0f * dt));
        RogueEmpurrarParaFora(&e->pos, e->raio, b->obst, b->numObst);

        // Encostou no jogador
        float contato = RogueDanoContato(e) * (e->elite ? ELITE_CONTATO : 1.0f);
        if (contato > 0.0f && enganado && dist < e->raio + RAIO_CORPO_JOGADOR)
            j->proxyHp -= contato * 3.0f * dt;                  // o holograma vai se desfazendo
        if (contato > 0.0f && Vector2Distance(e->pos, j->pos) < e->raio + RAIO_CORPO_JOGADOR)
            RogueFerirJogador(b, contato);
    }

    // Um inimigo não entra no outro
    for (int a = 0; a < MAX_INIMIGOS; a++) {
        for (int c = a + 1; c < MAX_INIMIGOS; c++) {

            Inimigo *e1 = &b->ini[a], *e2 = &b->ini[c];

            if (!e1->ativo || !e2->ativo)
                continue;

            Vector2 d = Vector2Subtract(e2->pos, e1->pos);
            float dist = Vector2Length(d), min = e1->raio + e2->raio;

            // O núcleo de corrupção não sai do lugar: só o outro é empurrado
            float w1 = (e1->tipo == INIMIGO_NUCLEO || e1->tipo == INIMIGO_JANELA) ? 0.0f : 1.0f;
            float w2 = (e2->tipo == INIMIGO_NUCLEO || e2->tipo == INIMIGO_JANELA) ? 0.0f : 1.0f;
            if (dist < min && dist > 0.01f && w1 + w2 > 0.0f) {
                Vector2 empurra = Vector2Scale(d, (min - dist) / dist / (w1 + w2));
                e1->pos = Vector2Subtract(e1->pos, Vector2Scale(empurra, w1));
                e2->pos = Vector2Add(e2->pos, Vector2Scale(empurra, w2));
            }
        }
    }
}

// Um disparo bateu perto da parede corrompida: ela racha e, sem vida, abre a passagem secreta
static void RogueAcertarParede(Biblioteca *b, ProgressoCorredor *prog, const Projetil *p)
{
    Rectangle r = PAREDE_SECRETA_ROGUE[b->paredeSecreta];
    Rectangle perto = { r.x - 16, r.y - 16, r.width + 32, r.height + 32 };

    if (!CheckCollisionPointRec(p->pos, perto))
        return;

    b->hpParede -= p->dano;
    RogueParticulas(b, p->pos, MAGENTA, 5, 120);

    if (b->hpParede > 0.0f) {
        TocarSomTom(sfxSelecao, 0.4f);
        return;
    }

    b->passagemAberta = true;
    b->mapa.no[b->mapa.no[b->noAtual].secreta].escondida = false;
    AlterarPontos(prog, 5);
    RogueAviso(b, "PASSAGEM SECRETA! (abre com a sala limpa)");
    RogueParticulas(b, CentroRetangulo(r), MAGENTA, 30, 240);
    TocarSomTom(sfxAcerto, 0.8f);
    MostrarEmocaoLuci(EMOCAO_ALEGRE, 2.0f);
    Telemetria("rogue_secreta", "descoberta", 0.0f, b->profundidade);
}

static void RogueAtualizarProjeteis(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    JogadorRogue *j = &b->j;

    for (int i = 0; i < MAX_PROJETEIS; i++) {

        Projetil *p = &b->proj[i];

        if (!p->ativo)
            continue;

        // Projétil Q (Disparo Dedutivo): vai atrás do alvo marcado
        Vector2 alvoQ;
        if (p->alvoDedutivo != 0 && RoguePosAlvoDedutivo(b, p->alvoDedutivo, &alvoQ) && Vector2Distance(alvoQ, p->pos) > 1.0f)
            p->vel = Vector2Scale(Vector2Normalize(Vector2Subtract(alvoQ, p->pos)), DEDUTIVO_VEL);

        // Teleguiado (Roteador, Botnet Reverso): vira aos poucos para o inimigo mais perto
        if (p->guiado) {
            int alvo = RogueInimigoMaisPerto(b, p->pos, ROTEADOR_AQUISICAO, p->ultimoAlvo - 1);
            if (alvo >= 0) {
                float vel = Vector2Length(p->vel);
                float atual = atan2f(p->vel.y, p->vel.x);
                Vector2 d = Vector2Subtract(b->ini[alvo].pos, p->pos);
                float diferenca = atan2f(d.y, d.x) - atual;
                while (diferenca > PI)  diferenca -= 2.0f * PI;
                while (diferenca < -PI) diferenca += 2.0f * PI;
                atual += Clamp(diferenca, -ROTEADOR_GIRO * dt, ROTEADOR_GIRO * dt);
                p->vel = (Vector2){ cosf(atual) * vel, sinf(atual) * vel };
            }
        }

        p->pos = Vector2Add(p->pos, Vector2Scale(p->vel, dt));

        // Alcance e tempo de vida (as armas novas não voam para sempre)
        if (p->alcance > 0.0f) {
            p->alcance -= Vector2Length(p->vel) * dt;
            if (p->alcance <= 0.0f) { RogueFimProjetil(b, prog, p); continue; }
        }
        if (p->vida > 0.0f) {
            p->vida -= dt;
            if (p->vida <= 0.0f) { RogueFimProjetil(b, prog, p); continue; }
        }

        // Saiu da arena ou bateu numa estante (o projétil Q passa por cima delas)
        bool bateu = !CheckCollisionPointRec(p->pos, ARENA_ROGUE);
        for (int k = 0; k < b->numObst && !bateu && p->alvoDedutivo == 0; k++)
            bateu = CheckCollisionPointRec(p->pos, b->obst[k]);

        if (bateu) {
            if (p->doJogador && b->temParedeSecreta && !b->passagemAberta)
                RogueAcertarParede(b, prog, p);
            RogueFimProjetil(b, prog, p);
            continue;
        }

        if (p->doJogador) {

            if (b->chefe.ativo && Vector2Distance(p->pos, b->chefe.pos) < CHEFE_RAIO + p->raio) {
                bool feria = RogueChefeVulneravel(&b->chefe);
                bool principal = (p->alvoDedutivo == 0 && !p->secundario);
                p->ativo = false;
                RogueFerirChefe(b, p->dano * ((feria && principal) ? RogueAnalisar(b, -1) : 1.0f), p->pos);
                if (feria && principal)
                    RogueMarcarDedutivo(b, &b->chefe.marca, &b->chefe.tempoMarca, -1, b->chefe.pos);
                if (p->arma == ARMA_ORBE && !p->secundario)
                    RogueExplodirOrbe(b, prog, p->pos);
                continue;
            }

            if (RogueLuciAcerto(b, prog, p))
                continue;

            if (RogueSilogistaAcerto(b, prog, p)) {
                if (p->arma == ARMA_ORBE && !p->secundario && b->silogista.etapa == SIL_VULNERAVEL)
                    RogueExplodirOrbe(b, prog, p->pos);
                continue;
            }

            // Barreira de energia do Firewall segura os tiros (o projétil Q passa)
            if (p->alvoDedutivo == 0 && RogueBarreiraBloqueia(b, p->pos, p->raio)) {
                RogueFimProjetil(b, prog, p);
                RogueParticulas(b, p->pos, (Color){ 0, 228, 48, 255 }, 4, 90);
                continue;
            }

            for (int k = 0; k < MAX_INIMIGOS; k++) {

                Inimigo *e = &b->ini[k];

                if (!e->ativo || e->surgindo > 0.0f || k == p->ultimoAlvo - 1 || Vector2Distance(p->pos, e->pos) > e->raio + p->raio)
                    continue;

                RogueAcertarInimigo(b, prog, p, k);
                break;
            }

        } else if (j->efeito[EFEITO_PROXY] > 0.0f && Vector2Distance(p->pos, j->proxyPos) < RAIO_CORPO_JOGADOR + p->raio) {

            p->ativo = false;                               // a bala bate no holograma
            j->proxyHp -= p->dano;
            RogueParticulas(b, p->pos, SKYBLUE, 4, 80);

        } else if (Vector2Distance(p->pos, j->pos) < RAIO_CORPO_JOGADOR + p->raio &&
                   j->invulneravel <= 0.0f && j->tempoEsquiva <= 0.0f) {

            p->ativo = false;
            RogueFerirJogador(b, p->dano);
        }
    }
}

// Fragmentos no chão voam até o jogador; itens caídos são pegos ao encostar
static void RogueAtualizarColetaveis(Biblioteca *b, float dt)
{
    for (int i = 0; i < MAX_COLETAVEIS; i++) {

        Coletavel *c = &b->col[i];

        if (!c->ativo)
            continue;

        c->anim += dt;
        c->pos = Vector2Add(c->pos, Vector2Scale(c->vel, dt));
        c->vel = Vector2Scale(c->vel, fmaxf(0.0f, 1.0f - 5.0f * dt));
        RogueEmpurrarParaFora(&c->pos, 6.0f, b->obst, b->numObst);

        float dist = Vector2Distance(c->pos, b->j.pos);

        if (c->anim > 0.4f && dist < RAIO_IMA)
            c->pos = Vector2Add(c->pos, Vector2Scale(Vector2Normalize(Vector2Subtract(b->j.pos, c->pos)), 320.0f * dt));

        if (c->anim > 0.4f && dist < RAIO_CORPO_JOGADOR + 8.0f) {

            c->ativo = false;

            if (c->fragmento) {
                b->perm->fragmentos++;
                RogueParticulas(b, c->pos, (Color){ 0, 228, 255, 255 }, 6, 100);
                TocarSomTom(sfxPegar, 1.5f);
            } else if (ITENS[c->item].temporario) {
                RogueAtivarTemporario(b, c->item);
                RogueParticulas(b, c->pos, CORES_RARIDADE[ITENS[c->item].raridade], 14, 160);
                TocarSomTom(sfxAcerto, 1.4f);
            } else {
                if (b->j.itens[c->item] < ITENS[c->item].maxPilha)
                    b->j.itens[c->item]++;
                RogueAviso(b, TextFormat("+1 %s", ITENS[c->item].nome));
                RogueParticulas(b, c->pos, CORES_RARIDADE[ITENS[c->item].raridade], 14, 160);
                TocarSomTom(sfxAcerto, 1.2f);
            }
        }
    }
}

// =============================================================
// REFORMULAÇÃO DO BLOCO 2: ATUALIZAÇÃO DOS SISTEMAS NOVOS
//   RogueAtualizarObjetivo   - ondas, reforços, núcleos, alvo prioritário, mecanismo
//   RogueAtualizarArmadilhas - feixes, zonas, torres, explosões, barreiras, bloqueios
//   RogueAtualizarAreas      - poças e explosões da build do jogador
//   RogueAtualizarEscolha    - a tela "escolha 1 de 3"
//   RogueAtualizarEvento     - eventos, sala de leitura e console de desafio
//   RogueAtualizarDesafioSala- as provas das salas de desafio
// =============================================================

// Inimigos que contam para ondas e reforços (sem ecos, spam, cópias, núcleos e o retransmissor)
static int RogueInimigosRelevantes(const Biblioteca *b)
{
    int n = 0;
    for (int i = 0; i < MAX_INIMIGOS; i++) {
        const Inimigo *e = &b->ini[i];
        if (e->ativo && !RogueInimigoPassageiro(e->tipo) && e->tipo != INIMIGO_NUCLEO && !e->prioritario)
            n++;
    }
    return n;
}

static int RogueContarTipo(const Biblioteca *b, TipoInimigo t)
{
    int n = 0;
    for (int i = 0; i < MAX_INIMIGOS; i++)
        if (b->ini[i].ativo && b->ini[i].tipo == t) n++;
    return n;
}

// O objetivo foi cumprido de outro jeito: os ecos que sobraram se desfazem (sem pontos)
static void RogueDissolverInimigos(Biblioteca *b)
{
    for (int i = 0; i < MAX_INIMIGOS; i++) {
        Inimigo *e = &b->ini[i];
        if (!e->ativo) continue;
        RogueParticulas(b, e->pos, DEF_INIMIGOS[e->tipo].cor, 10, 160);
        e->ativo = false;
    }

    for (int i = 0; i < MAX_PROJETEIS; i++)
        if (b->proj[i].ativo && !b->proj[i].doJogador) b->proj[i].ativo = false;
}

// Reforços do encontro atual (perto de um ponto, ou num ponto da sala)
static void RogueReforcar(Biblioteca *b, int quantidade, Vector2 perto, bool usarPerto)
{
    if (b->encontro < 0)
        return;

    const EncontroDef *enc = &ENCONTROS[b->encontro];
    const LayoutSala *l = layoutCombateAtual;

    for (int q = 0; q < quantidade; q++) {
        if (RogueInimigosRelevantes(b) >= REFORCO_LIMITE_VIVOS)
            return;

        TipoInimigo t = enc->grupo[GetRandomValue(0, enc->numGrupos - 1)].tipo;
        Vector2 base = usarPerto ? (Vector2){ perto.x + (float)GetRandomValue(-50, 50), perto.y + (float)GetRandomValue(-50, 50) }
                                 : ((l->numPontos > 0) ? l->pontos[GetRandomValue(0, l->numPontos - 1)] : (Vector2){ 400, 200 });
        RogueCriarInimigo(b, t, RogueLugarSurgir(b, base, DEF_INIMIGOS[t].raio));
    }
}

// Sala de combate vencida: abre as portas, deixa a recompensa anunciada na porta e conta pontos
// =============================================================
// SELETOR DE CHEFES: CONFRONTO DIRETO E RETORNO AO LOBBY
// =============================================================

// Chefes já vencidos pelo seletor nesta sessão do jogo (a recompensa sai só na 1ª vitória).
// Fica fora da Biblioteca porque RogueIniciar a zera a cada volta do corredor, e fora do save
// para não mudar o formato dele.
static unsigned int chefesVencidosSeletor = 0;

static const char *RogueDescricaoChefeSeletor(int chefe)
{
    if (chefe == CHEFE_SEL_SILOGISTA)
        return SILOGISTA_BH ? "Guardião da Câmara da Inferência. Acerte só as conclusões válidas (SHIFT = foco)."
                            : "Guardião da Câmara da Inferência. Monte o silogismo, ache o sofisma e ative o circuito.";
    return DESCRICOES_CHEFES_SELETOR[chefe];
}

static bool RogueChefeSeletorVencido(const Biblioteca *b, int chefe)
{
    if (chefesVencidosSeletor & (1u << chefe))                     return true;
    if (chefe == CHEFE_SEL_SILOGISTA && b->perm->silogistaVencido)  return true;
    if (chefe == CHEFE_SEL_ALUCINADOR && b->perm->alucinadorVencido) return true;
    return false;
}

// A recompensa do chefe só sai se ele nunca foi vencido (flags permanentes do Silogista e do
// Alucinador; para os outros três, a marca desta sessão)
static bool RogueSeletorTemRecompensa(const Biblioteca *b, int chefe)
{
    return !RogueChefeSeletorVencido(b, chefe);
}

static void RogueAbrirSeletor(Biblioteca *b)
{
    b->seletorAberto = true;
    b->seletorAnim = 0.0f;
    if (b->seletorFoco < 0 || b->seletorFoco >= NUM_CHEFES_SELETOR) b->seletorFoco = 0;
    TocarSom(sfxSelecao);
    Telemetria("seletor_aberto", "", 0.0f, b->perm->tentativas);
}

static void RogueFecharSeletor(Biblioteca *b)
{
    b->seletorAberto = false;
    TocarSomTom(sfxSelecao, 0.8f);
    Telemetria("seletor_fechado", "", b->seletorAnim, b->seletorFoco);
}

// Volta ao átrio depois de um confronto do seletor: some com o que veio do desafio e devolve
// o que o jogador tinha na mochila antes (o que comprou no Byteco não se perde)
static void RogueVoltarAoLobby(Biblioteca *b)
{
    RogueEsvaziarMochila(&b->j);
    if (b->temMochilaGuardada) {
        memcpy(b->j.itens, b->itensGuardados, sizeof(b->j.itens));
        b->j.armaExtra = b->armaGuardada;
        b->j.usandoExtra = b->usandoExtraGuardado;
        b->j.seloInferencia = b->seloGuardado;
        b->j.seloAmplificado = b->seloAmplificadoGuardado;
        b->temMochilaGuardada = false;
    }
    b->modoSeletor = false;
    b->seletorVencido = false;
    b->seletorRetorno = 0.0f;
    b->chefeSeletor = -1;
    RogueEntrarAtrio(b, false);
}

// O confronto do seletor terminou com vitória (o retorno espera os diálogos de vitória)
static void RogueSeletorVenceu(Biblioteca *b, ProgressoCorredor *prog, int pontos)
{
    if (!b->modoSeletor || b->seletorVencido)
        return;

    b->seletorVencido = true;
    b->seletorRetorno = 0.0f;
    RogueLimparBalasInimigas(b);
    if (b->recompensaSeletor && pontos > 0)
        AlterarPontos(prog, pontos);
    if (b->chefeSeletor >= 0 && b->chefeSeletor < NUM_CHEFES_SELETOR)
        chefesVencidosSeletor |= 1u << b->chefeSeletor;
    RogueAviso(b, b->recompensaSeletor ? "CONFRONTO VENCIDO! Voltando ao lobby..." : "VENCIDO! (treino: a recompensa já foi recebida)");
    TocarSom(sfxAcerto);
    Telemetria("seletor_vitoria", (b->chefeSeletor >= 0) ? NOMES_CHEFES_SELETOR[b->chefeSeletor] : "",
               (float)(GetTime() - b->inicio), b->recompensaSeletor ? 1 : 0);
}

// Começa um confronto escolhido no seletor: sem mapa procedural, com o personagem padrão
static void RogueIniciarConfronto(Biblioteca *b, int chefe)
{
    static const int camada[NUM_CHEFES_SELETOR] = { PROF_ESPECIAL_A, PROF_ESPECIAL_B, PROF_MINICHEFE, PROF_SILOGISTA, PROF_CHEFE };
    static const int especial[NUM_CHEFES_SELETOR] = { ESP_SENTINELA, ESP_RETRO, ESP_JANELA, -1, -1 };

    if (chefe < 0 || chefe >= NUM_CHEFES_SELETOR)
        return;

    // 1. Fecha o seletor
    b->seletorAberto = false;

    // 2. Marca o modo seletor (e se esta vitória ainda vale recompensa)
    b->modoSeletor = true;
    b->chefeSeletor = chefe;
    b->seletorVencido = false;
    b->seletorRetorno = 0.0f;
    b->recompensaSeletor = RogueSeletorTemRecompensa(b, chefe);
    b->especialDireto = especial[chefe];

    // 4. Personagem padrão: guarda a mochila do átrio e começa só com o Disparador
    memcpy(b->itensGuardados, b->j.itens, sizeof(b->itensGuardados));
    b->armaGuardada = b->j.armaExtra;
    b->usandoExtraGuardado = b->j.usandoExtra;
    b->seloGuardado = b->j.seloInferencia;
    b->seloAmplificadoGuardado = b->j.seloAmplificado;
    b->temMochilaGuardada = true;
    RogueEsvaziarMochila(&b->j);                // itens, armas extras, efeitos, build e selos
    b->j.ultimoUp = -1;

    // Fora do mapa: nenhum nó, nenhuma porta. A dificuldade é a da camada em que o chefe fica.
    b->noAtual = -1;
    b->indiceRota = -1;
    b->numPortas = 0;
    b->ladoEntrada = LADO_BAIXO;
    b->mapaAberto = false;
    b->combates = 0;
    b->falaPendente = NULL;
    b->conversaPendente = NULL;
    b->inicio = GetTime();
    float eq = PROF_DIFICULDADE[camada[chefe]];
    bool equilibrioProprio = (chefe >= CHEFE_SEL_JANELA);       // mini-chefe e chefes não escalam (igual à missão)
    b->profundidade = (int)(eq + 0.5f);
    b->fatorVidaInimigos  = equilibrioProprio ? 1.0f : 1.0f + DIFICULDADE_VIDA_PROF * eq;
    b->fatorRitmoInimigos = equilibrioProprio ? 1.0f : 1.0f + DIFICULDADE_RITMO_PROF * eq;
    b->fatorDanoSala      = equilibrioProprio ? 1.0f : 1.0f + DIFICULDADE_DANO_PROF * eq;

    // 3, 5, 6 e 7. RogueEntrarSala limpa a sala anterior, põe o jogador na entrada de baixo e
    // monta o confronto com o inicializador de sempre (intro, padrões, barras e vitória originais)
    TipoSalaRogue tipo = (chefe == CHEFE_SEL_SILOGISTA) ? SALA_SILOGISTA : ((chefe == CHEFE_SEL_ALUCINADOR) ? SALA_CHEFE : SALA_ESPECIAL);
    RogueEntrarSala(b, tipo);
    b->numPortas = 0;
    b->j.hp = RogueHpMax(b);
    b->j.ep = RogueEpMax(b);
    b->j.direcao = DIR_COSTAS;

    Telemetria("seletor_confronto", NOMES_CHEFES_SELETOR[chefe], 0.0f, b->recompensaSeletor ? 1 : 0);
}

// Cards do seletor: 5 lado a lado (o do foco sobe um pouco)
static Rectangle RogueRetCardSeletor(int i, int foco)
{
    float w = 140.0f, gap = 10.0f;
    float total = (float)NUM_CHEFES_SELETOR * w + (float)(NUM_CHEFES_SELETOR - 1) * gap;
    float x = 400.0f - total / 2.0f + (float)i * (w + gap);
    return (i == foco) ? (Rectangle){ x, 124, w, 312 } : (Rectangle){ x, 134, w, 300 };
}

static Rectangle RogueRetFecharSeletor(void)
{
    return (Rectangle){ 290, 450, 220, 30 };
}

// O seletor aberto: o resto do átrio espera (A/D ou setas, ENTER ou clique, ESC ou o botão)
static void RogueAtualizarSeletor(Biblioteca *b)
{
    b->seletorAnim += GetFrameTime();

    if (IsKeyPressed(KEY_ESCAPE) || IsKeyPressed(KEY_BACKSPACE)) {
        RogueFecharSeletor(b);
        return;
    }

    if (IsKeyPressed(KEY_A) || IsKeyPressed(KEY_LEFT))  { b->seletorFoco = (b->seletorFoco + NUM_CHEFES_SELETOR - 1) % NUM_CHEFES_SELETOR; TocarSom(sfxSelecao); }
    if (IsKeyPressed(KEY_D) || IsKeyPressed(KEY_RIGHT)) { b->seletorFoco = (b->seletorFoco + 1) % NUM_CHEFES_SELETOR;                      TocarSom(sfxSelecao); }

    Vector2 m = GetMousePosition();
    bool moveu = Vector2Length(GetMouseDelta()) > 0.5f;
    bool clique = IsMouseButtonPressed(MOUSE_BUTTON_LEFT);

    if (b->seletorAnim < 0.25f)                 // o E que abriu o terminal não confirma nada
        return;

    if (clique && CheckCollisionPointRec(m, RogueRetFecharSeletor())) {
        RogueFecharSeletor(b);
        return;
    }

    for (int i = 0; i < NUM_CHEFES_SELETOR; i++) {
        if (!CheckCollisionPointRec(m, RogueRetCardSeletor(i, b->seletorFoco))) continue;
        if (moveu && b->seletorFoco != i) { b->seletorFoco = i; TocarSom(sfxSelecao); }
        if (clique) { RogueIniciarConfronto(b, i); return; }
    }

    if (IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_KP_ENTER) || IsKeyPressed(KEY_E))
        RogueIniciarConfronto(b, b->seletorFoco);
}

static void RogueConcluirCombate(Biblioteca *b, ProgressoCorredor *prog)
{
    // Seletor de chefes: sem recompensa no chão (a build é descartada) e de volta ao átrio
    if (b->modoSeletor) {
        b->limpa = true;
        RogueDissolverInimigos(b);
        RogueSeletorVenceu(b, prog, PONTOS_SALA_ROGUE + 12);
        return;
    }

    b->limpa = true;
    RogueSalaConcluida(b);
    RogueDissolverInimigos(b);

    // Às vezes o combate deixa também um upgrade passivo (sistema antigo, preservado)
    int upgrade = RogueSortearItem(b, 0, true);
    if (upgrade >= 0 && GetRandomValue(1, 100) <= CHANCE_UPGRADE_SALA)
        RogueSoltar(b, (Vector2){ 400, 330 }, false, (TipoItem)upgrade);

    TipoRecompensa rec = RECOMPENSA_MELHORIA;
    if (b->eventoCombate) {
        b->perm->fragmentos += 10;
        RogueAviso(b, "BANCO ESTABILIZADO! +10 FRAGMENTOS");
    } else if (b->noAtual >= 0 && b->mapa.no[b->noAtual].recompensa != RECOMPENSA_NENHUMA) {
        rec = b->mapa.no[b->noAtual].recompensa;
    }
    RogueColocarRecompensa(b, rec);

    if (b->objetivoSala != OBJC_ELIMINAR && !b->eventoCombate)
        RogueAviso(b, "OBJETIVO CUMPRIDO!");

    AlterarPontos(prog, PONTOS_SALA_ROGUE + ((b->tipoSala == SALA_ELITE) ? 8 : 0) + ((b->tipoSala == SALA_ESPECIAL) ? 12 : 0));
    TocarSom(sfxAcerto);
    MostrarEmocaoLuci(EMOCAO_ALEGRE, 2.0f);
    Telemetria("rogue_sala_limpa", TextFormat("sala %d %s", b->indiceRota + 1, NOMES_OBJC[b->objetivoSala]), (float)(GetTime() - b->inicio), b->abatidos);
}

static void RogueAtualizarObjetivo(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    bool combate = (b->tipoSala == SALA_COMBATE || b->tipoSala == SALA_ELITE || b->tipoSala == SALA_ESPECIAL ||
                    (b->tipoSala == SALA_EVENTO && b->eventoCombate));
    if (!combate || b->limpa || b->desafioAberto)
        return;

    switch (b->objetivoSala) {

        case OBJC_ELIMINAR:
            // Ondas: a próxima chega (com aviso) quando sobra no máximo um inimigo
            if (b->ondaAtual + 1 < b->numOndas) {
                if (b->avisoOnda > 0.0f) {
                    b->avisoOnda -= dt;
                    if (b->avisoOnda <= 0.0f) { b->ondaAtual++; RogueSurgirOnda(b, b->ondaAtual); }
                } else if (RogueInimigosRelevantes(b) <= 1) {
                    b->avisoOnda = ONDA_AVISO;
                    RogueAviso(b, TextFormat("ONDA %d/%d CHEGANDO!", b->ondaAtual + 2, b->numOndas));
                    TocarSomTom(sfxErro, 0.7f);
                }
                return;
            }
            if (RogueInimigosVivos(b) == 0)
                RogueConcluirCombate(b, prog);
            break;

        case OBJC_SOBREVIVER:
            b->tempoObjetivo -= dt;
            b->reforco -= dt;
            if (b->reforco <= 0.0f) {
                b->reforco = REFORCO_INTERVALO;
                RogueReforcar(b, 2 + b->profundidade / 3, (Vector2){0}, false);
            }
            if (b->tempoObjetivo <= 0.0f)
                RogueConcluirCombate(b, prog);
            break;

        case OBJC_NUCLEOS: {
            if (RogueContarTipo(b, INIMIGO_NUCLEO) == 0) {
                RogueConcluirCombate(b, prog);
                break;
            }
            // Enquanto houver núcleo, ecos novos nascem perto de um deles
            b->reforco -= dt;
            if (b->reforco <= 0.0f) {
                b->reforco = REFORCO_INTERVALO + 1.0f;
                int vivos[MAX_INIMIGOS], n = 0;
                for (int i = 0; i < MAX_INIMIGOS; i++)
                    if (b->ini[i].ativo && b->ini[i].tipo == INIMIGO_NUCLEO) vivos[n++] = i;
                if (n > 0) RogueReforcar(b, 2, b->ini[vivos[GetRandomValue(0, n - 1)]].pos, true);
            }
        } break;

        case OBJC_PRIORITARIO:
            if (b->alvoPrioritario >= 0 && !b->ini[b->alvoPrioritario].ativo)
                b->alvoPrioritario = -1;

            if (b->alvoPrioritario >= 0) {
                b->reforco -= dt;
                if (b->reforco <= 0.0f) {
                    b->reforco = REFORCO_INTERVALO;
                    RogueReforcar(b, 2, b->ini[b->alvoPrioritario].pos, true);
                }
            } else if (RogueInimigosVivos(b) == 0) {
                RogueConcluirCombate(b, prog);
            }
            break;

        case OBJC_MECANISMO: {
            int restantes = 0;
            for (int k = 0; k < b->numMecanismos; k++) {
                if (b->mecanismoDesligado[k]) continue;
                restantes++;

                bool perto = Vector2Distance(b->j.pos, b->posMecanismo[k]) < MECANISMO_RAIO;
                if (perto && IsKeyDown(KEY_E) && b->j.tempoEsquiva <= 0.0f) {
                    b->progressoMecanismo[k] += dt;
                    if (GetRandomValue(0, 3) == 0) RogueParticulas(b, b->posMecanismo[k], (Color){ 0, 228, 255, 255 }, 1, 60);
                    if (b->progressoMecanismo[k] >= MECANISMO_TEMPO) {
                        b->mecanismoDesligado[k] = true;
                        restantes--;
                        RogueAviso(b, TextFormat("CONSOLE DESLIGADO (%d/%d)", b->numMecanismos - restantes, b->numMecanismos));
                        RogueParticulas(b, b->posMecanismo[k], (Color){ 0, 228, 255, 255 }, 20, 200);
                        TocarSomTom(sfxAcerto, 1.1f);
                    }
                } else {
                    b->progressoMecanismo[k] = fmaxf(0.0f, b->progressoMecanismo[k] - dt * 0.5f);
                }
            }

            if (restantes == 0) {
                RogueConcluirCombate(b, prog);
                break;
            }

            b->reforco -= dt;
            if (b->reforco <= 0.0f) {
                b->reforco = REFORCO_INTERVALO;
                RogueReforcar(b, 2, (Vector2){0}, false);
            }
        } break;

        default:
            break;
    }
}

// Barreiras e bloqueios sólidos entram no fim do vetor de estantes (colisão de todo mundo)
static void RogueAtualizarObstaculosDinamicos(Biblioteca *b)
{
    b->numObst = b->numObstFixos;

    for (int i = 0; i < MAX_ARMADILHAS && b->numObst < MAX_OBSTACULOS; i++) {
        const Armadilha *a = &b->arm[i];
        if (!a->ativo) continue;
        if (a->tipo == ARM_BARREIRA || (a->tipo == ARM_BLOQUEIO && a->fase == 2))
            b->obst[b->numObst++] = a->r;
    }
}

static void RogueAtualizarArmadilhas(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    JogadorRogue *j = &b->j;

    // Sala vencida: as armadilhas desligam (a não ser durante o desafio de integridade)
    bool desligadas = b->limpa && !(b->tipoSala == SALA_DESAFIO && b->estadoDesafio == 1);

    for (int i = 0; i < MAX_ARMADILHAS; i++) {

        Armadilha *a = &b->arm[i];
        if (!a->ativo) continue;

        if (desligadas) {
            if (a->tipo != ARM_BARREIRA) a->fase = 0;
            continue;
        }

        switch (a->tipo) {

            case ARM_FEIXE:
                a->timer -= dt;
                if (a->timer <= 0.0f) {
                    a->fase = (a->fase + 1) % 3;
                    a->timer = (a->fase == 1) ? FEIXE_AVISO : ((a->fase == 2) ? FEIXE_ATIVO : FEIXE_DESCANSO);
                    if (a->fase == 2) TocarSomTom(sfxTiro, 0.4f);
                    if (a->fase == 0) {
                        // O feixe muda de lugar a cada ciclo
                        float passo = (float)GetRandomValue(60, 130) * ((GetRandomValue(0, 1) == 0) ? -1.0f : 1.0f);
                        if (a->vertical) a->r.x = Clamp(a->r.x + passo, 110.0f, 680.0f);
                        else             a->r.y = Clamp(a->r.y + passo, 120.0f, 450.0f);
                    }
                }
                if (a->fase == 2 && CheckCollisionCircleRec(j->pos, RAIO_CORPO_JOGADOR, a->r))
                    RogueFerirJogador(b, FEIXE_DANO);
                break;

            case ARM_ZONA:
                a->timer -= dt;
                if (a->timer <= 0.0f) {
                    a->fase = (a->fase + 1) % 3;
                    a->timer = (a->fase == 1) ? 0.8f : ((a->fase == 2) ? ZONA_LIGADA : ZONA_DESLIGADA);
                }
                if (a->fase == 2) {
                    a->tick -= dt;
                    if (a->tick <= 0.0f && Vector2Distance(j->pos, a->pos) < a->raio) {
                        a->tick = ZONA_TICK;
                        RogueFerirJogador(b, ZONA_DANO);
                    }
                }
                break;

            case ARM_TORRE:
                a->timer -= dt;
                if (a->fase == 0 && a->timer <= 0.0f) { a->fase = 1; a->timer = TORRE_PREPARO; }
                else if (a->fase == 1 && a->timer <= 0.0f) {
                    Vector2 d = Vector2Subtract(j->pos, a->pos);
                    d = (Vector2Length(d) > 1.0f) ? Vector2Normalize(d) : (Vector2){ 0, 1 };
                    RogueDisparar(b, a->pos, d, TORRE_TIRO_VEL, TORRE_TIRO_DANO, 6.0f, false);
                    TocarSomTom(sfxTiro, 0.9f);
                    a->fase = 0;
                    a->timer = TORRE_INTERVALO;
                }
                break;

            case ARM_EXPLOSAO:
                a->timer -= dt;
                if (a->fase == 0 && a->timer <= 0.0f) {
                    // Marca o chão perto do jogador (dá tempo de sair)
                    a->fase = 1;
                    a->timer = EXPLOSAO_AVISO;
                    a->pos = (Vector2){ Clamp(j->pos.x + (float)GetRandomValue(-40, 40), ARENA_ROGUE.x + 30, ARENA_ROGUE.x + ARENA_ROGUE.width - 30),
                                        Clamp(j->pos.y + (float)GetRandomValue(-40, 40), ARENA_ROGUE.y + 30, ARENA_ROGUE.y + ARENA_ROGUE.height - 30) };
                }
                else if (a->fase == 1 && a->timer <= 0.0f) {
                    // Explode e fere todo mundo por perto (dá para atrair os inimigos)
                    if (Vector2Distance(j->pos, a->pos) < a->raio + RAIO_CORPO_JOGADOR * 0.5f)
                        RogueFerirJogador(b, EXPLOSAO_DANO);
                    for (int k = 0; k < MAX_INIMIGOS; k++) {
                        Inimigo *e = &b->ini[k];
                        if (!e->ativo || e->selado || e->surgindo > 0.0f || Vector2Distance(e->pos, a->pos) > a->raio + e->raio) continue;
                        Vector2 d = Vector2Subtract(e->pos, a->pos);
                        RogueFerirInimigo(b, prog, e, EXPLOSAO_DANO, (Vector2Length(d) > 0.1f) ? Vector2Normalize(d) : (Vector2){ 0, -1 });
                    }
                    RogueAnel(b, a->pos, a->raio, MAGENTA);
                    RogueParticulas(b, a->pos, MAGENTA, 18, 220);
                    TocarSomTom(sfxDano, 0.7f);
                    a->fase = 0;
                    a->timer = EXPLOSAO_INTERVALO;
                }
                break;

            case ARM_BARREIRA:
                if (a->vertical) {
                    a->r.x += a->vel * dt;
                    if (a->r.x < a->limiteA || a->r.x > a->limiteB) { a->vel = -a->vel; a->r.x = Clamp(a->r.x, a->limiteA, a->limiteB); }
                } else {
                    a->r.y += a->vel * dt;
                    if (a->r.y < a->limiteA || a->r.y > a->limiteB) { a->vel = -a->vel; a->r.y = Clamp(a->r.y, a->limiteA, a->limiteB); }
                }
                break;

            case ARM_BLOQUEIO:
                a->timer -= dt;
                if (a->timer <= 0.0f) {
                    a->fase = (a->fase + 1) % 3;
                    a->timer = (a->fase == 1) ? BLOQUEIO_AVISO : ((a->fase == 2) ? BLOQUEIO_SOLIDO : BLOQUEIO_LIVRE);
                }
                break;

            default:
                break;
        }
    }

    RogueAtualizarObstaculosDinamicos(b);
}

static void RogueAtualizarAreas(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    for (int i = 0; i < MAX_AREAS; i++) {

        AreaDano *a = &b->areas[i];
        if (!a->ativo) continue;

        if (a->atraso > 0.0f) {
            a->atraso -= dt;
            if (a->atraso <= 0.0f && a->danoInstantaneo > 0.0f) {
                b->golpeSecundario = true;
                RogueDanoArea(b, prog, a->pos, a->raio, a->danoInstantaneo, 160.0f);
                b->golpeSecundario = false;
                RogueAnel(b, a->pos, a->raio, a->cor);
                RogueParticulas(b, a->pos, a->cor, 14, 200);
                TocarSomTom(sfxAcerto, 0.8f);
                a->danoInstantaneo = 0.0f;
            }
            continue;
        }

        a->vida -= dt;
        if (a->vida <= 0.0f) { a->ativo = false; continue; }

        if (a->dps > 0.0f) {
            a->tick -= dt;
            if (a->tick <= 0.0f) {
                a->tick = 0.25f;
                for (int k = 0; k < MAX_INIMIGOS; k++) {
                    Inimigo *e = &b->ini[k];
                    if (!e->ativo || e->selado || e->surgindo > 0.0f || Vector2Distance(e->pos, a->pos) > a->raio + e->raio) continue;
                    b->golpeSecundario = true;
                    RogueFerirInimigo(b, prog, e, a->dps * 0.25f, (Vector2){ 0, 0 });
                    b->golpeSecundario = false;
                }
            }
        }
    }
}

// ---------- Escolha 1 de 3 ----------

static bool RogueUpgradeDisponivel(const Biblioteca *b, int u)
{
    const DefUpgrade *d = &UPGRADES[u];

    if (b->j.up[u] >= d->maxNivel)
        return false;
    for (int k = 0; k < NUM_UPGRADES; k++)
        if ((d->requer & BIT_UP(k)) && b->j.up[k] == 0)
            return false;
    if (d->arma >= 0 && d->arma != ARMA_DISPARADOR && (int)b->j.armaExtra != d->arma)
        return false;
    return true;
}

// Peso no sorteio: raridade (raras ficam mais comuns no fundo do mapa), sinergias e o que já está na build
static int RoguePesoUpgrade(const Biblioteca *b, int u, ModoEscolha modo)
{
    const DefUpgrade *d = &UPGRADES[u];

    if (modo == ESCOLHA_ARMA && d->categoria != CAT_APRIMORAMENTO && d->categoria != CAT_DISPARO)
        return 0;

    int peso = PESO_RARIDADE[d->raridade];
    if (d->raridade == RARIDADE_RARA)    peso += 4 * b->profundidade;
    if (d->raridade == RARIDADE_INCOMUM) peso += 2 * b->profundidade;
    if (modo == ESCOLHA_RARA && d->raridade == RARIDADE_COMUM) peso /= 6;
    if (d->categoria == CAT_SINERGIA)     peso *= 3;
    if (d->categoria == CAT_APRIMORAMENTO) peso += (modo == ESCOLHA_ARMA) ? 40 : 10;
    if (b->j.up[u] > 0)                    peso += 12;      // aprofundar a build também é uma escolha
    return (peso < 1) ? 1 : peso;
}

static int RogueSortearUpgrade(const Biblioteca *b, ModoEscolha modo, unsigned long long excluir, int raridade)
{
    int cand[NUM_UPGRADES], peso[NUM_UPGRADES], n = 0, total = 0;

    for (int u = 0; u < NUM_UPGRADES; u++) {
        if ((excluir & BIT_UP(u)) || !RogueUpgradeDisponivel(b, u))         continue;
        if (raridade >= 0 && (int)UPGRADES[u].raridade != raridade)        continue;
        int p = RoguePesoUpgrade(b, u, modo);
        if (p <= 0) continue;
        cand[n] = u; peso[n] = p; total += p; n++;
    }

    if (n == 0)
        return -1;

    int r = GetRandomValue(1, total);
    for (int i = 0; i < n; i++) {
        r -= peso[i];
        if (r <= 0) return cand[i];
    }
    return cand[n - 1];
}

static void RogueGerarOpcoes(Biblioteca *b, ModoEscolha modo)
{
    unsigned long long usados = 0;
    unsigned int itensUsados = 0;
    b->numOpcoes = 0;

    // Arsenal: uma arma nova (duas, se ainda não houver arma extra) e aprimoramentos de disparo
    if (modo == ESCOLHA_ARMA) {
        TipoArma a = RogueSortearArma(b, 0);
        if (a != ARMA_DISPARADOR) b->opcoes[b->numOpcoes++] = (OpcaoEscolha){ OPC_ARMA, a };
        if (b->j.armaExtra == ARMA_DISPARADOR && a != ARMA_DISPARADOR) {
            TipoArma a2 = RogueSortearArma(b, 1u << a);
            if (a2 != ARMA_DISPARADOR && a2 != a) b->opcoes[b->numOpcoes++] = (OpcaoEscolha){ OPC_ARMA, a2 };
        }
    }

    // Melhoria rara: pelo menos uma das três é rara (quando ainda existe alguma)
    if (modo == ESCOLHA_RARA) {
        int u = RogueSortearUpgrade(b, modo, usados, RARIDADE_RARA);
        if (u >= 0) { b->opcoes[b->numOpcoes++] = (OpcaoEscolha){ OPC_UPGRADE, u }; usados |= BIT_UP(u); }
    }

    while (b->numOpcoes < 3) {
        int u = RogueSortearUpgrade(b, modo, usados, -1);
        if (u < 0) break;
        b->opcoes[b->numOpcoes++] = (OpcaoEscolha){ OPC_UPGRADE, u };
        usados |= BIT_UP(u);
    }

    // Sem melhorias suficientes: completa com os upgrades passivos antigos
    while (b->numOpcoes < 3) {
        int it = RogueSortearItem(b, itensUsados, true);
        if (it < 0) break;
        b->opcoes[b->numOpcoes++] = (OpcaoEscolha){ OPC_ITEM, it };
        itensUsados |= 1u << it;
    }

    if (b->numOpcoes == 0)
        b->opcoes[b->numOpcoes++] = (OpcaoEscolha){ OPC_FRAGMENTOS, FC_OPCAO_RESERVA };

    // Embaralha (a rara não fica sempre no mesmo lugar)
    for (int i = b->numOpcoes - 1; i > 0; i--) {
        int k = GetRandomValue(0, i);
        OpcaoEscolha t = b->opcoes[i]; b->opcoes[i] = b->opcoes[k]; b->opcoes[k] = t;
    }
}

static void RogueAbrirEscolha(Biblioteca *b, ModoEscolha modo, bool gratis)
{
    RogueGerarOpcoes(b, modo);
    b->escolhaAberta = true;
    b->escolhaGratis = gratis;
    b->modoEscolha = modo;
    b->selecaoEscolha = 0;
    b->animEscolha = 0.0f;
    TocarSomTom(sfxAcerto, 1.3f);
}

static void RogueAplicarOpcao(Biblioteca *b, OpcaoEscolha o)
{
    JogadorRogue *j = &b->j;
    char texto[96];

    switch (o.tipo) {

        case OPC_UPGRADE: {
            // Sinergias que já podiam aparecer antes desta escolha
            unsigned long long antes = 0;
            for (int s = 0; s < NUM_UPGRADES; s++)
                if (UPGRADES[s].categoria == CAT_SINERGIA && RogueUpgradeDisponivel(b, s)) antes |= BIT_UP(s);

            j->up[o.id]++;
            j->ultimoUp = o.id;
            if (o.id == UP_VIDA) j->hp = fminf(RogueHpMax(b), j->hp + UP_VIDA_NIVEL);

            if (j->up[o.id] > 1) snprintf(texto, sizeof(texto), "%s NÍVEL %d", UPGRADES[o.id].nome, j->up[o.id]);
            else                 snprintf(texto, sizeof(texto), "NOVA MELHORIA: %s", UPGRADES[o.id].nome);
            RogueAviso(b, texto);

            for (int s = 0; s < NUM_UPGRADES; s++)
                if (UPGRADES[s].categoria == CAT_SINERGIA && !(antes & BIT_UP(s)) && RogueUpgradeDisponivel(b, s)) {
                    snprintf(texto, sizeof(texto), "Luci: Essa combinação abre uma SINERGIA: %s!", UPGRADES[s].nome);
                    RogueRecadoLuci(b, texto);
                    b->luciMsgTempo = 4.0f;
                    break;
                }

            RogueParticulas(b, j->pos, CORES_RARIDADE[UPGRADES[o.id].raridade], 26, 200);
            Telemetria("rogue_build", UPGRADES[o.id].nome, (float)UPGRADES[o.id].raridade, j->up[o.id]);
        } break;

        case OPC_ITEM:
            if (j->itens[o.id] < ITENS[o.id].maxPilha) j->itens[o.id]++;
            snprintf(texto, sizeof(texto), "Pegou: %s", ITENS[o.id].nome);
            RogueAviso(b, texto);
            RogueParticulas(b, j->pos, CORES_RARIDADE[ITENS[o.id].raridade], 20, 180);
            Telemetria("rogue_build", ITENS[o.id].nome, (float)ITENS[o.id].raridade, j->itens[o.id]);
            break;

        case OPC_ARMA:
            j->armaExtra = (TipoArma)o.id;           // substitui a arma secundária
            j->usandoExtra = true;
            j->carga = 0.0f;
            snprintf(texto, sizeof(texto), "Pegou: %s (TAB troca)", DEF_ARMAS[o.id].nome);
            RogueAviso(b, texto);
            RogueParticulas(b, j->pos, DEF_ARMAS[o.id].cor, 20, 180);
            Telemetria("rogue_build", DEF_ARMAS[o.id].nome, (float)DEF_ARMAS[o.id].raridade, 1);
            break;

        default:
            b->perm->fragmentos += FC_OPCAO_RESERVA;
            snprintf(texto, sizeof(texto), "+%d FRAGMENTOS DE CONHECIMENTO", FC_OPCAO_RESERVA);
            RogueAviso(b, texto);
            break;
    }

    TocarSomTom(sfxAcerto, 1.2f);
}

// Cartas da escolha na tela (também usadas no desenho e no mouse)
static Rectangle RogueCartaEscolha(int i, int n)
{
    float w = 222.0f, h = 300.0f, gap = 16.0f;
    float total = (float)n * w + (float)(n - 1) * gap;
    return (Rectangle){ 400.0f - total / 2.0f + (float)i * (w + gap), 132.0f, w, h };
}

#define RET_RECUSAR_ESCOLHA ((Rectangle){ 310, 480, 180, 26 })

static void RogueAtualizarEscolha(Biblioteca *b)
{
    int n = b->numOpcoes;
    b->animEscolha += GetFrameTime();

    if (IsKeyPressed(KEY_A) || IsKeyPressed(KEY_LEFT))  { b->selecaoEscolha = (b->selecaoEscolha + n - 1) % n; TocarSom(sfxSelecao); }
    if (IsKeyPressed(KEY_D) || IsKeyPressed(KEY_RIGHT)) { b->selecaoEscolha = (b->selecaoEscolha + 1) % n;     TocarSom(sfxSelecao); }
    for (int i = 0; i < n; i++)
        if (IsKeyPressed(KEY_ONE + i)) { b->selecaoEscolha = i; TocarSom(sfxSelecao); }

    bool clique = false;
    Vector2 m = GetMousePosition();
    for (int i = 0; i < n; i++)
        if (CheckCollisionPointRec(m, RogueCartaEscolha(i, n))) {
            if (Vector2Length(GetMouseDelta()) > 0.5f) b->selecaoEscolha = i;
            if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT)) { b->selecaoEscolha = i; clique = true; }
        }

    if (b->animEscolha < 0.35f)             // evita confirmar sem querer ao abrir
        return;

    if (IsKeyPressed(KEY_BACKSPACE) || (CliqueMouse() && MouseEm(RET_RECUSAR_ESCOLHA))) {
        b->perm->fragmentos += FC_RECUSAR_ESCOLHA;
        b->escolhaAberta = false;
        RogueAviso(b, TextFormat("Recusou: +%d FRAGMENTOS", FC_RECUSAR_ESCOLHA));
        TocarSom(sfxSelecao);
        return;
    }

    if (clique || IsKeyPressed(KEY_E) || IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_SPACE)) {
        RogueAplicarOpcao(b, b->opcoes[b->selecaoEscolha]);
        b->escolhaAberta = false;
    }
}

// Tocou na recompensa do chão
static void RogueUsarRecompensa(Biblioteca *b)
{
    JogadorRogue *j = &b->j;
    b->recompensaAtiva = false;

    switch (b->recompensaTipo) {
        case RECOMPENSA_MELHORIA: RogueAbrirEscolha(b, ESCOLHA_NORMAL, false); break;
        case RECOMPENSA_RARA:     RogueAbrirEscolha(b, ESCOLHA_RARA, false);   break;
        case RECOMPENSA_ARMA:     RogueAbrirEscolha(b, ESCOLHA_ARMA, false);   break;

        case RECOMPENSA_FRAGMENTOS: {
            int n = 5 + b->profundidade;
            for (int k = 0; k < n; k++)
                RogueSoltar(b, b->recompensaPos, true, ITEM_ANTIVIRUS);
            RogueAviso(b, TextFormat("BIBLIOTECA RESTAURADA: %d FRAGMENTOS!", n));
            TocarSomTom(sfxAcerto, 1.5f);
        } break;

        case RECOMPENSA_VIDA:
            j->hp = fminf(RogueHpMax(b), j->hp + RogueHpMax(b) * 0.35f);
            j->itens[ITEM_ANTIVIRUS]++;
            RogueAviso(b, "RESTAURAÇÃO: +35% de vida e 1 Antivírus");
            RogueParticulas(b, j->pos, LIME, 24, 180);
            TocarSomTom(sfxPegar, 0.9f);
            break;

        default:
            break;
    }

    Telemetria("rogue_recompensa_sala", NOMES_RECOMPENSA[b->recompensaTipo], (float)b->profundidade, b->indiceRota);
}

// ---------- Eventos, sala de leitura e console de desafio ----------

typedef struct {
    const char *titulo;
    char texto[320];
    int numOpcoes;
    char rotulo[3][160];
    char efeito[3][200];
    bool disponivel[3];
} TelaEvento;

static const char *NOMES_PENALIDADE[3] = { "+20% de dano recebido", "-10% de velocidade", "-15% de vida máxima" };

static void RogueMontarTelaEvento(const Biblioteca *b, TelaEvento *t)
{
    memset(t, 0, sizeof(*t));
    for (int i = 0; i < 3; i++) t->disponivel[i] = true;

    #define OPCAO(i, r, e) do { snprintf(t->rotulo[i], sizeof(t->rotulo[i]), "%s", (r)); \
                                snprintf(t->efeito[i], sizeof(t->efeito[i]), "%s", (e)); } while (0)

    switch (b->evento) {

        case EVT_ARQUIVO_CORROMPIDO:
            t->titulo = "ARQUIVO CORROMPIDO";
            snprintf(t->texto, sizeof(t->texto), "Um arquivo pulsa com dados instáveis. Lá dentro há algo raro, mas abri-lo sem cuidado vai corromper parte da sua integridade.");
            t->numOpcoes = 3;
            OPCAO(0, "Abrir o arquivo", "Perde 30% da vida atual. Escolha 1 de 3 melhorias RARAS.");
            OPCAO(1, "Verificar com a Lente", "Gasta 1 Lente da Verificação: abre com segurança e escolhe 1 de 3 melhorias.");
            OPCAO(2, "Deixar para lá", "Nada acontece.");
            t->disponivel[0] = b->j.hp > 10.0f;
            t->disponivel[1] = b->j.itens[ITEM_LENTE] > 0;
            break;

        case EVT_BANCO_INSTAVEL:
            t->titulo = "BANCO DE DADOS INSTÁVEL";
            snprintf(t->texto, sizeof(t->texto), "Um banco de dados está vazando Fragmentos de Conhecimento. Estabilizá-lo vai atrair ecos de ELITE.");
            t->numOpcoes = 3;
            OPCAO(0, "Estabilizar o banco", "Combate contra elites. Vencendo: +10 Fragmentos e 1 de 3 melhorias.");
            OPCAO(1, "Coletar o que vazou", "+3 Fragmentos agora, sem luta.");
            OPCAO(2, "Ignorar", "Nada acontece.");
            break;

        case EVT_MODELO_EXPERIMENTAL:
            t->titulo = "MODELO EXPERIMENTAL";
            snprintf(t->texto, sizeof(t->texto), "Uma versão beta de você mesmo oferece um poder que ninguém testou. Todo modelo sem testes tem efeitos colaterais.");
            t->numOpcoes = 2;
            OPCAO(0, "Instalar a versão beta", TextFormat("1 de 3 melhorias RARAS. Efeito colateral até o fim da tentativa: %s.", NOMES_PENALIDADE[b->varianteEvento]));
            OPCAO(1, "Recusar", "Testar antes de confiar. A Luci aprova: +1 de estabilidade.");
            t->disponivel[0] = !(b->j.penalidade & (1 << b->varianteEvento));
            break;

        case EVT_MEMORIA:
            t->titulo = "MEMÓRIA ESQUECIDA";
            snprintf(t->texto, sizeof(t->texto), "Entre as estantes, um registro antigo pisca com a assinatura da Luci. Ela fica em silêncio quando você se aproxima.");
            t->numOpcoes = 2;
            OPCAO(0, "Ler o registro com a Luci", "Uma memória dela. A Luci se estabiliza (+1).");
            OPCAO(1, "Arquivar para o Byteco", "+4 Fragmentos de Conhecimento.");
            break;

        case EVT_PROTOCOLO:
            t->titulo = "PROTOCOLO DE EMERGÊNCIA";
            snprintf(t->texto, sizeof(t->texto), "Um terminal de manutenção oferece restauração. Todo protocolo cobra um preço.");
            t->numOpcoes = 3;
            OPCAO(0, "Restauração paga", "Recupera 60% da vida. Custa 6 Fragmentos.");
            OPCAO(1, "Restauração por troca", (b->j.ultimoUp >= 0)
                  ? TextFormat("Recupera 40%% da vida. Perde um nível de: %s.", UPGRADES[b->j.ultimoUp].nome)
                  : "Recupera 40% da vida. Perde um nível da última melhoria (você não tem nenhuma).");
            OPCAO(2, "Recusar", "Nada acontece.");
            t->disponivel[0] = b->perm->fragmentos >= 6;
            t->disponivel[1] = b->j.ultimoUp >= 0 && b->j.up[b->j.ultimoUp] > 0;
            break;

        case EVT_FONTE_FALSA:
        case EVT_RESPOSTA_IA: {
            const QuizEvento *q = (b->evento == EVT_FONTE_FALSA) ? &QUIZ_FONTES[b->varianteEvento] : &QUIZ_RESPOSTAS[b->varianteEvento];
            t->titulo = (b->evento == EVT_FONTE_FALSA) ? "FONTE DUVIDOSA" : "RESPOSTA SUSPEITA";
            snprintf(t->texto, sizeof(t->texto), "%s", q->texto);
            t->numOpcoes = 3;
            for (int i = 0; i < 3; i++) OPCAO(i, q->opcoes[i], "");
        } break;

        case EVT_CONFIANCA_LUCI:
            t->titulo = "UMA PERGUNTA DA LUCI";
            snprintf(t->texto, sizeof(t->texto), "Luci: Thomas... posso perguntar uma coisa? Com tudo o que está acontecendo aqui... você confia em mim?");
            t->numOpcoes = 3;
            OPCAO(0, "\"Confio, mas vou conferir o que você disser.\"", "Confiança com verificação. (+1 de estabilidade)");
            OPCAO(1, "\"Confio totalmente.\"", "Ela fica feliz e divide um atalho: +3 Fragmentos.");
            OPCAO(2, "\"Ainda não sei.\"", "Uma resposta honesta.");
            break;

        case EVT_DESCANSO:
            t->titulo = "SALA DE LEITURA";
            snprintf(t->texto, sizeof(t->texto), "Poltronas antigas e uma luz calma. Os ecos não alcançam este lugar. Há tempo para UMA coisa.");
            t->numOpcoes = 3;
            OPCAO(0, "Descansar", "Recupera 40% da vida máxima.");
            OPCAO(1, "Conversar com a Luci", "+1 de estabilidade e uma conversa.");
            OPCAO(2, "Estudar", "Uma melhoria que você já tem sobe um nível.");
            t->disponivel[2] = false;
            for (int u = 0; u < NUM_UPGRADES; u++)
                if (b->j.up[u] > 0 && b->j.up[u] < UPGRADES[u].maxNivel) t->disponivel[2] = true;
            break;

        default:    // EVT_DESAFIO
            if (b->desafioSala == DESAFIO_SALA_ECOS) {
                t->titulo = "DESAFIO: VERIFICAÇÃO RELÂMPAGO";
                snprintf(t->texto, sizeof(t->texto), "Ecos falsos vão surgir pela sala. Destrua %d antes que o tempo acabe (%d s). Eco que ninguém confere explode em balas!",
                         DESAFIO_ECOS_META, (int)DESAFIO_ECOS_TEMPO);
            } else {
                t->titulo = "DESAFIO: TESTE DE INTEGRIDADE";
                snprintf(t->texto, sizeof(t->texto), "Sobreviva %d s entre feixes e explosões de dados levando no máximo %d golpes. Esquive com atenção aos avisos!",
                         (int)DESAFIO_INTEG_TEMPO, DESAFIO_INTEG_GOLPES);
            }
            t->numOpcoes = 2;
            OPCAO(0, "Aceitar o desafio", "Vencendo: 1 de 3 melhorias RARAS e +5 Fragmentos.");
            OPCAO(1, "Agora não", "A porta continua aberta. Dá para voltar ao console.");
            break;
    }

    #undef OPCAO
}

static void RogueResultadoEvento(Biblioteca *b, const char *texto)
{
    snprintf(b->resultadoEvento, sizeof(b->resultadoEvento), "%s", texto);
    b->eventoResolvido = true;
    b->eventoUsado = true;
}

static void RogueResolverEvento(Biblioteca *b, ProgressoCorredor *prog, SessaoDialogo *dlg, int op)
{
    JogadorRogue *j = &b->j;
    Telemetria("rogue_evento", TextFormat("%d", (int)b->evento), (float)op, b->profundidade);

    switch (b->evento) {

        case EVT_ARQUIVO_CORROMPIDO:
            if (op == 0) {
                j->hp = fmaxf(1.0f, j->hp * 0.7f);
                b->escolhaPendente = ESCOLHA_RARA;
                b->tremor = 0.25f;
                RogueResultadoEvento(b, "Os dados corrompidos queimam a sua integridade... mas algo valioso se revela.");
            } else if (op == 1) {
                j->itens[ITEM_LENTE]--;
                b->escolhaPendente = ESCOLHA_NORMAL;
                RogueResultadoEvento(b, "A Lente separa o que é dado do que é ruído. Verificar antes de abrir: sem nenhum dano.");
            } else {
                RogueResultadoEvento(b, "Luci: Às vezes não abrir um arquivo suspeito é a decisão mais segura.");
            }
            break;

        case EVT_BANCO_INSTAVEL:
            if (op == 0) {
                // Começa uma onda de elite aqui mesmo: as portas fecham até vencer
                b->eventoAberto = false;
                b->eventoUsado = true;
                b->eventoCombate = true;
                b->limpa = false;
                b->objetivoSala = OBJC_ELIMINAR;
                RogueMontarEncontro(b, &LAYOUT_EVENTO, RogueSortearEncontro(b, RogueNivelCombate(b)));
                TocarSomTom(sfxErro, 0.6f);
                return;
            } else if (op == 1) {
                b->perm->fragmentos += 3;
                RogueResultadoEvento(b, "Você recolhe o que vazou: +3 Fragmentos de Conhecimento.");
            } else {
                RogueResultadoEvento(b, "O banco segue vazando, longe de você.");
            }
            break;

        case EVT_MODELO_EXPERIMENTAL:
            if (op == 0) {
                j->penalidade |= 1 << b->varianteEvento;
                if (j->hp > RogueHpMax(b)) j->hp = RogueHpMax(b);
                b->escolhaPendente = ESCOLHA_RARA;
                RogueResultadoEvento(b, TextFormat("Versão beta instalada. Efeito colateral: %s. Escolha o seu poder.", NOMES_PENALIDADE[b->varianteEvento]));
            } else {
                RogueMudarEstabilidade(b, 1, "testar antes de confiar");
                RogueResultadoEvento(b, "Luci: Boa. Um modelo que ninguém testou pode fazer qualquer coisa... inclusive errar com confiança.");
            }
            break;

        case EVT_MEMORIA:
            if (op == 0) {
                b->eventoAberto = false;
                b->eventoUsado = true;
                b->memoriasVistas |= 1u << b->varianteEvento;
                RogueMudarEstabilidade(b, 1, "memória recuperada");
                DialogoIniciar(dlg, &dialogosMemoria[b->varianteEvento], OBJ_NENHUM);
                return;
            }
            b->perm->fragmentos += 4;
            RogueResultadoEvento(b, "O registro vira Fragmentos de Conhecimento: +4. A Luci não diz nada.");
            break;

        case EVT_PROTOCOLO:
            if (op == 0) {
                b->perm->fragmentos -= 6;
                j->hp = fminf(RogueHpMax(b), j->hp + RogueHpMax(b) * 0.6f);
                RogueParticulas(b, j->pos, LIME, 24, 180);
                RogueResultadoEvento(b, "Restauração concluída. -6 Fragmentos.");
            } else if (op == 1) {
                int u = j->ultimoUp;
                j->up[u]--;
                if (j->hp > RogueHpMax(b)) j->hp = RogueHpMax(b);
                j->hp = fminf(RogueHpMax(b), j->hp + RogueHpMax(b) * 0.4f);
                RogueParticulas(b, j->pos, LIME, 18, 160);
                RogueResultadoEvento(b, TextFormat("Restauração concluída. %s perdeu um nível.", UPGRADES[u].nome));
                if (j->up[u] == 0) j->ultimoUp = -1;
            } else {
                RogueResultadoEvento(b, "O terminal volta a dormir.");
            }
            break;

        case EVT_FONTE_FALSA:
        case EVT_RESPOSTA_IA: {
            const QuizEvento *q = (b->evento == EVT_FONTE_FALSA) ? &QUIZ_FONTES[b->varianteEvento] : &QUIZ_RESPOSTAS[b->varianteEvento];
            bool certo = (op == q->correta);
            RogueRegistrarResposta(b, certo);
            if (certo) {
                b->perm->fragmentos += 5;
                AlterarPontos(prog, PONTOS_DESAFIO);
                RogueMudarEstabilidade(b, 1, "fonte conferida");
                TocarSom(sfxAcerto);
                RogueResultadoEvento(b, TextFormat("CERTO! +5 Fragmentos. %s", q->explicacao));
            } else {
                j->hp = fmaxf(1.0f, j->hp - 15.0f);
                b->tremor = 0.25f;
                TocarSom(sfxErro);
                RogueResultadoEvento(b, TextFormat("ERROU (-15 de vida). %s", q->explicacao));
            }
        } break;

        case EVT_CONFIANCA_LUCI:
            if (op == 0) {
                RogueMudarEstabilidade(b, 1, "confiança com verificação");
                RogueHabitoLuci(b, false);
                RogueResultadoEvento(b, "Luci: É a melhor resposta que alguém já me deu. Confiar e conferir... vou lembrar disso.");
            } else if (op == 1) {
                b->perm->fragmentos += 3;
                b->perm->confiouCego++;
                RogueHabitoLuci(b, true);
                RogueResultadoEvento(b, "Luci: Que bom... assim fica tudo mais fácil. Para mim. (+3 Fragmentos)");
            } else {
                RogueResultadoEvento(b, "Luci: Justo. Confiança se constrói conferindo, não prometendo.");
            }
            break;

        case EVT_DESCANSO:
            if (op == 0) {
                j->hp = fminf(RogueHpMax(b), j->hp + RogueHpMax(b) * 0.4f);
                RogueParticulas(b, j->pos, LIME, 24, 180);
                RogueResultadoEvento(b, "Você descansa entre os livros. A integridade volta, devagar.");
            } else if (op == 1) {
                RogueMudarEstabilidade(b, 1, "uma boa conversa");
                RogueResultadoEvento(b, (RogueEstab(b) >= 4)
                    ? "Luci: Sabe o que eu gosto em você? Você pergunta \"de onde veio isso?\". Quase ninguém pergunta."
                    : "Luci: Às vezes eu sinto que tem outra voz dentro de mim, respondendo antes de eu pensar. Obrigada por ficar.");
            } else {
                int cand[NUM_UPGRADES], n = 0;
                for (int u = 0; u < NUM_UPGRADES; u++)
                    if (j->up[u] > 0 && j->up[u] < UPGRADES[u].maxNivel) cand[n++] = u;
                if (n > 0) {
                    int u = cand[GetRandomValue(0, n - 1)];
                    j->up[u]++;
                    if (u == UP_VIDA) j->hp = fminf(RogueHpMax(b), j->hp + UP_VIDA_NIVEL);
                    RogueResultadoEvento(b, TextFormat("Você estuda os seus próprios dados. %s subiu para o nível %d.", UPGRADES[u].nome, j->up[u]));
                }
            }
            break;

        default:    // EVT_DESAFIO
            b->eventoAberto = false;
            if (op != 0)
                return;                             // "agora não": dá para voltar ao console
            b->eventoUsado = true;
            b->estadoDesafio = 1;
            b->contadorDesafio = 0;
            b->j.golpesSofridos = 0;
            if (b->desafioSala == DESAFIO_SALA_ECOS) {
                b->tempoDesafioSala = DESAFIO_ECOS_TEMPO;
                b->cronoDesafio = 0.6f;
            } else {
                b->tempoDesafioSala = DESAFIO_INTEG_TEMPO;
                RogueCriarArmadilha(b, ARM_FEIXE);
                RogueCriarArmadilha(b, ARM_FEIXE);
                RogueCriarArmadilha(b, ARM_EXPLOSAO);
                RogueCriarArmadilha(b, ARM_TORRE);
            }
            RogueAviso(b, "DESAFIO INICIADO!");
            TocarSomTom(sfxErro, 0.8f);
            return;
    }
}

#define RET_FECHAR_EVENTO ((Rectangle){ 698, 88, 24, 20 })

// Opção i do evento (a mesma conta de DesenharEvento), para o mouse
static Rectangle RogueRetOpcaoEvento(const TelaEvento *t, int i)
{
    Rectangle painel = { 70, 80, 660, 420 };
    int x = (int)painel.x + 24, y = (int)painel.y + 18 + 40;
    char linhas[640];

    QuebrarTexto(t->texto, (int)painel.width - 48, 16, linhas, (int)sizeof(linhas));
    y += ContarLinhas(linhas) * 22 + 18;

    for (int k = 0; k <= i && k < t->numOpcoes; k++) {
        QuebrarTexto(TextFormat("%d) %s", k + 1, t->rotulo[k]), (int)painel.width - 90, 16, linhas, (int)sizeof(linhas));
        int nr = ContarLinhas(linhas);
        char ef[300] = "";
        if (t->efeito[k][0]) QuebrarTexto(t->efeito[k], (int)painel.width - 100, 12, ef, (int)sizeof(ef));
        int ne = ef[0] ? ContarLinhas(ef) : 0;
        int alt = nr * 20 + ne * 15 + 10;
        if (k == i)
            return (Rectangle){ (float)x - 10, (float)y - 5, painel.width - 28, (float)alt };
        y += alt + 6;
    }

    return (Rectangle){ 0, 0, 0, 0 };
}

static void RogueAtualizarEvento(Biblioteca *b, ProgressoCorredor *prog, SessaoDialogo *dlg)
{
    bool confirmar = IsKeyPressed(KEY_E) || IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_SPACE);

    // Mostrando o resultado: ENTER fecha (e abre a escolha prometida, se houver)
    if (b->eventoResolvido) {
        if (confirmar || CliqueMouse()) {
            b->eventoAberto = false;
            b->eventoResolvido = false;
            if (b->escolhaPendente >= 0) {
                RogueAbrirEscolha(b, (ModoEscolha)b->escolhaPendente, true);
                b->escolhaPendente = -1;
            }
        }
        return;
    }

    TelaEvento t;
    RogueMontarTelaEvento(b, &t);
    int n = t.numOpcoes;

    if (IsKeyPressed(KEY_W) || IsKeyPressed(KEY_UP))   { b->selecaoEvento = (b->selecaoEvento + n - 1) % n; TocarSom(sfxSelecao); }
    if (IsKeyPressed(KEY_S) || IsKeyPressed(KEY_DOWN)) { b->selecaoEvento = (b->selecaoEvento + 1) % n;     TocarSom(sfxSelecao); }
    for (int i = 0; i < n; i++)
        if (IsKeyPressed(KEY_ONE + i)) { b->selecaoEvento = i; TocarSom(sfxSelecao); }

    // Mouse: passar por cima marca, clicar escolhe; o X fecha sem escolher
    bool clique = CliqueMouse();
    for (int i = 0; i < n; i++) {
        if (!MouseEm(RogueRetOpcaoEvento(&t, i))) continue;
        if (MouseMexeu() && b->selecaoEvento != i) { b->selecaoEvento = i; TocarSom(sfxSelecao); }
        if (clique) { b->selecaoEvento = i; confirmar = true; }
    }

    if (IsKeyPressed(KEY_BACKSPACE) || (clique && MouseEm(RET_FECHAR_EVENTO))) {   // fecha sem escolher (dá para voltar)
        b->eventoAberto = false;
        return;
    }

    if (!confirmar)
        return;

    if (!t.disponivel[b->selecaoEvento]) {
        RogueAviso(b, "Essa opção não está disponível agora.");
        TocarSom(sfxErro);
        return;
    }

    RogueResolverEvento(b, prog, dlg, b->selecaoEvento);
}

// As provas da sala de desafio (as portas ficam abertas o tempo todo: é opcional)
static void RogueAtualizarDesafioSala(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    if (b->tipoSala != SALA_DESAFIO || b->estadoDesafio != 1)
        return;

    b->tempoDesafioSala -= dt;
    int resultado = 0;          // 1 = venceu, -1 = falhou

    if (b->desafioSala == DESAFIO_SALA_ECOS) {
        b->cronoDesafio -= dt;
        if (b->cronoDesafio <= 0.0f && RogueContarTipo(b, INIMIGO_ECO) < 5) {
            b->cronoDesafio = 1.2f;
            for (int k = 0; k < 2; k++) {
                Vector2 p;
                if (!RogueSortearLugar(b, 14.0f, 110.0f, &p)) continue;
                Inimigo *e = RogueCriarInimigo(b, INIMIGO_ECO, p);
                if (e != NULL) { e->desafio = true; e->timer = DESAFIO_ECO_TEMPO; }
            }
        }
        if (b->contadorDesafio >= DESAFIO_ECOS_META) resultado = 1;
        else if (b->tempoDesafioSala <= 0.0f)        resultado = -1;
    } else {
        if (b->j.golpesSofridos > DESAFIO_INTEG_GOLPES) resultado = -1;
        else if (b->tempoDesafioSala <= 0.0f)          resultado = 1;
    }

    if (resultado == 0)
        return;

    // Fim da prova: some com os ecos, as balas e as armadilhas
    RogueDissolverInimigos(b);
    memset(b->arm, 0, sizeof(b->arm));
    RogueAtualizarObstaculosDinamicos(b);

    if (resultado > 0) {
        b->estadoDesafio = 2;
        b->perm->fragmentos += 5;
        RogueColocarRecompensa(b, RECOMPENSA_RARA);
        AlterarPontos(prog, 10);
        RogueRegistrarResposta(b, true);
        RogueAviso(b, "DESAFIO CONCLUÍDO! +5 FRAGMENTOS");
        TocarSom(sfxAcerto);
        MostrarEmocaoLuci(EMOCAO_ALEGRE, 2.5f);
    } else {
        b->estadoDesafio = 3;
        RogueAviso(b, "DESAFIO FALHOU");
        RogueRecadoLuci(b, "Luci: Quase! A porta continua aberta. Da próxima vez, de olho nos avisos.");
        TocarSom(sfxErro);
    }
    Telemetria("rogue_desafio_sala", (b->desafioSala == DESAFIO_SALA_ECOS) ? "ecos" : "integridade", (float)resultado, b->contadorDesafio);
}


