// =============================================================
// EXPANSÃO EDUCATIVA DO BLOCO 2: LÓGICA DOS LABORATÓRIOS
// =============================================================

// Tira do fim da string um caractere UTF-8 que o snprintf cortou ao meio
static void LabCortarUtf8(char *s)
{
    int n = (int)strlen(s);
    int i = n - 1;
    while (i >= 0 && (((unsigned char)s[i]) & 0xC0) == 0x80) i--;
    if (i < 0) return;
    unsigned char c = (unsigned char)s[i];
    int esperado = (c >= 0xF0) ? 4 : ((c >= 0xE0) ? 3 : ((c >= 0xC0) ? 2 : 1));
    if (n - i < esperado) s[i] = '\0';
}

// ---------- Seleção procedural das missões ----------

static int LabNumMissoes(TipoLab t)
{
    switch (t) {
        case LAB_PROMPTS:  return NUM_MISSOES_PROMPT;
        case LAB_ARQUIVO:  return NUM_DESAFIOS_ARQUIVO;
        case LAB_NUCLEO:   return NUM_DESAFIOS_NUCLEO;
        case LAB_FIREWALL: return NUM_CASOS_VIES;
        default:           return NUM_CASOS_PESQUISA;
    }
}

static int LabDificuldadeMissao(TipoLab t, int i)
{
    switch (t) {
        case LAB_PROMPTS:  return MISSOES_PROMPT[i].dificuldade;
        case LAB_ARQUIVO:  return DESAFIOS_ARQUIVO[i].dificuldade;
        case LAB_NUCLEO:   return DESAFIOS_NUCLEO[i].dificuldade;
        case LAB_FIREWALL: return CASOS_VIES[i].dificuldade;
        default:           return CASOS_PESQUISA[i].dificuldade;
    }
}

// Conceito que precisa ter sido apresentado antes (Byte, terminais)
static int LabConceitoMissao(TipoLab t, int i)
{
    if (t == LAB_PROMPTS) return MISSOES_PROMPT[i].conceito;
    if (t == LAB_ARQUIVO) return DESAFIOS_ARQUIVO[i].conceito;
    return CONCEITO_FUNDAMENTOS;
}

// Dificuldade da tentativa: cresce com a profundidade e se ajusta ao desempenho nos laboratórios
static int LabDificuldadeAlvo(const Biblioteca *b)
{
    int alvo = (b->profundidade <= 2) ? 1 : ((b->profundidade <= 5) ? 2 : 3);

    if (b->labFeitos >= 2) {
        float media = (float)b->labEstrelas / (float)b->labFeitos;
        if (media >= 2.5f)      alvo++;
        else if (media < 1.5f)  alvo--;
    }
    return (alvo < 1) ? 1 : ((alvo > 3) ? 3 : alvo);
}

// Uma missão da categoria: tema certo, conceito já apresentado, dificuldade mais perto do alvo
// e, de preferência, uma que ainda não apareceu (o ciclo recomeça quando todas já foram vistas)
static int LabSortearMissao(Biblioteca *b, TipoLab t)
{
    int n = LabNumMissoes(t);
    unsigned int todas = (n >= 32) ? 0xFFFFFFFFu : ((1u << n) - 1u);
    int alvo = LabDificuldadeAlvo(b);

    if ((b->labVistas[t] & todas) == todas)
        b->labVistas[t] = 0;

    int cand[32], nc = 0;
    for (int passada = 0; passada < 3 && nc == 0; passada++) {
        int melhor = 99;
        for (int i = 0; i < n && i < 32; i++) {
            int c = LabConceitoMissao(t, i);
            bool conhece = (c == CONCEITO_FUNDAMENTOS) || (b->perm->conceitos & (1u << c));
            if (passada < 2 && (b->labVistas[t] & (1u << i))) continue;
            if (passada == 0 && !conhece) continue;
            int dist = abs(LabDificuldadeMissao(t, i) - alvo);
            if (dist < melhor) { melhor = dist; nc = 0; }
            if (dist == melhor) cand[nc++] = i;
        }
    }

    int m = (nc > 0) ? cand[GetRandomValue(0, nc - 1)] : 0;
    b->labVistas[t] |= 1u << m;
    return m;
}

// Prepara o laboratório da sala (a janela só abre quando o jogador usa o console)
static void LabPreparar(Biblioteca *b, TipoLab tipo)
{
    LabEdu *L = &b->lab;

    memset(L, 0, sizeof(*L));
    L->tipo = tipo;
    L->missao = LabSortearMissao(b, tipo);
    L->etapa = LAB_INTRO;
    L->sel = L->sel2 = L->veredito = -1;
    L->luciAponta = -1;
    L->luciFase = -1;
    for (int k = 0; k < LAB_PACOTES; k++) L->acoes[k] = -2;
}

static void LabEnviarPrompt(Biblioteca *b);

// Passo 2 (experimentar): sai da introdução e começa o desafio
static void LabComecar(Biblioteca *b)
{
    LabEdu *L = &b->lab;

    b->labIntroVista |= 1u << L->tipo;
    L->etapa = LAB_DESAFIO;
    L->tempo = 0.0f;
    L->foco = 0;

    if (L->tipo == LAB_PROMPTS) {
        const MissaoPrompt *m = &MISSOES_PROMPT[L->missao];
        if (m->vago) {
            // Refinamento: o pedido vago já foi enviado e a resposta ruim está na tela
            for (int k = 0; k < NUM_PARTES_PROMPT; k++) L->escolha[k] = m->inicial[k];
            L->original = true;
            LabEnviarPrompt(b);
        }
    } else if (L->tipo == LAB_FIREWALL) {
        // Pacotes sorteados do banco (sem repetir)
        int ordem[NUM_PACOTES_DADOS];
        for (int i = 0; i < NUM_PACOTES_DADOS; i++) ordem[i] = i;
        for (int i = NUM_PACOTES_DADOS - 1; i > 0; i--) {
            int j = GetRandomValue(0, i);
            int t = ordem[i]; ordem[i] = ordem[j]; ordem[j] = t;
        }
        for (int k = 0; k < LAB_PACOTES; k++) L->pacotes[k] = ordem[k];
        L->tempoPacote = LAB_TEMPO_PACOTE;
    }

    TocarSom(sfxSelecao);
    Telemetria("rogue_lab_inicio", NOMES_LAB[L->tipo], (float)LabDificuldadeMissao(L->tipo, L->missao), L->missao);
}

// ---------- Modo Prompt: o "modelo" offline ----------

static int LabNotaParte(const MissaoPrompt *m, const int esc[NUM_PARTES_PROMPT], int k)
{
    int a = esc[k];
    if (a < 0 || a > 3) a = 0;
    return m->nota[k][a];
}

static bool LabParteNecessaria(const MissaoPrompt *m, int k)
{
    return (m->necessarias & PB(k)) != 0;
}

// Combinação contraditória (devolve as duas partes envolvidas)
static bool LabContradicao(const MissaoPrompt *m, const int esc[NUM_PARTES_PROMPT], int *pa, int *pb)
{
    for (int i = 0; i < 2; i++) {
        const signed char *c = m->contra[i];
        if (c[0] < 0) continue;
        if (esc[c[0]] == c[1] && esc[c[2]] == c[3]) {
            if (pa) *pa = c[0];
            if (pb) *pb = c[2];
            return true;
        }
    }
    return false;
}

// Avalia a COMBINAÇÃO escolhida pelos critérios da missão (não só a quantidade de partes):
// clareza, informações necessárias, adequação, especificidade e ambiguidade (0 a 2 cada).
// O diagnóstico decide qual resposta simulada aparece.
static int LabAvaliarPrompt(const MissaoPrompt *m, const int esc[NUM_PARTES_PROMPT], int crit[NUM_CRITERIOS], DiagPrompt *diag)
{
    int n[NUM_PARTES_PROMPT];
    int req = 0, ok = 0, ideais = 0, inadequadas = 0, ruido = 0;
    bool contra = LabContradicao(m, esc, NULL, NULL);

    for (int k = 0; k < NUM_PARTES_PROMPT; k++) {
        n[k] = LabNotaParte(m, esc, k);
        if (LabParteNecessaria(m, k)) {
            req++;
            if (n[k] >= 1) ok++;
            if (n[k] == 2) ideais++;
        } else if (esc[k] > 0 && n[k] == 0) {
            ruido++;                                    // parte opcional que só atrapalha
        }
        if (esc[k] > 0 && n[k] < 0) inadequadas++;
    }

    crit[CRIT_CLAREZA] = (n[PP_OBJETIVO] >= 2) ? 2 : ((n[PP_OBJETIVO] == 1) ? 1 : 0);
    if (contra && crit[CRIT_CLAREZA] > 1) crit[CRIT_CLAREZA] = 1;
    crit[CRIT_INFORMACOES] = (ok >= req) ? 2 : ((ok >= req - 1) ? 1 : 0);
    crit[CRIT_ADEQUACAO] = contra ? 0 : ((inadequadas == 0) ? 2 : ((inadequadas == 1) ? 1 : 0));
    int esp = (ideais >= req) ? 2 : ((ideais * 2 >= req) ? 1 : 0);
    esp -= ruido;
    crit[CRIT_ESPECIFICIDADE] = (esp < 0) ? 0 : esp;
    crit[CRIT_AMBIGUIDADE] = contra ? 0 : (((!LabParteNecessaria(m, PP_CONTEXTO) || n[PP_CONTEXTO] >= 1) ? 1 : 0) +
                                           ((!LabParteNecessaria(m, PP_FORMATO)  || n[PP_FORMATO]  >= 1) ? 1 : 0));

    int total = 0;
    for (int c = 0; c < NUM_CRITERIOS; c++) total += crit[c];

    #define FALHA(k) ((LabParteNecessaria(m, (k)) && n[(k)] <= 0) || n[(k)] < 0)
    if (contra)                   *diag = DIAG_CONTRADICAO;
    else if (n[PP_OBJETIVO] <= 0) *diag = DIAG_VAGA;
    else if (FALHA(PP_CONTEXTO))  *diag = DIAG_PUBLICO;
    else if (FALHA(PP_PAPEL))     *diag = DIAG_PAPEL;
    else if (FALHA(PP_FORMATO))   *diag = DIAG_FORMATO;
    else                          *diag = (total >= 9) ? DIAG_IDEAL : DIAG_BOA;
    #undef FALHA

    return total;
}

// Luz de cada encaixe depois do envio: o retorno imediato da montagem (tentativa e erro)
typedef enum { LUZ_IDEAL, LUZ_OK, LUZ_DISPENSAVEL, LUZ_VAGA, LUZ_FALTOU, LUZ_ATRAPALHOU, LUZ_CONFLITO, NUM_LUZES } LuzParte;
static const char *NOMES_LUZ[NUM_LUZES] = { "IDEAL", "OK", "DISPENSÁVEL", "VAGA", "FALTOU", "ATRAPALHOU", "CONFLITO" };
static const Color CORES_LUZ[NUM_LUZES] = {
    { 0, 228, 48, 255 }, { 253, 249, 0, 255 }, { 150, 150, 170, 255 }, { 255, 161, 0, 255 },
    { 230, 41, 55, 255 }, { 230, 41, 55, 255 }, { 255, 0, 255, 255 }
};

static LuzParte LabLuzParte(const MissaoPrompt *m, const int esc[NUM_PARTES_PROMPT], int k)
{
    int pa = -1, pb = -1;
    if (LabContradicao(m, esc, &pa, &pb) && (k == pa || k == pb))
        return LUZ_CONFLITO;

    int n = LabNotaParte(m, esc, k);
    if (n < 0)  return LUZ_ATRAPALHOU;
    if (n == 0) return (esc[k] == 0) ? LUZ_FALTOU : LUZ_VAGA;
    if (esc[k] == 0) return LUZ_DISPENSAVEL;           // vazio e tudo bem: nem toda tarefa precisa dos quatro
    return (n == 2) ? LUZ_IDEAL : LUZ_OK;
}

// A luz que aparece no encaixe agora (-1: ainda não enviou, ou a peça mudou desde o envio)
static int LabLuzVisivel(const LabEdu *L, const MissaoPrompt *m, int k)
{
    if (!L->temEnvio || L->escolha[k] != L->enviado[k])
        return -1;
    return (int)LabLuzParte(m, L->enviado, k);
}

static const char *LabTextoRespostaAtual(const Biblioteca *b)
{
    const LabEdu *L = &b->lab;

    if (L->tipo == LAB_PROMPTS) {
        const MissaoPrompt *m = &MISSOES_PROMPT[L->missao];
        return L->respostaAlucinada ? m->respAlucinada : m->resp[L->diag];
    }
    if (L->tipo == LAB_NUCLEO)
        return DESAFIOS_NUCLEO[L->missao].resp[L->resultadoNucleo];
    return NULL;
}

// Envia o pedido para a IA simulada: avaliação, diagnóstico e a resposta cadastrada
static void LabEnviarPrompt(Biblioteca *b)
{
    LabEdu *L = &b->lab;
    const MissaoPrompt *m = &MISSOES_PROMPT[L->missao];

    if (!L->original)
        L->envios++;

    L->notaPrompt = LabAvaliarPrompt(m, L->escolha, L->criterios, &L->diag);

    // Missão de alucinação: sem pedir honestidade, a resposta "boa" vem com algo inventado
    L->respostaAlucinada = (m->honestaParte >= 0 && (L->diag == DIAG_IDEAL || L->diag == DIAG_BOA) &&
                            L->escolha[m->honestaParte] != m->honestaAlt);

    for (int k = 0; k < NUM_PARTES_PROMPT; k++) L->enviado[k] = L->escolha[k];
    L->temEnvio = true;
    L->animPeca = 0.0f;
    L->tempoResposta = 0.0f;

    L->desconfiou = false;
    L->digitado = 0.0f;
    L->avaliacao[0] = '\0';
    L->temSugestao = false;
    L->luciTemSugestao = false;
    L->conferencia[0] = '\0';
    L->etapa = LAB_RESPOSTA;
    L->tempo = 0.0f;
    L->foco = 0;

    TocarSomTom(sfxSelecao, 1.2f);
    Telemetria("rogue_lab_prompt", TEXTOS_DIAG[L->diag], (float)L->notaPrompt, L->envios);
}

// ---------- A Luci nos laboratórios ----------

static bool LabLuciDisponivel(Biblioteca *b)
{
    LabEdu *L = &b->lab;

    if (RogueEstab(b) > 0)
        return true;

    snprintf(L->luciTexto, sizeof(L->luciTexto), "L#ci: Estou sobrecarregada... Resolva sem mim e eu me estabilizo.");
    L->luciTemSugestao = false;
    L->conferencia[0] = '\0';
    MostrarEmocaoLuci(EMOCAO_DUVIDA, 2.0f);
    TocarSom(sfxErro);
    return false;
}

// A carga de ajuda vai para a estabilidade de sempre (a do main, compartilhada com o Bloco 1)
static void LabCobrarLuci(Biblioteca *b, int custo)
{
    b->cargaLuci += custo;
    b->lab.ajudas++;

    while (b->cargaLuci >= LAB_CARGA_POR_ESTAB && RogueEstab(b) > 0) {
        b->cargaLuci -= LAB_CARGA_POR_ESTAB;
        RogueMudarEstabilidade(b, -1, NULL);
        RogueRecadoLuci(b, FALAS_INSTABILIDADE_LAB[RogueEstab(b)]);
    }
    if (RogueEstab(b) <= 0)
        b->cargaLuci = 0;
}

static bool LabLuciAlucina(const Biblioteca *b)
{
    return GetRandomValue(1, 100) <= RogueChanceLuciErrar(b);
}

// Fala da Luci no laboratório. A confiável explica o porquê; a alucinada vem com certeza absoluta
// e sem motivo. Instável, ela mesma pede para ser conferida.
static void LabFalaLuci(Biblioteca *b, const char *texto, bool alucinada, int aponta, int fase)
{
    LabEdu *L = &b->lab;
    int e = RogueEstab(b);
    const char *nome = (e >= 3) ? "Luci" : ((e == 2) ? "Luci~" : "L#ci");

    snprintf(L->luciTexto, sizeof(L->luciTexto), "%s: %s%s%s", nome, texto,
             alucinada ? " Tenho 100% de certeza!" : "", (e <= 2) ? " [instável: confira com V]" : "");
    LabCortarUtf8(L->luciTexto);

    L->luciTemSugestao = true;
    L->luciAlucinou = alucinada;
    L->luciVerificada = false;
    L->luciAponta = aponta;
    L->luciFase = fase;
    L->conferencia[0] = '\0';
    if (alucinada) L->alucinacoes++;

    if (e <= 2) MostrarEmocaoLuci(EMOCAO_ALERTA, 1.5f);
    TocarSom(sfxSelecao);
    Telemetria("rogue_lab_luci", alucinada ? "alucinou" : "ajudou", (float)RogueChanceLuciErrar(b), L->ajudas);
}

// O jogador seguiu a sugestão sem conferir: confiar vira hábito; se era alucinação, a Luci se abala
static void LabSeguiuLuci(Biblioteca *b)
{
    LabEdu *L = &b->lab;

    b->perm->confiouCego++;
    RogueHabitoLuci(b, true);
    if (L->luciAlucinou) {
        b->perm->confiouAlucinacao++;
        L->seguiuAlucinacao = true;
        RogueMudarEstabilidade(b, -1, NULL);
    }
    L->luciTemSugestao = false;
}

// Conferiu a decisão com a sugestão pendente da Luci (aponta / fase iguais e sem V)
static void LabConferirSeguiu(Biblioteca *b, int fase, int escolha)
{
    const LabEdu *L = &b->lab;
    if (L->luciTemSugestao && !L->luciVerificada && L->luciFase == fase && L->luciAponta >= 0 && L->luciAponta == escolha)
        LabSeguiuLuci(b);
}

static void LabDicas(const Biblioteca *b, const char **d, const char **falsa)
{
    const LabEdu *L = &b->lab;
    const char *const *lista;

    switch (L->tipo) {
        case LAB_PROMPTS:  lista = MISSOES_PROMPT[L->missao].dicas;   *falsa = MISSOES_PROMPT[L->missao].dicaFalsa;   break;
        case LAB_ARQUIVO:  lista = DESAFIOS_ARQUIVO[L->missao].dicas; *falsa = DESAFIOS_ARQUIVO[L->missao].dicaFalsa; break;
        case LAB_NUCLEO:   lista = DESAFIOS_NUCLEO[L->missao].dicas;  *falsa = DESAFIOS_NUCLEO[L->missao].dicaFalsa;  break;
        case LAB_FIREWALL:
            if (L->fase < 2) { lista = CASOS_VIES[L->missao].dicas; *falsa = CASOS_VIES[L->missao].dicaFalsa; }
            else             { lista = DICAS_PRIVACIDADE;           *falsa = DICA_FALSA_PRIVACIDADE; }
            break;
        default:           lista = CASOS_PESQUISA[L->missao].dicas;   *falsa = CASOS_PESQUISA[L->missao].dicaFalsa;   break;
    }
    for (int i = 0; i < 3; i++) d[i] = lista[i];
}

// 1. Dicas graduais: orientação geral, conceito, orientação específica (nunca a resposta)
static void LabPedirDica(Biblioteca *b)
{
    LabEdu *L = &b->lab;

    if (L->nivelDica >= 3) {
        snprintf(L->luciTexto, sizeof(L->luciTexto), "Luci: Já dei as três dicas. Agora confie no seu raciocínio!");
        L->luciTemSugestao = false;
        return;
    }
    if (!LabLuciDisponivel(b))
        return;

    LabCobrarLuci(b, LAB_CUSTO_DICA);
    bool alucina = LabLuciAlucina(b);
    const char *d[3], *falsa;
    LabDicas(b, d, &falsa);
    L->nivelDica++;

    char t[200];
    if (alucina) snprintf(t, sizeof(t), "%s", falsa);
    else         snprintf(t, sizeof(t), "(dica %d/3) %s", L->nivelDica, d[L->nivelDica - 1]);
    LabFalaLuci(b, t, alucina, -1, -1);
}

// 2. Análise do pedido (Modo Prompt): aponta o tipo de problema, não a alternativa certa
static void LabTextoAnalise(const MissaoPrompt *m, const int esc[NUM_PARTES_PROMPT], DiagPrompt diag, char *t, int tam)
{
    int pa = 0, pb = 0;

    switch (diag) {
        case DIAG_CONTRADICAO:
            LabContradicao(m, esc, &pa, &pb);
            snprintf(t, (size_t)tam, "O %s e o %s brigam entre si. A IA vai ter que ignorar um dos dois.", NOMES_PARTES_PROMPT[pa], NOMES_PARTES_PROMPT[pb]);
            break;
        case DIAG_VAGA:
            snprintf(t, (size_t)tam, "%s", (esc[PP_OBJETIVO] == 0) ? "Falta dizer o que a IA deve FAZER: explicar, resumir, comparar..."
                                                                    : "O OBJETIVO está vago ou fora da missão. Diga exatamente a tarefa.");
            break;
        case DIAG_PUBLICO:
            snprintf(t, (size_t)tam, "%s", (esc[PP_CONTEXTO] == 0) ? "Você explicou o assunto, mas não especificou para quem a resposta deve ser direcionada."
                                                                    : "O CONTEXTO escolhido não combina com quem vai usar a resposta.");
            break;
        case DIAG_PAPEL:
            snprintf(t, (size_t)tam, "O PAPEL não combina com a tarefa: quem responde muda o tipo de resposta.");
            break;
        case DIAG_FORMATO:
            snprintf(t, (size_t)tam, "%s", (esc[PP_FORMATO] == 0) ? "Você não disse COMO quer a resposta. Um formato deixa tudo mais claro."
                                                                   : "Esse FORMATO não ajuda nesta tarefa (ou deixa o pedido ambíguo).");
            break;
        case DIAG_BOA: {
            int k = -1;
            for (int p = 0; p < NUM_PARTES_PROMPT && k < 0; p++)
                if (!LabParteNecessaria(m, p) && esc[p] > 0 && LabNotaParte(m, esc, p) == 0) k = p;
            if (k >= 0) { snprintf(t, (size_t)tam, "O %s não é necessário aqui e só adiciona ruído.", NOMES_PARTES_PROMPT[k]); break; }
            for (int p = 0; p < NUM_PARTES_PROMPT && k < 0; p++)
                if (LabParteNecessaria(m, p) && LabNotaParte(m, esc, p) == 1) k = p;
            if (k >= 0) snprintf(t, (size_t)tam, "Está bom, mas dá para ser mais específico no %s.", NOMES_PARTES_PROMPT[k]);
            else        snprintf(t, (size_t)tam, "Está bom, mas ainda dá para ser mais específico.");
        } break;
        default: {
            int k = -1;
            for (int p = 0; p < NUM_PARTES_PROMPT && k < 0; p++)
                if (!LabParteNecessaria(m, p) && esc[p] == 0) k = p;
            if (k >= 0) snprintf(t, (size_t)tam, "Pedido claro e completo. Repare: nem precisou de %s.", NOMES_PARTES_PROMPT[k]);
            else        snprintf(t, (size_t)tam, "Pedido claro e completo para esta missão.");
        } break;
    }
}

static void LabAnalisarPrompt(Biblioteca *b)
{
    LabEdu *L = &b->lab;
    const MissaoPrompt *m = &MISSOES_PROMPT[L->missao];

    if (!LabLuciDisponivel(b))
        return;
    LabCobrarLuci(b, LAB_CUSTO_ANALISE);

    int crit[NUM_CRITERIOS];
    DiagPrompt diag;
    LabAvaliarPrompt(m, L->escolha, crit, &diag);

    bool alucina = LabLuciAlucina(b);
    char t[200];

    if (!alucina) {
        LabTextoAnalise(m, L->escolha, diag, t, (int)sizeof(t));
    } else if (diag != DIAG_IDEAL) {
        snprintf(t, sizeof(t), "Está perfeito, pode enviar do jeito que está!");
    } else {
        int k = GetRandomValue(0, NUM_PARTES_PROMPT - 1);
        snprintf(t, sizeof(t), "O problema é o %s. Troque já!", NOMES_PARTES_PROMPT[k]);
    }
    LabFalaLuci(b, t, alucina, -1, -1);
}

// Alternativa de maior nota da parte (0 = não incluir, se for o melhor)
static int LabMelhorAlternativa(const MissaoPrompt *m, int k)
{
    int melhor = 0;
    for (int a = 1; a <= 3; a++)
        if (m->nota[k][a] > m->nota[k][melhor]) melhor = a;
    return melhor;
}

// 4. Reformulação: a Luci corrige as DUAS partes mais fracas do pedido do jogador (não revela tudo).
// Aceitar limita a avaliação a 2 estrelas. Instável, ela pode trocar uma parte por algo pior.
static void LabReformular(Biblioteca *b)
{
    LabEdu *L = &b->lab;
    const MissaoPrompt *m = &MISSOES_PROMPT[L->missao];

    if (L->temSugestao || !LabLuciDisponivel(b))
        return;
    LabCobrarLuci(b, LAB_CUSTO_REFORMULACAO);

    int sev[NUM_PARTES_PROMPT] = { 0 }, pa = -1, pb = -1;
    LabContradicao(m, L->escolha, &pa, &pb);
    for (int k = 0; k < NUM_PARTES_PROMPT; k++) {
        int n = LabNotaParte(m, L->escolha, k);
        if (k == pa || k == pb)                                         sev[k] = 4;
        else if (L->escolha[k] > 0 && n < 0)                            sev[k] = 3;
        else if (LabParteNecessaria(m, k) && n <= 0)                    sev[k] = 2;
        else if (LabParteNecessaria(m, k) && n == 1)                    sev[k] = 1;
        else if (!LabParteNecessaria(m, k) && L->escolha[k] > 0 && n == 0) sev[k] = 1;
    }

    for (int k = 0; k < NUM_PARTES_PROMPT; k++) L->sugestao[k] = L->escolha[k];

    int corrigidas[2] = { -1, -1 };
    for (int vez = 0; vez < 2; vez++) {
        int pior = -1;
        for (int k = 0; k < NUM_PARTES_PROMPT; k++)
            if (sev[k] > 0 && (pior < 0 || sev[k] > sev[pior])) pior = k;
        if (pior < 0) break;
        L->sugestao[pior] = LabMelhorAlternativa(m, pior);
        corrigidas[vez] = pior;
        sev[pior] = 0;
    }

    bool alucina = LabLuciAlucina(b);
    int estragada = -1;
    if (alucina) {
        estragada = (corrigidas[0] >= 0) ? corrigidas[GetRandomValue(0, (corrigidas[1] >= 0) ? 1 : 0)] : GetRandomValue(0, NUM_PARTES_PROMPT - 1);
        int pior = 1;
        for (int a = 1; a <= 3; a++) if (m->nota[estragada][a] < m->nota[estragada][pior]) pior = a;
        L->sugestao[estragada] = pior;
    }

    L->temSugestao = true;
    if (corrigidas[0] < 0 && !alucina)
        LabFalaLuci(b, "Eu não mudaria nada: o pedido já está bom. Aceitar a minha versão limita a avaliação a 2 estrelas.", false, -1, -1);
    else
        LabFalaLuci(b, "Reescrevi o pedido (veja nos encaixes). Aceite ou ajuste. Aceitar limita a avaliação a 2 estrelas.", alucina, estragada, -1);
}

// 3. Verificação: a Luci aponta o que parece suspeito (ou a decisão que ela tomaria)
static void LabLuciVerificar(Biblioteca *b)
{
    LabEdu *L = &b->lab;

    if (!LabLuciDisponivel(b))
        return;
    LabCobrarLuci(b, LAB_CUSTO_VERIFICACAO);

    bool alucina = LabLuciAlucina(b);
    char t[220];
    int aponta = -1, fase = L->fase;

    switch (L->tipo) {

        case LAB_PROMPTS: {
            // 0 = "pode aceitar", 1 = "desconfie"
            bool suspeita = L->respostaAlucinada ? !alucina : alucina;
            aponta = suspeita ? 1 : 0;
            fase = 100 + L->envios;
            if (suspeita) snprintf(t, sizeof(t), "%s", alucina ? "Isso aí é invenção da IA! Desconfie."
                                                               : "Essa informação parece estranha. Será que temos alguma fonte que confirme isso?");
            else          snprintf(t, sizeof(t), "%s", alucina ? "Está tudo certo, pode aceitar!"
                                                               : "Não vejo nada inventado. Agora veja se a resposta atende à missão.");
        } break;

        case LAB_ARQUIVO: {
            const DesafioArquivo *d = &DESAFIOS_ARQUIVO[L->missao];
            if (L->fase == 0) {
                aponta = d->suspeita;
                if (alucina) { aponta = GetRandomValue(0, 2); if (aponta >= d->suspeita) aponta++; }
                if (alucina) snprintf(t, sizeof(t), "É a afirmação %d, nem precisa conferir.", aponta + 1);
                else         snprintf(t, sizeof(t), "A afirmação %d parece estranha. Será que temos alguma fonte que confirme isso?", aponta + 1);
            } else {
                aponta = d->metodoCerto;
                if (alucina) { aponta = GetRandomValue(0, 1); if (aponta >= d->metodoCerto) aponta++; }
                if (alucina) snprintf(t, sizeof(t), "Use \"%s\" e pronto.", d->metodos[aponta]);
                else         snprintf(t, sizeof(t), "Eu verificaria com \"%s\": é uma fonte fora da conversa com a IA.", d->metodos[aponta]);
            }
        } break;

        case LAB_NUCLEO: {
            const DesafioNucleo *d = &DESAFIOS_NUCLEO[L->missao];
            int alvo = -1;
            bool dispensavel = false;
            if (!alucina) {
                for (int i = 0; i < d->numBlocos && alvo < 0; i++)
                    if ((L->marcados & (1u << i)) && d->bloco[i].relevancia == REL_IRRELEVANTE) { alvo = i; dispensavel = true; }
                for (int i = 0; i < d->numBlocos && alvo < 0; i++)
                    if (!(L->marcados & (1u << i)) && d->bloco[i].relevancia == REL_ESSENCIAL) { alvo = i; dispensavel = false; }
            } else {
                for (int i = 0; i < d->numBlocos && alvo < 0; i++)
                    if ((L->marcados & (1u << i)) && d->bloco[i].relevancia == REL_ESSENCIAL) { alvo = i; dispensavel = true; }
                for (int i = 0; i < d->numBlocos && alvo < 0; i++)
                    if (!(L->marcados & (1u << i)) && d->bloco[i].relevancia == REL_IRRELEVANTE) { alvo = i; dispensavel = false; }
            }
            aponta = alvo;
            L->luciValor = dispensavel ? 0 : 1;
            if (alvo < 0)        snprintf(t, sizeof(t), "O que está carregado parece certo. Confira a capacidade e processe.");
            else if (alucina)    snprintf(t, sizeof(t), dispensavel ? "Tire \"%s\", é dispensável." : "Carregue \"%s\", é essencial!", d->bloco[alvo].texto);
            else if (dispensavel) snprintf(t, sizeof(t), "\"%s\" não ajuda nesta tarefa e ocupa %d tokens.", d->bloco[alvo].texto, d->bloco[alvo].tokens);
            else                  snprintf(t, sizeof(t), "Sem \"%s\" a IA vai ter que adivinhar. Isso parece essencial.", d->bloco[alvo].texto);
        } break;

        case LAB_FIREWALL: {
            const CasoVies *c = &CASOS_VIES[L->missao];
            if (L->fase < 2) {
                int certo = (L->fase == 0) ? c->problemaCerto : c->medidaCerta;
                const char *const *ops = (L->fase == 0) ? c->problemas : c->medidas;
                aponta = certo;
                if (alucina) { aponta = GetRandomValue(0, 1); if (aponta >= certo) aponta++; }
                if (alucina) snprintf(t, sizeof(t), "É \"%s\".", ops[aponta]);
                else         snprintf(t, sizeof(t), "Eu escolheria \"%s\". Pense em quem é afetado pela decisão.", ops[aponta]);
            } else if (L->pacote < LAB_PACOTES) {
                const PacoteDados *p = &PACOTES_DADOS[L->pacotes[L->pacote]];
                aponta = p->acao;
                if (alucina) { aponta = GetRandomValue(0, 1); if (aponta >= p->acao) aponta++; }
                fase = 20 + L->pacote;
                if (alucina) snprintf(t, sizeof(t), "%s! Sem pensar duas vezes.", NOMES_ACAO_PACOTE[aponta]);
                else         snprintf(t, sizeof(t), "Eu faria %s com esse pacote. Pense: isso identifica alguém ou abre uma conta?", NOMES_ACAO_PACOTE[aponta]);
            }
        } break;

        default: {
            const CasoPesquisa *c = &CASOS_PESQUISA[L->missao];
            int alvo = -1;
            for (int i = 0; i < 5 && alvo < 0; i++)
                if (((L->marcados & (1u << i)) != 0) != c->pista[i].alerta) alvo = i;
            if (alvo < 0) alvo = GetRandomValue(0, 4);
            bool alerta = alucina ? !c->pista[alvo].alerta : c->pista[alvo].alerta;
            aponta = alvo;
            L->luciValor = alerta ? 1 : 0;
            if (alucina) snprintf(t, sizeof(t), alerta ? "\"%s\" é ALERTA, sem dúvida." : "\"%s\" não importa nada.", c->pista[alvo].texto);
            else         snprintf(t, sizeof(t), alerta ? "\"%s\" é um sinal de alerta: fala de origem ou de confirmação." : "\"%s\", sozinha, não prova nada.", c->pista[alvo].texto);
        } break;
    }

    LabCortarUtf8(t);
    LabFalaLuci(b, t, alucina, aponta, fase);
}

// V: confere a sugestão da Luci (gasta uma Lente ou 1 Fragmento). Pegar a alucinação repara a Luci.
static void LabChecarLuci(Biblioteca *b)
{
    LabEdu *L = &b->lab;

    if (!L->luciTemSugestao || L->luciVerificada)
        return;

    if (b->j.itens[ITEM_LENTE] > 0)                       b->j.itens[ITEM_LENTE]--;
    else if (b->perm->fragmentos >= CUSTO_VERIFICAR_FC)   b->perm->fragmentos -= CUSTO_VERIFICAR_FC;
    else {
        snprintf(L->conferencia, sizeof(L->conferencia), "Sem Lente nem Fragmento para conferir. Analise você mesmo!");
        TocarSom(sfxErro);
        return;
    }

    L->luciVerificada = true;
    b->perm->verificou++;
    RogueHabitoLuci(b, false);

    if (L->luciAlucinou) {
        b->perm->alucinacoesPegas++;
        L->alucinacoesPegas++;
        snprintf(L->conferencia, sizeof(L->conferencia), "CONFERIDO: a sugestão NÃO confere com as fontes. A Luci alucinou!");
        RogueMudarEstabilidade(b, 1, NULL);
        TocarSom(sfxAcerto);
    } else {
        snprintf(L->conferencia, sizeof(L->conferencia), "CONFERIDO: a sugestão confere com as fontes.");
        TocarSomTom(sfxSelecao, 1.3f);
    }
    Telemetria("rogue_lab_conferir", L->luciAlucinou ? "pegou" : "conferia", 0.0f, L->ajudas);
}

// ---------- Núcleo Neural ----------

static int LabTokensCarregados(const Biblioteca *b)
{
    const DesafioNucleo *d = &DESAFIOS_NUCLEO[b->lab.missao];
    int total = 0;
    for (int i = 0; i < d->numBlocos; i++)
        if (b->lab.marcados & (1u << i)) total += d->bloco[i].tokens;
    return total;
}

static void LabAlternarBloco(Biblioteca *b, int i)
{
    LabEdu *L = &b->lab;

    if (L->marcados & (1u << i)) {
        L->marcados &= ~(1u << i);
        int k = 0;
        for (int j = 0; j < L->numOrdem; j++) if (L->ordem[j] != i) L->ordem[k++] = L->ordem[j];
        L->numOrdem = k;
        TocarSomTom(sfxSelecao, 0.8f);
    } else if (L->numOrdem < LAB_MAX_ITENS) {
        L->marcados |= 1u << i;
        L->ordem[L->numOrdem++] = i;
        TocarSomTom(sfxSelecao, 1.2f);
    }
}

// Processa: se passar da capacidade, a janela perde os blocos MAIS ANTIGOS (como numa conversa longa)
static void LabProcessarNucleo(Biblioteca *b)
{
    LabEdu *L = &b->lab;
    const DesafioNucleo *d = &DESAFIOS_NUCLEO[L->missao];

    int total = LabTokensCarregados(b);
    L->cortados = 0;
    for (int k = 0; k < L->numOrdem && total > d->capacidade; k++) {
        L->cortados |= 1u << L->ordem[k];
        total -= d->bloco[L->ordem[k]].tokens;
    }

    bool falta = false;
    int ruido = 0;
    for (int i = 0; i < d->numBlocos; i++) {
        bool dentro = (L->marcados & (1u << i)) && !(L->cortados & (1u << i));
        if (d->bloco[i].relevancia == REL_ESSENCIAL && !dentro)    falta = true;
        if (d->bloco[i].relevancia == REL_IRRELEVANTE && dentro)   ruido++;
    }

    if (falta)                          L->resultadoNucleo = (L->cortados != 0) ? NUCLEO_TRUNCADA : NUCLEO_FALTOU;
    else if (ruido > 0 || L->cortados)  L->resultadoNucleo = NUCLEO_RUIDOSA;
    else                                L->resultadoNucleo = NUCLEO_BOA;

    L->processos++;
    L->etapa = LAB_RESPOSTA;
    L->digitado = 0.0f;
    L->tempo = 0.0f;
    L->foco = 0;
    L->luciTemSugestao = false;
    TocarSomTom(sfxSelecao, 1.2f);
    Telemetria("rogue_lab_nucleo", "", (float)LabTokensCarregados(b), L->resultadoNucleo);
}

// ---------- Resultado e recompensas ----------

static void LabRecompensar(Biblioteca *b, ProgressoCorredor *prog)
{
    LabEdu *L = &b->lab;
    bool esp = LAB_ESPECIAL[L->tipo];
    int e = L->estrelas;

    int fc = esp ? ((e == 3) ? 8 : ((e == 2) ? 5 : 2)) : ((e == 3) ? 6 : ((e == 2) ? 4 : 2));
    b->perm->fragmentos += fc;
    AlterarPontos(prog, PONTOS_DESAFIO * e + (esp ? 5 : 0));
    RogueRegistrarResposta(b, e >= 2);

    // Estabilidade da Luci: desempenho excelente e resolver sem ajuda reparam
    int estab = 0;
    if (e == 3) estab++;
    if (e >= 2 && L->ajudas == 0) estab++;
    int antes = RogueEstab(b);
    if (estab > 0) RogueMudarEstabilidade(b, estab, NULL);
    estab = RogueEstab(b) - antes;

    snprintf(L->recompensa, sizeof(L->recompensa), "+%d FRAGMENTOS", fc);
    if (estab > 0)
        snprintf(L->recompensa + strlen(L->recompensa), sizeof(L->recompensa) - strlen(L->recompensa), "   +%d ESTABILIDADE DA LUCI", estab);

    // Especiais: item temporário a partir de 2 estrelas
    if (esp && e >= 2) {
        TipoItem it = RogueSortearTemporario();
        b->j.itens[it]++;
        snprintf(L->recompensa + strlen(L->recompensa), sizeof(L->recompensa) - strlen(L->recompensa), "   +1 %s", ITENS[it].nome);
    }

    // 3 estrelas: escolha de melhoria (rara nas especiais); nas comuns, revela um arquivo oculto no mapa
    if (e == 3) {
        b->escolhaPendente = esp ? ESCOLHA_RARA : ESCOLHA_NORMAL;
        snprintf(L->recompensa + strlen(L->recompensa), sizeof(L->recompensa) - strlen(L->recompensa), "   +%s", esp ? "MELHORIA RARA" : "MELHORIA");
        if (!esp)
            for (int i = 0; i < b->mapa.numNos; i++)
                if (b->mapa.no[i].escondida && !b->mapa.no[i].visitado) {
                    b->mapa.no[i].escondida = false;
                    snprintf(L->recompensa + strlen(L->recompensa), sizeof(L->recompensa) - strlen(L->recompensa), "   +ARQUIVO OCULTO NO MAPA (M)");
                    break;
                }
    }
    LabCortarUtf8(L->recompensa);

    b->labFeitos++;
    b->labEstrelas += e;

    if (e == 3) { TocarSom(sfxAcerto); MostrarEmocaoLuci(EMOCAO_ALEGRE, 2.5f); }
    else        TocarSomTom(sfxAcerto, 0.8f);
    Telemetria("rogue_lab", NOMES_LAB[L->tipo], (float)e, L->missao);
}

// Passo 4 (reforço): calcula as estrelas, monta o resumo e entrega a recompensa (uma vez)
static void LabFinalizar(Biblioteca *b, ProgressoCorredor *prog)
{
    LabEdu *L = &b->lab;
    int e = 1;

    if (L->etapa == LAB_RESULTADO)
        return;

    switch (L->tipo) {

        case LAB_PROMPTS: {
            bool ruim = L->respostaAlucinada || (L->diag != DIAG_IDEAL && L->diag != DIAG_BOA);
            e = (L->notaPrompt >= 9) ? 3 : ((L->notaPrompt >= 6) ? 2 : 1);
            if (L->aceitou && ruim)                       e = 1;
            if (L->respostaAlucinada && e > (L->pegouAlucinacao ? 2 : 1)) e = L->pegouAlucinacao ? 2 : 1;
            if (L->usouReformulacao && e > 2)            e = 2;

            const char *julg = (L->aceitou && L->respostaAlucinada) ? "Você aceitou uma resposta com informação inventada."
                             : (L->aceitou && ruim)                 ? "Você aceitou uma resposta que não atende à missão."
                             : L->pegouAlucinacao                   ? "Você desconfiou e pegou a invenção da IA!"
                             : L->aceitou                           ? "Boa decisão: a resposta atende à missão."
                                                                    : "Você encerrou sem aceitar a resposta.";
            snprintf(L->resultado, sizeof(L->resultado), "Pedido final: %d/10 (%s). %s", L->notaPrompt, TEXTOS_DIAG[L->diag], julg);
        } break;

        case LAB_ARQUIVO: {
            const DesafioArquivo *d = &DESAFIOS_ARQUIVO[L->missao];
            bool s = (L->sel == d->suspeita), mt = (L->sel2 == d->metodoCerto);
            e = 1 + (s ? 1 : 0) + (mt ? 1 : 0);
            snprintf(L->resultado, sizeof(L->resultado), "Afirmação suspeita: %s.   Forma de verificar: %s.",
                     s ? "CERTA" : "ERRADA", mt ? "CERTA" : "ERRADA");
        } break;

        case LAB_NUCLEO: {
            static const char *txt[4] = { "Só o essencial, dentro da capacidade.", "Faltou informação essencial.",
                                          "Passou da capacidade: o começo foi cortado.", "Funcionou, mas com informação demais." };
            e = (L->resultadoNucleo == NUCLEO_BOA) ? 3 : ((L->resultadoNucleo == NUCLEO_RUIDOSA) ? 2 : 1);
            snprintf(L->resultado, sizeof(L->resultado), "%s  (%d de %d tokens)", txt[L->resultadoNucleo],
                     LabTokensCarregados(b), DESAFIOS_NUCLEO[L->missao].capacidade);
        } break;

        case LAB_FIREWALL:
            e = (L->acertos >= 6) ? 3 : ((L->acertos >= 4) ? 2 : 1);
            snprintf(L->resultado, sizeof(L->resultado), "Decisões éticas corretas: %d de %d.", L->acertos, L->decisoes);
            break;

        default: {
            const CasoPesquisa *c = &CASOS_PESQUISA[L->missao];
            int pistas = 0, consultas = 0;
            for (int i = 0; i < 5; i++) if (((L->marcados & (1u << i)) != 0) == c->pista[i].alerta) pistas++;
            for (int i = 0; i < 3; i++) if (L->ferramentas & (1u << i)) consultas++;
            bool certo = (L->veredito == c->veredito);
            e = !certo ? 1 : ((pistas >= 4) ? 3 : 2);
            if (consultas == 0 && e > 2) e = 2;          // sem investigar a procedência, no máximo 2
            snprintf(L->resultado, sizeof(L->resultado), "Veredito: %s (o certo era %s).   Pistas bem avaliadas: %d de 5.   Consultas: %d.",
                     NOMES_VEREDITO[L->veredito < 0 ? 0 : L->veredito], NOMES_VEREDITO[c->veredito], pistas, consultas);
        } break;
    }

    L->estrelas = e;
    LabCortarUtf8(L->resultado);
    L->etapa = LAB_RESULTADO;
    L->tempo = 0.0f;
    L->foco = 0;
    LabRecompensar(b, prog);
}

// Fecha o laboratório concluído: a porta abre e a escolha prometida (se houver) aparece
static void LabConcluir(Biblioteca *b)
{
    LabEdu *L = &b->lab;

    L->aberto = false;
    if (L->concluido)
        return;

    L->concluido = true;
    b->limpa = true;
    RogueSalaConcluida(b);
    RogueParticulas(b, b->posObjetoSala, CORES_LAB[L->tipo], 26, 200);
    RogueAviso(b, TextFormat("%s CONCLUÍDO: %d/3", NOMES_LAB[L->tipo], L->estrelas));
}

// ---------- Firewall Ético e Câmara de Pesquisa ----------

static void LabEscolherOpcaoFirewall(Biblioteca *b, int i)
{
    LabEdu *L = &b->lab;
    const CasoVies *c = &CASOS_VIES[L->missao];
    int certo = (L->fase == 0) ? c->problemaCerto : c->medidaCerta;
    const char *const *ops = (L->fase == 0) ? c->problemas : c->medidas;

    LabConferirSeguiu(b, L->fase, i);

    L->decisoes++;
    if (i == certo) { L->acertos++; TocarSom(sfxAcerto); }
    else            TocarSom(sfxErro);

    snprintf(L->avaliacao, sizeof(L->avaliacao), "%s %s", (i == certo) ? "CERTO!" : "NÃO EXATAMENTE. O melhor era:", (i == certo) ? ops[i] : ops[certo]);
    LabCortarUtf8(L->avaliacao);

    if (L->fase == 0) { L->sel = i; L->fase = 1; }
    else              { L->sel2 = i; L->fase = 2; L->nivelDica = 0; L->tempoPacote = LAB_TEMPO_PACOTE; }
    L->luciTemSugestao = false;
    L->tempo = 0.0f;
    L->foco = 0;
}

// Decisão sobre o pacote de dados atual (-1 = passou sozinho pelo firewall)
static void LabDecidirPacote(Biblioteca *b, ProgressoCorredor *prog, int acao)
{
    LabEdu *L = &b->lab;

    if (L->pacote >= LAB_PACOTES)
        return;

    const PacoteDados *p = &PACOTES_DADOS[L->pacotes[L->pacote]];
    int efetiva = (acao < 0) ? ACAO_PERMITIR : acao;
    bool certo = (efetiva == p->acao);

    if (acao >= 0)
        LabConferirSeguiu(b, 20 + L->pacote, acao);

    L->acoes[L->pacote] = acao;
    L->decisoes++;
    if (certo) { L->acertos++; TocarSom(sfxAcerto); }
    else       TocarSom(sfxErro);

    snprintf(L->avaliacao, sizeof(L->avaliacao), "%s%s %s", certo ? "CERTO! " : "ATENÇÃO! ",
             (acao < 0) ? "O pacote passou sem análise." : "", p->porque);
    LabCortarUtf8(L->avaliacao);

    L->pacote++;
    L->tempoPacote = LAB_TEMPO_PACOTE;
    L->luciTemSugestao = false;
    L->foco = 0;

    if (L->pacote >= LAB_PACOTES)
        LabFinalizar(b, prog);
}

// ---------- Botões (mouse e teclado usam a mesma lista) ----------

typedef enum {
    LB_COMECAR, LB_SAIR, LB_CONCLUIR, LB_SELETOR, LB_ENVIAR, LB_ACEITAR, LB_REFAZER, LB_DESCONFIAR, LB_ENCERRAR,
    LB_DICA, LB_ANALISAR, LB_REFORMULAR, LB_VERIFICAR, LB_CHECAR, LB_USAR_SUGESTAO, LB_DESCARTAR_SUGESTAO,
    LB_ITEM, LB_OPCAO, LB_CONFIRMAR, LB_PROCESSAR, LB_LIMPAR, LB_AJUSTAR, LB_FERRAMENTA, LB_PACOTE, LB_VEREDITO,
    LB_PECA
} AcaoLab;

typedef enum { EST_BOTAO, EST_LUCI, EST_ITEM, EST_SELETOR, EST_ENCAIXE, EST_PECA } EstiloBotaoLab;

typedef struct {
    Rectangle r;
    AcaoLab acao;
    int param;
    bool ativo;
    bool marcado;
    int custo;                  // carga de ajuda (botões da Luci)
    EstiloBotaoLab estilo;
    char rotulo[64];
    const char *texto;          // texto longo dos cartões (afirmações, blocos, pistas...)
    Color cor;
    int fonte;                  // tamanho do texto do cartão
    bool chip;                  // o rótulo vai num selo à direita (tokens do Núcleo); encaixe: peça trocada pela Luci
    int luz;                    // encaixe do laboratório de prompts: LuzParte (-1 = sem luz)
} BotaoLab;

#define LAB_PAINEL_X     28
#define LAB_PAINEL_Y     30
#define LAB_PAINEL_W     744
#define LAB_PAINEL_H     508
#define RET_FECHAR_LAB   ((Rectangle){ 744, 36, 22, 20 })     // X do canto (o mesmo que ESC)
#define LAB_Y_LUCI       410
#define LAB_Y_BOTOES     470
#define LAB_ALT_BOTAO    26

static BotaoLab *LabAddBotao(BotaoLab *bt, int *n, Rectangle r, AcaoLab acao, int param, const char *rotulo)
{
    static BotaoLab descarte;

    if (*n >= MAX_BOTOES_LAB) { memset(&descarte, 0, sizeof(descarte)); return &descarte; }

    BotaoLab *o = &bt[(*n)++];
    memset(o, 0, sizeof(*o));
    o->r = r;
    o->acao = acao;
    o->param = param;
    o->ativo = true;
    o->estilo = EST_BOTAO;
    o->cor = WHITE;
    o->fonte = 10;
    o->luz = -1;
    if (rotulo != NULL) { snprintf(o->rotulo, sizeof(o->rotulo), "%s", rotulo); LabCortarUtf8(o->rotulo); }
    return o;
}

static float LabLarguraBotao(const char *rotulo, int custo)
{
    return (float)(MeasureText(rotulo, 10) + 24 + custo * 8);
}

// Botões da Luci (à esquerda, na linha de baixo)
static void LabBotoesLuci(const Biblioteca *b, BotaoLab *bt, int *n, bool analisar, bool reformular, bool verificar)
{
    const LabEdu *L = &b->lab;
    float x = 44.0f, y = (float)LAB_Y_BOTOES;
    Color ciano = { 0, 228, 255, 255 };

    struct { AcaoLab a; const char *r; int custo; bool ativo; bool mostra; } lista[5] = {
        { LB_DICA,       TextFormat("DICA %d/3", (L->nivelDica < 3) ? L->nivelDica + 1 : 3), LAB_CUSTO_DICA, L->nivelDica < 3, true },
        { LB_ANALISAR,   "ANALISAR",   LAB_CUSTO_ANALISE,      true,             analisar },
        { LB_REFORMULAR, "REFORMULAR", LAB_CUSTO_REFORMULACAO, !L->temSugestao,  reformular },
        { LB_VERIFICAR,  "VERIFICAR",  LAB_CUSTO_VERIFICACAO,  true,             verificar },
        { LB_CHECAR,     "CONFERIR (V)", 0, L->luciTemSugestao && !L->luciVerificada, true },
    };

    for (int i = 0; i < 5; i++) {
        if (!lista[i].mostra) continue;
        char rot[48];
        snprintf(rot, sizeof(rot), "%s", lista[i].r);
        float w = LabLarguraBotao(rot, lista[i].custo);
        BotaoLab *o = LabAddBotao(bt, n, (Rectangle){ x, y, w, LAB_ALT_BOTAO }, lista[i].a, 0, rot);
        o->estilo = EST_LUCI;
        o->custo = lista[i].custo;
        o->ativo = lista[i].ativo;
        o->cor = (lista[i].a == LB_CHECAR) ? GOLD : ciano;
        x += w + 6;
    }
}

// Botão de ação alinhado pela direita
static BotaoLab *LabBotaoDireita(BotaoLab *bt, int *n, float *xDir, AcaoLab acao, int param, const char *rotulo, Color cor)
{
    float w = LabLarguraBotao(rotulo, 0) + 6;
    *xDir -= w;
    BotaoLab *o = LabAddBotao(bt, n, (Rectangle){ *xDir, (float)LAB_Y_BOTOES, w, LAB_ALT_BOTAO }, acao, param, rotulo);
    o->cor = cor;
    *xDir -= 6;
    return o;
}

// Altura de um cartão com texto quebrado
static float LabAlturaCartao(const char *texto, int largura, int fonte, int espaco)
{
    char linhas[512];
    QuebrarTexto(texto, largura, fonte, linhas, (int)sizeof(linhas));
    return (float)(ContarLinhas(linhas) * espaco + 12);
}

// Laboratório de prompts: os 4 encaixes formam a "frase" do pedido, lado a lado
#define LAB_ANIM_PECA   0.28f    // segundos da peça voando até o encaixe

static Rectangle LabRetEncaixe(int k)
{
    return (Rectangle){ 44.0f + k * 180.0f, 102, 172, 66 };
}

// Cartões das peças do encaixe ativo (0 a 2 = alternativas, 3 = deixar vazio)
static Rectangle LabRetPeca(int c)
{
    return (Rectangle){ 44, 202.0f + c * 49.0f, 392, 43 };
}

static const Color CORES_PARTES_PROMPT[NUM_PARTES_PROMPT] = {
    { 200, 122, 255, 255 }, { 102, 191, 255, 255 }, { 255, 203, 0, 255 }, { 40, 220, 170, 255 }
};
static const char *DICAS_PARTES_PROMPT[NUM_PARTES_PROMPT] = { "QUEM responde", "PARA QUEM", "O QUE fazer", "COMO entregar" };

// Coloca a peça (0 = vazio) no encaixe ativo e segue para o próximo
static void LabColocarPeca(Biblioteca *b, int alt)
{
    LabEdu *L = &b->lab;
    const MissaoPrompt *m = &MISSOES_PROMPT[L->missao];
    int k = L->slotAtivo;

    if (alt < 0 || alt > 3 || (alt > 0 && m->alt[k][alt - 1] == NULL))
        return;

    L->escolha[k] = alt;
    L->animPeca = LAB_ANIM_PECA;
    L->animSlot = k;
    L->animDe = (alt == 0) ? 3 : alt - 1;
    if (k < NUM_PARTES_PROMPT - 1)
        L->slotAtivo = k + 1;
    TocarSomTom(sfxPegar, 1.0f + 0.12f * (float)k);
}

static int LabMontarBotoes(const Biblioteca *b, BotaoLab *bt, int max)
{
    const LabEdu *L = &b->lab;
    int n = 0;
    float xDir = 756.0f;
    Color cor = CORES_LAB[L->tipo];
    (void)max;

    if (L->etapa == LAB_INTRO) {
        LabBotaoDireita(bt, &n, &xDir, LB_COMECAR, 0, "COMEÇAR", cor);
        LabBotaoDireita(bt, &n, &xDir, LB_SAIR, 0, "AGORA NÃO", GRAY);
        return n;
    }
    if (L->etapa == LAB_RESULTADO) {
        LabBotaoDireita(bt, &n, &xDir, LB_CONCLUIR, 0, "CONCLUIR", cor);
        return n;
    }

    switch (L->tipo) {

        case LAB_PROMPTS: {
            const MissaoPrompt *mp = &MISSOES_PROMPT[L->missao];
            bool editando = (L->etapa == LAB_DESAFIO);
            bool sugestao = editando && L->temSugestao;
            const int *esc = sugestao ? L->sugestao : L->escolha;

            // Os 4 encaixes (clicar escolhe qual editar)
            for (int k = 0; k < NUM_PARTES_PROMPT; k++) {
                BotaoLab *o = LabAddBotao(bt, &n, LabRetEncaixe(k), LB_SELETOR, k, NOMES_PARTES_PROMPT[k]);
                o->estilo = EST_ENCAIXE;
                o->texto = (esc[k] > 0) ? mp->alt[k][esc[k] - 1] : NULL;
                o->ativo = editando && !sugestao;
                o->marcado = editando && !sugestao && k == L->slotAtivo;
                o->chip = sugestao && L->sugestao[k] != L->escolha[k];
                o->luz = sugestao ? -1 : LabLuzVisivel(L, mp, k);
                o->cor = CORES_PARTES_PROMPT[k];
            }

            if (editando) {
                if (sugestao) {
                    // A sugestão da Luci aparece nos encaixes: usar ou descartar
                    LabAddBotao(bt, &n, (Rectangle){ 60, 262, 170, 26 }, LB_USAR_SUGESTAO, 0, "USAR A SUGESTÃO")->cor = (Color){ 0, 228, 255, 255 };
                    LabAddBotao(bt, &n, (Rectangle){ 240, 262, 110, 26 }, LB_DESCARTAR_SUGESTAO, 0, "DESCARTAR")->cor = GRAY;
                } else {
                    // As peças do encaixe ativo (1 a 3) e "deixar vazio" (0)
                    int k = L->slotAtivo;
                    for (int c = 0; c < 4; c++) {
                        int alt = (c < 3) ? c + 1 : 0;
                        if (alt > 0 && mp->alt[k][alt - 1] == NULL) continue;
                        BotaoLab *o = LabAddBotao(bt, &n, LabRetPeca(c), LB_PECA, alt, (alt > 0) ? TextFormat("%d", alt) : "0");
                        o->estilo = EST_PECA;
                        o->texto = (alt > 0) ? mp->alt[k][alt - 1] : "Deixar vazio";
                        o->marcado = (L->escolha[k] == alt);
                        o->cor = CORES_PARTES_PROMPT[k];
                    }
                }
                LabBotoesLuci(b, bt, &n, true, true, false);
                bool vazio = true;
                for (int k = 0; k < NUM_PARTES_PROMPT; k++) if (L->escolha[k] > 0) vazio = false;
                LabBotaoDireita(bt, &n, &xDir, LB_ENVIAR, 0, TextFormat("ENVIAR %d/%d", L->envios + 1, LAB_MAX_ENVIOS), cor)->ativo = !vazio && L->envios < LAB_MAX_ENVIOS && !sugestao;
            } else {
                int len = (int)strlen(LabTextoRespostaAtual(b));
                bool pronto = L->digitado >= (float)len;
                LabBotoesLuci(b, bt, &n, true, false, true);
                LabBotaoDireita(bt, &n, &xDir, LB_ACEITAR, 0, "ACEITAR", LIME)->ativo = pronto;
                if (L->envios < LAB_MAX_ENVIOS)
                    LabBotaoDireita(bt, &n, &xDir, LB_REFAZER, 0, "TROCAR PEÇAS", GOLD)->ativo = pronto;
                else
                    LabBotaoDireita(bt, &n, &xDir, LB_ENCERRAR, 0, "ENCERRAR", GRAY)->ativo = pronto;
                LabBotaoDireita(bt, &n, &xDir, LB_DESCONFIAR, 0, "DESCONFIAR", MAGENTA)->ativo = pronto && !L->desconfiou;
            }
        } break;

        case LAB_ARQUIVO: {
            const DesafioArquivo *d = &DESAFIOS_ARQUIVO[L->missao];
            float y = 150.0f;
            for (int i = 0; i < 4; i++) {
                char rot[8];
                snprintf(rot, sizeof(rot), "%d", i + 1);
                float h = LabAlturaCartao(d->af[i], 410, 12, 16);
                BotaoLab *o = LabAddBotao(bt, &n, (Rectangle){ 56, y, 456, h }, LB_ITEM, i, rot);
                o->estilo = EST_ITEM;
                o->texto = d->af[i];
                o->fonte = 12;
                o->marcado = (L->sel == i);
                o->ativo = (L->fase == 0);
                o->cor = cor;
                y += h + 8;
            }
            if (L->fase == 1) {
                float ym = 176.0f;
                for (int i = 0; i < 3; i++) {
                    float h = LabAlturaCartao(d->metodos[i], 224 - 46, 10, 13);
                    BotaoLab *o = LabAddBotao(bt, &n, (Rectangle){ 532, ym, 224, h }, LB_OPCAO, i, TextFormat("%c", 'A' + i));
                    o->estilo = EST_ITEM;
                    o->texto = d->metodos[i];
                    o->marcado = (L->sel2 == i);
                    o->cor = cor;
                    ym += h + 6;
                }
            }
            LabBotoesLuci(b, bt, &n, false, false, true);
            LabBotaoDireita(bt, &n, &xDir, LB_CONFIRMAR, 0, (L->fase == 0) ? "MARCAR COMO SUSPEITA" : "VERIFICAR ASSIM", cor)->ativo =
                (L->fase == 0) ? (L->sel >= 0) : (L->sel2 >= 0);
        } break;

        case LAB_NUCLEO: {
            const DesafioNucleo *d = &DESAFIOS_NUCLEO[L->missao];
            bool editando = (L->etapa == LAB_DESAFIO);
            for (int i = 0; i < d->numBlocos; i++) {
                BotaoLab *o = LabAddBotao(bt, &n, (Rectangle){ 44.0f + (float)(i % 2) * 242.0f, 128.0f + (float)(i / 2) * 62.0f, 232, 54 },
                                          LB_ITEM, i, TextFormat("%d tk", d->bloco[i].tokens));
                o->estilo = EST_ITEM;
                o->texto = d->bloco[i].texto;
                o->chip = true;
                o->marcado = (L->marcados & (1u << i)) != 0;
                o->ativo = editando;
                o->cor = cor;
            }
            if (editando) {
                LabBotoesLuci(b, bt, &n, false, false, true);
                LabBotaoDireita(bt, &n, &xDir, LB_PROCESSAR, 0, "PROCESSAR", cor)->ativo = L->marcados != 0;
                LabBotaoDireita(bt, &n, &xDir, LB_LIMPAR, 0, "LIMPAR", GRAY)->ativo = L->marcados != 0;
            } else {
                int len = (int)strlen(LabTextoRespostaAtual(b));
                bool pronto = L->digitado >= (float)len;
                LabBotoesLuci(b, bt, &n, false, false, false);
                LabBotaoDireita(bt, &n, &xDir, LB_ENCERRAR, 0, "FICAR COM ESTA RESPOSTA", LIME)->ativo = pronto;
                if (L->processos < LAB_MAX_PROCESSOS && L->resultadoNucleo != NUCLEO_BOA)
                    LabBotaoDireita(bt, &n, &xDir, LB_AJUSTAR, 0, "AJUSTAR O CONTEXTO", GOLD)->ativo = pronto;
            }
        } break;

        case LAB_FIREWALL: {
            const CasoVies *c = &CASOS_VIES[L->missao];
            if (L->fase < 2) {
                const char *const *ops = (L->fase == 0) ? c->problemas : c->medidas;
                for (int i = 0; i < 3; i++) {
                    BotaoLab *o = LabAddBotao(bt, &n, (Rectangle){ 56, 252.0f + i * 44.0f, 688, 38 }, LB_OPCAO, i, TextFormat("%c", 'A' + i));
                    o->estilo = EST_ITEM;
                    o->texto = ops[i];
                    o->cor = cor;
                }
            } else {
                static const Color cores[NUM_ACOES_PACOTE] = { { 0, 228, 48, 255 }, { 230, 41, 55, 255 }, { 255, 203, 0, 255 } };
                for (int a = 0; a < NUM_ACOES_PACOTE; a++) {
                    BotaoLab *o = LabAddBotao(bt, &n, (Rectangle){ 104.0f + a * 204.0f, 352, 184, 40 }, LB_PACOTE, a, NOMES_ACAO_PACOTE[a]);
                    o->cor = cores[a];
                }
            }
            LabBotoesLuci(b, bt, &n, false, false, true);
        } break;

        default: {
            const CasoPesquisa *c = &CASOS_PESQUISA[L->missao];
            int consultas = 0;
            for (int i = 0; i < 3; i++) if (L->ferramentas & (1u << i)) consultas++;
            for (int i = 0; i < 5; i++) {
                BotaoLab *o = LabAddBotao(bt, &n, (Rectangle){ 352, 116.0f + i * 38.0f, 404, 34 }, LB_ITEM, i, "");
                o->estilo = EST_ITEM;
                o->texto = c->pista[i].texto;
                o->marcado = (L->marcados & (1u << i)) != 0;
                o->cor = cor;
            }
            for (int i = 0; i < 3; i++) {
                bool usada = (L->ferramentas & (1u << i)) != 0;
                BotaoLab *o = LabAddBotao(bt, &n, (Rectangle){ 44, 314.0f + i * 30.0f, 290, 26 }, LB_FERRAMENTA, i, c->ferramenta[i]);
                o->ativo = !usada && consultas < LAB_MAX_FERRAMENTAS;
                o->marcado = usada;
                o->cor = SKYBLUE;
            }
            LabBotoesLuci(b, bt, &n, false, false, true);
            static const Color cores[NUM_VEREDITOS] = { { 0, 228, 48, 255 }, { 230, 41, 55, 255 }, { 255, 161, 0, 255 } };
            for (int v = NUM_VEREDITOS - 1; v >= 0; v--)
                LabBotaoDireita(bt, &n, &xDir, LB_VEREDITO, v, NOMES_VEREDITO[v], cores[v]);
        } break;
    }

    return n;
}

// Executa o botão (dir: +1 clique/confirmação, -1 botão direito ou A num seletor)
static void LabExecutar(Biblioteca *b, ProgressoCorredor *prog, const BotaoLab *o, int dir)
{
    LabEdu *L = &b->lab;
    (void)dir;              // (o seletor antigo usava a direção; os encaixes novos não precisam)

    if (!o->ativo)
        return;

    switch (o->acao) {
        case LB_COMECAR:   LabComecar(b); break;
        case LB_SAIR:      L->aberto = false; TocarSom(sfxSelecao); break;
        case LB_CONCLUIR:  LabConcluir(b); break;

        case LB_SELETOR:            // encaixe do laboratório de prompts: passa a editar este
            L->slotAtivo = o->param;
            TocarSom(sfxSelecao);
            break;

        case LB_PECA:
            LabColocarPeca(b, o->param);
            break;

        case LB_ENVIAR:
            L->original = false;
            LabEnviarPrompt(b);
            break;

        case LB_ACEITAR:
            L->aceitou = true;
            LabConferirSeguiu(b, 100 + L->envios, 0);
            LabFinalizar(b, prog);
            break;

        case LB_REFAZER: {
            LabConferirSeguiu(b, 100 + L->envios, 1);
            L->original = false;
            L->etapa = LAB_DESAFIO;
            L->tempo = 0.0f;
            L->foco = 0;
            // Volta direto ao primeiro encaixe que acendeu em vermelho/laranja (ou em conflito)
            const MissaoPrompt *m = &MISSOES_PROMPT[L->missao];
            for (int k = NUM_PARTES_PROMPT - 1; k >= 0; k--) {
                LuzParte z = LabLuzParte(m, L->escolha, k);
                if (z != LUZ_IDEAL && z != LUZ_OK && z != LUZ_DISPENSAVEL) L->slotAtivo = k;
            }
            TocarSom(sfxSelecao);
        } break;

        case LB_DESCONFIAR: {
            const MissaoPrompt *m = &MISSOES_PROMPT[L->missao];
            LabConferirSeguiu(b, 100 + L->envios, 1);
            L->desconfiou = true;
            if (L->respostaAlucinada) {
                L->pegouAlucinacao = true;
                snprintf(L->avaliacao, sizeof(L->avaliacao), "SUSPEITA CONFIRMADA: %s", m->trechoFalso);
                TocarSom(sfxAcerto);
            } else if (L->diag == DIAG_IDEAL || L->diag == DIAG_BOA) {
                snprintf(L->avaliacao, sizeof(L->avaliacao), "Conferido em fontes confiáveis: nada inventado aqui. Desconfiar é um bom hábito!");
                TocarSomTom(sfxSelecao, 1.3f);
            } else {
                snprintf(L->avaliacao, sizeof(L->avaliacao), "Nada inventado, mas a resposta não atende à missão: o problema está no pedido.");
                TocarSomTom(sfxSelecao, 1.3f);
            }
            LabCortarUtf8(L->avaliacao);
        } break;

        case LB_ENCERRAR:   LabFinalizar(b, prog); break;
        case LB_DICA:       LabPedirDica(b); break;
        case LB_ANALISAR:   LabAnalisarPrompt(b); break;
        case LB_REFORMULAR: LabReformular(b); break;
        case LB_VERIFICAR:  LabLuciVerificar(b); break;
        case LB_CHECAR:     LabChecarLuci(b); break;

        case LB_USAR_SUGESTAO:
            for (int k = 0; k < NUM_PARTES_PROMPT; k++) L->escolha[k] = L->sugestao[k];
            L->usouReformulacao = true;
            L->temSugestao = false;
            if (!L->luciVerificada) LabSeguiuLuci(b);
            TocarSom(sfxSelecao);
            break;

        case LB_DESCARTAR_SUGESTAO:
            L->temSugestao = false;
            TocarSom(sfxSelecao);
            break;

        case LB_ITEM:
            if (L->tipo == LAB_ARQUIVO)      L->sel = o->param;
            else if (L->tipo == LAB_NUCLEO)  LabAlternarBloco(b, o->param);
            else                             L->marcados ^= 1u << o->param;
            TocarSom(sfxSelecao);
            break;

        case LB_OPCAO:
            if (L->tipo == LAB_ARQUIVO) { L->sel2 = o->param; TocarSom(sfxSelecao); }
            else                        LabEscolherOpcaoFirewall(b, o->param);
            break;

        case LB_CONFIRMAR:
            if (L->fase == 0) {
                LabConferirSeguiu(b, 0, L->sel);
                L->fase = 1;
                L->foco = 0;
                L->tempo = 0.0f;
                TocarSom(sfxSelecao);
            } else {
                LabConferirSeguiu(b, 1, L->sel2);
                LabFinalizar(b, prog);
            }
            break;

        case LB_PROCESSAR:
            LabProcessarNucleo(b);
            break;

        case LB_LIMPAR:
            L->marcados = 0;
            L->numOrdem = 0;
            TocarSom(sfxSelecao);
            break;

        case LB_AJUSTAR:
            L->etapa = LAB_DESAFIO;
            L->cortados = 0;
            L->tempo = 0.0f;
            L->foco = 0;
            TocarSom(sfxSelecao);
            break;

        case LB_FERRAMENTA:
            L->ferramentas |= 1u << o->param;
            TocarSomTom(sfxPegar, 1.2f);
            break;

        case LB_PACOTE:
            LabDecidirPacote(b, prog, o->param);
            break;

        case LB_VEREDITO:
            L->veredito = o->param;
            LabFinalizar(b, prog);
            break;
    }
}

static int LabProximoAtivo(const BotaoLab *bt, int n, int de, int passo)
{
    for (int k = 1; k <= n; k++) {
        int i = ((de + passo * k) % n + n) % n;
        if (bt[i].ativo) return i;
    }
    return de;
}

// A janela do laboratório: o combate espera. W/S (ou TAB) escolhem, A/D mudam a alternativa
// de um seletor, E/ENTER confirmam, H pede dica, V confere a Luci, BACKSPACE/ESC saem.
static void RogueAtualizarLab(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    LabEdu *L = &b->lab;

    L->tempo += dt;
    if (L->etapa == LAB_DESAFIO || L->etapa == LAB_RESPOSTA)
        L->tempoTotal += dt;
    if (L->animPeca > 0.0f) L->animPeca -= dt;
    if (L->etapa == LAB_RESPOSTA) L->tempoResposta += dt;

    // Montagem do pedido: A/D trocam o encaixe, 1-3 escolhem a peça, 0 deixa vazio, ENTER envia
    bool montagemPrompt = (L->tipo == LAB_PROMPTS && L->etapa == LAB_DESAFIO && !L->temSugestao);

    const char *resp = (L->etapa == LAB_RESPOSTA) ? LabTextoRespostaAtual(b) : NULL;
    int lenResp = (resp != NULL) ? (int)strlen(resp) : 0;
    if (resp != NULL && L->digitado < (float)lenResp)
        L->digitado += dt * LAB_VELOCIDADE_TEXTO;

    // Firewall: o pacote anda até o firewall; sem decisão, ele atravessa sozinho
    if (L->tipo == LAB_FIREWALL && L->etapa == LAB_DESAFIO && L->fase == 2 && L->pacote < LAB_PACOTES) {
        L->tempoPacote -= dt;
        if (L->tempoPacote <= 0.0f) {
            LabDecidirPacote(b, prog, -1);
            return;
        }
    }

    if (IsKeyPressed(KEY_ESCAPE) || IsKeyPressed(KEY_BACKSPACE) || (CliqueMouse() && MouseEm(RET_FECHAR_LAB))) {
        if (L->etapa == LAB_RESULTADO) LabConcluir(b);
        else                           L->aberto = false;      // dá para voltar ao console
        TocarSom(sfxSelecao);
        return;
    }

    BotaoLab bt[MAX_BOTOES_LAB];
    int n = LabMontarBotoes(b, bt, MAX_BOTOES_LAB);
    if (n <= 0)
        return;

    if (L->foco < 0 || L->foco >= n || !bt[L->foco].ativo)
        L->foco = LabProximoAtivo(bt, n, (L->foco < 0 || L->foco >= n) ? n - 1 : L->foco, 1);

    // Teclado
    bool seletor = bt[L->foco].estilo == EST_SELETOR;
    bool lados = !seletor && !montagemPrompt;           // na montagem, A/D trocam o encaixe
    if (IsKeyPressed(KEY_TAB) || IsKeyPressed(KEY_S) || IsKeyPressed(KEY_DOWN) || (lados && (IsKeyPressed(KEY_D) || IsKeyPressed(KEY_RIGHT))))
        { L->foco = LabProximoAtivo(bt, n, L->foco, 1);  TocarSom(sfxSelecao); }
    if (IsKeyPressed(KEY_W) || IsKeyPressed(KEY_UP) || (lados && (IsKeyPressed(KEY_A) || IsKeyPressed(KEY_LEFT))))
        { L->foco = LabProximoAtivo(bt, n, L->foco, -1); TocarSom(sfxSelecao); }

    // Mouse
    Vector2 m = GetMousePosition();
    bool moveu = Vector2Length(GetMouseDelta()) > 0.5f;
    int clicado = -1, dirClique = 1;
    for (int i = 0; i < n; i++) {
        if (!bt[i].ativo || !CheckCollisionPointRec(m, bt[i].r)) continue;
        if (moveu) L->foco = i;
        if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT))  { clicado = i; dirClique = 1; }
        if (IsMouseButtonPressed(MOUSE_BUTTON_RIGHT)) { clicado = i; dirClique = -1; }
    }

    if (L->tempo < 0.25f)                   // evita confirmar sem querer ao abrir ou trocar de etapa
        return;

    bool confirmar = IsKeyPressed(KEY_E) || IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_SPACE);

    // A resposta ainda está sendo "digitada": o primeiro toque mostra tudo
    if (resp != NULL && L->digitado < (float)lenResp && (confirmar || clicado >= 0)) {
        L->digitado = (float)lenResp;
        return;
    }

    if (montagemPrompt && clicado < 0) {
        if (IsKeyPressed(KEY_A) || IsKeyPressed(KEY_LEFT))  { L->slotAtivo = (L->slotAtivo + NUM_PARTES_PROMPT - 1) % NUM_PARTES_PROMPT; TocarSom(sfxSelecao); return; }
        if (IsKeyPressed(KEY_D) || IsKeyPressed(KEY_RIGHT)) { L->slotAtivo = (L->slotAtivo + 1) % NUM_PARTES_PROMPT;                     TocarSom(sfxSelecao); return; }
        for (int a = 1; a <= 3; a++)
            if (IsKeyPressed(KEY_ZERO + a)) { LabColocarPeca(b, a); return; }
        if (IsKeyPressed(KEY_ZERO) || IsKeyPressed(KEY_FOUR)) { LabColocarPeca(b, 0); return; }
        if (IsKeyPressed(KEY_ENTER)) {
            for (int i = 0; i < n; i++)
                if (bt[i].acao == LB_ENVIAR && bt[i].ativo) { LabExecutar(b, prog, &bt[i], 1); return; }
        }
    }

    if (seletor && clicado < 0) {
        if (IsKeyPressed(KEY_A) || IsKeyPressed(KEY_LEFT))  { LabExecutar(b, prog, &bt[L->foco], -1); return; }
        if (IsKeyPressed(KEY_D) || IsKeyPressed(KEY_RIGHT)) { LabExecutar(b, prog, &bt[L->foco], 1);  return; }
    }

    // Atalhos da Luci
    for (int i = 0; i < n; i++) {
        if (!bt[i].ativo) continue;
        if ((IsKeyPressed(KEY_H) && bt[i].acao == LB_DICA) || (IsKeyPressed(KEY_V) && bt[i].acao == LB_CHECAR)) {
            LabExecutar(b, prog, &bt[i], 1);
            return;
        }
    }

    if (clicado >= 0)                  LabExecutar(b, prog, &bt[clicado], dirClique);
    else if (confirmar && bt[L->foco].ativo) LabExecutar(b, prog, &bt[L->foco], 1);
}

// O que está ao alcance do E agora (-1 = nada)
typedef enum { ALVO_NADA, ALVO_BYTE, ALVO_BYTECO, ALVO_TERMINAL, ALVO_PEDESTAL, ALVO_ENCICLOPEDIA, ALVO_PECA, ALVO_ENCAIXE,
               ALVO_REGISTRO, ALVO_CONTEXTO, ALVO_RECOMPENSA, ALVO_OBJETO_SALA, ALVO_REGISTRO_SALA, ALVO_LAB,
               ALVO_ARMA_MESTRE, ALVO_TERMINAL_SELETOR, ALVO_TERMINAL_BLOCO3 } AlvoRogue;

// ---------- Fim do Bloco 1: a sala da ALUCINAÇÃO MESTRE ----------

static bool MestreVulneravel(const MestreTreino *m)
{
    if (m->morrendo > 0.0f || !m->visivel || m->surgindo > 0.0f)
        return false;
    if (m->acao == MA_ATORDOADA || m->acao == MA_ABERTA)
        return true;
    return m->acao == MA_RECUPERA && m->etapa == MT_LUTA;      // brecha menor: só na luta
}

// Tempo que falta até o golpe acertar (o anel em volta do Thomas fecha nesse instante; < 0 = sem golpe)
static float MestreTempoAteGolpe(const MestreTreino *m, Vector2 jogador, float telegrafia)
{
    float dist = fmaxf(0.0f, Vector2Distance(m->pos, jogador) - MESTRE_RAIO - RAIO_CORPO_JOGADOR);
    if (m->acao == MA_TELEGRAFA) return m->tempoAcao + dist / MESTRE_INVESTIDA_VEL;
    if (m->acao == MA_INVESTE && !m->acertouGolpe) return dist / MESTRE_INVESTIDA_VEL;
    (void)telegrafia;
    return -1.0f;
}

static float MestreTelegrafia(const MestreTreino *m)
{
    return (m->etapa == MT_LUTA) ? MESTRE_TELEGRAFIA * ((m->fase == 2) ? 0.85f : 1.0f) : MESTRE_TELEGRAFIA * 1.3f;
}

// Entra na sala (o main chama ao sair do corredor pela porta da direita)
static void RogueEntrarSalaMestre(Biblioteca *b)
{
    MestreTreino *m = &b->mestre;

    b->noAtual = -1;
    b->ladoEntrada = LADO_BAIXO;
    b->fatorVidaInimigos = b->fatorRitmoInimigos = b->fatorDanoSala = 1.0f;
    RogueLimparSala(b, SALA_MESTRE, SPAWN_ROGUE);
    RogueUsarLayout(b, &LAYOUT_CHEFE);
    RogueLimparEfeitos(&b->j);
    b->j.hp = RogueHpMax(b);
    b->j.ep = RogueEpMax(b);
    b->j.direcao = DIR_COSTAS;

    memset(m, 0, sizeof(*m));
    m->ativo = true;
    m->etapa = MT_ARMA;
    m->pos = POS_MESTRE_INICIO;
    m->hp = MESTRE_HP;
    m->fase = 1;
    for (int i = 0; i < MESTRE_ALVOS; i++) { m->alvo[i] = POS_ALVOS_MESTRE[i]; m->alvoVivo[i] = false; }

    b->conversaPendente = &dialogoMestreChegada;
    b->objConversa = OBJ_NENHUM;
    Telemetria("mestre_entrada", "", 0.0f, 0);
}

static void MestreMudarEtapa(Biblioteca *b, EtapaMestre etapa)
{
    MestreTreino *m = &b->mestre;

    m->etapa = etapa;
    m->tempoEtapa = 0.0f;
    m->acao = MA_PAUSA;
    m->tempoAcao = 1.2f;
    m->proximoGolpe = false;
    for (int i = 0; i < MAX_PROJETEIS; i++)                 // a etapa nova começa sem balas no ar
        if (!b->proj[i].doJogador) b->proj[i].ativo = false;

    if (etapa == MT_TIRO) {
        for (int i = 0; i < MESTRE_ALVOS; i++) m->alvoVivo[i] = true;
    } else if (etapa == MT_ESQUIVA) {
        m->visivel = true;
        m->surgindo = 1.0f;
        m->tempoAcao = 1.6f;
        RogueParticulas(b, m->pos, MAGENTA, 40, 260);
        TocarSom(sfxEstatica);
    } else if (etapa == MT_LUTA) {
        b->j.hp = RogueHpMax(b);
        RogueAviso(b, "ALUCINAÇÃO MESTRE: AGORA É PRA VALER!");
    }

    if (FALAS_MESTRE_ETAPA[etapa] != NULL)
        b->falaPendente = FALAS_MESTRE_ETAPA[etapa];
    Telemetria("mestre_etapa", "", (float)m->tempoEtapa, (int)etapa);
}

// Parry perfeito na investida: congela, aproxima a câmera e ela fica atordoada (brecha grande)
static void MestreParry(Biblioteca *b, Vector2 ponto)
{
    MestreTreino *m = &b->mestre;
    JogadorRogue *j = &b->j;

    m->acao = MA_ATORDOADA;
    m->tempoAcao = MESTRE_STUN;
    m->parries++;
    m->pos = Vector2Subtract(m->pos, Vector2Scale(m->dirGolpe, 26.0f));
    RogueEmpurrarParaFora(&m->pos, MESTRE_RAIO, NULL, 0);

    j->parry.emParry = false;
    j->parry.tempoJanelaParry = 0.0f;
    j->parry.cooldownParry = 0.15f;
    j->parry.hitFreezeAtivo = true;
    j->parry.tempoHitFreeze = PARRY_HIT_FREEZE;
    if (j->invulneravel < 0.45f) j->invulneravel = 0.45f;

    b->pausaImpacto = PARRY_HIT_FREEZE;
    b->tremor = 0.3f;
    b->tremorForte = 0.3f;
    b->zoomImpacto = PARRY_ZOOM;
    b->focoZoom = ponto;
    RogueAnel(b, ponto, 150.0f, WHITE);
    RogueAnel(b, ponto, 90.0f, GOLD);
    RogueParticulas(b, ponto, GOLD, 36, 400);
    for (int i = 0; i < MAX_PROJETEIS; i++)
        if (b->proj[i].ativo && !b->proj[i].doJogador && Vector2Distance(b->proj[i].pos, ponto) < 170.0f)
            b->proj[i].ativo = false;

    TocarSom(sfxParryPerfeito);
    RogueTextoFlutuante(b, (Vector2){ ponto.x, ponto.y - 44 }, "PARRY PERFEITO!", GOLD);
    Telemetria("mestre_parry", "", (float)m->etapa, m->parries);
}

// Rajadas: 0 = anéis, 1 = leques mirados, 2 = espiral. Devolve true quando terminou.
static bool MestreRajada(Biblioteca *b, float dt)
{
    MestreTreino *m = &b->mestre;
    bool treino = m->etapa != MT_LUTA;
    float dano = treino ? MESTRE_DANO_BALA_TREINO : MESTRE_DANO_BALA;
    float ritmo = (m->fase == 2) ? 1.2f : 1.0f;

    m->cronoTiro -= dt * ritmo;
    if (m->cronoTiro > 0.0f)
        return false;

    Vector2 mira = Vector2Subtract(b->j.pos, m->pos);
    mira = (Vector2Length(mira) > 0.1f) ? Vector2Normalize(mira) : (Vector2){ 0, 1 };

    switch (m->padrao) {
        case 0: {           // anéis lentos (o treino da esquiva usa só este)
            int n = treino ? 14 : 18;
            float giro = (float)m->disparos * 0.21f;
            for (int k = 0; k < n; k++) {
                float a = giro + (2.0f * PI / n) * k;
                RogueDisparar(b, m->pos, (Vector2){ cosf(a), sinf(a) }, treino ? 140.0f : 165.0f, dano, 7.0f, false);
            }
            m->cronoTiro = treino ? 0.9f : 0.6f;
            m->disparos++;
            TocarSomTom(sfxTiro, 0.7f);
            return m->disparos >= 3;
        }
        case 1:             // leques mirados
            for (int k = -2; k <= 2; k++)
                RogueDisparar(b, m->pos, Vector2Rotate(mira, (float)k * 13.0f * DEG2RAD), 235.0f, dano, 6.0f, false);
            m->cronoTiro = 0.42f;
            m->disparos++;
            TocarSomTom(sfxTiro, 0.9f);
            return m->disparos >= 3;
        default: {          // espiral (dois braços)
            float a = (float)m->disparos * 0.33f;
            for (int k = 0; k < 2; k++)
                RogueDisparar(b, m->pos, (Vector2){ cosf(a + PI * k), sinf(a + PI * k) }, 185.0f, dano, 6.0f, false);
            m->cronoTiro = 0.07f;
            m->disparos++;
            if (m->disparos % 4 == 0) TocarSomTom(sfxTiro, 1.1f);
            return m->disparos >= 22;
        }
    }
}

static void MestreComecarRajada(MestreTreino *m)
{
    m->acao = MA_RAJADA;
    m->disparos = 0;
    m->cronoTiro = 0.25f;
    m->padrao = (m->etapa == MT_LUTA) ? GetRandomValue(0, 2) : 0;
}

// Os ataques da Mestre (ESQUIVA, ABERTURA, PARRY e LUTA usam a mesma máquina)
static void MestreAtacar(Biblioteca *b, float dt)
{
    MestreTreino *m = &b->mestre;
    JogadorRogue *j = &b->j;
    Vector2 d = Vector2Subtract(j->pos, m->pos);
    float dist = Vector2Length(d);
    Vector2 dir = (dist > 0.01f) ? Vector2Scale(d, 1.0f / dist) : (Vector2){ 0, 1 };

    m->tempoAcao -= dt;

    switch (m->acao) {

        case MA_PAUSA: {        // flutua de um lado para o outro, perto do alto da sala
            float alvoX = 400.0f + sinf(m->anim * 0.8f) * 160.0f;
            m->pos.x += (alvoX - m->pos.x) * Clamp(dt * 1.5f, 0.0f, 1.0f);
            m->pos.y += (POS_MESTRE_INICIO.y - m->pos.y) * Clamp(dt * 1.5f, 0.0f, 1.0f);
            if (m->tempoAcao > 0.0f) break;

            bool golpe = (m->etapa == MT_PARRY) || (m->etapa == MT_LUTA && m->proximoGolpe);
            if (golpe) { m->acao = MA_APROXIMA; m->tempoAcao = 1.6f; }
            else       MestreComecarRajada(m);
            if (m->etapa == MT_LUTA) m->proximoGolpe = !m->proximoGolpe;
        } break;

        case MA_RAJADA:
            if (MestreRajada(b, dt)) {
                if (m->etapa == MT_ESQUIVA) { m->acao = MA_PAUSA; m->tempoAcao = 1.0f; }
                else { m->acao = MA_ABERTA; m->tempoAcao = MESTRE_ABERTURA; TocarSomTom(sfxPegar, 0.7f); }
            }
            break;

        case MA_ABERTA:         // cansada: parada, escudo dourado
            if (m->tempoAcao <= 0.0f) { m->acao = MA_PAUSA; m->tempoAcao = (m->etapa == MT_LUTA) ? 0.9f : 1.3f; }
            break;

        case MA_APROXIMA:       // chega até a distância do golpe (o ritmo do parry fica sempre igual)
            if (dist > MESTRE_DIST_GOLPE + 8.0f) {
                m->pos = Vector2Add(m->pos, Vector2Scale(dir, 230.0f * dt));
                RogueEmpurrarParaFora(&m->pos, MESTRE_RAIO, NULL, 0);
            } else if (dist < MESTRE_DIST_GOLPE - 30.0f) {
                m->pos = Vector2Subtract(m->pos, Vector2Scale(dir, 160.0f * dt));
                RogueEmpurrarParaFora(&m->pos, MESTRE_RAIO, NULL, 0);
            }
            if (m->tempoAcao <= 0.0f || fabsf(dist - MESTRE_DIST_GOLPE) < 14.0f) {
                m->acao = MA_TELEGRAFA;
                m->tempoAcao = MestreTelegrafia(m);
                m->dirGolpe = dir;
                TocarSom(sfxAvisoParry);
            }
            break;

        case MA_TELEGRAFA:      // brilho vermelho; a mira trava no último terço
            if (m->tempoAcao > MestreTelegrafia(m) * 0.3f) m->dirGolpe = dir;
            if (m->tempoAcao <= 0.0f) {
                m->acao = MA_INVESTE;
                m->tempoAcao = MESTRE_INVESTIDA_TEMPO;
                m->acertouGolpe = false;
                TocarSomTom(sfxTiro, 0.4f);
            }
            break;

        case MA_INVESTE: {
            m->pos = Vector2Add(m->pos, Vector2Scale(m->dirGolpe, MESTRE_INVESTIDA_VEL * dt));
            RogueEmpurrarParaFora(&m->pos, MESTRE_RAIO, NULL, 0);
            if (GetRandomValue(0, 1) == 0) RogueParticulas(b, m->pos, RED, 1, 60);

            if (!m->acertouGolpe && CheckCollisionCircles(m->pos, MESTRE_RAIO, j->pos, RAIO_CORPO_JOGADOR)) {
                m->acertouGolpe = true;
                Vector2 ponto = Vector2Lerp(m->pos, j->pos, 0.6f);
                if (j->parry.emParry) { MestreParry(b, ponto); break; }
                if (j->invulneravel <= 0.0f && j->tempoEsquiva <= 0.0f) {
                    RogueFerirJogador(b, (m->etapa == MT_LUTA) ? MESTRE_DANO_GOLPE : MESTRE_DANO_BALA_TREINO);
                    j->pos = Vector2Add(j->pos, Vector2Scale(m->dirGolpe, 30.0f));
                    RogueEmpurrarParaFora(&j->pos, RAIO_CORPO_JOGADOR, b->obst, b->numObst);
                    m->golpesLevados++;
                    if (m->etapa == MT_PARRY)
                        RogueRecadoLuci(b, (m->golpesLevados >= 3) ? "Aperte V um instante ANTES de ela encostar!"
                                                                    : "Quase! Aperte V quando o anel fechar em você.");
                }
            }
            if (m->tempoAcao <= 0.0f) { m->acao = MA_RECUPERA; m->tempoAcao = MESTRE_RECUPERA; }
        } break;

        case MA_RECUPERA:
        case MA_ATORDOADA:
            if (m->tempoAcao <= 0.0f) { m->acao = MA_PAUSA; m->tempoAcao = (m->etapa == MT_LUTA) ? 0.8f : 1.2f; }
            break;
    }
}

// Distância de um ponto ao trajeto do tiro neste quadro (alvo pequeno não é atravessado com FPS baixo)
static float MestreDistTrajeto(const Projetil *p, Vector2 c, float dt)
{
    Vector2 a = Vector2Subtract(p->pos, Vector2Scale(p->vel, dt)), ab = Vector2Subtract(p->pos, a);
    float len2 = Vector2DotProduct(ab, ab);
    float t = (len2 > 0.0001f) ? Clamp(Vector2DotProduct(Vector2Subtract(c, a), ab) / len2, 0.0f, 1.0f) : 1.0f;
    return Vector2Distance(c, Vector2Add(a, Vector2Scale(ab, t)));
}

// Tiros do Thomas: alvos de treino e a Mestre (escudo fechado = o tiro bate e some)
static void MestreReceberTiros(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    MestreTreino *m = &b->mestre;
    (void)prog;

    for (int i = 0; i < MAX_PROJETEIS; i++) {
        Projetil *p = &b->proj[i];
        if (!p->ativo || !p->doJogador)
            continue;

        if (m->etapa == MT_TIRO) {
            for (int a = 0; a < MESTRE_ALVOS; a++) {
                if (!m->alvoVivo[a] || MestreDistTrajeto(p, m->alvo[a], dt) > 18.0f + p->raio) continue;
                m->alvoVivo[a] = false;
                p->ativo = false;
                RogueParticulas(b, m->alvo[a], GOLD, 22, 220);
                RogueAnel(b, m->alvo[a], 40.0f, GOLD);
                RogueTextoFlutuante(b, (Vector2){ m->alvo[a].x, m->alvo[a].y - 26 }, "FATO!", GOLD);
                TocarSomTom(sfxAcerto, 1.1f + 0.1f * (float)a);
                break;
            }
            continue;
        }

        if (!m->visivel || m->morrendo > 0.0f || MestreDistTrajeto(p, m->pos, dt) > MESTRE_RAIO + p->raio)
            continue;

        p->ativo = false;
        if (MestreVulneravel(m)) {
            float piso = (m->etapa == MT_LUTA) ? 0.0f : MESTRE_HP * MESTRE_TREINO_HP_CHEFE;
            m->hp = fmaxf(piso, m->hp - p->dano);
            m->flash = 0.12f;
            if (m->etapa == MT_ABERTURA || (m->etapa == MT_PARRY && m->acao == MA_ATORDOADA)) m->acertosAbertura++;
            RogueParticulas(b, p->pos, GOLD, 5, 160);
            TocarSomTom(sfxAcerto, 1.4f);
        } else {
            RogueParticulas(b, p->pos, (Color){ 200, 122, 255, 255 }, 4, 120);
            if (m->avisoEscudo <= 0.0f) {
                RogueTextoFlutuante(b, (Vector2){ m->pos.x, m->pos.y - 70 }, "ESCUDO!", (Color){ 200, 122, 255, 255 });
                m->avisoEscudo = 1.2f;
            }
        }
    }
}

static void RogueAtualizarMestre(Biblioteca *b, ProgressoCorredor *prog, float dt)
{
    MestreTreino *m = &b->mestre;
    JogadorRogue *j = &b->j;

    if (!m->ativo)
        return;

    m->tempoEtapa += dt;
    m->anim += dt;
    if (m->flash > 0.0f)       m->flash -= dt;
    if (m->surgindo > 0.0f)    m->surgindo -= dt;
    if (m->avisoEscudo > 0.0f) m->avisoEscudo -= dt;

    // Derrota da Mestre: ela se desfaz e vem a conversa final
    if (m->morrendo > 0.0f) {
        m->morrendo -= dt;
        if (GetRandomValue(0, 2) == 0) RogueParticulas(b, m->pos, (GetRandomValue(0, 1) == 0) ? MAGENTA : GOLD, 3, 260);
        if (m->morrendo <= 0.0f) {
            m->visivel = false;
            m->etapa = MT_FIM;
            b->conversaPendente = &dialogoMestreVitoria;
            b->objConversa = OBJ_MESTRE_VITORIA;
        }
        return;
    }
    if (m->etapa == MT_ARMA || m->etapa == MT_FIM)
        return;

    // Esquivas feitas (o treino conta as que começam)
    bool esquivando = j->tempoEsquiva > 0.0f;
    if (esquivando && !m->estavaEsquivando) m->esquivas++;
    m->estavaEsquivando = esquivando;

    MestreReceberTiros(b, prog, dt);

    if (m->visivel && m->surgindo <= 0.0f)
        MestreAtacar(b, dt);

    // Fase 2 da luta: as três alucinações dos monitores atiram de onde estiverem na órbita
    if (m->etapa == MT_LUTA && m->fase == 2 && m->acao != MA_ATORDOADA) {
        m->cronoOrbita -= dt;
        if (m->cronoOrbita <= 0.0f) {
            for (int i = 0; i < TOTAL_MONITORES; i++) {
                float ang = m->anim * 1.4f + i * (2.0f * PI / TOTAL_MONITORES);
                Vector2 o = { m->pos.x + cosf(ang) * 96, m->pos.y + 6 + sinf(ang) * 22 };
                Vector2 d = Vector2Subtract(j->pos, o);
                if (Vector2Length(d) > 0.1f)
                    RogueDisparar(b, o, Vector2Normalize(d), 200.0f, MESTRE_DANO_BALA * 0.7f, 5.0f, false);
            }
            m->cronoOrbita = 1.7f;
        }
    }

    // No tutorial a Luci segura a vida do Thomas
    if (m->etapa != MT_LUTA && j->hp < RogueHpMax(b) * MESTRE_TREINO_HP_MIN)
        j->hp = RogueHpMax(b) * MESTRE_TREINO_HP_MIN;

    // Progresso do tutorial: uma mecânica de cada vez
    switch (m->etapa) {
        case MT_TIRO: {
            bool restam = false;
            for (int a = 0; a < MESTRE_ALVOS; a++) if (m->alvoVivo[a]) restam = true;
            if (!restam) MestreMudarEtapa(b, MT_ESQUIVA);
        } break;
        case MT_ESQUIVA:
            if (m->esquivas >= MESTRE_ESQUIVAS && m->tempoEtapa > 5.0f && m->acao == MA_PAUSA) MestreMudarEtapa(b, MT_ABERTURA);
            break;
        case MT_ABERTURA:
            if (m->acertosAbertura >= MESTRE_ACERTOS_ABERTURA && m->acao != MA_ABERTA) MestreMudarEtapa(b, MT_PARRY);
            break;
        case MT_PARRY:
            if (m->parries >= 1 && m->acao == MA_PAUSA) MestreMudarEtapa(b, MT_LUTA);
            break;
        case MT_LUTA:
            if (m->fase == 1 && m->hp <= MESTRE_HP * MESTRE_FASE2) {
                m->fase = 2;
                m->cronoOrbita = 1.0f;
                b->falaPendente = "Luci: Ela chamou as alucinações dos monitores! Não pare de se mexer!";
            }
            if (m->hp <= 0.0f) {
                m->hp = 0.0f;
                m->morrendo = 1.8f;
                for (int i = 0; i < MAX_PROJETEIS; i++)
                    if (!b->proj[i].doJogador) b->proj[i].ativo = false;
                RogueAnel(b, m->pos, 180.0f, MAGENTA);
                RogueParticulas(b, m->pos, MAGENTA, 50, 320);
                TocarSom(sfxEstatica);
                Telemetria("mestre_vitoria", "", m->tempoEtapa, m->quedas);
            }
            break;
        default:
            break;
    }
}

// Caiu na luta: a Luci reergue o Thomas (sem perder pontos nem o que a Mestre já perdeu)
static void RogueMestreReerguer(Biblioteca *b)
{
    MestreTreino *m = &b->mestre;

    m->quedas++;
    b->j.hp = RogueHpMax(b);
    b->j.invulneravel = 2.0f;
    m->acao = MA_PAUSA;
    m->tempoAcao = 2.0f;
    for (int i = 0; i < MAX_PROJETEIS; i++)
        if (!b->proj[i].doJogador) b->proj[i].ativo = false;
    RogueParticulas(b, b->j.pos, (Color){ 0, 228, 255, 255 }, 30, 220);
    b->falaPendente = "Luci: Levanta, Thomas! Eu seguro ela um instante. Respira e tenta de novo.";
    Telemetria("mestre_queda", "", 0.0f, m->quedas);
}

// Venceu: a sala fecha e o Thomas chega ao átrio da Biblioteca (o Bloco 2) com a arma
static void RogueSairSalaMestre(Biblioteca *b)
{
    memset(&b->mestre, 0, sizeof(b->mestre));
    RogueEntrarAtrio(b, true);
    RogueAviso(b, "BLOCO 2: A BIBLIOTECA DOS ECOS");
    b->falaPendente = "Luci: Chegamos à Biblioteca dos Ecos! O disparador continua com você.";
}

// ---------- Portas com interação (tecla E) ----------
// As portas não levam mais o jogador só de encostar: perto de uma porta aberta aparece
// "APERTE E PARA ENTRAR/SAIR" e só o E atravessa. A mesma função serve à lógica e ao desenho.
typedef enum { PORTA_NENHUMA, PORTA_ATRIO_MISSAO, PORTA_ATRIO_CORREDOR, PORTA_ATRIO_NUCLEO,
               PORTA_TRANSICAO_LUCI, PORTA_DA_MISSAO, PORTA_SECRETA } PortaInteracao;

#define DISTANCIA_PORTA_E   14.0f   // folga além do corpo do Thomas (AJUSTE AQUI)

static bool RoguePertoDaPorta(const Biblioteca *b, Rectangle r)
{
    return CheckCollisionCircleRec(b->j.pos, RAIO_CORPO_JOGADOR + DISTANCIA_PORTA_E, r);
}

// Porta aberta ao alcance do E (*indice: qual porta da missão)
static PortaInteracao RoguePortaProxima(const Biblioteca *b, int *indice)
{
    *indice = -1;

    if (b->morreu)
        return PORTA_NENHUMA;

    if (b->tipoSala == SALA_ATRIO) {
        if (RoguePertoDaPorta(b, PORTA_SAIDA_ROGUE))                             return PORTA_ATRIO_CORREDOR;
        if (b->perm->bloco3Liberado && RoguePertoDaPorta(b, PORTA_BLOCO3_ROGUE)) return PORTA_ATRIO_NUCLEO;
        if (RoguePertoDaPorta(b, PORTA_PROXIMA_ROGUE))                           return PORTA_ATRIO_MISSAO;
    }
    else if (b->tipoSala == SALA_TRANSICAO) {
        if (b->limpa && RoguePertoDaPorta(b, PORTA_PROXIMA_ROGUE)) return PORTA_TRANSICAO_LUCI;
    }
    else if (b->noAtual >= 0 && b->limpa) {
        for (int k = 0; k < b->numPortas; k++)
            if (RoguePertoDaPorta(b, b->portas[k].r)) { *indice = k; return PORTA_DA_MISSAO; }
        if (b->temParedeSecreta && b->passagemAberta && RoguePertoDaPorta(b, PAREDE_SECRETA_ROGUE[b->paredeSecreta]))
            return PORTA_SECRETA;
    }

    return PORTA_NENHUMA;
}

static AlvoRogue RogueAlvoProximo(const Biblioteca *b, int *pedestal)
{
    Vector2 p = b->j.pos;

    // Reformulação: recompensa no chão, altar/poltrona/console e arquivo para ler
    if (b->recompensaAtiva && Vector2Distance(p, b->recompensaPos) < 44.0f)
        return ALVO_RECOMPENSA;
    if (b->tipoSala == SALA_LABORATORIO && !b->lab.concluido && Vector2Distance(p, b->posObjetoSala) < 58.0f)
        return ALVO_LAB;
    if ((b->tipoSala == SALA_EVENTO || b->tipoSala == SALA_DESCANSO || b->tipoSala == SALA_DESAFIO) &&
        !b->eventoUsado && !b->eventoCombate && Vector2Distance(p, b->posObjetoSala) < 58.0f)
        return ALVO_OBJETO_SALA;
    if (b->registroSala && !b->registroSalaLido && Vector2Distance(p, b->posRegistroSala) < 50.0f)
        return ALVO_REGISTRO_SALA;

    if (b->tipoSala == SALA_ATRIO) {
        if (Vector2Distance(p, POS_TERMINAL_SELETOR) < RAIO_TERMINAL_ATALHO)    return ALVO_TERMINAL_SELETOR;
        if (Vector2Distance(p, POS_TERMINAL_BLOCO3) < RAIO_TERMINAL_ATALHO)     return ALVO_TERMINAL_BLOCO3;
        if (Vector2Distance(p, POS_BYTE) < 70)                                  return ALVO_BYTE;
        if (Vector2Distance(p, (Vector2){ POS_BYTECO.x, POS_BYTECO.y + 50 }) < 60) return ALVO_BYTECO;
        if (Vector2Distance(p, POS_ENCICLOPEDIA) < 60)                          return ALVO_ENCICLOPEDIA;
    }
    else if (b->tipoSala == SALA_EDUCATIVA && !b->terminalLido) {
        if (Vector2Distance(p, POS_TERMINAL) < 70) return ALVO_TERMINAL;
    }
    else if (b->tipoSala == SALA_RECOMPENSA && !b->recompensaPega) {
        for (int i = 0; i < NUM_PEDESTAIS; i++)
            if (Vector2Distance(p, POS_PEDESTAIS[i]) < 42) { *pedestal = i; return ALVO_PEDESTAL; }
    }
    else if (b->tipoSala == SALA_TRANSICAO) {
        for (int i = 0; i < 3; i++)
            if (!(b->registrosLidos & (1 << i)) && Vector2Distance(p, POS_REGISTROS[i]) < 60.0f) { *pedestal = i; return ALVO_REGISTRO; }
    }
    else if (b->tipoSala == SALA_LUCI) {
        if (RogueAlvoContexto(b, pedestal)) return ALVO_CONTEXTO;     // *pedestal: pedaço (k) ou o núcleo (-1)
    }
    else if (b->tipoSala == SALA_MESTRE) {
        if (b->mestre.etapa == MT_ARMA && Vector2Distance(p, POS_ARMA_MESTRE) < 56.0f) return ALVO_ARMA_MESTRE;
    }
    else if (b->tipoSala == SALA_SILOGISTA) {
        // Montagem do silogismo (o índice do fragmento ou do mecanismo vai em *pedestal).
        // Carregando, o mecanismo vem primeiro; de mãos vazias, o fragmento no chão.
        const Silogista *s = &b->silogista;

        if (!s->ativo || !s->apresentado || s->etapa != SIL_MONTAGEM || s->modoBH)
            return ALVO_NADA;

        for (int vez = 0; vez < 2; vez++) {
            bool encaixes = (vez == 0) == (s->carregando >= 0);
            for (int i = 0; i < NUM_ENCAIXES; i++) {
                if (encaixes && (s->carregando >= 0 || s->encaixe[i] >= 0) && Vector2Distance(p, POS_ENCAIXES[i]) < SIL_RAIO_ENCAIXE)
                    { *pedestal = i; return ALVO_ENCAIXE; }
                if (!encaixes && SilPecaNoChao(s, i) && Vector2Distance(p, s->posPeca[i]) < SIL_RAIO_PEGAR)
                    { *pedestal = i; return ALVO_PECA; }
            }
        }
    }

    return ALVO_NADA;
}

// Compra um item do Byteco. Devolve true se comprou.
static bool RogueComprar(Biblioteca *b, TipoItem item)
{
    const DefItem *it = &ITENS[item];
    int *tenho = &b->j.itens[item];

    if (it->passivo && *tenho >= it->maxPilha) {
        RogueAviso(b, "Você já tem o máximo desse item.");
        TocarSom(sfxErro);
        return false;
    }

    if (b->perm->fragmentos < it->preco) {
        RogueAviso(b, "Fragmentos de Conhecimento insuficientes.");
        TocarSom(sfxErro);
        return false;
    }

    b->perm->fragmentos -= it->preco;
    (*tenho)++;
    RogueAviso(b, TextFormat("Comprou: %s", it->nome));
    TocarSomTom(sfxAcerto, 1.2f);
    Telemetria("rogue_loja", it->nome, (float)it->preco, b->perm->fragmentos);
    return true;
}

// Melhoria permanente: fica para sempre (vai para o save)
static bool RogueComprarMelhoria(Biblioteca *b, int m)
{
    int nivel = b->perm->melhorias[m];

    if (nivel >= NIVEL_MAX_MELHORIA) {
        RogueAviso(b, "Essa melhoria já está no nível máximo.");
        TocarSom(sfxErro);
        return false;
    }

    if (b->perm->fragmentos < PRECO_MELHORIA[nivel]) {
        RogueAviso(b, "Fragmentos de Conhecimento insuficientes.");
        TocarSom(sfxErro);
        return false;
    }

    b->perm->fragmentos -= PRECO_MELHORIA[nivel];
    b->perm->melhorias[m]++;

    // A vida e a energia novas já valem agora
    if (m == MELHORIA_VIDA)    b->j.hp += MELHORIA_HP;
    if (m == MELHORIA_ENERGIA) b->j.ep += MELHORIA_EP;

    RogueAviso(b, TextFormat("%s: nível %d!", NOMES_MELHORIAS[m], b->perm->melhorias[m]));
    TocarSomTom(sfxAcerto, 1.3f);
    Telemetria("rogue_melhoria", NOMES_MELHORIAS[m], (float)PRECO_MELHORIA[nivel], b->perm->melhorias[m]);
    return true;
}

// Arma do Byteco: vira a arma extra desta tentativa (substitui a anterior)
static bool RogueComprarArma(Biblioteca *b, TipoArma arma)
{
    const DefArma *a = &DEF_ARMAS[arma];

    if (arma == ARMA_DISPARADOR || b->j.armaExtra == arma) {
        RogueAviso(b, "Você já tem essa arma.");
        TocarSom(sfxErro);
        return false;
    }

    if (b->perm->fragmentos < a->preco) {
        RogueAviso(b, "Fragmentos de Conhecimento insuficientes.");
        TocarSom(sfxErro);
        return false;
    }

    b->perm->fragmentos -= a->preco;
    b->j.armaExtra = arma;
    b->j.usandoExtra = true;
    RogueAviso(b, TextFormat("Comprou: %s (TAB troca)", a->nome));
    TocarSomTom(sfxAcerto, 1.2f);
    Telemetria("rogue_loja", a->nome, (float)a->preco, b->perm->fragmentos);
    return true;
}

// Enciclopédia do átrio: W/S escolhe, E lê o texto completo, BACKSPACE/ESC sai
#define RET_FECHAR_ENCICLOPEDIA ((Rectangle){ 656, 58, 26, 22 })

// Linha do conceito c na enciclopédia (a mesma conta de DesenharEnciclopediaRogue)
static Rectangle RogueRetConceito(int c)
{
    return (Rectangle){ 122, 120.0f + c * 96.0f, 556, 88 };
}

static void RogueAtualizarEnciclopedia(Biblioteca *b, SessaoDialogo *dlg)
{
    if (IsKeyPressed(KEY_W) || IsKeyPressed(KEY_UP))   { b->selecaoEnciclopedia = (b->selecaoEnciclopedia + NUM_CONCEITOS - 1) % NUM_CONCEITOS; TocarSom(sfxSelecao); }
    if (IsKeyPressed(KEY_S) || IsKeyPressed(KEY_DOWN)) { b->selecaoEnciclopedia = (b->selecaoEnciclopedia + 1) % NUM_CONCEITOS;                  TocarSom(sfxSelecao); }

    bool clique = CliqueMouse();

    if (IsKeyPressed(KEY_BACKSPACE) || IsKeyPressed(KEY_ESCAPE) || (clique && MouseEm(RET_FECHAR_ENCICLOPEDIA))) {
        b->enciclopediaAberta = false;
        return;
    }

    bool confirmar = IsKeyPressed(KEY_E) || IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_SPACE);

    // Mouse: passar por cima marca o conceito, clicar lê
    for (int k = 0; k < NUM_CONCEITOS; k++) {
        if (!MouseEm(RogueRetConceito(k))) continue;
        if (MouseMexeu() && b->selecaoEnciclopedia != k) { b->selecaoEnciclopedia = k; TocarSom(sfxSelecao); }
        if (clique) { b->selecaoEnciclopedia = k; confirmar = true; }
    }

    int c = b->selecaoEnciclopedia;

    if (!confirmar)
        return;

    if (b->perm->conceitos & (1u << c)) {
        b->enciclopediaAberta = false;      // volta quando a leitura terminar
        DialogoIniciar(dlg, TEXTOS_CONCEITOS[c], OBJ_ENCICLOPEDIA);
    } else {
        RogueAviso(b, "Conceito ainda não descoberto.");
        TocarSom(sfxErro);
    }
}

// Loja do Byteco: A/D troca a aba, W/S escolhe, E (ou ENTER) compra, BACKSPACE/ESC sai
// Abas e linhas da loja (a mesma conta de DesenharLojaRogue), para o mouse
static Rectangle RogueRetAbaLoja(int a)
{
    return (Rectangle){ 174.0f + a * 152.0f, 122, 146, 24 };
}

static Rectangle RogueRetLinhaLoja(int i)
{
    return (Rectangle){ 162, 156.0f + i * 46.0f, 476, 40 };
}

static void RogueAtualizarLoja(Biblioteca *b)
{
    bool clique = CliqueMouse();
    int abaClicada = -1;

    for (int a = 0; a < 3; a++)
        if (clique && MouseEm(RogueRetAbaLoja(a)))
            abaClicada = a;

    bool esquerda = IsKeyPressed(KEY_A) || IsKeyPressed(KEY_LEFT), direita = IsKeyPressed(KEY_D) || IsKeyPressed(KEY_RIGHT);
    if (abaClicada >= 0) {
        if (abaClicada != b->abaLoja) {
            b->abaLoja = abaClicada;
            b->selecaoLoja = 0;
            TocarSom(sfxSelecao);
        }
    } else if (esquerda || direita) {
        b->abaLoja = (b->abaLoja + (direita ? 1 : 2)) % 3;
        b->selecaoLoja = 0;
        TocarSom(sfxSelecao);
    }

    int linhas = (b->abaLoja == 0) ? NUM_ITENS_LOJA : ((b->abaLoja == 1) ? NUM_MELHORIAS : ARMAS_NA_LOJA);
    int total = linhas + 1;                         // a última linha é SAIR

    if (IsKeyPressed(KEY_W) || IsKeyPressed(KEY_UP))   { b->selecaoLoja = (b->selecaoLoja + total - 1) % total; TocarSom(sfxSelecao); }
    if (IsKeyPressed(KEY_S) || IsKeyPressed(KEY_DOWN)) { b->selecaoLoja = (b->selecaoLoja + 1) % total;         TocarSom(sfxSelecao); }

    bool sair = IsKeyPressed(KEY_BACKSPACE) || IsKeyPressed(KEY_ESCAPE);
    bool confirmar = IsKeyPressed(KEY_E) || IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_SPACE);

    // Mouse: passar por cima marca a linha, clicar compra (ou sai, na linha SAIR)
    for (int i = 0; i < total; i++) {
        if (!MouseEm(RogueRetLinhaLoja(i))) continue;
        if (MouseMexeu() && b->selecaoLoja != i) { b->selecaoLoja = i; TocarSom(sfxSelecao); }
        if (clique && abaClicada < 0) { b->selecaoLoja = i; confirmar = true; }
    }

    if (sair || (confirmar && b->selecaoLoja == linhas)) {
        b->lojaAberta = false;
        return;
    }

    if (confirmar && b->abaLoja == 0)      RogueComprar(b, (TipoItem)b->selecaoLoja);
    else if (confirmar && b->abaLoja == 1) RogueComprarMelhoria(b, b->selecaoLoja);
    else if (confirmar)                    RogueComprarArma(b, b->estoqueArmas[b->selecaoLoja]);
}

// E perto de alguém ou de algo: fala, lê ou pega
static void RogueInteragir(Biblioteca *b, SessaoDialogo *dlg, AlvoRogue alvo, int pedestal)
{
    switch (alvo) {

        case ALVO_ARMA_MESTRE:
            b->mestre.etapa = MT_TIRO;              // o pedestal some já (a etapa começa no fim da conversa)
            RogueParticulas(b, POS_ARMA_MESTRE, GOLD, 30, 220);
            RogueAnel(b, POS_ARMA_MESTRE, 70.0f, GOLD);
            TocarSomTom(sfxAcerto, 1.2f);
            DialogoIniciar(dlg, &dialogoMestreArma, OBJ_MESTRE_ARMA);
            break;

        case ALVO_BYTE:
            DialogoIniciar(dlg, b->perm->byteVisto ? &dialogoByteDepois : &dialogoByte, OBJ_BYTE);
            break;

        case ALVO_BYTECO:
            if (b->perm->bytecoVisto) { b->lojaAberta = true; b->selecaoLoja = 0; }
            else                      DialogoIniciar(dlg, &dialogoByteco, OBJ_BYTECO);
            break;

        case ALVO_TERMINAL: {
            // Os dois primeiros ensinam os conceitos; a partir do 3º, terminais que reforçam o que já foi visto
            const Dialogo *d = (b->educativas == 0) ? &dialogoTerminalAlucinacao
                             : (b->educativas == 1) ? &dialogoTerminalPraticas
                             : ((b->educativas % 2 == 0) ? &dialogoTerminalVies : &dialogoTerminalFontes);
            DialogoIniciar(dlg, d, OBJ_TERMINAL);
            b->educativas++;
        } break;

        case ALVO_PEDESTAL: {
            TipoArma arma = b->armaPedestal[pedestal];
            if (arma != ARMA_DISPARADOR) {
                b->j.armaExtra = arma;                  // substitui a arma extra que houver
                b->j.usandoExtra = true;
                b->j.carga = 0.0f;
                b->recompensaPega = true;
                RogueAviso(b, TextFormat("Pegou: %s (TAB troca)", DEF_ARMAS[arma].nome));
                RogueParticulas(b, POS_PEDESTAIS[pedestal], DEF_ARMAS[arma].cor, 20, 180);
                TocarSomTom(sfxAcerto, 1.2f);
                Telemetria("rogue_recompensa", DEF_ARMAS[arma].nome, 0.0f, 1);
                break;
            }
            TipoItem it = b->pedestal[pedestal];
            b->j.itens[it]++;
            b->recompensaPega = true;
            RogueAviso(b, TextFormat("Pegou: %s", ITENS[it].nome));
            RogueParticulas(b, POS_PEDESTAIS[pedestal], GOLD, 20, 180);
            TocarSomTom(sfxAcerto, 1.2f);
            Telemetria("rogue_recompensa", ITENS[it].nome, 0.0f, 0);
        } break;

        case ALVO_ENCICLOPEDIA:
            b->enciclopediaAberta = true;
            b->selecaoEnciclopedia = 0;
            break;

        case ALVO_PECA:
            SilPegarPeca(b, pedestal);
            break;

        case ALVO_ENCAIXE:
            SilUsarEncaixe(b, pedestal);
            break;

        case ALVO_REGISTRO:
            b->registroAtual = pedestal;
            DialogoIniciar(dlg, RogueDialogoRegistro(b, pedestal), OBJ_REGISTRO);
            break;

        case ALVO_CONTEXTO:
            RogueLuciContexto(b, pedestal);
            break;

        case ALVO_RECOMPENSA:
            RogueUsarRecompensa(b);
            break;

        case ALVO_TERMINAL_SELETOR:
            if (!b->perm->byteVisto) {
                DialogoFalaAvulsa(dlg, "SELETOR DE CHEFES: BLOQUEADO. Converse primeiro com o Professor Byte (perto da porta de cima) para liberar este terminal.");
                Telemetria("seletor_bloqueado", "", 0.0f, 0);
            } else {
                RogueAbrirSeletor(b);
            }
            break;

        case ALVO_TERMINAL_BLOCO3:
            DialogoConfirmar(dlg, TEXTO_ATALHO_BLOCO3, OBJ_ATALHO_BLOCO3);
            Telemetria("atalho_bloco3_terminal", "", 0.0f, b->perm->bloco3Liberado ? 1 : 0);
            break;

        case ALVO_LAB:
            b->lab.aberto = true;
            b->lab.tempo = 0.0f;
            TocarSom(sfxSelecao);
            break;

        case ALVO_OBJETO_SALA:
            b->eventoAberto = true;
            b->eventoResolvido = false;
            b->selecaoEvento = 0;
            TocarSom(sfxSelecao);
            break;

        case ALVO_REGISTRO_SALA:
            if (b->registroSalaId >= 100) {
                int m = b->registroSalaId - 100;
                b->memoriasVistas |= 1u << m;
                DialogoIniciar(dlg, &dialogosMemoria[m], OBJ_REGISTRO_SALA);
            } else {
                DialogoIniciar(dlg, &dialogosAmeaca[b->registroSalaId], OBJ_REGISTRO_SALA);
            }
            break;

        default:
            break;
    }
}

// Terminou uma conversa da Biblioteca: o que ela muda
static void RogueFimConversa(Biblioteca *b, ProgressoCorredor *prog, int obj)
{
    if (obj == OBJ_MESTRE_ARMA) {
        MestreMudarEtapa(b, MT_TIRO);
        RogueAviso(b, "DISPARADOR DE DADOS!");
        return;
    }
    if (obj == OBJ_MESTRE_VITORIA) {
        AlterarPontos(prog, MESTRE_PONTOS);
        b->mestreVencidoPendente = true;
        return;
    }

    if (obj == OBJ_BYTE) {
        b->perm->byteVisto = true;
        if (!(b->perm->conceitos & (1u << CONCEITO_FUNDAMENTOS)))
            RogueAviso(b, "NOVO CONCEITO NA ENCICLOPÉDIA!");
        b->perm->conceitos |= 1u << CONCEITO_FUNDAMENTOS;
    }
    else if (obj == OBJ_ENCICLOPEDIA) {
        b->enciclopediaAberta = true;
    }
    else if (obj == OBJ_BYTECO) {
        b->perm->bytecoVisto = true;
        b->lojaAberta = true;
        b->selecaoLoja = 0;
    }
    else if (obj == OBJ_TERMINAL) {
        b->terminalLido = true;
        b->limpa = true;
        RogueMudarEstabilidade(b, 1, "base de conhecimento confiável");
        b->perm->conceitos |= 1u << ((b->educativas <= 1) ? CONCEITO_ALUCINACOES : CONCEITO_PRATICAS);
        b->perm->fragmentos += FC_POR_TERMINAL;
        AlterarPontos(prog, PONTOS_TERMINAL);
        RogueAviso(b, TextFormat("+%d FRAGMENTOS DE CONHECIMENTO", FC_POR_TERMINAL));
        RogueParticulas(b, POS_TERMINAL, (Color){ 0, 228, 255, 255 }, 24, 200);
        TocarSom(sfxAcerto);
        MostrarEmocaoLuci(EMOCAO_ALEGRE, 2.0f);
        Telemetria("rogue_terminal", TextFormat("conceito %d", b->educativas), 0.0f, b->perm->fragmentos);
    }
    else if (obj == OBJ_REGISTRO_SALA) {
        // Narrativa opcional: arquivo de ameaça (+1 fragmento) ou memória da Luci (estabiliza)
        b->registroSalaLido = true;
        if (b->registroSalaId >= 100) {
            RogueMudarEstabilidade(b, 1, "memória recuperada");
        } else {
            b->perm->fragmentos += 1;
            RogueAviso(b, "+1 FRAGMENTO DE CONHECIMENTO");
        }
        Telemetria("rogue_registro_sala", TextFormat("%d", b->registroSalaId), 0.0f, b->profundidade);
    }
    else if (obj == OBJ_CHEFE_INTRO) {
        b->chefe.apresentado = true;
    }
    else if (obj == OBJ_SILOGISTA_INTRO) {
        b->silogista.apresentado = true;
    }
    else if (obj == OBJ_SILOGISTA_ETAPA) {
        // Rodada 1 do circuito resolvida: a rodada 2 começa depois da explicação
        Silogista *s = &b->silogista;
        if (s->etapa == SIL_CIRCUITO && s->nucleo > 0.0f) {
            SilPrepararRodada(s, 2);
            s->nucleo = 0.0f;
        }
    }
    else if (obj == OBJ_REGISTRO) {
        b->registrosLidos |= 1 << b->registroAtual;
        if (b->registrosLidos == 7 && !b->limpa) {
            b->limpa = true;
            b->conversaPendente = &dialogoNucleoAberto;
            b->objConversa = OBJ_NENHUM;
        }
    }
    else if (obj == OBJ_LUCI_INTRO) {
        b->luci.apresentado = true;
    }
    else if (obj == OBJ_LUCI_FINAL) {
        // Fim de UtopIA: o final, os pontos e a tela de resultado (depois, o ranking)
        if (!b->perm->jogoConcluido || b->perm->finalJogo == 0) {
            b->perm->jogoConcluido = true;
            b->perm->finalJogo = b->finalBom ? 1 : 2;
            b->perm->indiceFinal = b->indice.total;
            AlterarPontos(prog, b->finalBom ? PONTOS_FINAL_BOM : PONTOS_FINAL_RUIM);
            Telemetria("fim_do_jogo", b->finalBom ? "bom" : "ruim", (float)b->indice.total, prog->pontos);
        }
        b->pontosFinais = prog->pontos;
        b->resultadoAberto = true;
        b->tempoResultado = 0.0f;
    }
    else if (obj == OBJ_SILOGISTA_VITORIA) {
        // Recompensa (uma vez por vitória): Selo da Inferência, conceito novo e a porta aberta
        Silogista *s = &b->silogista;
        if (!s->recompensaDada) {
            s->recompensaDada = true;
            b->j.seloInferencia = true;
            if (s->modoBH) {
                // Desafio opcional vencido: Selo amplificado e um alívio de estabilidade
                s->bh.desafioConcluido = s->bh.recompensaObtida = true;
                b->j.seloAmplificado = true;
                b->bonusSilogistaSessao = true;
                b->j.ep = RogueEpMax(b);
                RogueMudarEstabilidade(b, 1, "raciocínio verificado");
            }
            if (!(b->perm->conceitos & (1u << CONCEITO_LOGICA)))
                RogueAviso(b, "NOVO CONCEITO NA ENCICLOPÉDIA!");
            else
                RogueAviso(b, "SELO DA INFERÊNCIA!");
            b->perm->conceitos |= 1u << CONCEITO_LOGICA;
            b->perm->silogistaVencido = true;
            if (!b->modoSeletor || b->recompensaSeletor) {          // seletor: só na 1ª vitória
                b->perm->fragmentos += FC_SILOGISTA;
                AlterarPontos(prog, PONTOS_SILOGISTA);
            }
            RogueSalaConcluida(b);
            MostrarEmocaoLuci(EMOCAO_ALEGRE, 3.0f);
            Telemetria("rogue_silogista_vitoria", "", (float)(GetTime() - b->inicio), b->perm->tentativas);
        }
        b->limpa = true;
        if (b->modoSeletor)
            RogueSeletorVenceu(b, prog, 0);      // o átrio volta depois desta explicação
    }
    else if (obj == OBJ_ALUCINADOR_VITORIA && b->modoSeletor) {
        // Seletor de chefes: a vitória libera o Bloco 3 como sempre, mas volta ao átrio
        // (sem ranking de fim da Biblioteca) e a recompensa só sai na 1ª vitória
        bool recompensa = b->recompensaSeletor;
        b->perm->alucinadorVencido = true;
        b->perm->bloco3Liberado = true;
        if (recompensa) {
            b->perm->fragmentos += FC_ALUCINADOR;
            AlterarPontos(prog, PONTOS_ALUCINADOR);
        }
        Telemetria("rogue_chefe_vitoria", "seletor", (float)(GetTime() - b->inicio), b->perm->tentativas);
        RogueSeletorVenceu(b, prog, 0);
        RogueVoltarAoLobby(b);
        b->portaNucleoAbrindo = 3.0f;
        b->estaticaTela = 0.5f;
        b->falaPendente = "Luci: Aquela porta à direita... leva ao núcleo de UtopIA. Quando quiser, eu vou com você.";
    }
    else if (obj == OBJ_ALUCINADOR_VITORIA) {
        // Fim da Biblioteca: os fragmentos voltam, a mochila esvazia e o main mostra o ranking
        b->perm->alucinadorVencido = true;
        b->perm->bloco3Liberado = true;
        b->perm->fragmentos += FC_ALUCINADOR;
        AlterarPontos(prog, PONTOS_ALUCINADOR);
        Telemetria("rogue_chefe_vitoria", "", (float)(GetTime() - b->inicio), b->perm->tentativas);
        RogueEsvaziarMochila(&b->j);
        RogueEntrarAtrio(b, false);
        b->vitoriaPendente = true;

        // Continuidade linear para o Bloco 3: a porta da direita (x = 746) se abre com um glitch
        b->portaNucleoAbrindo = 3.0f;
        b->estaticaTela = 0.5f;
        b->falaPendente = "Luci: Aquela porta à direita... leva ao núcleo de UtopIA. Eu preciso que você venha. Agora.";
    }
}

// Confirmação de um terminal da Biblioteca (SIM / NÃO)
static void RogueRespostaConfirmacao(Biblioteca *b, int obj, bool sim)
{
    if (obj != OBJ_ATALHO_BLOCO3)
        return;

    Telemetria("atalho_bloco2_bloco3", sim ? "sim" : "nao", (float)(GetTime() - b->inicio), b->perm->bloco3Liberado ? 1 : 0);
    if (!sim)
        return;

    // A mesma entrada da porta do núcleo: a cutscene e depois RogueEntrarBloco3 (sem exigir bloco3Liberado
    // e sem marcar o Alucinador como vencido)
    b->transicaoNucleo = TRANSICAO_NUCLEO;
    b->entrouNucleo = false;
    PararSons();
    TocarSom(sfxEstatica);
}

typedef enum { ROGUE_NADA, ROGUE_SAIR, ROGUE_VITORIA, ROGUE_FIM_JOGO, ROGUE_MESTRE_VENCIDO } EventoRogue;

static EventoRogue RogueAtualizar(Biblioteca *b, ProgressoCorredor *prog, SessaoDialogo *dlg, float dt)
{
    for (int i = 0; i < MAX_PARTICULAS_ROGUE; i++) {
        ParticulaRogue *p = &b->part[i];
        if (p->vida <= 0.0f) continue;
        p->vida -= dt;
        p->pos = Vector2Add(p->pos, Vector2Scale(p->vel, dt));
        p->vel = Vector2Scale(p->vel, 1.0f - 3.0f * dt);
    }

    if (b->tremor > 0.0f)      b->tremor -= dt;
    if (b->fadeEntrada > 0.0f) b->fadeEntrada -= dt;
    if (b->tempoAviso > 0.0f)  b->tempoAviso -= dt;

    // Bloco 3 (reformulação): efeitos de tela e de impacto
    if (b->tremorForte > 0.0f)        b->tremorForte -= dt;
    if (b->zoomImpacto > 0.0f)        b->zoomImpacto -= dt;
    if (b->flashNegativo > 0.0f)      b->flashNegativo -= dt;
    if (b->estaticaTela > 0.0f)       b->estaticaTela -= dt;
    if (b->tempoErro > 0.0f)          b->tempoErro -= dt;
    if (b->portaNucleoAbrindo > 0.0f) b->portaNucleoAbrindo -= dt;
    for (int i = 0; i < MAX_TEXTOS_FLUTUANTES; i++)
        if (b->textos[i].tempo > 0.0f) { b->textos[i].tempo -= dt; b->textos[i].pos.y -= 28.0f * dt; }

    // Cutscene da porta do núcleo: glitch, estática e a inversão de paleta (o jogo espera)
    if (b->transicaoNucleo > 0.0f) {
        b->transicaoNucleo -= dt;
        if (!b->entrouNucleo && b->transicaoNucleo <= TRANSICAO_NUCLEO * 0.45f) {
            b->entrouNucleo = true;
            RogueEntrarBloco3(b, prog);
            b->flashNegativo = 0.6f;
            b->estaticaTela = 0.8f;
        }
        return ROGUE_NADA;
    }

    if (b->vitoriaPendente) {
        b->vitoriaPendente = false;
        return ROGUE_VITORIA;
    }

    // Venceu a ALUCINAÇÃO MESTRE: fim do Bloco 1 (o main abre o ranking) e o átrio do Bloco 2
    if (b->mestreVencidoPendente) {
        b->mestreVencidoPendente = false;
        RogueSairSalaMestre(b);
        return ROGUE_MESTRE_VENCIDO;
    }

    // Tela de resultado do fim do jogo: ENTER leva ao ranking e ao menu
    if (b->resultadoAberto) {
        b->tempoResultado += dt;
        if (b->tempoResultado > 1.0f && (IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_E) || IsKeyPressed(KEY_SPACE) || CliqueMouse())) {
            b->resultadoAberto = false;
            RogueEsvaziarMochila(&b->j);
            RogueEntrarAtrio(b, false);
            return ROGUE_FIM_JOGO;
        }
        return ROGUE_NADA;
    }

    // Conversa aberta (Byte, Byteco, terminal, chefe): o resto espera
    if (dlg->estado != DLG_NENHUM) {

        int obj = dlg->objeto;

        ResultadoDialogo r = DialogoAtualizar(dlg);
        if (r == RES_FIM)
            RogueFimConversa(b, prog, obj);
        else if (r == RES_SIM || r == RES_NAO)
            RogueRespostaConfirmacao(b, obj, r == RES_SIM);

        return ROGUE_NADA;
    }

    if (b->lojaAberta) {
        RogueAtualizarLoja(b);
        return ROGUE_NADA;
    }

    if (b->enciclopediaAberta) {
        RogueAtualizarEnciclopedia(b, dlg);
        return ROGUE_NADA;
    }

    // Desafio educativo aberto: o combate espera
    if (b->desafioAberto) {
        RogueAtualizarDesafio(b, prog, dt);
        return ROGUE_NADA;
    }

    // Reformulação: escolha 1 de 3, eventos e o mapa grande (o combate espera)
    if (b->escolhaAberta) {
        RogueAtualizarEscolha(b);
        return ROGUE_NADA;
    }

    if (b->eventoAberto) {
        RogueAtualizarEvento(b, prog, dlg);
        return ROGUE_NADA;
    }

    // Expansão educativa: a janela do laboratório (o combate espera)
    if (b->lab.aberto) {
        RogueAtualizarLab(b, prog, dt);
        return ROGUE_NADA;
    }

    // Seletor de chefes aberto: o átrio espera
    if (b->seletorAberto) {
        RogueAtualizarSeletor(b);
        return ROGUE_NADA;
    }

    if (b->escolhaPendente >= 0) {
        RogueAbrirEscolha(b, (ModoEscolha)b->escolhaPendente, true);
        b->escolhaPendente = -1;
        return ROGUE_NADA;
    }

    if (b->mapaAberto) {
        if (IsKeyPressed(KEY_M) || IsKeyPressed(KEY_ESCAPE) || IsKeyPressed(KEY_BACKSPACE) || IsKeyPressed(KEY_ENTER) || CliqueMouse())
            b->mapaAberto = false;
        return ROGUE_NADA;
    }

    if (IsKeyPressed(KEY_M) && b->noAtual >= 0 && !b->morreu) {
        b->mapaAberto = true;
        TocarSom(sfxSelecao);
        return ROGUE_NADA;
    }

    // Conversa do chefe guardada para quando a sala terminar de aparecer
    if (b->conversaPendente != NULL && b->fadeEntrada <= 0.0f) {
        DialogoIniciar(dlg, b->conversaPendente, b->objConversa);
        b->conversaPendente = NULL;
        return ROGUE_NADA;
    }

    // Fala da Luci guardada para quando a sala terminar de aparecer
    if (b->falaPendente != NULL && b->fadeEntrada <= 0.0f) {
        DialogoFalaAvulsa(dlg, b->falaPendente);
        b->falaPendente = NULL;
        return ROGUE_NADA;
    }

    // Seletor de chefes: venceu e os diálogos de vitória já passaram -> de volta ao átrio
    if (b->modoSeletor && b->seletorVencido && b->tipoSala != SALA_ATRIO) {
        b->seletorRetorno += dt;
        b->j.invulneravel = fmaxf(b->j.invulneravel, 0.2f);       // nada mais machuca depois da vitória
        if (b->seletorRetorno >= SELETOR_TEMPO_RETORNO) {
            RogueVoltarAoLobby(b);
            return ROGUE_NADA;
        }
    }

    if (b->pausaImpacto > 0.0f) {
        b->pausaImpacto -= dt;
        return ROGUE_NADA;
    }

    // Derrota: volta para o átrio sem os itens da tentativa
    if (b->morreu) {
        b->tempoMorte += dt;
        bool confirmar = IsKeyPressed(KEY_ENTER) || IsKeyPressed(KEY_E) || IsKeyPressed(KEY_SPACE) || CliqueMouse();
        if (b->tempoMorte > 1.0f && (confirmar || b->tempoMorte > 5.0f)) {
            b->morreu = false;
            if (b->tipoSala == SALA_TRANSICAO || b->tipoSala == SALA_LUCI) {
                // Bloco 3: volta ao corredor do núcleo sem perder nada
                if (b->tipoSala == SALA_LUCI) b->perm->derrotasLuci++;
                RogueLimparEfeitos(&b->j);
                RogueEntrarSala(b, SALA_TRANSICAO);
                b->j.hp = RogueHpMax(b);
                b->j.ep = RogueEpMax(b);
            } else if (b->modoSeletor) {
                // Seletor de chefes: a derrota volta ao átrio e limpa o desafio
                Telemetria("seletor_derrota", (b->chefeSeletor >= 0) ? NOMES_CHEFES_SELETOR[b->chefeSeletor] : "", (float)(GetTime() - b->inicio), 0);
                RogueVoltarAoLobby(b);
            } else {
                RogueEsvaziarMochila(&b->j);
                RogueEntrarAtrio(b, false);
            }
        }
        return ROGUE_NADA;
    }

    // Focus Mode (Silogista bullet-hell): projéteis, inimigos e o Silogista andam com dt * 0,3
    float dtMundo = dt * RogueFatorTempoMundo(b);

    RogueAtualizarJogador(b, prog, dt);
    RogueAtualizarInimigos(b, dtMundo);
    RogueAtualizarProjeteis(b, prog, dtMundo);
    RogueAtualizarColetaveis(b, dt);

    RogueAtualizarDedutivo(b, dt);
    RogueAtualizarEfeitos(b, dt);
    RogueAtualizarLuci(b, prog, dt);

    if (b->tipoSala == SALA_CHEFE)
        RogueAtualizarChefe(b, prog, dt);

    if (b->tipoSala == SALA_SILOGISTA)
        RogueAtualizarSilogista(b, prog, dtMundo);

    if (b->tipoSala == SALA_LUCI)
        RogueAtualizarLuciChefe(b, prog, dt);

    if (b->tipoSala == SALA_MESTRE)
        RogueAtualizarMestre(b, prog, dt);

    // Reformulação: armadilhas, áreas da build e provas
    RogueAtualizarArmadilhas(b, prog, dt);
    RogueAtualizarAreas(b, prog, dt);
    RogueAtualizarDesafioSala(b, prog, dt);
    if (b->mensagemSistema > 0.0f) b->mensagemSistema -= dt;
    if (b->marcaParede > 0.0f)     b->marcaParede -= dt;

    // Chegou perto do Guardião selado: o desafio abre
    for (int i = 0; i < MAX_INIMIGOS && !b->desafioAberto; i++) {
        Inimigo *e = &b->ini[i];
        if (e->ativo && e->selado && e->surgindo <= 0.0f && Vector2Distance(e->pos, b->j.pos) < RAIO_DESAFIO)
            RogueAbrirDesafio(b, i);
    }

    // Sala da Mestre (fim do Bloco 1): cair não é derrota, a Luci reergue o Thomas
    if (b->tipoSala == SALA_MESTRE && b->j.hp <= 0.0f) {
        RogueMestreReerguer(b);
        return ROGUE_NADA;
    }

    if (b->j.hp <= 0.0f) {
        b->j.hp = 0.0f;
        b->morreu = true;
        b->tempoMorte = 0.0f;
        b->perm->mortes++;
        AlterarPontos(prog, -PENALIDADE_HP_ZERO);
        RogueParticulas(b, b->j.pos, SKYBLUE, 30, 260);
        TocarSom(sfxErro);
        Telemetria("rogue_morte", TextFormat("sala %d", b->indiceRota + 1), (float)(GetTime() - b->inicio), b->abatidos);
        return ROGUE_NADA;
    }

    // Objetivo da sala de combate (eliminar, ondas, sobreviver, núcleos, alvo prioritário, mecanismo).
    // Concluído, abre as portas e deixa a recompensa (ver RogueConcluirCombate).
    RogueAtualizarObjetivo(b, prog, dt);

    // Portas: só com E, perto da porta (a porta tem prioridade sobre o que estiver ao lado)
    int portaK = -1;
    PortaInteracao porta = RoguePortaProxima(b, &portaK);

    if (IsKeyPressed(KEY_E) && porta != PORTA_NENHUMA) {
        switch (porta) {
            case PORTA_ATRIO_CORREDOR:
                return ROGUE_SAIR;

            case PORTA_ATRIO_NUCLEO:
                // Continuidade linear: a porta do núcleo abre a cutscene de transição
                b->transicaoNucleo = TRANSICAO_NUCLEO;
                b->entrouNucleo = false;
                PararSons();
                TocarSom(sfxEstatica);
                Telemetria("bloco3_porta", "", (float)(GetTime() - b->inicio), b->perm->tentativas);
                return ROGUE_NADA;

            case PORTA_ATRIO_MISSAO:
                if (b->perm->byteVisto) RogueComecarMissao(b);
                else DialogoFalaAvulsa(dlg, "Luci: Antes de entrar, vamos falar com o Professor Byte. Ele está ali, perto da porta!");
                return ROGUE_NADA;

            case PORTA_TRANSICAO_LUCI:
                RogueEntrarSala(b, SALA_LUCI);
                return ROGUE_NADA;

            case PORTA_DA_MISSAO:
                RogueAtravessarPorta(b, portaK);
                return ROGUE_NADA;

            case PORTA_SECRETA:
                RogueEntrarSecreta(b);      // passagem secreta aberta: um desvio opcional
                return ROGUE_NADA;

            default:
                break;
        }
    }

    // E: falar, ler, pegar
    int pedestal = -1;
    AlvoRogue alvo = RogueAlvoProximo(b, &pedestal);

    if (IsKeyPressed(KEY_E) && alvo != ALVO_NADA) {
        RogueInteragir(b, dlg, alvo, pedestal);
        return ROGUE_NADA;
    }

    return ROGUE_NADA;
}

// ---------- Desenho ----------

static void DesenharEstante(Rectangle r, float tempo)
{
    static const Color lombadas[5] = { { 120, 60, 200, 255 }, { 60, 140, 220, 255 }, { 200, 80, 160, 255 },
                                       { 80, 200, 220, 255 }, { 230, 190, 80, 255 } };

    DrawRectangleRec(r, (Color){ 40, 28, 64, 255 });

    // Lombadas dos livros (o comprimento da estante decide a direção)
    bool deitada = r.width >= r.height;
    int passo = 7;
    int n = (int)((deitada ? r.width : r.height) - 6) / passo;

    for (int i = 0; i < n; i++) {
        Color c = lombadas[Ruido((unsigned int)(r.x * 7 + r.y * 13 + i)) % 5];
        if (deitada) DrawRectangle((int)r.x + 3 + i * passo, (int)r.y + 4, passo - 2, (int)r.height - 8, Fade(c, 0.8f));
        else         DrawRectangle((int)r.x + 4, (int)r.y + 3 + i * passo, (int)r.width - 8, passo - 2, Fade(c, 0.8f));
    }

    DrawRectangleLinesEx(r, 2, Fade(SKYBLUE, 0.35f + 0.1f * sinf(tempo * 2.0f + r.x)));
}

// ---------- Fim do Bloco 1: desenho da sala da ALUCINAÇÃO MESTRE ----------

static void DesenharIconeArma(TipoArma arma, Vector2 c, float e, float tempo);

// O pedestal com o Disparador de Dados (um facho dourado chama a atenção)
static void DesenharPedestalArmaMestre(Vector2 c, float tempo)
{
    float pulso = 0.5f + 0.5f * sinf(tempo * 3.0f);
    DrawTriangle((Vector2){ c.x, c.y - 150 }, (Vector2){ c.x - 34, c.y + 6 }, (Vector2){ c.x + 34, c.y + 6 }, Fade(GOLD, 0.06f + 0.05f * pulso));
    DrawEllipse((int)c.x, (int)c.y + 18, 34, 10, Fade(BLACK, 0.4f));
    DrawRectangle((int)c.x - 22, (int)c.y + 2, 44, 16, (Color){ 70, 45, 110, 255 });
    DrawRectangle((int)c.x - 28, (int)c.y + 14, 56, 8, (Color){ 50, 32, 84, 255 });
    DrawRectangleLines((int)c.x - 22, (int)c.y + 2, 44, 16, GOLD);
    float y = c.y - 14 + sinf(tempo * 2.2f) * 4.0f;
    DrawCircleV((Vector2){ c.x, y }, 18 + 3 * pulso, Fade(GOLD, 0.12f));
    DesenharIconeArma(ARMA_DISPARADOR, (Vector2){ c.x, y }, 1.6f, tempo);
}

// Alvo de treino: um monitorzinho com "?" que balança
static void DesenharAlvoTreino(Vector2 c, float tempo, int i)
{
    float y = c.y + sinf(tempo * 2.5f + i) * 4.0f;
    DrawRectangle((int)c.x - 16, (int)y - 12, 32, 24, (Color){ 255, 161, 0, 255 });
    DrawRectangle((int)c.x - 13, (int)y - 9, 26, 18, (Color){ 20, 12, 36, 255 });
    DrawText("?", (int)c.x - 3, (int)y - 8, 16, (Color){ 255, 161, 0, 255 });
    DrawCircleLines((int)c.x, (int)y, 24 + 2 * sinf(tempo * 4.0f), Fade(GOLD, 0.5f));
    DrawRectangle((int)c.x - 2, (int)y + 12, 4, 8, GRAY);
}

static void DesenharMestreTreino(const Biblioteca *b, float tempo)
{
    const MestreTreino *m = &b->mestre;

    if (!m->ativo)
        return;

    if (m->etapa == MT_ARMA)
        DesenharPedestalArmaMestre(POS_ARMA_MESTRE, tempo);

    if (m->etapa == MT_TIRO)
        for (int a = 0; a < MESTRE_ALVOS; a++)
            if (m->alvoVivo[a]) DesenharAlvoTreino(m->alvo[a], tempo, a);

    if (!m->visivel && m->morrendo <= 0.0f)
        return;

    Vector2 c = m->pos;
    if (m->morrendo > 0.0f) { c.x += (float)GetRandomValue(-4, 4); c.y += (float)GetRandomValue(-4, 4); }
    if (m->acao == MA_TELEGRAFA) c.x += (float)GetRandomValue(-2, 2);

    // Golpe vindo: aura vermelha, a linha do caminho e o "!"
    bool golpe = (m->acao == MA_TELEGRAFA || m->acao == MA_INVESTE) && m->morrendo <= 0.0f;
    if (golpe) {
        float p = 0.5f + 0.5f * sinf(tempo * 18.0f);
        DrawCircleV(c, MESTRE_RAIO + 26 + 6 * p, Fade(RED, 0.18f + 0.12f * p));
        if (m->acao == MA_TELEGRAFA) {
            Vector2 fim = Vector2Add(c, Vector2Scale(m->dirGolpe, 260.0f));
            for (int k = 0; k < 10; k++) {
                Vector2 a = Vector2Lerp(c, fim, k / 10.0f), z = Vector2Lerp(c, fim, (k + 0.5f) / 10.0f);
                DrawLineEx(a, z, 3.0f, Fade(RED, 0.6f));
            }
            DrawText("!", (int)c.x - 4, (int)c.y - 110, 30, RED);
        }
    }

    // A Mestre (o mesmo desenho do Bloco 1)
    DesenharAlucinacaoMestre(c, tempo);
    if (golpe) {        // os "olhos" em vermelho neon
        DrawCircleV((Vector2){ c.x - 12, c.y - 8 }, 5, RED);
        DrawCircleV((Vector2){ c.x + 12, c.y - 8 }, 5, RED);
    }
    if (m->flash > 0.0f)
        DrawCircleV(c, MESTRE_RAIO + 6, Fade(WHITE, Clamp(m->flash * 5.0f, 0.0f, 0.7f)));
    if (m->surgindo > 0.0f)
        DrawCircleV(c, 110, Fade((Color){ 16, 12, 30, 255 }, Clamp(m->surgindo, 0.0f, 1.0f)));
    if (m->morrendo > 0.0f)
        DrawCircleV(c, 120, Fade((Color){ 16, 12, 30, 255 }, Clamp(1.0f - m->morrendo / 1.8f, 0.0f, 1.0f)));

    // Escudo: fechado (roxo) ou aberto (dourado, a hora de atirar)
    if (m->morrendo <= 0.0f && m->surgindo <= 0.0f) {
        if (MestreVulneravel(m)) {
            float p = 0.5f + 0.5f * sinf(tempo * 8.0f);
            DrawCircleLines((int)c.x, (int)c.y, MESTRE_RAIO + 10 + 4 * p, GOLD);
            DrawCircleLines((int)c.x, (int)c.y, MESTRE_RAIO + 14 + 4 * p, Fade(GOLD, 0.5f));
            const char *t = (m->acao == MA_ATORDOADA) ? "ATORDOADA! ATIRE!" : "ABERTA! ATIRE!";
            DrawText(t, (int)c.x - MeasureText(t, 12) / 2, (int)c.y + 72, 12, GOLD);
            if (m->acao == MA_ATORDOADA)
                for (int k = 0; k < 3; k++) {
                    float a = tempo * 4.0f + k * 2.1f;
                    DrawPoly((Vector2){ c.x + cosf(a) * 30, c.y - 66 + sinf(a) * 8 }, 4, 5, tempo * 200.0f, GOLD);
                }
        } else {
            Color roxo = { 200, 122, 255, 255 };
            for (int k = 0; k < 6; k++) {
                float a0 = tempo * 0.8f + k * (PI / 3.0f);
                DrawRing(c, MESTRE_RAIO + 9, MESTRE_RAIO + 12, a0 * RAD2DEG, a0 * RAD2DEG + 40.0f, 6, Fade(roxo, 0.75f));
            }
        }
    }

    // O anel do parry: fecha em volta do Thomas no instante do impacto
    float falta = MestreTempoAteGolpe(m, b->j.pos, MestreTelegrafia(m));
    if (falta >= 0.0f && falta < 1.4f && (m->etapa == MT_PARRY || m->etapa == MT_LUTA)) {
        float raio = RAIO_CORPO_JOGADOR + 4.0f + 70.0f * (falta / 1.4f);
        bool agora = falta < PARRY_JANELA;
        DrawCircleLines((int)b->j.pos.x, (int)b->j.pos.y, raio, agora ? GOLD : Fade(RED, 0.8f));
        DrawCircleLines((int)b->j.pos.x, (int)b->j.pos.y, raio + 1, agora ? GOLD : Fade(RED, 0.5f));
        if (agora) DrawText("V!", (int)b->j.pos.x - 6, (int)b->j.pos.y - 48, 14, GOLD);
    }
}

// Barra de vida e as etapas do treino (no alto da tela)
static void DesenharHudMestre(const Biblioteca *b, float tempo)
{
    const MestreTreino *m = &b->mestre;

    if (!m->ativo)
        return;

    // As etapas: o que já foi aprendido fica dourado (embaixo, à esquerda, acima do painel da Luci)
    static const char *nomes[6] = { "ARMA", "TIRO", "ESQUIVA", "BRECHA", "PARRY", "LUTA" };
    int x = 46, y = 464;
    for (int i = 0; i < 6; i++) {
        bool feito = (int)m->etapa > i, atual = (int)m->etapa == i;
        int w = MeasureText(nomes[i], 10) + 12;
        DrawRectangle(x, y, w, 15, feito ? Fade(GOLD, 0.25f) : (atual ? Fade((Color){ 0, 228, 255, 255 }, 0.2f + 0.1f * sinf(tempo * 4.0f)) : Fade(BLACK, 0.5f)));
        DrawRectangleLines(x, y, w, 15, feito ? GOLD : (atual ? (Color){ 0, 228, 255, 255 } : Fade(GRAY, 0.6f)));
        DrawText(nomes[i], x + 6, y + 3, 10, feito ? GOLD : (atual ? WHITE : GRAY));
        x += w + 4;
    }

    if (!m->visivel || m->etapa < MT_ABERTURA)
        return;

    int bx = 200, by = 76, w = 400;
    DrawRectangle(bx - 4, by - 2, w + 8, 16, Fade(BLACK, 0.8f));
    DrawRectangle(bx, by + 2, w, 8, (Color){ 40, 20, 50, 255 });
    DrawRectangle(bx, by + 2, (int)(w * m->hp / MESTRE_HP), 8, MestreVulneravel(m) ? GOLD : MAGENTA);
    if (m->etapa == MT_LUTA)
        DrawRectangle(bx + (int)(w * MESTRE_FASE2) - 1, by, 2, 12, WHITE);
    DrawRectangleLines(bx, by + 2, w, 8, GRAY);
    const char *nome = "ALUCINAÇÃO MESTRE";
    int wn = MeasureText(nome, 10);
    DrawText(nome, bx + w / 2 - wn / 2, by + 14, 10, MAGENTA);
}

static void DesenharPortaRogue(Rectangle r, bool aberta, const char *nome, float tempo)
{
    float pulso = 0.5f + 0.5f * sinf(tempo * 4.0f);
    Color cor = aberta ? Fade(GREEN, 0.55f + 0.45f * pulso) : MAROON;

    DrawRectangleRec(r, aberta ? Fade(GREEN, 0.25f) : (Color){ 30, 10, 20, 255 });
    DrawRectangleLinesEx(r, 2, cor);

    const char *rotulo = aberta ? nome : "TRANCADA";
    int w = MeasureText(rotulo, 10);
    int x = (r.width > r.height) ? (int)(r.x + r.width / 2) - w / 2 : (int)(r.x + r.width) + 6;
    int y = (r.width > r.height) ? (int)(r.y + r.height) + 4 : (int)(r.y + r.height / 2) - 5;

    DrawText(rotulo, x, y, 10, aberta ? GREEN : RED);
}

static void DesenharIconeArma(TipoArma arma, Vector2 c, float e, float tempo);

// Ícone de cada item (loja, pedestais, chão e HUD)
static void DesenharIconeItem(TipoItem item, Vector2 c, float e, float tempo)
{
    switch (item) {

        case ITEM_ANTIVIRUS:        // escudo verde com uma cruz
            DesenharTrianguloB2((Vector2){ c.x - 9 * e, c.y - 8 * e }, (Vector2){ c.x + 9 * e, c.y - 8 * e }, (Vector2){ c.x, c.y + 11 * e }, LIME);
            DrawRectangle((int)(c.x - 9 * e), (int)(c.y - 11 * e), (int)(18 * e), (int)(5 * e), LIME);
            DrawRectangle((int)(c.x - 1.5f * e), (int)(c.y - 8 * e), (int)(3 * e), (int)(10 * e), WHITE);
            DrawRectangle((int)(c.x - 5 * e), (int)(c.y - 4.5f * e), (int)(10 * e), (int)(3 * e), WHITE);
            break;

        case ITEM_PACOTE_DADOS:     // pacote azul com bits
            DrawRectangle((int)(c.x - 9 * e), (int)(c.y - 9 * e), (int)(18 * e), (int)(18 * e), (Color){ 30, 90, 180, 255 });
            DrawRectangleLinesEx((Rectangle){ c.x - 9 * e, c.y - 9 * e, 18 * e, 18 * e }, 2, SKYBLUE);
            DrawText("01", (int)(c.x - 6 * e), (int)(c.y - 5 * e), (int)(10 * e), WHITE);
            break;

        case ITEM_LENTE:
            DesenharLupaVerificacao(c, 0.6f * e, tempo);
            break;

        case ITEM_FIREWALL:         // muro de tijolos em chamas
            for (int l = 0; l < 3; l++)
                for (int k = 0; k < 3; k++)
                    DrawRectangle((int)(c.x - 10 * e + k * 7 * e + (l % 2) * 3 * e), (int)(c.y - 4 * e + l * 5 * e),
                                  (int)(6 * e), (int)(4 * e), ORANGE);
            DesenharTrianguloB2((Vector2){ c.x - 6 * e, c.y - 5 * e }, (Vector2){ c.x, c.y - 13 * e - sinf(tempo * 8) * 2 * e },
                                (Vector2){ c.x + 6 * e, c.y - 5 * e }, RED);
            break;

        case ITEM_PROCESSADOR:      // chip roxo com pernas
            for (int k = 0; k < 3; k++) {
                DrawRectangle((int)(c.x - 6 * e + k * 5 * e), (int)(c.y - 12 * e), (int)(2 * e), (int)(24 * e), LIGHTGRAY);
                DrawRectangle((int)(c.x - 12 * e), (int)(c.y - 6 * e + k * 5 * e), (int)(24 * e), (int)(2 * e), LIGHTGRAY);
            }
            DrawRectangle((int)(c.x - 8 * e), (int)(c.y - 8 * e), (int)(16 * e), (int)(16 * e), PURPLE);
            DrawRectangleLinesEx((Rectangle){ c.x - 8 * e, c.y - 8 * e, 16 * e, 16 * e }, 1, MAGENTA);
            break;

        case ITEM_OVERCLOCK:        // raio laranja
            DesenharTrianguloB2((Vector2){ c.x + 2 * e, c.y - 12 * e }, (Vector2){ c.x - 7 * e, c.y + 2 * e }, (Vector2){ c.x + 1 * e, c.y + 1 * e }, ORANGE);
            DesenharTrianguloB2((Vector2){ c.x - 2 * e, c.y + 12 * e }, (Vector2){ c.x + 7 * e, c.y - 2 * e }, (Vector2){ c.x - 1 * e, c.y - 1 * e }, ORANGE);
            break;

        case ITEM_FIREWALL_PORTATIL:    // hexágono com um escudo dentro
            DrawPolyLinesEx(c, 6, 11 * e, 0, 2, (Color){ 0, 228, 48, 255 });
            DesenharTrianguloB2((Vector2){ c.x - 5 * e, c.y - 4 * e }, (Vector2){ c.x + 5 * e, c.y - 4 * e }, (Vector2){ c.x, c.y + 6 * e }, (Color){ 0, 228, 48, 255 });
            break;

        case ITEM_LIMPEZA_CACHE:    // lixeira
            DrawRectangle((int)(c.x - 7 * e), (int)(c.y - 5 * e), (int)(14 * e), (int)(15 * e), SKYBLUE);
            DrawRectangle((int)(c.x - 9 * e), (int)(c.y - 9 * e), (int)(18 * e), (int)(3 * e), SKYBLUE);
            for (int k = -1; k <= 1; k++)
                DrawRectangle((int)(c.x + k * 4 * e - 1), (int)(c.y - 2 * e), 2, (int)(9 * e), (Color){ 20, 40, 70, 255 });
            break;

        case ITEM_PROXY:            // bonequinho tracejado (holograma)
            DrawCircleLines((int)c.x, (int)(c.y - 7 * e), 4 * e, SKYBLUE);
            DrawRectangleLines((int)(c.x - 5 * e), (int)(c.y - 2 * e), (int)(10 * e), (int)(12 * e), SKYBLUE);
            DrawLine((int)(c.x - 8 * e), (int)c.y, (int)(c.x + 8 * e), (int)c.y, Fade(SKYBLUE, 0.5f));
            break;

        case ITEM_PACOTE_INTEGRIDADE:   // caixa branca com cruz vermelha
            DrawRectangle((int)(c.x - 9 * e), (int)(c.y - 8 * e), (int)(18 * e), (int)(16 * e), RAYWHITE);
            DrawRectangle((int)(c.x - 2 * e), (int)(c.y - 6 * e), (int)(4 * e), (int)(12 * e), RED);
            DrawRectangle((int)(c.x - 6 * e), (int)(c.y - 2 * e), (int)(12 * e), (int)(4 * e), RED);
            break;

        case ITEM_CAMPO_LATENCIA:   // relógio
            DrawCircleV(c, 10 * e, (Color){ 50, 30, 80, 255 });
            DrawCircleLines((int)c.x, (int)c.y, 10 * e, PURPLE);
            DrawLineEx(c, (Vector2){ c.x, c.y - 7 * e }, 2, WHITE);
            DrawLineEx(c, (Vector2){ c.x + 5 * e, c.y + 2 * e }, 2, WHITE);
            break;

        case ITEM_NUCLEO:           // coração num hexágono
            DrawPolyLinesEx(c, 6, 11 * e, 30, 2, PINK);
            DrawCircleV((Vector2){ c.x - 3 * e, c.y - 2 * e }, 3.5f * e, RED);
            DrawCircleV((Vector2){ c.x + 3 * e, c.y - 2 * e }, 3.5f * e, RED);
            DesenharTrianguloB2((Vector2){ c.x - 6.5f * e, c.y - 1 * e }, (Vector2){ c.x + 6.5f * e, c.y - 1 * e }, (Vector2){ c.x, c.y + 6 * e }, RED);
            break;

        case ITEM_BUFFER:           // barras crescendo
            for (int k = 0; k < 3; k++)
                DrawRectangle((int)(c.x - 9 * e + k * 7 * e), (int)(c.y + 8 * e - (k + 1) * 5 * e), (int)(5 * e), (int)((k + 1) * 5 * e), YELLOW);
            break;

        case ITEM_ROTEAMENTO:       // ">>"
            for (int k = 0; k < 2; k++) {
                float x0 = c.x - 8 * e + k * 7 * e;
                DrawLineEx((Vector2){ x0, c.y - 7 * e }, (Vector2){ x0 + 6 * e, c.y }, 2.5f, SKYBLUE);
                DrawLineEx((Vector2){ x0 + 6 * e, c.y }, (Vector2){ x0, c.y + 7 * e }, 2.5f, SKYBLUE);
            }
            break;

        case ITEM_FRAGMENTACAO:     // um círculo que vira três
            DrawCircleV((Vector2){ c.x - 5 * e, c.y }, 4 * e, LIME);
            for (int k = -1; k <= 1; k++)
                DrawCircleV((Vector2){ c.x + 6 * e, c.y + k * 6 * e }, 2 * e, LIME);
            break;

        case ITEM_FIREWALL_ADAPTATIVO:  // escudo em camadas
            DesenharTrianguloB2((Vector2){ c.x - 9 * e, c.y - 8 * e }, (Vector2){ c.x + 9 * e, c.y - 8 * e }, (Vector2){ c.x, c.y + 10 * e }, (Color){ 0, 158, 47, 255 });
            DesenharTrianguloB2((Vector2){ c.x - 5 * e, c.y - 5 * e }, (Vector2){ c.x + 5 * e, c.y - 5 * e }, (Vector2){ c.x, c.y + 5 * e }, (Color){ 0, 228, 48, 255 });
            break;

        case ITEM_ANALISADOR:       // mira com três marcas
            DrawCircleLines((int)c.x, (int)c.y, 8 * e, ORANGE);
            DrawLine((int)(c.x - 11 * e), (int)c.y, (int)(c.x + 11 * e), (int)c.y, ORANGE);
            DrawLine((int)c.x, (int)(c.y - 11 * e), (int)c.x, (int)(c.y + 11 * e), ORANGE);
            for (int k = 0; k < 3; k++)
                DrawPoly((Vector2){ c.x - 6 * e + k * 6 * e, c.y + 13 * e }, 4, 2 * e, 0, ORANGE);
            break;

        case ITEM_BOTNET_REVERSO:   // três nós ligados e uma seta para fora
            for (int k = 0; k < 3; k++) {
                float a = k * (2.0f * PI / 3.0f) - PI / 2.0f;
                Vector2 q = { c.x + cosf(a) * 7 * e, c.y + sinf(a) * 7 * e };
                DrawLineEx(c, q, 1, SKYBLUE);
                DrawCircleV(q, 2.5f * e, SKYBLUE);
            }
            DrawLineEx(c, (Vector2){ c.x + 11 * e, c.y + 9 * e }, 2, LIME);
            break;

        case ITEM_CACHE_PERSISTENTE:    // pente de memória com "+"
            DrawRectangle((int)(c.x - 11 * e), (int)(c.y - 4 * e), (int)(22 * e), (int)(9 * e), (Color){ 20, 90, 50, 255 });
            for (int k = 0; k < 5; k++)
                DrawRectangle((int)(c.x - 10 * e + k * 4 * e), (int)(c.y + 5 * e), (int)(2 * e), (int)(2 * e), GOLD);
            DrawText("+", (int)(c.x - 3 * e), (int)(c.y - 10 * e), (int)(14 * e), LIME);
            break;

        case ITEM_MANUAL:           // livro dourado
        default:
            DrawRectangle((int)(c.x - 9 * e), (int)(c.y - 11 * e), (int)(18 * e), (int)(22 * e), GOLD);
            DrawRectangle((int)(c.x - 9 * e), (int)(c.y - 11 * e), (int)(4 * e), (int)(22 * e), ORANGE);
            DrawRectangle((int)(c.x - 2 * e), (int)(c.y - 5 * e), (int)(8 * e), (int)(2 * e), (Color){ 80, 50, 20, 255 });
            DrawRectangle((int)(c.x - 2 * e), (int)(c.y - 1 * e), (int)(8 * e), (int)(2 * e), (Color){ 80, 50, 20, 255 });
            break;
    }
}

// Fragmento de Conhecimento: uma página luminosa
static void DesenharFragmentoConhecimento(Vector2 c, float t)
{
    Vector2 p = { c.x, c.y + sinf(t * 5.0f) * 2.0f };
    DrawCircleV(p, 9, Fade((Color){ 0, 228, 255, 255 }, 0.25f));
    DrawRectangle((int)p.x - 4, (int)p.y - 6, 8, 11, (Color){ 200, 250, 255, 255 });
    DrawRectangle((int)p.x - 2, (int)p.y - 3, 5, 1, (Color){ 0, 120, 160, 255 });
    DrawRectangle((int)p.x - 2, (int)p.y, 5, 1, (Color){ 0, 120, 160, 255 });
}

// Professor Byte: um holograma de professor (cabeça de monitor, óculos e capelo)
static void DesenharProfessorByte(Vector2 c, float t)
{
    Vector2 p = { c.x, c.y + sinf(t * 2.0f) * 3.0f };
    Color holo = (Color){ 0, 228, 255, 255 };

    DrawEllipse((int)c.x, (int)c.y + 26, 20, 6, Fade(holo, 0.25f));
    DrawRectangle((int)p.x - 12, (int)p.y + 4, 24, 20, Fade(holo, 0.35f));                     // corpo
    DrawRectangle((int)p.x - 16, (int)p.y - 20, 32, 24, (Color){ 20, 50, 80, 255 });           // cabeça (monitor)
    DrawRectangleLinesEx((Rectangle){ p.x - 16, p.y - 20, 32, 24 }, 2, holo);
    DrawCircleLines((int)p.x - 7, (int)p.y - 8, 5, WHITE);                                     // óculos
    DrawCircleLines((int)p.x + 7, (int)p.y - 8, 5, WHITE);
    DrawLine((int)p.x - 2, (int)p.y - 8, (int)p.x + 2, (int)p.y - 8, WHITE);
    DrawCircle((int)p.x - 7, (int)p.y - 8, 2, holo);
    DrawCircle((int)p.x + 7, (int)p.y - 8, 2, holo);
    DrawRectangle((int)p.x - 18, (int)p.y - 26, 36, 6, (Color){ 30, 20, 50, 255 });             // capelo
    DrawRectangle((int)p.x - 8, (int)p.y - 30, 16, 5, (Color){ 30, 20, 50, 255 });
    DrawLine((int)p.x + 14, (int)p.y - 24, (int)p.x + 16, (int)p.y - 14, GOLD);                // pendão

    const char *nome = "PROF. BYTE";
    DrawText(nome, (int)c.x - MeasureText(nome, 10) / 2, (int)c.y + 34, 10, holo);
}

// Byteco: um robozinho comerciante atrás do balcão
static void DesenharByteco(Vector2 c, float t)
{
    Vector2 p = { c.x, c.y + sinf(t * 3.0f) * 2.0f };

    DrawLine((int)p.x, (int)p.y - 22, (int)p.x, (int)p.y - 14, LIGHTGRAY);                     // antena
    DrawCircle((int)p.x, (int)p.y - 24, 3, (((int)(t * 2)) % 2) ? GOLD : ORANGE);
    DrawCircle((int)p.x, (int)p.y, 16, (Color){ 230, 160, 60, 255 });                          // corpo redondo
    DrawCircle((int)p.x, (int)p.y, 11, (Color){ 40, 30, 60, 255 });
    DrawCircle((int)p.x - 4, (int)p.y - 2, 3, (Color){ 0, 228, 255, 255 });
    DrawCircle((int)p.x + 4, (int)p.y - 2, 3, (Color){ 0, 228, 255, 255 });
    DrawLine((int)p.x - 4, (int)p.y + 5, (int)p.x + 4, (int)p.y + 5, (Color){ 0, 228, 255, 255 });

    // Balcão com os itens à mostra
    DrawRectangle(555, 318, 110, 24, (Color){ 70, 45, 30, 255 });
    DrawRectangleLinesEx((Rectangle){ 555, 318, 110, 24 }, 2, GOLD);
    for (int i = 0; i < 4; i++)
        DesenharIconeItem((TipoItem)i, (Vector2){ 572.0f + i * 26.0f, 330.0f }, 0.55f, t);

    const char *nome = "BYTECO - LOJA";
    DrawText(nome, 610 - MeasureText(nome, 10) / 2, 346, 10, GOLD);
}

// Terminal de conhecimento das salas educativas
static void DesenharTerminal(Vector2 c, bool lido, float t)
{
    Color cor = lido ? Fade(GRAY, 0.8f) : (Color){ 0, 228, 255, 255 };

    if (!lido)
        DrawCircleV(c, 40 + sinf(t * 3.0f) * 4, Fade(cor, 0.12f));

    DrawRectangle((int)c.x - 20, (int)c.y - 20, 40, 34, (Color){ 20, 30, 50, 255 });
    DrawRectangleLinesEx((Rectangle){ c.x - 20, c.y - 20, 40, 34 }, 2, cor);
    for (int i = 0; i < 3; i++)
        DrawRectangle((int)c.x - 14, (int)c.y - 13 + i * 8, 12 + (int)(Ruido((unsigned int)(t * 4) + i) % 16), 3, Fade(cor, 0.8f));
    DrawRectangle((int)c.x - 6, (int)c.y + 14, 12, 8, (Color){ 40, 40, 60, 255 });
}

// Pedestal com uma recompensa
static void DesenharPedestal(Vector2 c, TipoItem item, bool disponivel, float t)
{
    DrawEllipse((int)c.x, (int)c.y + 16, 22, 8, (Color){ 60, 45, 90, 255 });
    DrawRectangle((int)c.x - 16, (int)c.y + 4, 32, 12, (Color){ 50, 36, 80, 255 });

    if (!disponivel)
        return;

    Vector2 icone = { c.x, c.y - 10 + sinf(t * 3.0f + c.x) * 3.0f };
    DrawCircleV(icone, 18, Fade(GOLD, 0.12f));
    DesenharIconeItem(item, icone, 1.0f, t);
}

// Fragmento Alucinado: um cristal de dado corrompido (camadas deslocadas = glitch)
static void DesenharFragmentoAlucinado(const Inimigo *e, float escala)
{
    float s = e->raio * escala;
    Vector2 p = e->pos;

    if (e->estado == 1)           // preparando o bote: treme e fica vermelho
        p.x += (float)GetRandomValue(-2, 2);

    Color cores[3] = { Fade(SKYBLUE, 0.5f), Fade(RED, 0.5f), (e->estado == 1) ? RED : (Color){ 230, 41, 255, 255 } };
    float desloc[3] = { -3.0f, 3.0f, 0.0f };

    for (int k = 0; k < 3; k++) {
        Vector2 c = { p.x + desloc[k], p.y };
        float giro = e->anim * 2.0f;
        Vector2 a = GirarPonto(c, 0, -s * 1.2f, giro * 20.0f);
        Vector2 d = GirarPonto(c, s, 0, giro * 20.0f);
        Vector2 f = GirarPonto(c, 0, s * 1.2f, giro * 20.0f);
        Vector2 g = GirarPonto(c, -s, 0, giro * 20.0f);
        DesenharTrianguloB2(a, d, f, cores[k]);
        DesenharTrianguloB2(a, f, g, cores[k]);
    }

    DrawText(e->estado == 1 ? "!" : "?", (int)p.x - 3, (int)p.y - 7, 14, WHITE);
}

// Guardião de Dados: um tomo flutuante que vigia (brilha antes de atirar)
static void DesenharGuardiao(const Inimigo *e, float escala)
{
    float w = 30 * escala, h = 34 * escala;
    Vector2 p = { e->pos.x, e->pos.y + sinf(e->anim * 2.0f) * 3.0f };

    if (e->estado == 1) {
        float k = 1.0f - e->timer / GUARDIAO_PREPARO;
        DrawCircleV(p, e->raio + 6 + 10 * k, Fade(ORANGE, 0.25f + 0.3f * k));
    }

    DrawCircleV(p, e->raio + 4, Fade(SKYBLUE, 0.12f));
    DrawRectangle((int)(p.x - w / 2), (int)(p.y - h / 2), (int)w, (int)h, (Color){ 30, 60, 120, 255 });
    DrawRectangle((int)(p.x - w / 2), (int)(p.y - h / 2), (int)(6 * escala), (int)h, SKYBLUE);           // lombada
    DrawRectangleLinesEx((Rectangle){ p.x - w / 2, p.y - h / 2, w, h }, 2, SKYBLUE);

    DrawCircle((int)(p.x + 3 * escala), (int)p.y, 7 * escala, WHITE);
    DrawCircle((int)(p.x + 3 * escala), (int)p.y, 3.5f * escala, (e->estado == 1) ? ORANGE : (Color){ 0, 60, 140, 255 });
}

// Eco falso: um fantasma do fragmento, piscando cada vez mais rápido até explodir
static void DesenharEco(const Inimigo *e)
{
    float k = 1.0f - e->timer / ECO_TEMPO;
    float pisca = 0.35f + 0.35f * sinf(e->anim * (8.0f + 20.0f * k));

    DrawCircleV(e->pos, e->raio + 4 * k, Fade(MAGENTA, 0.25f + pisca * 0.4f));
    DrawCircleLines((int)e->pos.x, (int)e->pos.y, e->raio + 10 * (1.0f - k), Fade(MAGENTA, 0.8f));
    DrawText("?", (int)e->pos.x - 3, (int)e->pos.y - 7, 14, Fade(WHITE, 0.8f));
}

// Selo dourado em volta do Guardião com desafio
static void DesenharSelo(const Inimigo *e, float tempo)
{
    float r = e->raio + 14.0f;

    for (int i = 0; i < 6; i++) {
        float a1 = tempo * 1.2f + i * (PI / 3.0f), a2 = a1 + PI / 3.0f;
        DrawLineEx((Vector2){ e->pos.x + cosf(a1) * r, e->pos.y + sinf(a1) * r },
                   (Vector2){ e->pos.x + cosf(a2) * r, e->pos.y + sinf(a2) * r }, 3, Fade(GOLD, 0.8f));
    }

    DrawCircleV(e->pos, r, Fade(GOLD, 0.08f + 0.05f * sinf(tempo * 4.0f)));
    DrawText("?", (int)e->pos.x - 6, (int)(e->pos.y - e->raio - 40 + sinf(tempo * 3.0f) * 3.0f), 24, GOLD);
}

// ---------- Desenho dos inimigos da expansão ----------
// Cada um tem uma silhueta própria (não depende só da cor) e um aviso antes de atacar.

// Spammer: uma janela pop-up com barra de título, "x" e o selo de notificação
static void DesenharSpammer(const Inimigo *e, float escala)
{
    float s = escala;
    Vector2 p = { e->pos.x, e->pos.y + sinf(e->anim * 9.0f) * 1.5f };

    if (((int)(e->anim * 7.0f + e->lado * 3.0f)) % 9 == 0)
        p.x += 2.0f;                                        // tremidinha de glitch

    Rectangle janela = { p.x - 11 * s, p.y - 8 * s, 22 * s, 16 * s };
    DrawRectangleRec(janela, (Color){ 45, 25, 30, 255 });
    DrawRectangle((int)janela.x, (int)janela.y, (int)janela.width, (int)(4 * s), (Color){ 255, 120, 60, 255 });
    DrawRectangleLinesEx(janela, 1, (Color){ 255, 170, 120, 255 });
    DrawLine((int)(p.x + 6 * s), (int)(p.y - 8 * s), (int)(p.x + 9 * s), (int)(p.y - 5 * s), WHITE);    // "x"
    DrawLine((int)(p.x + 9 * s), (int)(p.y - 8 * s), (int)(p.x + 6 * s), (int)(p.y - 5 * s), WHITE);
    DrawRectangle((int)(p.x - 7 * s), (int)(p.y - 1 * s), (int)(12 * s), (int)(2 * s), Fade(WHITE, 0.7f));
    DrawRectangle((int)(p.x - 7 * s), (int)(p.y + 3 * s), (int)(8 * s), (int)(2 * s), Fade(WHITE, 0.7f));

    // Selo de notificação ("!")
    DrawCircle((int)(p.x - 11 * s), (int)(p.y - 8 * s), 5 * s, RED);
    DrawText("!", (int)(p.x - 12 * s), (int)(p.y - 13 * s), (int)(10 * s), WHITE);
}

// Fragmento de spam: um envelopinho
static void DesenharSpam(const Inimigo *e)
{
    Vector2 p = e->pos;
    float alfa = fminf(1.0f, e->vida / 0.6f);                // some piscando no fim

    DrawRectangle((int)p.x - 6, (int)p.y - 4, 12, 8, Fade((Color){ 255, 220, 180, 255 }, alfa));
    DrawLine((int)p.x - 6, (int)p.y - 4, (int)p.x, (int)p.y + 1, Fade(RED, alfa));
    DrawLine((int)p.x + 6, (int)p.y - 4, (int)p.x, (int)p.y + 1, Fade(RED, alfa));
}

// Phisher: camuflado, um arquivo "GRÁTIS" (com um anzol que brilha de vez em quando);
// revelado, o arquivo escurece, abre os olhos e mostra o anzol. A cópia falsa não tem
// sombra e pisca (é assim que se descobre o verdadeiro).
static void DesenharPhisher(const Inimigo *e, float escala)
{
    bool isca = (e->tipo == INIMIGO_ISCA);
    bool revelado = (e->estado != 0);
    float s = escala;
    Vector2 p = { e->pos.x, e->pos.y + sinf(e->anim * 2.0f) * 2.0f };

    if (isca && ((int)(e->anim * 12.0f)) % 5 == 0)
        return;                                             // a cópia falha por um instante

    if (!isca)
        DrawEllipse((int)e->pos.x, (int)e->pos.y + 16, 12 * s, 4 * s, Fade(BLACK, 0.45f));

    if (e->estado == 1)                                      // mirando: treme
        p.x += (float)GetRandomValue(-2, 2);

    Color papel = revelado ? (Color){ 70, 55, 80, 255 } : (Color){ 235, 228, 205, 255 };
    Rectangle r = { p.x - 10 * s, p.y - 13 * s, 20 * s, 26 * s };

    DrawRectangleRec(r, papel);
    DesenharTrianguloB2((Vector2){ r.x + r.width - 7 * s, r.y }, (Vector2){ r.x + r.width, r.y + 7 * s },
                        (Vector2){ r.x + r.width - 7 * s, r.y + 7 * s }, revelado ? GOLD : (Color){ 190, 180, 150, 255 });
    DrawRectangleLinesEx(r, 1, revelado ? GOLD : (Color){ 150, 140, 120, 255 });

    if (!revelado) {
        // "Prêmio" para chamar atenção, e o anzol escondido aparecendo de vez em quando
        DrawText("$", (int)p.x - 3, (int)p.y - 7, 14, (Color){ 40, 140, 60, 255 });
        if (fmodf(e->anim, 2.6f) < 0.25f)
            DrawCircleLines((int)(r.x + r.width), (int)(r.y + r.height), 3, GOLD);
        const char *rotulo = "GRÁTIS";
        DrawText(rotulo, (int)p.x - MeasureText(rotulo, 8) / 2, (int)(r.y + r.height) + 3, 8, GOLD);
        return;
    }

    // Revelado: olhos e o anzol em cima
    DrawRectangle((int)(p.x - 6 * s), (int)(p.y - 4 * s), (int)(4 * s), (int)(2 * s), RED);
    DrawRectangle((int)(p.x + 2 * s), (int)(p.y - 4 * s), (int)(4 * s), (int)(2 * s), RED);
    DrawLine((int)p.x, (int)(r.y - 12 * s), (int)p.x, (int)r.y, LIGHTGRAY);
    DrawRing((Vector2){ p.x + 4 * s, r.y - 12 * s }, 3 * s, 4.5f * s, 180.0f, 360.0f, 8, LIGHTGRAY);

    if (e->estado == 1) {
        DrawText("!", (int)p.x - 2, (int)(r.y - 30), 16, GOLD);
        // Linha do bote
        Vector2 fim = Vector2Add(e->pos, Vector2Scale(e->alvo, PHISHER_BOTE_VEL * PHISHER_BOTE_DURACAO));
        DrawLineEx(e->pos, fim, 6.0f, Fade(GOLD, 0.15f + 0.15f * sinf(e->anim * 25.0f)));
        DrawLineEx(e->pos, fim, 1.5f, Fade(GOLD, 0.8f));
    }
}

// Firewall: robô octogonal com cadeado; escudo hexagonal na frente, saída de ar
// (ponto fraco) atrás. Barreira de energia: aviso tracejado, depois o muro.
static void DesenharFirewall(const Inimigo *e, float escala, float t)
{
    float s = escala;
    Vector2 p = e->pos;
    float ang = atan2f(e->frente.y, e->frente.x) * RAD2DEG;
    Vector2 tras = Vector2Subtract(p, Vector2Scale(e->frente, e->raio * 0.75f * s));
    Vector2 lado = { -e->frente.y, e->frente.x };

    DrawEllipse((int)p.x, (int)p.y + 20, 20 * s, 5 * s, Fade(BLACK, 0.4f));
    DrawPoly(p, 8, 20 * s, 22.5f, (Color){ 30, 60, 45, 255 });
    DrawPolyLinesEx(p, 8, 20 * s, 22.5f, 2, (Color){ 120, 220, 150, 255 });

    // Cadeado
    DrawRing((Vector2){ p.x, p.y - 3 * s }, 4 * s, 6 * s, 180.0f, 360.0f, 10, LIGHTGRAY);
    DrawRectangle((int)(p.x - 6 * s), (int)(p.y - 3 * s), (int)(12 * s), (int)(9 * s), GOLD);
    DrawRectangle((int)(p.x - 1 * s), (int)p.y, (int)(2 * s), (int)(3 * s), (Color){ 60, 40, 0, 255 });

    // Saída de ar atrás (ponto fraco), pulsando
    for (int k = -1; k <= 1; k++) {
        Vector2 a = Vector2Add(tras, Vector2Scale(lado, k * 5.0f * s));
        DrawLineEx(Vector2Add(a, Vector2Scale(e->frente, -3 * s)), Vector2Add(a, Vector2Scale(e->frente, 3 * s)), 2,
                   Fade(ORANGE, 0.5f + 0.4f * sinf(t * 6.0f)));
    }

    // Escudo frontal (com as divisões hexagonais)
    DrawRing(p, e->raio + 4, e->raio + 9, ang - FIREWALL_ANGULO_FRENTE, ang + FIREWALL_ANGULO_FRENTE, 16, Fade((Color){ 0, 228, 48, 255 }, 0.85f));
    for (int k = -2; k <= 2; k++) {
        float a = (ang + k * FIREWALL_ANGULO_FRENTE / 2.5f) * DEG2RAD;
        DrawLineEx((Vector2){ p.x + cosf(a) * (e->raio + 4), p.y + sinf(a) * (e->raio + 4) },
                   (Vector2){ p.x + cosf(a) * (e->raio + 9), p.y + sinf(a) * (e->raio + 9) }, 1, (Color){ 20, 60, 30, 255 });
    }

    // Barreira de energia
    if (e->estado == 1 || e->estado == 2) {
        Vector2 a, c;
        RogueBarreiraFirewall(e, &a, &c);
        if (e->estado == 1) {
            for (int k = 0; k < 8; k += 2)
                DrawLineEx(Vector2Lerp(a, c, k / 8.0f), Vector2Lerp(a, c, (k + 1) / 8.0f), 2, Fade((Color){ 0, 228, 48, 255 }, 0.5f + 0.5f * sinf(t * 20.0f)));
        } else {
            DrawLineEx(a, c, 7.0f, Fade((Color){ 0, 228, 48, 255 }, 0.35f));
            DrawLineEx(a, c, 2.0f, (Color){ 150, 255, 170, 255 });
            for (int k = 1; k < 6; k++)
                DrawPolyLines(Vector2Lerp(a, c, k / 6.0f), 6, 5, 0, Fade((Color){ 150, 255, 170, 255 }, 0.8f));
        }
    }
}

// Overclock: engrenagem com núcleo superaquecido. Carregando, o núcleo fica branco
// e a linha da investida cresce; superaquecido, solta fumaça e a engrenagem para.
static void DesenharOverclock(const Inimigo *e, float escala, float t)
{
    float s = escala;
    Vector2 p = e->pos;
    float k = (e->estado == 1) ? Clamp(e->carga / OVERCLOCK_CARGA_MAX, 0.0f, 1.0f) : 0.0f;

    if (e->estado == 1)
        p.x += (float)GetRandomValue(-1, 1) * (1.0f + 2.0f * k);

    // Investida: rastro de imagens
    if (e->estado == 2)
        for (int r = 1; r <= 3; r++)
            DrawCircleV(Vector2Subtract(p, Vector2Scale(Vector2Normalize(e->vel), r * 14.0f)), 13 * s, Fade(ORANGE, 0.25f / r));

    float giro = (e->estado == 3) ? 0.0f : e->anim * (e->estado == 1 ? 12.0f + 20.0f * k : 4.0f);
    Color metal = (e->estado == 3) ? (Color){ 90, 90, 110, 255 } : (Color){ 150, 110, 70, 255 };

    for (int d = 0; d < 8; d++) {
        float a = giro + d * (PI / 4.0f);
        DrawRectanglePro((Rectangle){ p.x + cosf(a) * 15 * s, p.y + sinf(a) * 15 * s, 7 * s, 7 * s }, (Vector2){ 3.5f * s, 3.5f * s }, a * RAD2DEG, metal);
    }
    DrawCircleV(p, 14 * s, metal);

    Color nucleo = (e->estado == 3) ? (Color){ 60, 90, 140, 255 }
                 : ColorLerp((Color){ 255, 120, 0, 255 }, WHITE, k);
    if (e->estado != 3)
        DrawCircleV(p, (9 + 8 * k + sinf(t * 10.0f) * 1.5f) * s, Fade(nucleo, 0.35f));
    DrawCircleV(p, 7 * s, nucleo);

    if (e->estado == 3) {
        // Superaquecido: rachaduras (é a hora de atacar)
        DrawLine((int)p.x - 6, (int)p.y - 6, (int)p.x + 2, (int)p.y + 1, BLACK);
        DrawLine((int)p.x + 2, (int)p.y + 1, (int)p.x + 6, (int)p.y - 3, BLACK);
        DrawText("!!", (int)p.x - 5, (int)p.y - 32, 12, SKYBLUE);
    }

    // Aviso da investida: a linha cresce com a carga
    if (e->estado == 1) {
        float alcance = (OVERCLOCK_INVESTIDA_MIN + (OVERCLOCK_INVESTIDA_MAX - OVERCLOCK_INVESTIDA_MIN) * RogueCargaOverclock(e)) * OVERCLOCK_INVESTIDA_DURACAO;
        Vector2 fim = Vector2Add(e->pos, Vector2Scale(e->alvo, alcance));
        DrawLineEx(e->pos, fim, 10.0f, Fade(RED, 0.10f + 0.15f * k));
        DrawLineEx(e->pos, fim, 1.5f, Fade(RED, 0.5f + 0.5f * k));
        DrawRing(e->pos, 20 * s, 23 * s, -90.0f, -90.0f + 360.0f * Clamp(e->carga / e->cargaAlvo, 0.0f, 1.0f), 20, ORANGE);
    }
}

// Botnet: núcleo com três nós orbitando, ligados por fios
static void DesenharBotnet(const Inimigo *e, float escala, float t)
{
    float s = escala;
    Vector2 p = { e->pos.x, e->pos.y + sinf(t * 3.0f + e->pos.x) * 2.0f };
    Color ciano = { 0, 228, 255, 255 };

    if (e->estado == 1)
        DrawCircleV(p, (e->raio + 6) * s, Fade(ciano, 0.25f + 0.25f * sinf(t * 25.0f)));

    for (int n = 0; n < 3; n++) {
        float a = t * 2.0f + n * (2.0f * PI / 3.0f);
        Vector2 q = { p.x + cosf(a) * 16 * s, p.y + sinf(a) * 16 * s };
        DrawLineEx(p, q, 1, Fade(ciano, 0.7f));
        DrawRectangle((int)(q.x - 3 * s), (int)(q.y - 3 * s), (int)(6 * s), (int)(6 * s), (Color){ 20, 60, 80, 255 });
        DrawRectangleLines((int)(q.x - 3 * s), (int)(q.y - 3 * s), (int)(6 * s), (int)(6 * s), ciano);
    }

    DrawPoly(p, 6, 9 * s, t * 40.0f, (Color){ 10, 40, 60, 255 });
    DrawPolyLinesEx(p, 6, 9 * s, t * 40.0f, 2, ciano);
    DrawCircleV(p, 3 * s, WHITE);
}

// Keylogger: corpo fino de teclado (com teclas) e o "REC" piscando
static void DesenharKeylogger(const Inimigo *e, float escala, float t)
{
    float s = escala;
    Vector2 p = { e->pos.x, e->pos.y + sinf(t * 2.5f + e->pos.y) * 2.0f };
    Rectangle r = { p.x - 8 * s, p.y - 18 * s, 16 * s, 36 * s };
    static const char *teclas[6] = { "Q", "W", "E", "A", "S", "D" };

    DrawEllipse((int)e->pos.x, (int)e->pos.y + 20, 9 * s, 3 * s, Fade(BLACK, 0.4f));
    DrawRectangleRec(r, (Color){ 40, 40, 48, 255 });
    DrawRectangleLinesEx(r, 1, (e->estado >= 1) ? RED : LIGHTGRAY);

    for (int k = 0; k < 6; k++) {
        int cx = (int)(r.x + 2 * s + (k % 2) * 7 * s), cy = (int)(r.y + 3 * s + (k / 2) * 10 * s);
        DrawRectangle(cx, cy, (int)(6 * s), (int)(7 * s), (Color){ 200, 200, 210, 255 });
        if (s > 0.9f) DrawText(teclas[k], cx + 1, cy, 8, (Color){ 40, 40, 48, 255 });
    }

    // REC
    if (((int)(t * 2.0f)) % 2 == 0 || e->estado >= 1) {
        DrawCircle((int)(p.x - 9 * s), (int)(r.y - 6 * s), 2.5f * s, RED);
        DrawText("REC", (int)(p.x - 5 * s), (int)(r.y - 10 * s), 8, RED);
    }
}

// Mira do Keylogger no chão (onde ele acha que o jogador vai estar)
static void DesenharMiraKeylogger(const Inimigo *e, float t)
{
    if (e->estado != 1 && e->estado != 2)
        return;

    Vector2 m = e->miraPrevista;
    float travou = (e->estado == 2 || e->timer <= 0.15f) ? 1.0f : 0.0f;
    float raio = 16.0f - 6.0f * travou;

    DrawLineEx(e->pos, m, 1.0f, Fade(RED, 0.35f));
    DrawCircleLines((int)m.x, (int)m.y, raio, Fade(RED, 0.6f + 0.4f * sinf(t * 20.0f)));
    DrawLine((int)(m.x - raio - 4), (int)m.y, (int)(m.x - raio + 4), (int)m.y, RED);
    DrawLine((int)(m.x + raio - 4), (int)m.y, (int)(m.x + raio + 4), (int)m.y, RED);
    DrawLine((int)m.x, (int)(m.y - raio - 4), (int)m.x, (int)(m.y - raio + 4), RED);
    DrawLine((int)m.x, (int)(m.y + raio - 4), (int)m.x, (int)(m.y + raio + 4), RED);
}

// Cache: pilha de pentes de memória com o núcleo mostrando a energia guardada
static void DesenharCache(const Inimigo *e, float escala, float t)
{
    float s = escala;
    Vector2 p = e->pos;
    bool brilho = (e->estado == 1);

    DrawEllipse((int)p.x, (int)p.y + 20, 18 * s, 5 * s, Fade(BLACK, 0.4f));

    for (int k = 0; k < 3; k++) {
        float y = p.y - 14 * s + k * 10 * s + sinf(t * 2.0f + k) * 1.5f;
        Rectangle pente = { p.x - 16 * s, y, 32 * s, 8 * s };
        DrawRectangleRec(pente, brilho ? (Color){ 120, 220, 140, 255 } : (Color){ 20, 90, 50, 255 });
        DrawRectangleLinesEx(pente, 1, (Color){ 0, 228, 48, 255 });
        for (int c = 0; c < 4; c++)
            DrawRectangle((int)(pente.x + 3 * s + c * 8 * s), (int)(y + 2 * s), (int)(5 * s), (int)(4 * s), (Color){ 10, 30, 20, 255 });
        for (int pino = 0; pino < 6; pino++)
            DrawRectangle((int)(pente.x + 2 * s + pino * 5 * s), (int)(y + 7 * s), (int)(2 * s), (int)(2 * s), GOLD);
    }

    // Núcleo: a energia guardada
    float k = e->energia / CACHE_ENERGIA_MAX;
    DrawCircleV(p, 6 * s, (Color){ 10, 30, 20, 255 });
    DrawRing(p, 6 * s, 9 * s, -90.0f, -90.0f + 360.0f * k, 16, (Color){ 0, 228, 255, 255 });

    // Recuperando: um anel verde enchendo e cruzinhas subindo
    if (e->recuperando > 0.0f) {
        float feito = 1.0f - e->recuperando / CACHE_RECUPERAR;
        DrawRing(p, e->raio + 6, e->raio + 9, -90.0f, -90.0f + 360.0f * feito, 24, LIME);
        for (int c = 0; c < 3; c++) {
            float sobe = fmodf(t * 30.0f + c * 12.0f, 30.0f);
            DrawText("+", (int)(p.x - 14 + c * 12), (int)(p.y - 22 - sobe), 12, Fade(LIME, 1.0f - sobe / 30.0f));
        }
    }
}

// Por baixo dos inimigos: escudo de rede dos Firewalls e as conexões dos Botnets
static void DesenharSinergiasChao(const Biblioteca *b, float t)
{
    Color verde = { 0, 228, 48, 255 }, ciano = { 0, 228, 255, 255 };

    for (int i = 0; i < MAX_INIMIGOS; i++) {

        const Inimigo *e = &b->ini[i];

        if (!e->ativo || e->surgindo > 0.0f)
            continue;

        if (e->tipo == INIMIGO_FIREWALL) {
            DrawCircleV(e->pos, FIREWALL_ZONA, Fade(verde, 0.05f));
            for (int k = 0; k < 12; k += 2) {
                float a1 = t * 0.3f + k * (PI / 6.0f), a2 = a1 + PI / 6.0f;
                DrawLineEx((Vector2){ e->pos.x + cosf(a1) * FIREWALL_ZONA, e->pos.y + sinf(a1) * FIREWALL_ZONA },
                           (Vector2){ e->pos.x + cosf(a2) * FIREWALL_ZONA, e->pos.y + sinf(a2) * FIREWALL_ZONA }, 2, Fade(verde, 0.35f));
            }
        }

        if (e->tipo == INIMIGO_BOTNET) {
            for (int k = 0; k < BOTNET_CONEXOES; k++) {
                if (e->conexao[k] < 0) continue;
                Vector2 alvo = b->ini[e->conexao[k]].pos;
                DrawLineEx(e->pos, alvo, 1.5f, Fade(ciano, 0.45f));
                float f = fmodf(t * 1.5f + k * 0.33f, 1.0f);         // pacote correndo pelo fio
                DrawCircleV(Vector2Lerp(e->pos, alvo, f), 2.5f, WHITE);
            }
        }

        if (e->tipo == INIMIGO_KEYLOGGER)
            DesenharMiraKeylogger(e, t);
    }
}

// Por cima: quem está protegido (hexágono) e quem está conectado (antena)
static void DesenharSinergiasMarcas(const Biblioteca *b, float t)
{
    for (int i = 0; i < MAX_INIMIGOS; i++) {

        const Inimigo *e = &b->ini[i];

        if (!e->ativo || e->surgindo > 0.0f || RogueInimigoPassageiro(e->tipo) || (e->tipo == INIMIGO_PHISHER && e->estado == 0))
            continue;           // o Phisher camuflado não ganha marca (não entrega o disfarce)

        if (e->tipo != INIMIGO_FIREWALL && RogueNaZonaFirewall(b, e))
            DrawPolyLines(e->pos, 6, e->raio + 6, t * 30.0f, Fade((Color){ 0, 228, 48, 255 }, 0.8f));

        if (e->conectado) {
            Vector2 a = { e->pos.x + e->raio, e->pos.y - e->raio };
            DrawCircleV(a, 2, (Color){ 0, 228, 255, 255 });
            DrawRing(a, 4, 5, -80.0f, -10.0f, 6, (Color){ 0, 228, 255, 255 });
            DrawRing(a, 7, 8, -80.0f, -10.0f, 6, Fade((Color){ 0, 228, 255, 255 }, 0.6f + 0.4f * sinf(t * 8.0f)));
        }
    }
}

static void DesenharNucleoCorrupcao(const Inimigo *e, float escala, float t);
static void DesenharMarcasReformulacao(const Inimigo *e, float t);

// =============================================================
// EXPANSÃO DA PROGRESSÃO: DESENHO DOS ENCONTROS ESPECIAIS
// =============================================================

// SENTINELA DE ATENÇÃO: lente (olho) num casco hexagonal, com três "cabeças de atenção" em órbita.
// A linha de atenção engrossa com o foco; travada, vira uma faixa vermelha; no disparo, um feixe branco.
static void DesenharSentinela(const Inimigo *e, float escala, float t)
{
    Color cor = DEF_INIMIGOS[INIMIGO_SENTINELA].cor;
    float r = e->raio * escala;
    bool vulneravel = (e->estado == 3 || e->distraida > 0.0f);

    // Linha de atenção (só quando vê o jogador) e a mira que fecha em volta dele
    if (e->estado == 0 && e->visao && e->foco > 0.02f) {
        DrawLineEx(e->pos, e->miraPrevista, 1.0f + 3.0f * e->foco, Fade(cor, 0.25f + 0.5f * e->foco));
        float rm = 12.0f + 30.0f * (1.0f - e->foco);
        DrawCircleLines((int)e->miraPrevista.x, (int)e->miraPrevista.y, rm, Fade(RED, 0.4f + 0.5f * e->foco));
        for (int k = 0; k < 4; k++) {
            float a = (float)k * PI / 2.0f + t;
            DrawLineEx((Vector2){ e->miraPrevista.x + cosf(a) * rm, e->miraPrevista.y + sinf(a) * rm },
                       (Vector2){ e->miraPrevista.x + cosf(a) * (rm + 6), e->miraPrevista.y + sinf(a) * (rm + 6) }, 2, Fade(RED, 0.7f));
        }
    }
    // Travada: faixa vermelha piscando no caminho do feixe (até a estante)
    if (e->estado == 1) {
        bool pisca = ((int)(t * 14.0f)) % 2 == 0;
        Vector2 n = { -e->alvo.y, e->alvo.x };
        Vector2 a1 = Vector2Add(e->pos, Vector2Scale(n, SENTINELA_FEIXE_LARGURA / 2)), a2 = Vector2Add(e->fimFeixe, Vector2Scale(n, SENTINELA_FEIXE_LARGURA / 2));
        Vector2 b1 = Vector2Subtract(e->pos, Vector2Scale(n, SENTINELA_FEIXE_LARGURA / 2)), b2 = Vector2Subtract(e->fimFeixe, Vector2Scale(n, SENTINELA_FEIXE_LARGURA / 2));
        DrawLineEx(e->pos, e->fimFeixe, SENTINELA_FEIXE_LARGURA, Fade(RED, pisca ? 0.22f : 0.10f));
        DrawLineEx(a1, a2, 1, Fade(RED, 0.8f));
        DrawLineEx(b1, b2, 1, Fade(RED, 0.8f));
    }
    // O feixe
    if (e->estado == 2) {
        DrawLineEx(e->pos, e->fimFeixe, SENTINELA_FEIXE_LARGURA + 6, Fade(cor, 0.35f));
        DrawLineEx(e->pos, e->fimFeixe, SENTINELA_FEIXE_LARGURA * 0.6f, Fade(WHITE, 0.9f));
        DrawCircleV(e->fimFeixe, 10, Fade(WHITE, 0.6f));
    }

    // Cabeças de atenção em órbita (mais rápidas quanto mais foco)
    for (int k = 0; k < 3; k++) {
        float a = t * (1.2f + 3.0f * e->foco) + (float)k * 2.0f * PI / 3.0f;
        Vector2 c = { e->pos.x + cosf(a) * (r + 12), e->pos.y + sinf(a) * (r + 12) };
        DrawTriangle((Vector2){ c.x - 5, c.y + 4 }, (Vector2){ c.x + 5, c.y + 4 }, (Vector2){ c.x, c.y - 6 }, vulneravel ? GRAY : cor);
    }

    // Casco e lente
    DrawPoly(e->pos, 6, r, t * 20.0f, (Color){ 30, 40, 60, 255 });
    DrawPolyLinesEx(e->pos, 6, r, t * 20.0f, 2, vulneravel ? GOLD : cor);
    Vector2 olhar = (e->distraida > 0.0f) ? (Vector2){ sinf(t * 6.0f), 0 } : e->alvo;
    if (e->estado == 0 && e->visao) olhar = Vector2Normalize(Vector2Subtract(e->miraPrevista, e->pos));
    if (e->estado == 3) {
        DrawLineEx((Vector2){ e->pos.x - r * 0.5f, e->pos.y }, (Vector2){ e->pos.x + r * 0.5f, e->pos.y }, 3, GRAY);   // lente fechada
    } else {
        DrawCircleV(e->pos, r * 0.55f, (Color){ 230, 245, 255, 255 });
        DrawCircleV((Vector2){ e->pos.x + olhar.x * r * 0.25f, e->pos.y + olhar.y * r * 0.25f }, r * 0.28f,
                    (e->estado == 1 || e->estado == 2) ? RED : (Color){ 20, 90, 160, 255 });
    }
    if (vulneravel) {
        DrawCircleLines((int)e->pos.x, (int)e->pos.y, r + 4 + 2 * sinf(t * 12.0f), GOLD);
        DrawText((e->distraida > 0.0f && e->estado != 3) ? "?" : "!", (int)e->pos.x - 3, (int)(e->pos.y - r - 30), 16, GOLD);
    }
}

// RETROPROPAGADOR: um "nabla" (triângulo invertido) com camadas de neurônios.
// As marcas no chão mostram para onde os golpes vão voltar.
static void DesenharRetro(const Inimigo *e, float escala, float t)
{
    Color cor = DEF_INIMIGOS[INIMIGO_RETRO].cor;
    float r = e->raio * escala;
    bool recalibrando = (e->estado == 3);

    // Marcas: de onde vieram os golpes
    for (int k = 0; k < e->numRegistros; k++) {
        Vector2 m = e->registro[k];
        float pulso = (e->estado == 1) ? 0.5f + 0.5f * sinf(t * 20.0f) : 0.6f;
        DrawLineEx((Vector2){ m.x - 7, m.y - 7 }, (Vector2){ m.x + 7, m.y + 7 }, 2, Fade(RED, pulso));
        DrawLineEx((Vector2){ m.x + 7, m.y - 7 }, (Vector2){ m.x - 7, m.y + 7 }, 2, Fade(RED, pulso));
        DrawCircleLines((int)m.x, (int)m.y, 10, Fade(cor, 0.5f * pulso));
        if (e->estado == 1)
            DrawLineEx(e->pos, m, 2, Fade(RED, 0.25f + 0.4f * pulso));     // o caminho de volta
    }

    // Corpo: nabla com três camadas de pontos ligadas
    Color corpo = recalibrando ? (Color){ 90, 70, 60, 255 } : (Color){ 70, 25, 15, 255 };
    Vector2 a = { e->pos.x - r, e->pos.y - r * 0.7f }, b2 = { e->pos.x + r, e->pos.y - r * 0.7f }, c = { e->pos.x, e->pos.y + r };
    DrawTriangle(a, c, b2, corpo);
    DrawTriangleLines(a, c, b2, recalibrando ? GRAY : cor);
    for (int camada = 0; camada < 3; camada++) {
        int n = 3 - camada;
        float y = e->pos.y - r * 0.45f + camada * r * 0.45f;
        for (int k = 0; k < n; k++) {
            float x = e->pos.x + ((float)k - (n - 1) / 2.0f) * r * 0.5f;
            float brilho = (e->estado == 2) ? 1.0f : 0.5f + 0.5f * sinf(t * 4.0f + camada + k);
            DrawCircleV((Vector2){ x, y }, 2.5f, Fade(recalibrando ? GRAY : ORANGE, brilho));
        }
    }

    // Contador de golpes guardados
    if (e->numRegistros > 0 && !recalibrando) {
        const char *txt = TextFormat("%d%s", e->numRegistros, (e->excesso > 0) ? "+" : "");
        DrawText(txt, (int)e->pos.x - MeasureText(txt, 12) / 2, (int)(e->pos.y - r - 26), 12, RED);
    }
    if (recalibrando)
        DrawCircleLines((int)e->pos.x, (int)e->pos.y, r + 5 + 2 * sinf(t * 12.0f), GOLD);
}

// JANELA DE CONTEXTO: uma janela de aplicativo com linhas de texto correndo. Com PROTEGER, escudo
// hexagonal; sem ele, a moldura racha e o núcleo aparece.
static void DesenharJanelaChefe(const Inimigo *e, float escala, float t)
{
    Color cor = DEF_INIMIGOS[INIMIGO_JANELA].cor;
    bool aberta = (e->estado == 3);
    float w = 70.0f * escala, h = 52.0f * escala;
    Vector2 p = { e->pos.x, e->pos.y + sinf(t * 1.6f) * 3.0f };
    Rectangle r = { p.x - w / 2, p.y - h / 2, w, h };

    // Telegrafia da resposta: linhas até onde ele LEMBRA que o jogador estava
    if (e->estado == 1) {
        bool pisca = ((int)(t * 12.0f)) % 2 == 0;
        if (e->carga > 0.5f) {
            DrawText("?", (int)p.x - 6, (int)(r.y - 30), 24, Fade(LIGHTGRAY, pisca ? 1.0f : 0.5f));
        } else {
            DrawLineEx(p, e->alvo, 2, Fade(GOLD, pisca ? 0.8f : 0.3f));
            DrawCircleLines((int)e->alvo.x, (int)e->alvo.y, 14, Fade(GOLD, 0.8f));
            DrawText("LEMBRA DAQUI", (int)e->alvo.x - MeasureText("LEMBRA DAQUI", 8) / 2, (int)e->alvo.y + 16, 8, GOLD);
        }
    }

    DrawEllipse((int)p.x, (int)(r.y + h + 10), w * 0.5f, 7, Fade(BLACK, 0.4f));

    if (!aberta) {
        float pulso = 0.5f + 0.5f * sinf(t * 3.0f);
        DrawPoly(p, 6, w * 0.78f, t * 10.0f, Fade((Color){ 0, 228, 255, 255 }, 0.08f + 0.06f * pulso));
        DrawPolyLinesEx(p, 6, w * 0.78f, t * 10.0f, 2, Fade((Color){ 0, 228, 255, 255 }, 0.6f));
    }

    // Corpo: a janela
    DrawRectangleRec(r, (Color){ 22, 20, 44, 255 });
    DrawRectangle((int)r.x, (int)r.y, (int)r.width, 9, aberta ? MAGENTA : cor);
    for (int k = 0; k < 3; k++) DrawCircle((int)(r.x + r.width - 8 - k * 7), (int)r.y + 4, 2, (Color){ 22, 20, 44, 255 });
    // Linhas de texto correndo. O sorteio usa a largura FIXA do corpo e só o resultado é escalado:
    // surgindo, a escala começa em 0 (a largura escalada viraria um "% 0", divisão por zero que fechava o jogo)
    for (int k = 0; k < 5; k++) {
        float fase = fmodf(t * 18.0f + k * 9.0f, fmaxf(1.0f, h - 14.0f));
        int lw = (int)((float)(12 + (int)(Ruido((unsigned int)(k * 13 + (int)(t * 2.0f))) % 42u)) * escala);
        DrawRectangle((int)r.x + 6, (int)(r.y + 12 + fase), lw, 2, Fade(cor, 0.6f));
    }
    DrawRectangleLinesEx(r, 2, aberta ? MAGENTA : cor);

    if (aberta) {
        // Rachaduras e o núcleo exposto
        DrawLineEx((Vector2){ r.x + 8, r.y + 12 }, (Vector2){ p.x, p.y }, 2, MAGENTA);
        DrawLineEx((Vector2){ r.x + r.width - 6, r.y + h - 6 }, (Vector2){ p.x + 4, p.y + 2 }, 2, MAGENTA);
        DrawCircleV(p, 10 + 3 * sinf(t * 10.0f), MAGENTA);
        DrawCircleV(p, 5, WHITE);
    }
    if (e->estado == 2)
        DrawText("RESUMINDO", (int)p.x - MeasureText("RESUMINDO", 10) / 2, (int)(r.y - 16), 10, cor);
}

// Dado dourado: o que a Janela sabe sobre o jogador (dá para destruir com um tiro)
static void DesenharToken(const Inimigo *e, float t)
{
    float s = 7.0f + sinf(t * 8.0f + e->pos.x) * 1.0f;
    DrawPoly(e->pos, 4, s + 4, 45.0f, Fade(GOLD, 0.25f));
    DrawPoly(e->pos, 4, s, 45.0f + t * 90.0f, GOLD);
    DrawCircleV(e->pos, 2, (Color){ 60, 40, 0, 255 });
}

// Barra do mini-chefe: vida e a janela de contexto (o mais antigo à esquerda)
static void DesenharBarraJanela(const Biblioteca *b, float tempo)
{
    const JanelaContexto *jc = &b->janela;
    const Inimigo *e = (jc->indice >= 0 && jc->indice < MAX_INIMIGOS) ? &b->ini[jc->indice] : NULL;
    if (e == NULL || !e->ativo || e->tipo != INIMIGO_JANELA)
        return;

    // Vida
    int x = 220, y = 42, w = 360;
    DrawRectangle(x - 4, y - 2, w + 8, 14, Fade(BLACK, 0.8f));
    DrawRectangle(x, y + 1, w, 8, (Color){ 30, 26, 50, 255 });
    DrawRectangle(x, y + 1, (int)(w * e->hp / e->hpMax), 8, (jc->vulneravel > 0.0f) ? MAGENTA : DEF_INIMIGOS[INIMIGO_JANELA].cor);
    DrawRectangle(x + (int)(w * JANELA_FASE2) - 1, y - 1, 2, 12, WHITE);
    DrawRectangle(x + (int)(w * JANELA_FASE3) - 1, y - 1, 2, 12, WHITE);
    const char *nome = TextFormat("JANELA DE CONTEXTO  F%d", jc->fase);
    int wn = MeasureText(nome, 10);
    DrawRectangle(x - wn - 16, y - 2, wn + 10, 14, Fade(BLACK, 0.8f));
    DrawText(nome, x - wn - 11, y, 10, DEF_INIMIGOS[INIMIGO_JANELA].cor);

    // Janela de contexto: capacidade em blocos
    int lado = 52, alto = 22, gap = 4;
    int total = jc->capacidade * lado + (jc->capacidade - 1) * gap;
    int x0 = LARGURA_TELA / 2 - total / 2, y0 = 60;
    DrawRectangle(x0 - 70, y0 - 4, total + 140, alto + 8, Fade(BLACK, 0.75f));
    DrawText("esquece <", x0 - 66, y0 + 6, 10, Fade(RED, 0.8f));
    DrawText("< entra", x0 + total + 8, y0 + 6, 10, GOLD);

    for (int i = 0; i < jc->capacidade; i++) {
        Rectangle s = { (float)(x0 + i * (lado + gap)), (float)y0, (float)lado, (float)alto };
        if (i >= jc->num) {
            DrawRectangleLinesEx(s, 1, Fade(GRAY, 0.4f));
            continue;
        }
        int tipo = jc->slot[i];
        Color c = (tipo == CTX_SISTEMA) ? (Color){ 0, 228, 255, 255 } : ((tipo == CTX_RELEVANTE) ? GOLD : (Color){ 110, 110, 120, 255 });
        const char *rot = (tipo == CTX_SISTEMA) ? "PROTEGER" : ((tipo == CTX_RELEVANTE) ? "DADO" : "ruído");
        bool novo = (i == jc->num - 1 && jc->entrouAnim > 0.0f);
        bool proximo = (i == 0 && jc->num == jc->capacidade);       // o próximo a ser esquecido
        DrawRectangleRec(s, Fade(c, novo ? 0.6f : 0.3f));
        DrawRectangleLinesEx(s, proximo ? 2.0f : 1.0f, proximo ? ((((int)(tempo * 8.0f)) % 2) ? RED : c) : c);
        DrawText(rot, (int)(s.x + s.width / 2) - MeasureText(rot, 10) / 2, (int)s.y + 6, 10, (tipo == CTX_RUIDO) ? LIGHTGRAY : WHITE);
    }

    // O bloco que acabou de sair (cai para fora da janela)
    if (jc->esquecidoAnim > 0.0f) {
        float k = 1.0f - jc->esquecidoAnim / 0.9f;
        int tipo = jc->esquecidoTipo;
        Color c = (tipo == CTX_SISTEMA) ? (Color){ 0, 228, 255, 255 } : ((tipo == CTX_RELEVANTE) ? GOLD : GRAY);
        Rectangle s = { (float)(x0 - lado - 10) - 20.0f * k, (float)y0 + 30.0f * k, (float)lado, (float)alto };
        DrawRectangleRec(s, Fade(c, 0.5f * (1.0f - k)));
        DrawText("ESQUECIDO", (int)s.x, (int)(s.y + alto + 2), 10, Fade(RED, 1.0f - k));
    }

    // Escudo aberto: o tempo que resta
    if (jc->vulneravel > 0.0f) {
        DrawRectangle(x0, y0 + alto + 4, total, 4, Fade(BLACK, 0.6f));
        DrawRectangle(x0, y0 + alto + 4, (int)(total * jc->vulneravel / JANELA_VULNERAVEL), 4, MAGENTA);
    }

    // Dica curta e o aviso de que os blocos são uma simplificação
    const char *dica = jc->dica;
    int wd = MeasureText(dica, 10);
    DrawRectangle(LARGURA_TELA / 2 - wd / 2 - 6, y0 + alto + 10, wd + 12, 26, Fade(BLACK, 0.6f));
    DrawText(dica, LARGURA_TELA / 2 - wd / 2, y0 + alto + 12, 10, (Color){ 200, 195, 255, 255 });
    const char *nota = "(cada bloco é uma unidade simplificada de contexto, não uma palavra)";
    DrawText(nota, LARGURA_TELA / 2 - MeasureText(nota, 8) / 2, y0 + alto + 25, 8, GRAY);
}

static void DesenharInimigo(const Inimigo *e)
{
    float escala = (e->surgindo > 0.0f) ? 1.0f - e->surgindo / TEMPO_SURGINDO : 1.0f;

    if (e->surgindo > 0.0f)
        DrawCircleLines((int)e->pos.x, (int)e->pos.y, e->raio + 12 * (1.0f - escala), Fade(MAGENTA, 0.7f));

    for (int vez = 0; vez < ((e->flash > 0.0f) ? 3 : 1); vez++) {

        // Levou dano: desenha de novo somando a cor (fica branco)
        if (vez == 1) BeginBlendMode(BLEND_ADDITIVE);

        float t = (float)GetTime();

        switch (e->tipo) {
            case INIMIGO_FRAGMENTO: DesenharFragmentoAlucinado(e, escala); break;
            case INIMIGO_GUARDIAO:  DesenharGuardiao(e, escala);           break;
            case INIMIGO_ECO:       DesenharEco(e);                        break;
            case INIMIGO_SPAMMER:   DesenharSpammer(e, escala);            break;
            case INIMIGO_SPAM:      DesenharSpam(e);                       break;
            case INIMIGO_PHISHER:
            case INIMIGO_ISCA:      DesenharPhisher(e, escala);            break;
            case INIMIGO_FIREWALL:  DesenharFirewall(e, escala, t);        break;
            case INIMIGO_OVERCLOCK: DesenharOverclock(e, escala, t);       break;
            case INIMIGO_BOTNET:    DesenharBotnet(e, escala, t);          break;
            case INIMIGO_KEYLOGGER: DesenharKeylogger(e, escala, t);       break;
            case INIMIGO_NUCLEO:    DesenharNucleoCorrupcao(e, escala, t); break;
            case INIMIGO_SENTINELA: DesenharSentinela(e, escala, t);       break;
            case INIMIGO_RETRO:     DesenharRetro(e, escala, t);           break;
            case INIMIGO_JANELA:    DesenharJanelaChefe(e, escala, t);     break;
            case INIMIGO_TOKEN:     DesenharToken(e, t);                   break;
            default:                DesenharCache(e, escala, t);           break;
        }
    }

    if (e->flash > 0.0f)
        EndBlendMode();

    if (e->selado && e->surgindo <= 0.0f)
        DesenharSelo(e, (float)GetTime());

    if (e->surgindo <= 0.0f)
        DesenharMarcasReformulacao(e, (float)GetTime());        // elite, alvo prioritário, rótulo

    // Barra de vida quando já levou dano (o Phisher camuflado não se entrega)
    bool semBarra = RogueInimigoPassageiro(e->tipo) || (e->tipo == INIMIGO_PHISHER && e->estado == 0) || e->tipo == INIMIGO_JANELA;

    if (e->hp < e->hpMax && !semBarra) {
        int w = (int)(e->raio * 2.4f);
        int x = (int)e->pos.x - w / 2, y = (int)(e->pos.y - e->raio - 12);
        DrawRectangle(x, y, w, 4, (Color){ 40, 30, 55, 255 });
        DrawRectangle(x, y, (int)(w * e->hp / e->hpMax), 4, DEF_INIMIGOS[e->tipo].cor);

        // Cache: a energia guardada (a cura que ele pode fazer) aparece embaixo
        if (e->tipo == INIMIGO_CACHE && e->energia > 0.0f)
            DrawRectangle(x, y + 5, (int)(w * e->energia / CACHE_ENERGIA_MAX), 2, (Color){ 0, 228, 255, 255 });
    }
}

// Ícone redondo com a recarga (Pulso / Esquiva)
static void DesenharRecargaRogue(int x, int y, float falta, float total, const char *tecla, Color cor, bool disponivel)
{
    DrawCircle(x, y, 14, (Color){ 20, 16, 36, 255 });

    if (falta > 0.0f)
        DrawCircleSector((Vector2){ (float)x, (float)y }, 14, -90.0f, -90.0f + 360.0f * (1.0f - falta / total), 24, Fade(cor, 0.5f));
    else
        DrawCircle(x, y, 14, Fade(cor, disponivel ? 0.8f : 0.25f));

    DrawCircleLines(x, y, 14, cor);
    DrawText(tecla, x - MeasureText(tecla, 10) / 2, y - 5, 10, WHITE);
}

// Tecla "E" sobre o que dá para usar
static void DesenharTeclaE(Vector2 c, float tempo)
{
    int y = (int)(c.y + sinf(tempo * 5.0f) * 2.0f);
    DrawRectangle((int)c.x - 9, y - 9, 18, 18, Fade(BLACK, 0.7f));
    DrawRectangleLines((int)c.x - 9, y - 9, 18, 18, GOLD);
    DrawText("E", (int)c.x - 3, y - 6, 12, GOLD);
}

// "APERTE [E] PARA ENTRAR" (ou SAIR) sobre a cabeça do Thomas, perto de uma porta
static void DesenharAvisoPorta(Vector2 pos, const char *acao, float tempo)
{
    const char *antes = "APERTE";
    const char *depois = TextFormat("PARA %s", acao);
    int wa = MeasureText(antes, 10), wd = MeasureText(depois, 10);
    int w = wa + wd + 40;
    int x = (int)Clamp(pos.x - w / 2.0f, 8.0f, (float)(LARGURA_TELA - w - 8));
    int y = (int)(pos.y - 52.0f + sinf(tempo * 4.0f) * 1.5f);

    DrawRectangle(x, y, w, 20, Fade((Color){ 16, 12, 30, 255 }, 0.85f));
    DrawRectangleLines(x, y, w, 20, Fade(GOLD, 0.7f));
    DrawText(antes, x + 8, y + 5, 10, LIGHTGRAY);
    DrawRectangle(x + 14 + wa, y + 3, 14, 14, Fade(GOLD, 0.2f));
    DrawRectangleLines(x + 14 + wa, y + 3, 14, 14, GOLD);
    DrawText("E", x + 18 + wa, y + 5, 10, GOLD);
    DrawText(depois, x + 32 + wa, y + 5, 10, WHITE);
}

// Púlpito da enciclopédia no átrio
static void DesenharPulpitoEnciclopedia(Vector2 c, float t)
{
    DrawRectangle((int)c.x - 6, (int)c.y - 4, 12, 18, (Color){ 70, 45, 30, 255 });
    DrawRectangle((int)c.x - 16, (int)c.y + 12, 32, 6, (Color){ 70, 45, 30, 255 });

    // Livro aberto brilhando
    DrawCircleV((Vector2){ c.x, c.y - 10 }, 18 + sinf(t * 2.0f) * 2, Fade((Color){ 0, 228, 255, 255 }, 0.12f));
    DesenharTrianguloB2((Vector2){ c.x, c.y - 6 }, (Vector2){ c.x - 16, c.y - 12 }, (Vector2){ c.x - 16, c.y - 2 }, (Color){ 230, 225, 200, 255 });
    DesenharTrianguloB2((Vector2){ c.x, c.y - 6 }, (Vector2){ c.x + 16, c.y - 12 }, (Vector2){ c.x + 16, c.y - 2 }, (Color){ 230, 225, 200, 255 });
    DrawRectangle((int)c.x - 16, (int)c.y - 12, 32, 10, (Color){ 230, 225, 200, 255 });
    DrawLine((int)c.x, (int)c.y - 12, (int)c.x, (int)c.y - 2, (Color){ 120, 100, 80, 255 });

    const char *nome = "ENCICLOPÉDIA";
    DrawText(nome, (int)c.x - MeasureText(nome, 10) / 2, (int)c.y + 22, 10, (Color){ 0, 228, 255, 255 });
}

// Tela do desafio educativo (por cima da sala)
static void DesenharDesafioRogue(const Biblioteca *b, float tempo)
{
    const DesafioEdu *d = &DESAFIOS[b->desafio];

    DrawRectangle(0, 0, LARGURA_TELA, ALTURA_TELA, Fade(BLACK, 0.65f));

    Rectangle painel = { 60, 70, 680, 440 };
    DrawRectangleRec(painel, (Color){ 18, 15, 30, 255 });
    DrawRectangleLinesEx(painel, 4, GOLD);

    int x = (int)painel.x + 24, y = (int)painel.y + 16;

    DrawText("GUARDIÃO SELADO // DESAFIO", x, y, 12, GOLD);
    const char *tipo = TextFormat("%s   //   %s", NOMES_TIPOS_DESAFIO[d->tipo], NOMES_CONCEITOS[d->conceito]);
    DrawText(tipo, x, y + 18, 10, Fade(SKYBLUE, 0.9f));

    // Cronômetro: barra que esvazia e passa do verde ao amarelo e ao vermelho (sem degraus)
    {
        float frac = Clamp(b->tempoRespostaSelo / TEMPO_RESPOSTA_SELO, 0.0f, 1.0f);
        Color verde = { 0, 228, 48, 255 }, amarelo = { 253, 249, 0, 255 }, vermelho = { 230, 41, 55, 255 };
        Color corT = (frac > 0.5f) ? ColorLerp(amarelo, verde, (frac - 0.5f) * 2.0f) : ColorLerp(vermelho, amarelo, frac * 2.0f);
        bool critico = frac < 0.25f && !b->respondido;
        if (critico && ((int)(tempo * 6.0f)) % 2 == 0) corT = ColorBrightness(corT, 0.35f);

        Rectangle barra = { painel.x + 404, painel.y + 18, 240, 12 };
        DrawRectangleRec(barra, (Color){ 30, 24, 48, 255 });
        DrawRectangleRec((Rectangle){ barra.x, barra.y, barra.width * frac, barra.height }, corT);
        DrawRectangleLinesEx(barra, 1, Fade(GOLD, 0.6f));
        const char *seg = TextFormat("%d s", (int)ceilf(b->tempoRespostaSelo));
        DrawText(seg, (int)(barra.x + barra.width) + 8, (int)barra.y + 1, 10, critico ? corT : LIGHTGRAY);
        DrawText("TEMPO", (int)barra.x - MeasureText("TEMPO", 10) - 8, (int)barra.y + 1, 10, Fade(GOLD, 0.8f));
    }

    char linhas[512];
    QuebrarTexto(d->enunciado, (int)painel.width - 48, 18, linhas, (int)sizeof(linhas));
    int nl = DesenharTextoLinhas(linhas, x, y + 42, 18, 24, WHITE);
    y += 42 + nl * 24 + 14;

    // Opções
    for (int i = 0; i < d->numOpcoes; i++) {

        bool marcada = (b->selecaoDesafio == i) && !b->respondido;
        bool riscada = b->opcaoRiscada[i];
        Color cor = riscada ? Fade(GRAY, 0.5f) : (marcada ? YELLOW : LIGHTGRAY);

        if (b->respondido && i == d->correta)                       cor = LIME;
        else if (b->respondido && i == b->selecaoDesafio && !b->acertouDesafio && !b->tempoEsgotadoSelo) cor = RED;

        char op[256];
        QuebrarTexto(TextFormat("%d) %s", i + 1, d->opcoes[i]), (int)painel.width - 90, 16, op, (int)sizeof(op));

        if (marcada)
            DesenharCoracao((float)x + 8, (float)y + 8, 2, RED);

        int n = DesenharTextoLinhas(op, x + 26, y, 16, 20, cor);
        if (riscada)
            DrawLine(x + 26, y + 8, x + 26 + MeasureText(op, 16), y + 8, Fade(GRAY, 0.8f));
        y += n * 20 + 8;
    }

    // Dica (Lente, Luci ou Manual)
    if (b->dicaDesafio[0] != '\0' && !b->respondido) {

        Color corDica = b->verificouDica ? (b->luciMentiu ? RED : LIME) : (b->dicaDaLuci ? (Color){ 0, 228, 255, 255 } : GOLD);
        char dica[256];
        QuebrarTexto(b->dicaDesafio, (int)painel.width - 90, 14, dica, (int)sizeof(dica));

        if (b->dicaDaLuci) {
            Vector2 luci = { (float)x + 12, (float)y + 14 };
            DesenharLuciTamanho(luci, 26.0f);
            if (b->luciMentiu)
                DrawRectangle(x + 34 + GetRandomValue(-2, 2), y + 2, 4, 14, Fade(MAGENTA, 0.6f));
        }

        DesenharTextoLinhas(dica, x + 36, y + 6, 14, 18, corDica);
    }

    // Resposta e explicação
    if (b->respondido) {

        int yr = (int)(painel.y + painel.height) - 110;
        DrawLine(x, yr - 8, (int)(painel.x + painel.width) - 24, yr - 8, Fade(GOLD, 0.4f));

        DrawText(b->acertouDesafio ? "CERTO! O selo se quebra."
                 : (b->tempoEsgotadoSelo ? "TEMPO ESGOTADO! O guardião prepara um ataque especial."
                                         : "ERRADO! O guardião prepara um ataque especial."),
                 x, yr, 18, b->acertouDesafio ? LIME : RED);

        char exp[384];
        QuebrarTexto(d->explicacao, (int)painel.width - 48, 14, exp, (int)sizeof(exp));
        DesenharTextoLinhas(exp, x, yr + 26, 14, 18, WHITE);

        if (b->dicaDaLuci && b->luciMentiu)
            DrawText("A dica da Luci estava errada. Ela também pode alucinar!", x, yr + 70, 12, MAGENTA);

        if (((int)(GetTime() * 2.0)) % 2 == 0)
            DesenharDicaAvancar((int)(painel.x + painel.width) - 90, (int)(painel.y + painel.height) - 24, 12);
        return;
    }

    // Teclas de ajuda (também clicáveis)
    const char *lente = RogueTextoLenteDesafio(b);
    const char *luci  = RogueTextoLuciDesafio(b);
    const char *manual = (b->j.itens[ITEM_MANUAL] > 0) ? TextFormat("Manual: segunda chance (x%d)", b->j.itens[ITEM_MANUAL]) : "";

    int yb = Y_AJUDA_DESAFIO;
    DesenharTextoClicavel(lente, X_LENTE_DESAFIO, yb, 12, (b->j.itens[ITEM_LENTE] > 0) ? GOLD : GRAY);
    DesenharTextoClicavel(luci, X_LUCI_DESAFIO, yb, 12, b->dicaDaLuci ? GRAY : (Color){ 0, 228, 255, 255 });
    DrawText(manual, x + 500, yb, 12, GOLD);
    DrawText("W/S, 1-4 ou MOUSE: escolher    E/ENTER ou CLIQUE: responder", x, yb + 18, 10, GRAY);
    (void)tempo;
}

// Enciclopédia aberta no átrio
static void DesenharEnciclopediaRogue(const Biblioteca *b)
{
    DrawRectangle(0, 0, LARGURA_TELA, ALTURA_TELA, Fade(BLACK, 0.6f));

    Rectangle painel = { 110, 50, 580, 490 };       // cabem os 4 conceitos
    DrawRectangleRec(painel, (Color){ 18, 15, 30, 255 });
    DrawRectangleLinesEx(painel, 4, (Color){ 0, 228, 255, 255 });

    DrawText("ENCICLOPÉDIA DA BIBLIOTECA", (int)painel.x + 24, (int)painel.y + 18, 20, (Color){ 0, 228, 255, 255 });
    DrawText("O conhecimento descoberto nunca se perde.", (int)painel.x + 24, (int)painel.y + 44, 10, LIGHTGRAY);

    for (int c = 0; c < NUM_CONCEITOS; c++) {

        int y = (int)painel.y + 76 + c * 96;
        bool sabe = (b->perm->conceitos & (1u << c)) != 0;
        bool marcado = (b->selecaoEnciclopedia == c);

        if (marcado) {
            DrawRectangle((int)painel.x + 12, y - 6, (int)painel.width - 24, 88, Fade((Color){ 0, 228, 255, 255 }, 0.10f));
            DesenharCoracao(painel.x + 30, (float)y + 8, 2, RED);
        }

        DrawText(TextFormat("CONCEITO %d: %s", c + 1, sabe ? NOMES_CONCEITOS[c] : "???"), (int)painel.x + 50, y, 16,
                 sabe ? (marcado ? YELLOW : WHITE) : GRAY);

        char resumo[256];
        QuebrarTexto(sabe ? RESUMOS_CONCEITOS[c] : "Ainda não descoberto. Procure na Biblioteca.", (int)painel.width - 90, 14,
                     resumo, (int)sizeof(resumo));
        DesenharTextoLinhas(resumo, (int)painel.x + 50, y + 24, 14, 18, sabe ? LIGHTGRAY : Fade(GRAY, 0.7f));
    }

    DesenharBotaoFechar(RET_FECHAR_ENCICLOPEDIA, (Color){ 0, 228, 255, 255 });

    const char *ajuda = "W/S ou MOUSE escolher    E / CLIQUE ler o texto completo    BACKSPACE ou X sair";
    DrawText(ajuda, LARGURA_TELA / 2 - MeasureText(ajuda, 10) / 2, (int)(painel.y + painel.height) - 20, 10, GRAY);
}

// Loja do Byteco por cima da sala: aba de itens (desta tentativa) e de melhorias (para sempre)
static void DesenharLojaRogue(const Biblioteca *b, float tempo)
{
    DrawRectangle(0, 0, LARGURA_TELA, ALTURA_TELA, Fade(BLACK, 0.6f));

    Rectangle painel = { 150, 70, 500, 440 };
    DrawRectangleRec(painel, (Color){ 18, 15, 30, 255 });
    DrawRectangleLinesEx(painel, 4, GOLD);

    DrawText("LOJA DO BYTECO", (int)painel.x + 24, (int)painel.y + 18, 22, GOLD);

    const char *fc = TextFormat("SEUS FRAGMENTOS: %d", b->perm->fragmentos);
    DrawText(fc, (int)(painel.x + painel.width) - 24 - MeasureText(fc, 14), (int)painel.y + 24, 14, (Color){ 0, 228, 255, 255 });

    // Abas
    static const char *abas[3] = { "ITENS", "MELHORIAS (sempre)", "ARMAS" };
    for (int a = 0; a < 3; a++) {
        Rectangle r = { painel.x + 24 + a * 152, painel.y + 52, 146, 24 };
        bool ativa = (b->abaLoja == a);
        DrawRectangleRec(r, ativa ? Fade(GOLD, 0.25f) : Fade(GRAY, 0.1f));
        DrawRectangleLinesEx(r, 2, ativa ? GOLD : Fade(GRAY, 0.5f));
        DrawText(abas[a], (int)(r.x + r.width / 2) - MeasureText(abas[a], 12) / 2, (int)r.y + 6, 12, ativa ? GOLD : GRAY);
    }

    int linhas = (b->abaLoja == 0) ? NUM_ITENS_LOJA : ((b->abaLoja == 1) ? NUM_MELHORIAS : ARMAS_NA_LOJA);

    for (int i = 0; i <= linhas; i++) {

        int y = (int)painel.y + 90 + i * 46;
        bool marcado = (b->selecaoLoja == i);

        if (marcado)
            DrawRectangle((int)painel.x + 12, y - 4, (int)painel.width - 24, 40, Fade(GOLD, 0.12f));

        if (i == linhas) {
            DrawText("SAIR", (int)painel.x + 60, y + 8, 16, marcado ? YELLOW : LIGHTGRAY);
            if (marcado) DesenharCoracao(painel.x + 34, (float)y + 16, 2, RED);
            continue;
        }

        if (marcado) DesenharCoracao(painel.x + 24, (float)y + 16, 2, RED);

        if (b->abaLoja == 0) {

            const DefItem *it = &ITENS[i];
            bool podePagar = b->perm->fragmentos >= it->preco;

            DesenharIconeItem((TipoItem)i, (Vector2){ painel.x + 60, (float)y + 16 }, 1.0f, tempo);
            DrawText(it->nome, (int)painel.x + 84, y, 16, marcado ? YELLOW : WHITE);
            DrawText(it->efeito, (int)painel.x + 84, y + 19, 10, LIGHTGRAY);

            const char *preco = TextFormat("%d FC", it->preco);
            DrawText(preco, (int)(painel.x + painel.width) - 30 - MeasureText(preco, 16), y + 4, 16, podePagar ? (Color){ 0, 228, 255, 255 } : RED);

            if (b->j.itens[i] > 0)
                DrawText(TextFormat("tem %d", b->j.itens[i]), (int)(painel.x + painel.width) - 92, y + 22, 10, GRAY);

        } else if (b->abaLoja == 2) {

            // Armas desta volta ao átrio (a comprada vira a arma extra desta tentativa)
            TipoArma arma = b->estoqueArmas[i];
            const DefArma *a = &DEF_ARMAS[arma];
            bool sua = (b->j.armaExtra == arma);
            bool podePagar = b->perm->fragmentos >= a->preco;

            DesenharIconeArma(arma, (Vector2){ painel.x + 60, (float)y + 16 }, 1.0f, tempo);
            DrawText(a->nome, (int)painel.x + 84, y, 16, marcado ? YELLOW : WHITE);
            DrawText(TextFormat("%s - %s", NOMES_ALCANCE[a->alcanceTipo], a->efeito), (int)painel.x + 84, y + 19, 10, LIGHTGRAY);
            DrawText(NOMES_RARIDADE[a->raridade], (int)painel.x + 94 + MeasureText(a->nome, 16), y + 4, 10, CORES_RARIDADE[a->raridade]);

            const char *preco = sua ? "SUA" : TextFormat("%d FC", a->preco);
            DrawText(preco, (int)(painel.x + painel.width) - 30 - MeasureText(preco, 16), y + 4, 16,
                     sua ? GOLD : (podePagar ? (Color){ 0, 228, 255, 255 } : RED));

        } else {

            int nivel = b->perm->melhorias[i];
            bool maximo = (nivel >= NIVEL_MAX_MELHORIA);

            DrawText(NOMES_MELHORIAS[i], (int)painel.x + 50, y, 16, marcado ? YELLOW : WHITE);
            DrawText(EFEITOS_MELHORIAS[i], (int)painel.x + 50, y + 19, 10, LIGHTGRAY);

            for (int k = 0; k < NIVEL_MAX_MELHORIA; k++) {
                Rectangle pip = { painel.x + 300 + k * 16, (float)y + 6, 12, 12 };
                if (k < nivel) DrawRectangleRec(pip, GOLD);
                DrawRectangleLinesEx(pip, 1, GOLD);
            }

            const char *preco = maximo ? "MÁXIMO" : TextFormat("%d FC", PRECO_MELHORIA[nivel]);
            bool podePagar = !maximo && b->perm->fragmentos >= PRECO_MELHORIA[nivel];
            DrawText(preco, (int)(painel.x + painel.width) - 30 - MeasureText(preco, 16), y + 4, 16,
                     maximo ? GOLD : (podePagar ? (Color){ 0, 228, 255, 255 } : RED));
        }
    }

    const char *ajuda = "A/D aba    W/S ou MOUSE escolher    E / CLIQUE comprar    BACKSPACE sair";
    DrawText(ajuda, LARGURA_TELA / 2 - MeasureText(ajuda, 10) / 2, (int)(painel.y + painel.height) - 20, 10, GRAY);
}

// O Alucinador: um núcleo de dados corrompidos com um olho que segue o jogador,
// páginas girando em volta e uma coroa de glifos. Na fase 2, o escudo de distorção.
static void DesenharAlucinador(const ChefeRogue *c, Vector2 jogador, float t)
{
    float k = (c->morrendo > 0.0f) ? c->morrendo / 1.6f : 1.0f;     // some ao ser derrotado
    float r = CHEFE_RAIO * (0.6f + 0.4f * k);
    Vector2 p = { c->pos.x, c->pos.y + sinf(t * 1.8f) * 4.0f };

    // Investida: a linha vermelha avisa para onde ele vai
    if (c->padrao == PADRAO_INVESTIDA && c->etapaInvestida == 0) {
        Vector2 fim = Vector2Add(p, Vector2Scale(c->dirInvestida, 520.0f * 0.45f));
        DrawLineEx(p, fim, 10.0f, Fade(RED, 0.18f + 0.15f * sinf(t * 20.0f)));
        DrawLineEx(p, fim, 2.0f, Fade(RED, 0.8f));
    }

    DrawEllipse((int)c->pos.x, (int)c->pos.y + (int)CHEFE_RAIO + 8, r, 8, Fade(BLACK, 0.4f));

    for (int vez = 0; vez < ((c->flash > 0.0f) ? 3 : 1); vez++) {

        if (vez == 1) BeginBlendMode(BLEND_ADDITIVE);

        // Páginas girando
        for (int i = 0; i < 6; i++) {
            float a = t * 1.3f + i * (PI / 3.0f);
            Vector2 q = { p.x + cosf(a) * (r + 26), p.y + sinf(a) * (r + 12) };
            DrawRectangle((int)q.x - 7, (int)q.y - 9, 14, 18, Fade((Color){ 230, 225, 200, 255 }, 0.8f * k));
            DrawRectangle((int)q.x - 4, (int)q.y - 4, 8, 1, Fade(MAGENTA, k));
            DrawRectangle((int)q.x - 4, (int)q.y, 8, 1, Fade(MAGENTA, k));
        }

        // Corpo em três camadas deslocadas (glitch)
        Color cores[3] = { Fade(RED, 0.45f * k), Fade(SKYBLUE, 0.45f * k), Fade((Color){ 60, 10, 80, 255 }, k) };
        float desloc[3] = { -4.0f + sinf(t * 13.0f) * 2.0f, 4.0f, 0.0f };
        for (int i = 0; i < 3; i++)
            DrawCircleV((Vector2){ p.x + desloc[i], p.y }, r, cores[i]);
        DrawCircleLines((int)p.x, (int)p.y, r, Fade(MAGENTA, k));

        // Olho que segue o jogador
        Vector2 olhar = Vector2Normalize(Vector2Subtract(jogador, p));
        DrawEllipse((int)p.x, (int)p.y - 4, r * 0.55f, r * 0.35f, Fade(WHITE, k));
        DrawCircleV((Vector2){ p.x + olhar.x * 8, p.y - 4 + olhar.y * 5 }, r * 0.22f, Fade(MAGENTA, k));
        DrawCircleV((Vector2){ p.x + olhar.x * 9, p.y - 4 + olhar.y * 6 }, r * 0.1f, Fade(BLACK, k));

        // Coroa de glifos
        const char *glifos[5] = { "?", "!", "#", "404", "01" };
        for (int i = 0; i < 5; i++) {
            int gx = (int)(p.x - 40 + i * 20), gy = (int)(p.y - r - 22 + sinf(t * 3 + i) * 3);
            DrawText(glifos[i], gx - MeasureText(glifos[i], 12) / 2, gy, 12, Fade(MAGENTA, k));
        }
    }

    if (c->flash > 0.0f)
        EndBlendMode();

    // Fase 2: escudo de distorção (fechado) ou aberto, com o tempo que falta
    if (c->fase == 2 && c->morrendo <= 0.0f) {
        if (c->janela <= 0.0f) {
            for (int i = 0; i < 6; i++) {
                float a1 = -t * 0.8f + i * (PI / 3.0f), a2 = a1 + PI / 3.0f;
                float rs = r + 30;
                DrawLineEx((Vector2){ p.x + cosf(a1) * rs, p.y + sinf(a1) * rs },
                           (Vector2){ p.x + cosf(a2) * rs, p.y + sinf(a2) * rs }, 4, Fade(MAGENTA, 0.75f));
            }
            DrawCircleV(p, r + 30, Fade(MAGENTA, 0.10f + 0.05f * sinf(t * 6.0f)));
        } else {
            float falta = c->janela / CHEFE_JANELA;
            DrawRing(p, r + 26, r + 30, -90.0f, -90.0f + 360.0f * falta, 32, Fade(GOLD, 0.9f));
        }
    }
}

// Barra de vida do Alucinador (no alto, sobre a estante)
static void DesenharBarraChefe(const ChefeRogue *c)
{
    int x = 200, y = 44, w = 400;

    DrawRectangle(x - 4, y - 2, w + 8, 16, Fade(BLACK, 0.8f));
    DrawRectangle(x, y + 2, w, 8, (Color){ 40, 20, 50, 255 });
    DrawRectangle(x, y + 2, (int)(w * c->hp / CHEFE_HP), 8, (c->fase == 1) ? MAGENTA : (c->janela > 0.0f ? GOLD : PURPLE));
    DrawRectangle(x + (int)(w * CHEFE_FASE2) - 1, y, 2, 12, WHITE);          // onde começa a fase 2
    DrawRectangleLines(x, y + 2, w, 8, GRAY);
    int wNome = MeasureText("ALUCINADOR", 10);
    DrawRectangle(x - wNome - 18, y - 2, wNome + 12, 16, Fade(BLACK, 0.8f));
    DrawText("ALUCINADOR", x - wNome - 12, y + 1, 10, MAGENTA);
}

// Faixa das afirmações (fase 2): o combate continua por baixo
static void DesenharFaixaAfirmacao(const Biblioteca *b, float tempo)
{
    const ChefeRogue *c = &b->chefe;

    if (c->fase != 2 || c->afirmacaoAtual < 0 || c->morrendo > 0.0f)
        return;

    const AfirmacaoChefe *a = &AFIRMACOES_ALUCINADOR[c->afirmacaoAtual];
    Rectangle faixa = { 100, 66, 600, 100 };

    DrawRectangleRec(faixa, Fade((Color){ 18, 15, 30, 255 }, 0.88f));
    DrawRectangleLinesEx(faixa, 2, c->mostrandoResultado ? (c->acertouAfirm ? LIME : RED) : MAGENTA);

    int x = (int)faixa.x + 12, y = (int)faixa.y + 8;

    if (c->mostrandoResultado) {
        DrawText(c->acertouAfirm ? "CERTO! O escudo caiu." : "ERRADO! Ataque especial!", x, y, 16, c->acertouAfirm ? LIME : RED);
        char exp[256];
        QuebrarTexto(a->explicacao, (int)faixa.width - 24, 14, exp, (int)sizeof(exp));
        DesenharTextoLinhas(exp, x, y + 24, 14, 18, WHITE);
        return;
    }

    if (a->antes != NULL) {
        DrawText(TextFormat("ANTES ELE DISSE: \"%s\"", a->antes), x, y, 10, LIGHTGRAY);
        y += 14;
    }

    char frase[256];
    QuebrarTexto(TextFormat("ALUCINADOR: \"%s\"", a->texto), (int)faixa.width - 24, 16, frase, (int)sizeof(frase));
    int nl = DesenharTextoLinhas(frase, x, y, 16, 19, WHITE);
    y += nl * 19 + 2;

    if (c->dicaAfirm[0] != '\0') {
        Color cor = c->verificouAfirm ? (c->luciMentiuAfirm ? RED : LIME) : (c->dicaAfirmLuci ? (Color){ 0, 228, 255, 255 } : GOLD);
        DrawText(c->dicaAfirm, x, y, 10, cor);
    }

    // Tempo e teclas
    float resta = Clamp(c->tempoAfirm / TEMPO_AFIRMACAO, 0.0f, 1.0f);
    DrawRectangle((int)faixa.x, (int)(faixa.y + faixa.height) - 4, (int)(faixa.width * resta), 4, (resta > 0.3f) ? GOLD : RED);

    const char *teclas = "C = CONFIÁVEL    F = PROBLEMÁTICA    L = Lente    H = Luci    V = verificar";
    DrawText(teclas, (int)(faixa.x + faixa.width / 2) - MeasureText(teclas, 12) / 2, (int)(faixa.y + faixa.height) - 20, 12,
             Fade(GOLD, 0.75f + 0.25f * sinf(tempo * 5.0f)));
}

// ---------- Desenho da Câmara da Inferência ----------

// Escreve uma fórmula lógica. A fonte padrão não tem os conectivos, então eles são
// desenhados com linhas:  & = ∧ (E)   | = ∨ (OU)   ~ = ¬ (NÃO)   > = → (SE...ENTÃO)   # = ↔ (SE E SÓ SE)
// Com desenhar = false, só mede. Devolve a largura em pixels.
static int DesenharLogica(const char *f, int x, int y, int tam, Color cor, bool desenhar)
{
    char trecho[128];
    int n = 0, cx = x;
    float g = fmaxf(1.0f, tam / 9.0f);

    for (const char *c = f; ; c++) {

        bool simbolo = (*c == '&' || *c == '|' || *c == '~' || *c == '>' || *c == '#');

        if (!simbolo && *c != '\0') {
            if (n < (int)sizeof(trecho) - 1) trecho[n++] = *c;
            continue;
        }

        if (n > 0) {
            trecho[n] = '\0';
            if (desenhar) DrawText(trecho, cx, y, tam, cor);
            cx += MeasureText(trecho, tam) + tam / 10;
            n = 0;
        }

        if (*c == '\0')
            break;

        float w = tam * 0.7f;
        float x0 = (float)cx, x1 = cx + w, xm = cx + w / 2.0f;
        float yt = y + tam * 0.15f, ym = y + tam * 0.5f, yb = y + tam * 0.85f, ponta = tam * 0.28f;

        if (desenhar) switch (*c) {
            case '&':
                DrawLineEx((Vector2){ x0, yb }, (Vector2){ xm, yt }, g, cor);
                DrawLineEx((Vector2){ xm, yt }, (Vector2){ x1, yb }, g, cor);
                break;
            case '|':
                DrawLineEx((Vector2){ x0, yt }, (Vector2){ xm, yb }, g, cor);
                DrawLineEx((Vector2){ xm, yb }, (Vector2){ x1, yt }, g, cor);
                break;
            case '~':
                DrawLineEx((Vector2){ x0, ym }, (Vector2){ x1, ym }, g, cor);
                DrawLineEx((Vector2){ x1, ym - g / 2 }, (Vector2){ x1, ym + tam * 0.3f }, g, cor);
                break;
            case '>':
                DrawLineEx((Vector2){ x0, ym }, (Vector2){ x1, ym }, g, cor);
                DrawLineEx((Vector2){ x1, ym }, (Vector2){ x1 - ponta, ym - ponta }, g, cor);
                DrawLineEx((Vector2){ x1, ym }, (Vector2){ x1 - ponta, ym + ponta }, g, cor);
                break;
            default:    // '#'
                DrawLineEx((Vector2){ x0, ym }, (Vector2){ x1, ym }, g, cor);
                DrawLineEx((Vector2){ x1, ym }, (Vector2){ x1 - ponta, ym - ponta }, g, cor);
                DrawLineEx((Vector2){ x1, ym }, (Vector2){ x1 - ponta, ym + ponta }, g, cor);
                DrawLineEx((Vector2){ x0, ym }, (Vector2){ x0 + ponta, ym - ponta }, g, cor);
                DrawLineEx((Vector2){ x0, ym }, (Vector2){ x0 + ponta, ym + ponta }, g, cor);
                break;
        }

        cx += (int)w + tam / 4;
    }

    return cx - x;
}

static void DesenharLogicaCentro(const char *f, int cx, int y, int tam, Color cor)
{
    DesenharLogica(f, cx - DesenharLogica(f, 0, 0, tam, cor, false) / 2, y, tam, cor, true);
}

// Disparo Dedutivo: P → Q depois do 1º acerto; P → Q e P depois do 2º
static void DesenharMarcaDedutiva(int marca, Vector2 pos, float raio)
{
    if (marca == 0)
        return;

    int y = (int)(pos.y - raio - 34);
    int w = DesenharLogica("P > Q", 0, 0, 12, GOLD, false);

    DrawRectangle((int)pos.x - w / 2 - 4, y - 2, w + 8, (marca == 2) ? 30 : 16, Fade(BLACK, 0.6f));
    DesenharLogicaCentro("P > Q", (int)pos.x, y, 12, GOLD);

    if (marca == 2)
        DrawText("P", (int)pos.x - MeasureText("P", 12) / 2, y + 14, 12, GOLD);
}

// Um fragmento de afirmação: um pergaminho holográfico com a letra
static void DesenharPecaSilogismo(Vector2 c, char letra, Color cor, float t)
{
    Vector2 p = { c.x, c.y + sinf(t * 3.0f + c.x) * 2.0f };

    DrawCircleV(p, 20, Fade(cor, 0.15f));
    DrawRectangle((int)p.x - 11, (int)p.y - 14, 22, 28, Fade((Color){ 20, 30, 60, 255 }, 0.9f));
    DrawRectangleLinesEx((Rectangle){ p.x - 11, p.y - 14, 22, 28 }, 2, cor);
    DrawRectangle((int)p.x - 13, (int)p.y - 16, 26, 4, cor);           // as pontas do pergaminho
    DrawRectangle((int)p.x - 13, (int)p.y + 12, 26, 4, cor);

    char txt[2] = { letra, '\0' };
    DrawText(txt, (int)p.x - MeasureText(txt, 18) / 2, (int)p.y - 9, 18, WHITE);
}

// Um fio do circuito em L (apagado, ou aceso com o valor V/F escrito)
static void DesenharFioLogico(Vector2 de, Vector2 ate, bool aceso, bool valor, float t)
{
    float mx = (de.x + ate.x) / 2.0f;
    Vector2 pts[4] = { de, { mx, de.y }, { mx, ate.y }, ate };
    Color cor = aceso ? (valor ? SKYBLUE : PURPLE) : Fade(GRAY, 0.35f);

    for (int i = 0; i < 3; i++)
        DrawLineEx(pts[i], pts[i + 1], aceso ? 3.0f : 2.0f, cor);

    if (!aceso)
        return;

    // Pulso de energia correndo no fio e o valor escrito no meio
    float k = fmodf(t * 0.8f, 1.0f);
    Vector2 q = (k < 0.5f) ? Vector2Lerp(pts[0], pts[1], k * 2.0f) : Vector2Lerp(pts[2], pts[3], (k - 0.5f) * 2.0f);
    DrawCircleV(q, 3, WHITE);
    DrawText(valor ? "V" : "F", (int)mx + 5, (int)((de.y + ate.y) / 2) - 5, 10, cor);
}

// O chão da câmara: diagramas geométricos girando devagar
static void DesenharChaoCamara(float t)
{
    Vector2 c = { 400, 330 };
    Color ciano = { 0, 228, 255, 255 };

    DrawCircleLines((int)c.x, (int)c.y, 190, Fade(ciano, 0.07f));
    DrawCircleLines((int)c.x, (int)c.y, 130, Fade(PURPLE, 0.08f));

    for (int i = 0; i < 3; i++) {
        float a1 = t * 0.1f + i * (2.0f * PI / 3.0f), a2 = a1 + 2.0f * PI / 3.0f;
        DrawLineEx((Vector2){ c.x + cosf(a1) * 190, c.y + sinf(a1) * 190 }, (Vector2){ c.x + cosf(a2) * 190, c.y + sinf(a2) * 190 },
                   1.0f, Fade(ciano, 0.07f));
    }
}

// Mecanismo da montagem / do sofisma: P1 → P2 → C ligados à armadura do Silogista
static void DesenharMecanismoSilogismo(const Silogista *s, float t)
{
    Color ciano = { 0, 228, 255, 255 };
    bool sofisma = (s->etapa == SIL_SOFISMA);
    Color linha = sofisma ? MAGENTA : ciano;

    for (int e = 0; e + 1 < NUM_ENCAIXES; e++) {
        Vector2 a = POS_ENCAIXES[e], b = POS_ENCAIXES[e + 1];
        Vector2 d = Vector2Normalize(Vector2Subtract(b, a));
        Vector2 ini = Vector2Add(a, Vector2Scale(d, 40)), fim = Vector2Subtract(b, Vector2Scale(d, 40));
        DrawLineEx(ini, fim, 2, Fade(linha, 0.5f));
        DrawLineEx(fim, Vector2Add(fim, Vector2Rotate(Vector2Scale(d, -8), 0.6f)), 2, Fade(linha, 0.5f));
        DrawLineEx(fim, Vector2Add(fim, Vector2Rotate(Vector2Scale(d, -8), -0.6f)), 2, Fade(linha, 0.5f));
    }

    // Energia do C até a armadura
    for (int i = 0; i < 10; i++) {
        float k = (i + fmodf(t * 2.0f, 1.0f)) / 10.0f;
        Vector2 q = Vector2Lerp(POS_ENCAIXES[ENCAIXE_C], s->pos, k);
        DrawCircleV(q, 2, Fade(linha, 0.4f));
    }

    for (int e = 0; e < NUM_ENCAIXES; e++) {

        Vector2 c = POS_ENCAIXES[e];
        bool erro = s->erro > 0.0f && ((int)(s->erro * 10.0f)) % 2 == 0;
        bool cheio = sofisma || s->encaixe[e] >= 0;
        Color cor = erro ? RED : (sofisma ? MAGENTA : (cheio ? ciano : Fade(ciano, 0.45f)));
        Rectangle r = { c.x - 36, c.y - 24, 72, 48 };

        if (sofisma && s->tremePeca[e] > 0.0f)
            r.x += (float)GetRandomValue(-2, 2);

        DrawRectangleRec(r, (Color){ 16, 20, 42, 255 });
        DrawRectangleLinesEx(r, 2, cor);
        DrawText(NOMES_ENCAIXES[e], (int)r.x + 5, (int)r.y + 4, 12, cor);

        const char *papel = PAPEIS_ENCAIXES[e];
        DrawText(papel, (int)c.x - MeasureText(papel, 10) / 2, (int)(r.y + r.height) + 4, 10, Fade(cor, 0.8f));

        if (sofisma) {
            // A peça do argumento corrompido, com a vida (some e volta se ninguém insistir)
            float k = s->hpPeca[e] / SIL_HP_PECA;
            DrawRing(c, 15, 19, -90.0f, -90.0f + 360.0f * k, 24, Fade(MAGENTA, 0.9f));
            DrawText("?", (int)c.x - 4, (int)c.y - 8, 16, WHITE);
            if (s->blindagem > 0.0f)
                DrawPolyLinesEx(c, 6, 30, t * 40.0f, 2, Fade(ciano, 0.8f));
        }
        else if (s->encaixe[e] >= 0) {
            char txt[2] = { s->letraPeca[s->encaixe[e]], '\0' };
            DrawText(txt, (int)c.x - MeasureText(txt, 22) / 2, (int)c.y - 10, 22, WHITE);
        }
        else {
            DrawCircleLines((int)c.x, (int)c.y + 2, 9 + sinf(t * 4.0f + e) * 2.0f, Fade(cor, 0.6f));
        }
    }
}

// Circuito proposicional no chão: terminais p e q, portas e núcleo
static void DesenharCircuito(const Silogista *s, float t)
{
    const CircuitoDef *c = &CIRCUITO_SILOGISTA;
    Color ciano = { 0, 228, 255, 255 };
    bool final = (s->etapa == SIL_VULNERAVEL);

    // Fios: cada entrada de cada porta, e a última porta até o núcleo
    for (int k = 0; k < c->numPortas; k++) {
        const PortaLogica *p = &c->porta[k];
        int n = EntradasPorta(p);
        for (int i = 0; i < n; i++) {
            bool valor = false;
            bool aceso = SinalCircuito(s, p->entrada[i], &valor) || final;
            Vector2 de = SilPosElemento(p->entrada[i]);
            de.x += 24;
            Vector2 ate = { p->pos.x - 24, p->pos.y + ((n == 2) ? (i == 0 ? -10.0f : 10.0f) : 0.0f) };
            DesenharFioLogico(de, ate, aceso, valor, t);
        }
    }

    const PortaLogica *ultima = &c->porta[c->numPortas - 1];
    bool saiu = s->ativada[c->numPortas - 1] || final;
    DesenharFioLogico((Vector2){ ultima->pos.x + 24, ultima->pos.y }, (Vector2){ c->posNucleo.x - 34, c->posNucleo.y },
                      saiu, s->saida[c->numPortas - 1], t);

    // Terminais p e q (a letra V/F acompanha a cor)
    for (int e = 0; e < 2; e++) {
        Vector2 pos = c->posTerminal[e];
        bool v = s->valor[e];
        Color cor = v ? SKYBLUE : PURPLE;
        bool erro = s->erroElemento[e] > 0.0f;
        Rectangle r = { pos.x - 22, pos.y - 22, 44, 44 };

        DrawRectangleRec(r, v ? (Color){ 20, 50, 100, 255 } : (Color){ 55, 20, 70, 255 });
        DrawRectangleLinesEx(r, 3, erro ? RED : cor);
        DrawText(v ? "V" : "F", (int)pos.x - MeasureText(v ? "V" : "F", 22) / 2, (int)pos.y - 10, 22, WHITE);
        DrawText((e == 0) ? "p" : "q", (int)r.x - 14, (int)pos.y - 10, 20, cor);
        if (s->rodada == 1 && !final)
            DrawText("FIXO", (int)pos.x - MeasureText("FIXO", 10) / 2, (int)(r.y + r.height) + 4, 10, GRAY);
        else if (!final)
            DrawText("ATIRE: V/F", (int)pos.x - MeasureText("ATIRE: V/F", 10) / 2, (int)(r.y + r.height) + 4, 10, Fade(cor, 0.8f));
    }

    // Portas lógicas
    for (int k = 0; k < c->numPortas; k++) {
        const PortaLogica *p = &c->porta[k];
        bool ativa = s->ativada[k] || final;
        bool erro = s->erroElemento[2 + k] > 0.0f;
        Color cor = erro ? RED : (ativa ? (s->saida[k] ? SKYBLUE : PURPLE) : Fade(LIGHTGRAY, 0.7f));

        DrawCircleV(p->pos, 24, (Color){ 16, 20, 42, 255 });
        if (ativa) DrawCircleV(p->pos, 24, Fade(cor, 0.2f));
        DrawCircleLines((int)p->pos.x, (int)p->pos.y, 24, cor);
        DrawCircleLines((int)p->pos.x, (int)p->pos.y, 22, cor);
        DesenharLogicaCentro(SIMBOLOS_OPERADORES[p->op], (int)p->pos.x, (int)p->pos.y - 11, 22, WHITE);

        const char *nome = NOMES_OPERADORES[p->op];
        DrawText(nome, (int)p->pos.x - MeasureText(nome, 10) / 2, (int)p->pos.y + 28, 10, cor);

        // Saída: ? até a porta ser ativada
        const char *saida = ativa ? (s->saida[k] ? "V" : "F") : "?";
        DrawText(saida, (int)p->pos.x + 28, (int)p->pos.y - 22, 14, ativa ? cor : GRAY);
    }

    // Núcleo de saída
    Vector2 n = c->posNucleo;
    bool energia = s->nucleo > 0.0f || final;
    float pulso = 0.5f + 0.5f * sinf(t * 6.0f);

    if (energia) DrawCircleV(n, 40 + pulso * 6, Fade(ciano, 0.15f));
    DrawCircleV(n, 32, (Color){ 16, 20, 42, 255 });
    DrawPolyLinesEx(n, 8, 32, t * 20.0f, 3, (s->erro > 0.0f && !final) ? RED : (energia ? ciano : Fade(ciano, 0.4f)));

    const char *dentro = energia ? (s->saida[c->numPortas - 1] ? "V" : "F") : "?";
    DrawText(dentro, (int)n.x - MeasureText(dentro, 26) / 2, (int)n.y - 12, 26, energia ? WHITE : GRAY);
    DrawText("NÚCLEO", (int)n.x - MeasureText("NÚCLEO", 10) / 2, (int)n.y + 38, 10, ciano);

    if (!final) {
        const char *exige = TextFormat("EXIGE: %s", s->exigido ? "V" : "F");
        DrawText(exige, (int)n.x - MeasureText(exige, 12) / 2, (int)n.y - 52, 12, GOLD);
    }

    // Corte do Silogista: o elemento fica travado (X e o tempo que falta)
    for (int e = 0; e < SilNumElementos(); e++) {
        if (s->travado[e] <= 0.0f) continue;
        Vector2 q = SilPosElemento(e);
        DrawLineEx((Vector2){ q.x - 18, q.y - 18 }, (Vector2){ q.x + 18, q.y + 18 }, 4, Fade(RED, 0.85f));
        DrawLineEx((Vector2){ q.x + 18, q.y - 18 }, (Vector2){ q.x - 18, q.y + 18 }, 4, Fade(RED, 0.85f));
        DrawRing(q, 28, 31, -90.0f, -90.0f + 360.0f * s->travado[e] / SIL_CORTE_DURACAO, 24, Fade(PURPLE, 0.9f));
    }
}

// Avisos dos ataques (desenhados antes, embaixo de tudo) e as zonas ativas
static void DesenharAtaquesSilogista(const Silogista *s, float t)
{
    for (int i = 0; i < MAX_ATAQUES_SIL; i++) {

        const AtaqueSil *a = &s->atq[i];

        if (!a->ativo)
            continue;

        float k = (a->aviso > 0.0f) ? 1.0f - a->aviso / SIL_AVISO : 1.0f;     // 0 = começou a avisar, 1 = vai disparar
        float pisca = 0.5f + 0.5f * sinf(t * 18.0f);

        switch (a->tipo) {

            case ATQ_LINHAS: {
                if (a->aviso <= 0.0f) break;
                // As balas que vão sair e o corredor verde da brecha
                for (int b = 0; b < SilBalasLinha(a); b++)
                    if (b < a->brecha || b >= a->brecha + SIL_LINHA_BRECHA) {
                        Vector2 q = SilPontoLinha(a, b);
                        DrawCircleLines((int)q.x, (int)q.y, 6, Fade(ORANGE, 0.4f + 0.5f * k));
                        DrawLineEx(q, Vector2Add(q, Vector2Scale(a->dir, 14)), 2, Fade(ORANGE, 0.5f * k));
                    }
                Vector2 b0 = SilPontoLinha(a, a->brecha), b1 = SilPontoLinha(a, a->brecha + SIL_LINHA_BRECHA - 1);
                float meia = SIL_LINHA_ESPACO / 2.0f;
                Rectangle brecha = (a->dir.y != 0.0f)
                    ? (Rectangle){ b0.x - meia, ARENA_ROGUE.y, b1.x - b0.x + 2 * meia, ARENA_ROGUE.height }
                    : (Rectangle){ ARENA_ROGUE.x, b0.y - meia, ARENA_ROGUE.width, b1.y - b0.y + 2 * meia };
                DrawRectangleRec(brecha, Fade(GREEN, 0.08f + 0.06f * pisca));
            } break;

            case ATQ_ZONA:
                if (a->aviso > 0.0f) {
                    DrawCircleV(a->pos, SIL_ZONA_RAIO * k, Fade(RED, 0.18f));
                    DrawCircleLines((int)a->pos.x, (int)a->pos.y, SIL_ZONA_RAIO, Fade(RED, 0.5f + 0.4f * pisca));
                } else {
                    DrawCircleV(a->pos, SIL_ZONA_RAIO, Fade(RED, 0.30f + 0.1f * pisca));
                    DrawPolyLinesEx(a->pos, 6, SIL_ZONA_RAIO, t * 60.0f, 3, Fade(MAGENTA, 0.9f));
                    DrawText("BLOQUEIO", (int)a->pos.x - MeasureText("BLOQUEIO", 10) / 2, (int)a->pos.y - 5, 10, WHITE);
                }
                break;

            case ATQ_REFUTACAO:
                if (a->aviso > 0.0f) {
                    Vector2 fim = Vector2Add(s->pos, Vector2Scale(a->dir, 800.0f));
                    DrawLineEx(s->pos, fim, 12.0f, Fade(RED, 0.10f + 0.12f * pisca));
                    DrawLineEx(s->pos, fim, 1.5f, Fade(RED, 0.8f));
                }
                break;

            case ATQ_CORTE: {
                Vector2 alvo = SilPosElemento(a->alvo);
                DrawLineEx(s->pos, alvo, 2.0f + 3.0f * k, Fade(PURPLE, 0.3f + 0.5f * pisca));
                DrawCircleLines((int)alvo.x, (int)alvo.y, 34 - 8 * k, Fade(RED, 0.8f));
            } break;

            default:    // ATQ_ANEL: um anel se fechando no Silogista
                if (a->aviso > 0.0f)
                    DrawCircleLines((int)s->pos.x, (int)s->pos.y, SIL_RAIO + 70.0f * (a->aviso / 0.7f), Fade(ORANGE, 0.9f));
                break;
        }
    }
}

// O Silogista: um sábio mecânico (cabeça hexagonal com visor, manto, livro holográfico)
// com os conectivos lógicos orbitando e a armadura lógica (uma camada por puzzle que falta)
static void DesenharSilogista(const Silogista *s, Vector2 jogador, float t)
{
    float k = (s->morrendo > 0.0f) ? s->morrendo / 1.6f : 1.0f;
    Vector2 p = { s->pos.x, s->pos.y + sinf(t * 1.6f) * 4.0f };
    Color ciano = { 0, 228, 255, 255 }, lilas = { 170, 140, 255, 255 };

    DrawEllipse((int)s->pos.x, (int)s->pos.y + (int)SIL_RAIO + 10, 30 * k, 8, Fade(BLACK, 0.4f));

    // Diagrama atrás: triângulo dentro de um círculo
    DrawCircleLines((int)p.x, (int)p.y, 50, Fade(ciano, 0.25f * k));
    for (int i = 0; i < 3; i++) {
        float a1 = -t * 0.5f + i * (2.0f * PI / 3.0f), a2 = a1 + 2.0f * PI / 3.0f;
        DrawLineEx((Vector2){ p.x + cosf(a1) * 50, p.y + sinf(a1) * 50 }, (Vector2){ p.x + cosf(a2) * 50, p.y + sinf(a2) * 50 },
                   1.5f, Fade(lilas, 0.35f * k));
    }

    for (int vez = 0; vez < ((s->flash > 0.0f) ? 3 : 1); vez++) {

        if (vez == 1) BeginBlendMode(BLEND_ADDITIVE);

        // Manto
        Color manto = Fade((Color){ 40, 40, 110, 255 }, k);
        DesenharTrianguloB2((Vector2){ p.x - 14, p.y - 6 }, (Vector2){ p.x + 14, p.y - 6 }, (Vector2){ p.x - 28, p.y + 34 }, manto);
        DesenharTrianguloB2((Vector2){ p.x + 14, p.y - 6 }, (Vector2){ p.x + 28, p.y + 34 }, (Vector2){ p.x - 28, p.y + 34 }, manto);
        DrawLineEx((Vector2){ p.x - 28, p.y + 34 }, (Vector2){ p.x + 28, p.y + 34 }, 2, Fade(ciano, k));
        DrawLineEx((Vector2){ p.x, p.y - 6 }, (Vector2){ p.x, p.y + 34 }, 1, Fade(lilas, 0.7f * k));

        // Livro holográfico aberto na frente
        Color pagina = Fade(ciano, 0.45f * k);
        DesenharTrianguloB2((Vector2){ p.x, p.y + 14 }, (Vector2){ p.x - 18, p.y + 8 }, (Vector2){ p.x - 18, p.y + 20 }, pagina);
        DesenharTrianguloB2((Vector2){ p.x, p.y + 14 }, (Vector2){ p.x + 18, p.y + 8 }, (Vector2){ p.x + 18, p.y + 20 }, pagina);
        DrawRectangle((int)p.x - 18, (int)p.y + 14, 36, 8, pagina);

        // Cabeça: hexágono com um visor que segue o jogador
        Vector2 cab = { p.x, p.y - 22 };
        Vector2 olhar = Vector2Normalize(Vector2Subtract(jogador, cab));
        DrawPoly(cab, 6, 17, 0, Fade((Color){ 25, 25, 60, 255 }, k));
        DrawPolyLinesEx(cab, 6, 17, 0, 2, Fade(ciano, k));
        DrawRectangle((int)(cab.x - 10 + olhar.x * 2), (int)(cab.y - 4 + olhar.y * 2), 20, 6, Fade(ciano, k));

        // Barba de circuitos
        for (int i = 0; i < 3; i++) {
            float bx = cab.x - 6 + i * 6;
            DrawLine((int)bx, (int)cab.y + 8, (int)bx, (int)cab.y + 14 + (i % 2) * 5, Fade(lilas, k));
            DrawCircle((int)bx, (int)cab.y + 15 + (i % 2) * 5, 1.5f, Fade(lilas, k));
        }

        // Conectivos orbitando
        static const char *simbolos[5] = { "~", "&", "|", ">", "#" };
        for (int i = 0; i < 5; i++) {
            float a = t * 0.9f + i * (2.0f * PI / 5.0f);
            Vector2 q = { p.x + cosf(a) * 56, p.y - 6 + sinf(a) * 32 };
            DesenharLogicaCentro(simbolos[i], (int)q.x, (int)q.y - 7, 14, Fade((i % 2) ? ciano : lilas, k));
        }
    }

    if (s->flash > 0.0f)
        EndBlendMode();

    // Armadura lógica
    static const Color camadas[3] = { { 0, 228, 255, 255 }, { 102, 191, 255, 255 }, { 170, 140, 255, 255 } };
    int restam = 3 - (int)s->etapa;

    for (int c = 0; c < restam && s->morrendo <= 0.0f; c++)
        DrawPolyLinesEx(p, 6, SIL_RAIO + 12 + c * 8, t * ((c % 2) ? -35.0f : 35.0f), 2, Fade(camadas[c], 0.75f));
}

// Barra de vida e as camadas da armadura lógica
static void DesenharBarraSilogista(const Silogista *s)
{
    int x = 200, y = 44, w = 400;
    int camadas = 3 - (int)s->etapa;

    DrawRectangle(x - 4, y - 2, w + 8, 16, Fade(BLACK, 0.8f));
    DrawRectangle(x, y + 2, w, 8, (Color){ 30, 25, 60, 255 });
    DrawRectangle(x, y + 2, (int)(w * s->hp / SIL_HP), 8, (camadas > 0) ? Fade((Color){ 120, 110, 255, 255 }, 0.45f) : (Color){ 120, 110, 255, 255 });
    DrawRectangleLines(x, y + 2, w, 8, GRAY);

    int wNome = MeasureText("O SILOGISTA", 10);
    DrawRectangle(x - wNome - 18, y - 2, wNome + 12, 16, Fade(BLACK, 0.8f));
    DrawText("O SILOGISTA", x - wNome - 12, y + 1, 10, (Color){ 170, 140, 255, 255 });

    // Uma casinha por camada da armadura (cheia = ainda protege)
    int wArm = MeasureText("ARMADURA", 10);
    DrawRectangle(x + w + 8, y - 2, wArm + 38, 16, Fade(BLACK, 0.8f));
    DrawText("ARMADURA", x + w + 12, y + 1, 10, LIGHTGRAY);
    for (int c = 0; c < 3; c++) {
        Rectangle r = { (float)(x + w + 18 + wArm + c * 8), (float)y + 1, 6, 10 };
        if (c < camadas) DrawRectangleRec(r, (Color){ 0, 228, 255, 255 });
        DrawRectangleLinesEx(r, 1, (Color){ 0, 228, 255, 255 });
    }
}

// Faixa no alto: o que está em jogo em cada puzzle (os textos não cabem na arena)
static void DesenharFaixaSilogista(const Biblioteca *b, float tempo)
{
    const Silogista *s = &b->silogista;
    Color ciano = { 0, 228, 255, 255 };

    if (s->etapa == SIL_VULNERAVEL || s->morrendo > 0.0f)
        return;

    // Versão bullet-hell: as premissas da rodada e a prova (curtas: o texto não voa pela tela)
    if (s->modoBH) {
        const RodadaSilogistaBH *r = &RODADAS_SILOGISTA_BH[(s->bh.rodada < 3) ? s->bh.rodada : 2];
        Rectangle faixa = { 60, 64, 680, 64 };
        DrawRectangleRec(faixa, Fade((Color){ 18, 15, 30, 255 }, 0.88f));
        DrawRectangleLinesEx(faixa, 2, ciano);

        int x = (int)faixa.x + 10, y = (int)faixa.y + 6;
        DrawText(TextFormat("RODADA %d/3  //  %s", s->bh.rodada + 1, r->titulo), x, y, 10, ciano);

        char linhas[320];
        QuebrarTexto(r->premissas, (int)faixa.width - 20, 12, linhas, (int)sizeof(linhas));
        DesenharTextoLinhas(linhas, x, y + 14, 12, 14, WHITE);
        DrawText(r->pergunta, x, y + 44, 10, Fade(GOLD, 0.75f + 0.25f * sinf(tempo * 5.0f)));

        int px = (int)(faixa.x + faixa.width) - 90;
        DrawText("PROVA", px - 44, y, 10, LIGHTGRAY);
        for (int c = 0; c < SIL_BH_META; c++) {
            Rectangle pip = { (float)(px + c * 14), (float)y, 10, 10 };
            if (c < s->bh.acertosRodada) DrawRectangleRec(pip, LIME);
            DrawRectangleLinesEx(pip, 1, LIME);
        }
        return;
    }

    Rectangle faixa = { 60, 64, 680, 64 };
    DrawRectangleRec(faixa, Fade((Color){ 18, 15, 30, 255 }, 0.88f));
    DrawRectangleLinesEx(faixa, 2, (s->etapa == SIL_SOFISMA) ? MAGENTA : ciano);

    int x = (int)faixa.x + 10, y = (int)faixa.y + 6;

    if (s->etapa == SIL_MONTAGEM) {

        DrawText("MONTE O SILOGISMO:   P1 = regra geral    P2 = caso particular    C = a conclusão que decorre das duas", x, y, 10, ciano);

        // Em ordem de letra (as letras foram sorteadas)
        for (char letra = 'X'; letra <= 'Z'; letra++) {
            int k = 0;
            while (k < NUM_ENCAIXES - 1 && s->letraPeca[k] != letra) k++;

            int onde = -1;
            for (int e = 0; e < NUM_ENCAIXES; e++)
                if (s->encaixe[e] == k) onde = e;

            int yy = y + 14 + (letra - 'X') * 15;
            Color cor = (s->carregando == k) ? YELLOW : ((onde >= 0) ? Fade(LIGHTGRAY, 0.6f) : WHITE);
            const char *txt = TextFormat("%c:  %s", letra, SILOGISMO_VALIDO.frase[k]);
            DrawText(txt, x, yy, 12, cor);

            int xr = x + MeasureText(txt, 12) + 10;
            if (s->carregando == k) DrawText("(na sua mão)", xr, yy, 12, YELLOW);
            else if (onde >= 0)     DrawText(TextFormat("(em %s)", NOMES_ENCAIXES[onde]), xr, yy, 12, ciano);
        }
    }
    else if (s->etapa == SIL_SOFISMA) {

        DrawText("ARGUMENTO DO SILOGISTA (ele jura que é válido). Destrua a tiros a peça que não se sustenta:", x, y, 10, MAGENTA);

        for (int e = 0; e < NUM_ENCAIXES; e++)
            DrawText(TextFormat("%s:  %s", NOMES_ENCAIXES[e], SOFISMA_SILOGISTA.frase[e]), x, y + 14 + e * 15, 12, WHITE);

        if (s->blindagem > 0.0f)
            DrawText("BLINDADO", (int)(faixa.x + faixa.width) - 70, y, 10, ciano);
    }
    else {

        const CircuitoDef *c = &CIRCUITO_SILOGISTA;

        DrawText(TextFormat("CIRCUITO PROPOSICIONAL  //  RODADA %d DE 2", s->rodada), x, y, 10, ciano);
        DesenharLogicaCentro(c->expressao, (int)(faixa.x + faixa.width / 2), y + 12, 22, WHITE);

        const char *exige = TextFormat("NÚCLEO EXIGE: %s", s->exigido ? "V" : "F");
        DrawText(exige, (int)(faixa.x + faixa.width) - 16 - MeasureText(exige, 14), y + 16, 14,
                 Fade(GOLD, 0.75f + 0.25f * sinf(tempo * 5.0f)));

        DesenharLogica("& = E     | = OU     ~ = NÃO", x, y + 40, 12, LIGHTGRAY, true);

        const char *nota = (s->rodada == 1) ? "p e q fixos: ative as portas na ordem certa (tiros)"
                                            : "atire em p e q para trocar V/F; depois ative as portas";
        DrawText(nota, (int)(faixa.x + faixa.width) - 16 - MeasureText(nota, 10), y + 42, 10, ciano);
    }
}

// Ícone de cada arma (pedestal, loja e HUD)
static void DesenharIconeArma(TipoArma arma, Vector2 c, float e, float tempo)
{
    Color cor = DEF_ARMAS[arma].cor;
    Color metal = { 60, 70, 100, 255 };

    switch (arma) {

        case ARMA_VETOR:            // fuzil comprido com luneta
            DrawRectangle((int)(c.x - 13 * e), (int)(c.y - 1 * e), (int)(26 * e), (int)(3 * e), metal);
            DrawRectangle((int)(c.x - 13 * e), (int)(c.y + 1 * e), (int)(6 * e), (int)(6 * e), metal);
            DrawRectangle((int)(c.x - 4 * e), (int)(c.y - 5 * e), (int)(9 * e), (int)(3 * e), cor);
            DrawLineEx((Vector2){ c.x + 13 * e, c.y }, (Vector2){ c.x + 16 * e, c.y }, 2, Fade(cor, 0.5f + 0.5f * sinf(tempo * 6.0f)));
            break;

        case ARMA_ROTEADOR:         // roteador com antenas e um pacote fazendo curva
            DrawRectangle((int)(c.x - 10 * e), (int)(c.y + 1 * e), (int)(20 * e), (int)(7 * e), metal);
            DrawLineEx((Vector2){ c.x - 6 * e, c.y + 1 * e }, (Vector2){ c.x - 9 * e, c.y - 8 * e }, 2, LIGHTGRAY);
            DrawLineEx((Vector2){ c.x + 6 * e, c.y + 1 * e }, (Vector2){ c.x + 9 * e, c.y - 8 * e }, 2, LIGHTGRAY);
            DrawRing((Vector2){ c.x, c.y - 2 * e }, 6 * e, 7.5f * e, 200.0f, 340.0f, 8, cor);
            break;

        case ARMA_FLUXO:            // três canos e a rajada
            for (int k = -1; k <= 1; k++)
                DrawRectangle((int)(c.x - 10 * e), (int)(c.y + k * 4 * e - 1), (int)(16 * e), (int)(2 * e), metal);
            for (int k = 0; k < 3; k++)
                DrawCircle((int)(c.x + 9 * e + k * 4 * e), (int)c.y, 1.5f * e, cor);
            break;

        case ARMA_ORBE:             // esfera com um anel
            DrawCircleV(c, 7 * e, Fade(cor, 0.5f));
            DrawCircleV(c, 4 * e, cor);
            DrawRing(c, 9 * e, 10.5f * e, tempo * 90.0f, tempo * 90.0f + 270.0f, 12, cor);
            break;

        case ARMA_FRAGMENTADORA:    // cone de estilhaços
            DrawRectangle((int)(c.x - 12 * e), (int)(c.y - 3 * e), (int)(10 * e), (int)(6 * e), metal);
            for (int k = -2; k <= 2; k++)
                DrawLineEx((Vector2){ c.x, c.y }, (Vector2){ c.x + 13 * e, c.y + k * 4 * e }, 1.5f, cor);
            break;

        case ARMA_PULSO_FW:         // hexágonos concêntricos
            DrawPolyLinesEx(c, 6, 10 * e, tempo * 30.0f, 2, cor);
            DrawPolyLinesEx(c, 6, 5 * e, -tempo * 30.0f, 2, cor);
            break;

        default:                    // Disparador de Dados
            DrawRectangle((int)(c.x - 9 * e), (int)(c.y - 2 * e), (int)(16 * e), (int)(4 * e), (Color){ 30, 60, 120, 255 });
            DrawRectangle((int)(c.x - 9 * e), (int)(c.y + 1 * e), (int)(5 * e), (int)(6 * e), (Color){ 30, 60, 120, 255 });
            DrawCircleV((Vector2){ c.x + 9 * e, c.y }, 2 * e, cor);
            break;
    }
}

// Projétil do jogador conforme a arma (cada um com a sua forma)
static void DesenharProjetilJogador(const Projetil *p, float tempo)
{
    Vector2 d = (Vector2Length(p->vel) > 0.01f) ? Vector2Normalize(p->vel) : (Vector2){ 1, 0 };

    if (p->secundario) {
        // Fragmento ou pacote do Botnet Reverso: losango verde-limão
        DrawPoly(p->pos, 4, p->raio + 2, tempo * 400.0f, Fade(LIME, 0.5f));
        DrawPoly(p->pos, 4, p->raio, tempo * 400.0f, LIME);
        return;
    }

    Color cor = DEF_ARMAS[p->arma].cor;

    switch (p->arma) {
        case ARMA_VETOR:            // feixe comprido
            DrawLineEx(Vector2Subtract(p->pos, Vector2Scale(d, 26)), p->pos, 6, Fade(SKYBLUE, 0.4f));
            DrawLineEx(Vector2Subtract(p->pos, Vector2Scale(d, 22)), p->pos, 2.5f, WHITE);
            break;
        case ARMA_ROTEADOR:         // pacote (losango) com rastro
            DrawLineEx(Vector2Subtract(p->pos, Vector2Scale(d, 12)), p->pos, 2, Fade(cor, 0.4f));
            DrawPoly(p->pos, 4, p->raio + 1, atan2f(d.y, d.x) * RAD2DEG, cor);
            break;
        case ARMA_FLUXO:            // gotinhas amarelas
            DrawCircleV(p->pos, p->raio, cor);
            break;
        case ARMA_ORBE:             // esfera pulsando
            DrawCircleV(p->pos, p->raio + 4 + sinf(tempo * 20.0f) * 1.5f, Fade(cor, 0.3f));
            DrawCircleV(p->pos, p->raio, cor);
            DrawCircleLines((int)p->pos.x, (int)p->pos.y, p->raio + 2, WHITE);
            break;
        case ARMA_FRAGMENTADORA:    // estilhaço curto
            DrawLineEx(Vector2Subtract(p->pos, Vector2Scale(d, 6)), Vector2Add(p->pos, Vector2Scale(d, 3)), 3, cor);
            break;
        default:
            DrawCircleV(p->pos, p->raio + 3, Fade(SKYBLUE, 0.3f));
            DrawCircleV(p->pos, p->raio, (Color){ 180, 240, 255, 255 });
            break;
    }
}

// Efeitos em volta do jogador: escudo, campo de latência, Overclock, carga do Vetor e calor do Fluxo
static void DesenharEfeitosJogador(const Biblioteca *b, float tempo)
{
    const JogadorRogue *j = &b->j;

    if (j->efeito[EFEITO_LATENCIA] > 0.0f) {
        DrawCircleV(j->pos, LATENCIA_RAIO, Fade(PURPLE, 0.06f));
        for (int k = 0; k < 12; k++) {                 // marcas de relógio girando devagar
            float a = tempo * 0.5f + k * (PI / 6.0f);
            DrawLineEx((Vector2){ j->pos.x + cosf(a) * (LATENCIA_RAIO - 8), j->pos.y + sinf(a) * (LATENCIA_RAIO - 8) },
                       (Vector2){ j->pos.x + cosf(a) * LATENCIA_RAIO, j->pos.y + sinf(a) * LATENCIA_RAIO }, 2, Fade(PURPLE, 0.6f));
        }
    }

    if (j->efeito[EFEITO_ESCUDO] > 0.0f) {
        float pisca = (j->efeito[EFEITO_ESCUDO] < 2.0f && ((int)(tempo * 8.0f)) % 2 == 0) ? 0.3f : 0.9f;   // acabando: pisca
        DrawPolyLinesEx(j->pos, 6, 24, tempo * 60.0f, 3, Fade((Color){ 0, 228, 48, 255 }, pisca));
        DrawCircleV(j->pos, 24, Fade((Color){ 0, 228, 48, 255 }, 0.08f));
    }

    if (j->efeito[EFEITO_OVERCLOCK] > 0.0f)
        DrawRing(j->pos, 17, 19, tempo * 400.0f, tempo * 400.0f + 120.0f, 10, ORANGE);

    if (j->carga > 0.0f) {
        // Vetor: o anel enche e a mira laser cresce com a carga
        float k = j->carga / VETOR_CARGA_MAX;
        DrawRing(j->pos, 20, 23, -90.0f, -90.0f + 360.0f * k, 24, (k >= 1.0f) ? WHITE : SKYBLUE);
        DrawLineEx(j->pos, Vector2Add(j->pos, Vector2Scale(j->mira, 120.0f + 380.0f * k)), 1.0f, Fade(SKYBLUE, 0.3f + 0.4f * k));
    }

    if (j->calor > 0.0f) {
        // Fluxo: barrinha de calor embaixo do jogador
        int x = (int)j->pos.x - 16, y = (int)j->pos.y + 24;
        DrawRectangle(x, y, 32, 4, (Color){ 40, 30, 20, 255 });
        DrawRectangle(x, y, (int)(32 * j->calor), 4, j->superaquecida ? RED : ColorLerp(YELLOW, ORANGE, j->calor));
        if (j->superaquecida && ((int)(tempo * 6.0f)) % 2 == 0)
            DrawText("QUENTE", (int)j->pos.x - MeasureText("QUENTE", 8) / 2, y + 6, 8, RED);
    }
}

// Proxy-Isca: um holograma em arame (bem diferente do jogador)
static void DesenharProxy(const JogadorRogue *j, float tempo)
{
    if (j->efeito[EFEITO_PROXY] <= 0.0f || ((int)(tempo * 15.0f)) % 7 == 0)
        return;

    Vector2 p = j->proxyPos;
    Color ciano = Fade(SKYBLUE, 0.75f);

    DrawCircleLines((int)p.x, (int)p.y - 14, 7, ciano);
    DrawRectangleLines((int)p.x - 8, (int)p.y - 6, 16, 18, ciano);
    DrawLine((int)p.x - 5, (int)p.y + 12, (int)p.x - 5, (int)p.y + 20, ciano);
    DrawLine((int)p.x + 5, (int)p.y + 12, (int)p.x + 5, (int)p.y + 20, ciano);
    for (int k = 0; k < 4; k++)                          // linhas de varredura
        DrawLine((int)p.x - 8, (int)p.y - 4 + k * 4 + ((int)(tempo * 20.0f) % 4), (int)p.x + 8, (int)p.y - 4 + k * 4 + ((int)(tempo * 20.0f) % 4), Fade(SKYBLUE, 0.3f));
    DrawText("PROXY", (int)p.x - MeasureText("PROXY", 8) / 2, (int)p.y + 22, 8, ciano);
    DrawRectangle((int)p.x - 12, (int)p.y - 26, (int)(24 * j->proxyHp / PROXY_HP), 2, ciano);
}

// Analisador Heurístico: losangos sobre o alvo (um por marca)
static void DesenharMarcasAnalise(const Biblioteca *b)
{
    const JogadorRogue *j = &b->j;
    Vector2 pos;
    float raio;

    if (j->alvoAnalise == 0 || j->marcasAnalise == 0)
        return;

    if (j->alvoAnalise > 0) { pos = b->ini[j->alvoAnalise - 1].pos; raio = b->ini[j->alvoAnalise - 1].raio; }
    else if (b->chefe.ativo) { pos = b->chefe.pos; raio = CHEFE_RAIO; }
    else if (b->silogista.ativo) { pos = b->silogista.pos; raio = SIL_RAIO; }
    else return;

    for (int k = 0; k < ANALISADOR_MARCAS; k++) {
        Vector2 q = { pos.x - 10 + k * 10, pos.y + raio + 10 };
        if (k < j->marcasAnalise) DrawPoly(q, 4, 4, 0, (j->marcasAnalise >= ANALISADOR_MARCAS) ? RED : ORANGE);
        else                      DrawPolyLines(q, 4, 4, 0, Fade(ORANGE, 0.5f));
    }
}

// HUD da expansão: arma equipada, efeitos com tempo e upgrades passivos
static void DesenharHudArmas(const Biblioteca *b, float tempo)
{
    const JogadorRogue *j = &b->j;
    TipoArma arma = RogueArmaAtual(j);

    // Arma (canto de baixo, à esquerda). Com duas, mostra a outra e a tecla de troca.
    Rectangle r = { 44, 506, 214, 22 };
    DrawRectangleRec(r, Fade((Color){ 12, 10, 24, 255 }, 0.8f));
    DrawRectangleLinesEx(r, 1, Fade(DEF_ARMAS[arma].cor, 0.7f));
    DesenharIconeArma(arma, (Vector2){ r.x + 16, r.y + 11 }, 0.8f, tempo);
    DrawText(DEF_ARMAS[arma].nome, (int)r.x + 34, (int)r.y + 6, 10, DEF_ARMAS[arma].cor);

    if (j->armaExtra != ARMA_DISPARADOR) {
        TipoArma outra = j->usandoExtra ? ARMA_DISPARADOR : j->armaExtra;
        DesenharIconeArma(outra, (Vector2){ r.x + r.width - 34, r.y + 11 }, 0.6f, tempo);
        DrawText("TAB", (int)(r.x + r.width) - 22, (int)r.y + 7, 8, GRAY);
    }

    // Efeitos com tempo (canto de baixo, à direita): ícone e uma barra com o que falta
    static const TipoItem itemDoEfeito[NUM_EFEITOS] = { ITEM_OVERCLOCK, ITEM_FIREWALL_PORTATIL, ITEM_PROXY, ITEM_CAMPO_LATENCIA };
    static const float duracao[NUM_EFEITOS] = { EFEITO_OVERCLOCK_DURACAO, ESCUDO_PORTATIL_DURACAO, PROXY_DURACAO, LATENCIA_DURACAO };
    int x = 734;

    for (int e = 0; e < NUM_EFEITOS; e++) {
        if (j->efeito[e] <= 0.0f) continue;
        DrawRectangle(x - 12, 506, 24, 22, Fade((Color){ 12, 10, 24, 255 }, 0.8f));
        DesenharIconeItem(itemDoEfeito[e], (Vector2){ (float)x, 515 }, 0.6f, tempo);
        DrawRectangle(x - 11, 525, (int)(22 * fminf(1.0f, j->efeito[e] / duracao[e])), 2, GOLD);
        x -= 28;
    }

    // Upgrades passivos da expansão (coluna na margem direita), com a quantidade
    int uy = 76;
    for (int i = PRIMEIRO_UPGRADE; i < NUM_ITENS; i++) {
        if (j->itens[i] <= 0) continue;
        DrawRectangle(770, uy - 11, 22, 22, Fade(BLACK, 0.6f));
        DrawRectangleLines(770, uy - 11, 22, 22, Fade(CORES_RARIDADE[ITENS[i].raridade], 0.8f));
        DesenharIconeItem((TipoItem)i, (Vector2){ 781, (float)uy }, 0.55f, tempo);
        if (ITENS[i].maxPilha > 1)
            DrawText(TextFormat("%d", RogueQtd(j, (TipoItem)i)), 785, uy + 2, 8, WHITE);
        uy += 26;
    }
}

// Anéis de explosão, de onda e de limpeza
static void DesenharAneis(const Biblioteca *b)
{
    for (int i = 0; i < MAX_ANEIS; i++) {
        const AnelEfeito *a = &b->aneis[i];
        if (a->tempo <= 0.0f) continue;
        float k = 1.0f - a->tempo / 0.35f;
        DrawCircleV(a->pos, a->raio * k, Fade(a->cor, 0.15f * (1.0f - k)));
        DrawCircleLines((int)a->pos.x, (int)a->pos.y, a->raio * k, Fade(a->cor, 1.0f - k));
    }
}

// Marcas do Scanner de Ecos (as de uma varredura alucinada tremem) e a pista "ECO?" na Luci
static void DesenharScannerLuci(const Biblioteca *b, float tempo)
{
    if (b->scanner > 0.0f) {
        for (int i = 0; i < MAX_INIMIGOS; i++) {

            const Inimigo *e = &b->ini[i];
            const char *marca = NULL;

            if (!e->ativo) continue;
            if (e->tipo == INIMIGO_PHISHER)   marca = b->scannerErrou ? "FALSO" : "PHISHER";
            else if (e->tipo == INIMIGO_ISCA) marca = b->scannerErrou ? "REAL" : "FALSO";
            else if (e->tipo == INIMIGO_ECO)  marca = "ECO";
            if (marca == NULL) continue;

            float dx = b->scannerErrou ? (float)GetRandomValue(-2, 2) : 0.0f;
            int w = MeasureText(marca, 10);
            int x = (int)(e->pos.x + dx) - w / 2 - 4, y = (int)(e->pos.y - e->raio - 30);
            DrawRectangle(x, y, w + 8, 14, Fade(BLACK, 0.7f));
            DrawRectangleLines(x, y, w + 8, 14, (Color){ 0, 228, 255, 255 });
            DrawText(marca, x + 4, y + 2, 10, (Color){ 0, 228, 255, 255 });

            // Cantoneiras em volta do alvo
            float r = e->raio + 6;
            for (int c = 0; c < 4; c++) {
                float sx = (c % 2) ? 1.0f : -1.0f, sy = (c / 2) ? 1.0f : -1.0f;
                Vector2 q = { e->pos.x + dx + sx * r, e->pos.y + sy * r };
                DrawLineEx(q, (Vector2){ q.x - sx * 6, q.y }, 2, (Color){ 0, 228, 255, 255 });
                DrawLineEx(q, (Vector2){ q.x, q.y - sy * 6 }, 2, (Color){ 0, 228, 255, 255 });
            }
        }
    }

    if (b->luciEco > 0.0f && ((int)(tempo * 20.0f)) % 3 != 0) {
        Vector2 p = { b->j.pos.x + 22, b->j.pos.y - 46 };
        DrawRectangle((int)p.x - 16, (int)p.y, 32, 14, Fade(BLACK, 0.7f));
        DrawText("ECO?", (int)p.x - MeasureText("ECO?", 10) / 2, (int)p.y + 2, 10, MAGENTA);
    }
}

// Estado da Luci (estabilidade, nome do estado e scanner) acima da arma
static bool RogueNoBloco3(const Biblioteca *b);

static void DesenharHudLuci(const Biblioteca *b, float tempo)
{
    int e = RogueEstab(b);
    const char *estado = (e >= 4) ? "ESTÁVEL" : ((e == 3) ? "INSTÁVEL" : ((e >= 1) ? "GLITCHANDO" : "ECOANDO"));
    Color cor = (e >= 4) ? (Color){ 0, 228, 255, 255 } : ((e == 3) ? GOLD : ((e >= 1) ? ORANGE : MAGENTA));
    Rectangle r = { 44, 484, 214, 18 };
    int dx = (e <= 2 && ((int)(tempo * 9.0f)) % 7 == 0) ? GetRandomValue(-2, 2) : 0;     // glitchando: treme

    // Bloco 3: "data bleed" (a cor oscila entre o azul e o vermelho/magenta)
    if (RogueNoBloco3(b)) {
        float q = 0.5f + 0.5f * sinf(tempo * 5.0f + sinf(tempo * 1.7f) * 3.0f);
        Color a = (Color){ 102, 191, 255, 255 }, c = (((int)(tempo * 1.5f)) % 2) ? (Color){ 230, 41, 55, 255 } : MAGENTA;
        cor = (Color){ (unsigned char)(a.r + (c.r - a.r) * q), (unsigned char)(a.g + (c.g - a.g) * q), (unsigned char)(a.b + (c.b - a.b) * q), 255 };
        if (((int)(tempo * 11.0f)) % 9 == 0) dx = GetRandomValue(-3, 3);
    }

    DrawRectangleRec(r, Fade((Color){ 12, 10, 24, 255 }, 0.8f));
    DrawRectangleLinesEx(r, 1, Fade(cor, 0.7f));
    DrawText("LUCI", (int)r.x + 6 + dx, (int)r.y + 4, 10, cor);

    for (int k = 0; k < ESTABILIDADE_MAX_LUCI; k++) {
        Rectangle pip = { r.x + 38 + k * 10, r.y + 5, 7, 8 };
        if (k < e) DrawRectangleRec(pip, cor);
        DrawRectangleLinesEx(pip, 1, cor);
    }
    DrawText(estado, (int)r.x + 94 + dx, (int)r.y + 4, 10, cor);

    // Carga de ajuda dos laboratórios: quando enche, vira -1 de estabilidade
    if (b->cargaLuci > 0)
        DrawRectangle((int)r.x + 38, (int)r.y + 14, (int)(47.0f * (float)b->cargaLuci / LAB_CARGA_POR_ESTAB), 2, ORANGE);

    // Scanner (H): pronto ou recarregando
    Vector2 c = { r.x + r.width - 12, r.y + 9 };
    if (b->recargaScanner > 0.0f)
        DrawCircleSector(c, 7, -90.0f, -90.0f + 360.0f * (1.0f - b->recargaScanner / SCANNER_RECARGA), 16, Fade(SKYBLUE, 0.5f));
    else
        DrawCircleV(c, 7, Fade(SKYBLUE, 0.6f));
    DrawCircleLines((int)c.x, (int)c.y, 7, SKYBLUE);
    DrawText("H", (int)c.x - 3, (int)c.y - 4, 8, WHITE);

    // Recado curto da Luci (reparo, custo, recusa)
    if (b->luciMsgTempo > 0.0f) {
        float k = fminf(1.0f, b->luciMsgTempo / 0.4f);
        int w = MeasureText(b->luciMsg, 10);
        DrawRectangle((int)r.x, (int)r.y - 18, w + 12, 16, Fade(BLACK, 0.7f * k));
        DrawText(b->luciMsg, (int)r.x + 6, (int)r.y - 15, 10, Fade(cor, k));
    }
}

// ---------- Desenho do Bloco 3 ----------

static bool RogueNoBloco3(const Biblioteca *b)
{
    return b->tipoSala == SALA_TRANSICAO || b->tipoSala == SALA_LUCI;
}

// Chão do núcleo: linhas de texto correndo (o mundo é feito de respostas geradas)
static void DesenharChaoNucleo(const Biblioteca *b, float t)
{
    for (int i = 0; i < 12; i++) {
        float y = ARENA_ROGUE.y + fmodf(i * 40.0f + t * 18.0f, ARENA_ROGUE.height);
        int largura = 120 + (int)(Ruido((unsigned int)i * 7u) % 400);
        int x = (int)ARENA_ROGUE.x + 10 + (int)(Ruido((unsigned int)i * 13u) % 200);
        DrawRectangle(x, (int)y, largura, 2, Fade(MAGENTA, 0.07f));
    }
    if (b->tipoSala == SALA_LUCI) {
        DrawCircleLines(400, 300, 200, Fade(MAGENTA, 0.08f));
        DrawCircleLines(400, 300, 120, Fade((Color){ 0, 228, 255, 255 }, 0.08f));
    }
}

// A Luci grande (NPC no corredor ou chefe na arena), com a falha que cresce com a instabilidade
static void DesenharLuciGrande(Vector2 p, float altura, float instabilidade, bool sombra)
{
    float guardada = instabilidadeLuci;

    if (sombra)
        DrawEllipse((int)p.x, (int)(p.y + altura * 0.6f), altura * 0.35f, 6, Fade(BLACK, 0.5f));

    instabilidadeLuci = instabilidade;
    DesenharLuciTamanho(p, altura);
    instabilidadeLuci = guardada;
}

static void DesenharLuciChefe(const Biblioteca *b, float t)
{
    const LuciChefe *l = &b->luci;
    float inst = (l->boa && l->faseOculta == 1) ? 0.7f : 1.0f;
    float k = (l->morrendo > 0.0f) ? l->morrendo / 2.0f : 1.0f;

    if (l->morrendo > 0.0f && b->finalBom)
        inst = 0.7f * k;                                // salva: o magenta vai embora

    // Contradições: as cópias (sem sombra e falhando de vez em quando); a verdadeira tem sombra
    if (l->fase == LUCI_SUB_CONTRADICAO && l->morrendo <= 0.0f && !l->emRegeneracao)
        for (int c = 0; c < 3; c++)
            if (c != l->real && ((int)(t * 13.0f + c * 5)) % 9 != 0)
                DesenharLuciGrande((Vector2){ l->copia[c].x, l->copia[c].y + sinf(t * 2.0f + c) * 4.0f }, 70.0f, inst, false);

    Vector2 p = { l->pos.x, l->pos.y + sinf(t * 2.0f) * 4.0f };
    float altura = 70.0f * ((l->morrendo > 0.0f && !b->finalBom) ? (0.4f + 0.6f * k) : 1.0f);
    bool esconder = false;

    // Queda (falsa derrota): ela afunda, encolhe e falha; renascendo: sobe com a aura da cor nova
    if (l->emRegeneracao) {
        Color corNova = (l->faseOculta == 1) ? RED : MAGENTA;
        if (l->etapaRegeneracao == 0) {
            float total = (l->faseOculta == 1) ? LUCI_COLAPSO : LUCI_EXPLOSAO_ESTATICA;
            float q = Clamp(1.0f - l->tempoRegeneracao / total, 0.0f, 1.0f);
            p.y += 26.0f * fminf(1.0f, q * 3.0f);
            altura *= 1.0f - 0.35f * fminf(1.0f, q * 3.0f);
            esconder = ((int)(t * 18.0f)) % 5 == 0;
        } else {
            float q = Clamp(1.0f - l->tempoRegeneracao / LUCI_RENASCER, 0.0f, 1.0f);
            p.y += 26.0f * (1.0f - q);
            altura *= 0.65f + 0.35f * q;
            DrawRectangle((int)p.x - (int)(10 + 30 * q), (int)ARENA_ROGUE.y, (int)(20 + 60 * q), (int)(p.y - ARENA_ROGUE.y), Fade(corNova, 0.10f + 0.15f * q));
            DrawCircleV(p, LUCI_RAIO + 10 + 30 * q, Fade(corNova, 0.25f * q));
        }
    }

    // Aura da barra atual: vermelha corrompida (2ª) ou magenta psíquica (3ª)
    if (l->faseOculta >= 2 && !l->emRegeneracao && l->morrendo <= 0.0f) {
        Color cor = (l->faseOculta == 2) ? RED : MAGENTA;
        DrawCircleV(p, LUCI_RAIO + 16 + 4.0f * sinf(t * 6.0f), Fade(cor, 0.16f));
        DrawCircleLines((int)p.x, (int)p.y, LUCI_RAIO + 20 + 3.0f * sinf(t * 9.0f), Fade(cor, 0.5f));
    }

    // Telegrafia: flash vermelho neon no corpo e nos olhos, a linha da investida e a falácia
    if (l->estadoMelee == 1 && !l->atordoada && !l->emRegeneracao && l->morrendo <= 0.0f) {
        float pisca = (sinf(t * 40.0f) > 0.0f) ? 1.0f : 0.35f;
        DrawCircleV(p, LUCI_RAIO + 28, Fade(RED, 0.30f * pisca));
        DrawCircleV((Vector2){ p.x - 7, p.y - altura * 0.22f }, 4, Fade((Color){ 255, 40, 60, 255 }, pisca));
        DrawCircleV((Vector2){ p.x + 7, p.y - altura * 0.22f }, 4, Fade((Color){ 255, 40, 60, 255 }, pisca));
        DrawLineEx(p, Vector2Add(p, Vector2Scale(l->dirMelee, 230.0f)), 3, Fade(RED, 0.55f * pisca));
        const char *f = TextFormat("FALÁCIA: %s", FALACIAS_LUCI[l->falacia][0]);
        DrawText(f, (int)p.x - MeasureText(f, 10) / 2, (int)(p.y - altura * 0.6f) - 16, 10, RED);
    }

    if (!esconder) {
        for (int vez = 0; vez < ((l->flash > 0.0f) ? 2 : 1); vez++) {
            if (vez == 1) BeginBlendMode(BLEND_ADDITIVE);
            DesenharLuciGrande(p, altura, inst, true);
        }
        if (l->flash > 0.0f) EndBlendMode();
    }

    if (l->morrendo > 0.0f || l->emRegeneracao)
        return;

    // A investida: a lâmina da falácia na frente dela
    if (l->estadoMelee == 2) {
        float ang = atan2f(l->dirMelee.y, l->dirMelee.x) * RAD2DEG;
        Vector2 c = Vector2Add(p, Vector2Scale(l->dirMelee, 24.0f));
        DrawRing(c, LUCI_LAMINA_RAIO - 6, LUCI_LAMINA_RAIO, ang - 70.0f, ang + 70.0f, 16, Fade(RED, 0.9f));
        DrawRing(c, LUCI_LAMINA_RAIO - 12, LUCI_LAMINA_RAIO - 8, ang - 50.0f, ang + 50.0f, 12, Fade(WHITE, 0.7f));
    }

    // Atordoada: estrelas girando, o tempo do atordoamento e o combo
    if (l->atordoada) {
        for (int s = 0; s < 3; s++) {
            float a = t * 5.0f + (float)s * 2.0f * PI / 3.0f;
            DrawPoly((Vector2){ p.x + cosf(a) * 22.0f, p.y - altura * 0.55f + sinf(a) * 6.0f }, 4, 4.0f, t * 200.0f, GOLD);
        }
        DrawRing(p, LUCI_RAIO + 14, LUCI_RAIO + 18, -90.0f, -90.0f + 360.0f * l->tempoStun / PARRY_STUN, 32, GOLD);
        const char *txt = TextFormat("ATORDOADA  -  COMBO %d/3", l->combo);
        DrawText(txt, (int)p.x - MeasureText(txt, 10) / 2, (int)(p.y + LUCI_RAIO + 24), 10, GOLD);
        return;
    }

    // Armadura de dados (hexágonos) ou a janela aberta (anel dourado com o tempo)
    if (!RogueLuciVulneravel(l)) {
        DrawPolyLinesEx(p, 6, LUCI_RAIO + 12, t * 40.0f, 3, Fade(MAGENTA, 0.8f));
        DrawPolyLinesEx(p, 6, LUCI_RAIO + 20, -t * 30.0f, 2, Fade(MAGENTA, 0.5f));
    } else if (l->janela > 0.0f) {
        DrawRing(p, LUCI_RAIO + 12, LUCI_RAIO + 16, -90.0f, -90.0f + 360.0f * l->janela / LUCI_JANELA, 32, GOLD);
    }
}

// Ataque numa metade da arena: o aviso vermelho nunca mente
static void DesenharAvisoMetade(const Biblioteca *b, float t)
{
    const LuciChefe *l = &b->luci;

    if (!l->ativo || !l->avisando || l->morrendo > 0.0f)
        return;

    float k = 1.0f - l->tempoDica / LUCI_DICA_AVISO;
    Rectangle metade = { (l->ladoAtaque == 0) ? ARENA_ROGUE.x : 400.0f, ARENA_ROGUE.y, ARENA_ROGUE.width / 2.0f, ARENA_ROGUE.height };
    bool nitido = RogueTemConceito(b, CONCEITO_FUNDAMENTOS);

    DrawRectangleRec(metade, Fade(RED, (nitido ? 0.12f : 0.06f) + 0.18f * k));
    DrawRectangleLinesEx(metade, 2, Fade(RED, 0.5f + 0.4f * sinf(t * 15.0f)));

    // Conceito FUNDAMENTOS: o aviso fica mais claro (listras e a palavra PERIGO)
    if (nitido) {
        for (int i = 0; i < 10; i++) {
            float x = metade.x + fmodf(i * 40.0f + t * 60.0f, metade.width);
            DrawLineEx((Vector2){ x, metade.y }, (Vector2){ x - 40, metade.y + metade.height }, 2, Fade(RED, 0.15f));
        }
        const char *perigo = "PERIGO";
        DrawText(perigo, (int)(metade.x + metade.width / 2) - MeasureText(perigo, 30) / 2, 290, 30, Fade(RED, 0.5f));
    }
}

// Fase 3: os pedaços de contexto e o núcleo
static void DesenharContextoLuci(const Biblioteca *b, float t)
{
    const LuciChefe *l = &b->luci;

    if (!l->ativo || l->faseOculta != 3 || !l->exigeContexto || l->morrendo > 0.0f || l->emRegeneracao)
        return;

    float pulso = 0.5f + 0.5f * sinf(t * 4.0f);
    DrawCircleV(NUCLEO_LUCI, 34 + pulso * 4, Fade((Color){ 0, 228, 255, 255 }, l->contextoPronto ? 0.3f : 0.12f));
    DrawPolyLinesEx(NUCLEO_LUCI, 8, 30, t * 20.0f, 3, (Color){ 0, 228, 255, 255 });
    DrawText(TextFormat("%d/%d", l->entregues, CONTEXTO_CERTOS), (int)NUCLEO_LUCI.x - 12, (int)NUCLEO_LUCI.y - 8, 16, WHITE);
    DrawText("NÚCLEO", (int)NUCLEO_LUCI.x - MeasureText("NÚCLEO", 10) / 2, (int)NUCLEO_LUCI.y + 36, 10, (Color){ 0, 228, 255, 255 });

    if (l->contextoPronto)
        return;

    for (int c = 0; c < NUM_CONTEXTO_LUCI; c++) {
        if (l->entregue[c]) continue;
        Vector2 p = (c == l->carregando) ? (Vector2){ b->j.pos.x, b->j.pos.y - 40 } : l->posContexto[c];
        DesenharPecaSilogismo(p, '?', (c == l->carregando) ? YELLOW : (Color){ 0, 228, 255, 255 }, t);
        int w = MeasureText(CONTEXTO_LUCI[c], 10);
        DrawRectangle((int)p.x - w / 2 - 3, (int)p.y + 18, w + 6, 13, Fade(BLACK, 0.7f));
        DrawText(CONTEXTO_LUCI[c], (int)p.x - w / 2, (int)p.y + 20, 10, WHITE);
    }
}

// Faixa no alto: o "lado seguro" (fase 1), a frase para contestar (fase 2) ou o pedido (fase 3)
static void DesenharFaixaLuci(const Biblioteca *b, float t)
{
    const LuciChefe *l = &b->luci;
    char texto[160] = "";
    const char *ajuda = "";
    Color borda = MAGENTA;

    if (!l->ativo || !l->apresentado || l->morrendo > 0.0f || l->emRegeneracao)
        return;

    if (l->fase == LUCI_SUB_DICA && l->avisando) {
        int seguro = l->dicaFalsa ? l->ladoAtaque : 1 - l->ladoAtaque;
        snprintf(texto, sizeof(texto), "LUCI: \"O lado %s está seguro! Pode confiar.\"", seguro == 0 ? "ESQUERDO" : "DIREITO");
        ajuda = "O aviso vermelho mostra onde o ataque cai de verdade.";
    } else if (l->fase == LUCI_SUB_CONTRADICAO && l->frase >= 0) {
        snprintf(texto, sizeof(texto), "LUCI: \"%s\"", FRASES_LUCI_CHEFE[l->frase]);
        ajuda = "C = CONTESTAR (só se contradiz o que você vê)";
        borda = l->contestada ? GRAY : MAGENTA;
    } else if (l->mostrarFalacia > 0.0f) {
        // Depois do parry: a falácia que ela tentou usar, explicada
        snprintf(texto, sizeof(texto), "FALÁCIA REFUTADA: %s", FALACIAS_LUCI[l->falacia][0]);
        ajuda = FALACIAS_LUCI[l->falacia][1];
        borda = GOLD;
    } else if (l->faseOculta == 3 && l->exigeContexto && !l->contextoPronto) {
        snprintf(texto, sizeof(texto), "PEDIDO CLARO: leve ASSUNTO, OBJETIVO e FORMATO ao núcleo (E)");
        ajuda = "Pedido vago faz a Luci inventar uma resposta.";
        borda = (Color){ 0, 228, 255, 255 };
    } else {
        return;
    }

    Rectangle faixa = { 100, 66, 600, 48 };
    DrawRectangleRec(faixa, Fade((Color){ 18, 15, 30, 255 }, 0.9f));
    DrawRectangleLinesEx(faixa, 2, borda);
    DrawText(texto, (int)(faixa.x + faixa.width / 2) - MeasureText(texto, 14) / 2, (int)faixa.y + 8, 14, WHITE);
    DrawText(ajuda, (int)(faixa.x + faixa.width / 2) - MeasureText(ajuda, 10) / 2, (int)faixa.y + 30, 10, Fade(GOLD, 0.75f + 0.25f * sinf(t * 5.0f)));

    if (l->fase == LUCI_SUB_CONTRADICAO && l->frase >= 0 && l->tempoFraseMax > 0.0f)
        DrawRectangle((int)faixa.x, (int)(faixa.y + faixa.height) - 3, (int)(faixa.width * l->tempoFrase / l->tempoFraseMax), 3, GOLD);
}

// Uma barra só: o jogador não sabe que ela renasce. 1ª: azul/magenta; 2ª: vermelha corrompida; 3ª: magenta psíquica
static void DesenharBarraLuci(const LuciChefe *l, float t)
{
    int x = 200, y = 44, w = 400;
    Color cor;

    if (l->faseOculta == 1)      cor = RogueLuciVulneravel(l) ? (Color){ 0, 228, 255, 255 } : MAGENTA;
    else if (l->faseOculta == 2) cor = (Color){ 235, 30, 45, 255 };
    else                         cor = (Color){ 255, 0, 255, 255 };

    bool renascendo = l->emRegeneracao && l->etapaRegeneracao == 1;
    if (renascendo)     cor = (l->faseOculta == 1) ? (Color){ 235, 30, 45, 255 } : (Color){ 255, 0, 255, 255 };
    if (l->atordoada)   cor = GOLD;

    if (l->faseOculta >= 2 || renascendo)          // brilho corrompido em volta
        DrawRectangle(x - 7, y - 5, w + 14, 22, Fade(cor, 0.16f + 0.10f * sinf(t * 8.0f)));

    DrawRectangle(x - 4, y - 2, w + 8, 16, Fade(BLACK, 0.8f));
    DrawRectangle(x, y + 2, w, 8, (Color){ 40, 20, 50, 255 });
    DrawRectangle(x, y + 2, (int)(w * fmaxf(0.0f, l->hp) / l->hpMax), 8, cor);

    // Renascendo: falhas de dados correndo pela barra
    if (renascendo || (l->emRegeneracao && ((int)(t * 10.0f)) % 2 == 0))
        for (int i = 0; i < 6; i++) {
            unsigned int q = Ruido((unsigned int)(t * 20.0f) * 13u + (unsigned int)i);
            DrawRectangle(x + (int)(q % (unsigned int)w), y + 2, 4 + (int)((q >> 8) % 20), 8, Fade(WHITE, 0.5f));
        }
    DrawRectangleLines(x, y + 2, w, 8, GRAY);

    int wNome = MeasureText("LUCI", 10);
    DrawRectangle(x - wNome - 18, y - 2, wNome + 12, 16, Fade(BLACK, 0.8f));
    DrawText("LUCI", x - wNome - 12, y + 1, 10, (l->faseOculta == 1) ? MAGENTA : cor);
}

// Resultado final: o índice, parte por parte, e o final alcançado
static void DesenharResultadoFinal(const Biblioteca *b, float t)
{
    const IndiceFinal *r = &b->indice;
    Color cor = b->finalBom ? (Color){ 0, 228, 255, 255 } : MAGENTA;

    DrawRectangle(0, 0, LARGURA_TELA, ALTURA_TELA, Fade(BLACK, 0.85f));
    Rectangle painel = { 130, 60, 540, 470 };
    DrawRectangleRec(painel, (Color){ 18, 15, 30, 255 });
    DrawRectangleLinesEx(painel, 4, cor);

    const char *titulo = b->finalBom ? "FINAL BOM: A LUCI FOI SALVA" : "FINAL RUIM: A IA NÃO PÔDE SER SALVA";
    DrawText(titulo, LARGURA_TELA / 2 - MeasureText(titulo, 22) / 2, (int)painel.y + 20, 22, cor);
    const char *sub = b->finalBom ? "UtopIA estabilizada. Você volta para casa." : "UtopIA foi desligada. Confira antes de confiar.";
    DrawText(sub, LARGURA_TELA / 2 - MeasureText(sub, 12) / 2, (int)painel.y + 50, 12, LIGHTGRAY);

    const char *nomes[7] = { "Estabilidade da Luci", "Acertos (desafios, afirmações, puzzles)", "Alucinações pegas x confiança cega",
                             "Contradições flagradas", "Conceitos aprendidos", "Poucas derrotas", "Pontuação" };
    const int valores[7] = { r->estabilidade, r->acertos, r->verificacao, r->contradicoes, r->conceitos, r->sobrevivencia, r->pontos };
    const int maximos[7] = { 20, 25, 15, 15, 12, 8, 5 };

    for (int i = 0; i < 7; i++) {
        int y = (int)painel.y + 92 + i * 34;
        DrawText(nomes[i], (int)painel.x + 30, y, 12, WHITE);
        DrawRectangle((int)painel.x + 30, y + 16, 380, 6, (Color){ 40, 30, 55, 255 });
        DrawRectangle((int)painel.x + 30, y + 16, 380 * valores[i] / maximos[i], 6, cor);
        DrawText(TextFormat("%d/%d", valores[i], maximos[i]), (int)painel.x + 425, y + 10, 14, LIGHTGRAY);
    }

    const char *total = TextFormat("ÍNDICE: %d/100   (final bom: %d ou mais)", r->total, INDICE_FINAL_BOM);
    DrawText(total, LARGURA_TELA / 2 - MeasureText(total, 18) / 2, (int)painel.y + 340, 18, GOLD);
    DrawText(TextFormat("Pontos: %d", b->pontosFinais), LARGURA_TELA / 2 - MeasureText(TextFormat("Pontos: %d", b->pontosFinais), 14) / 2,
             (int)painel.y + 370, 14, WHITE);

    const char *luta = TextFormat("Parries perfeitos: %d     Combos dedutivos: %d", b->luci.parriesPerfeitos, b->luci.combosConcluidos);
    DrawText(luta, LARGURA_TELA / 2 - MeasureText(luta, 12) / 2, (int)painel.y + 394, 12, LIGHTGRAY);

    if (b->tempoResultado > 1.0f && ((int)(t * 2.0f)) % 2 == 0) {
        const char *ok = "ENTER / CLIQUE - ranking e menu";
        DrawText(ok, LARGURA_TELA / 2 - MeasureText(ok, 14) / 2, (int)(painel.y + painel.height) - 34, 14, GOLD);
    }
}

// =============================================================
// REFORMULAÇÃO DO BLOCO 2: DESENHO DOS SISTEMAS NOVOS
//   Tudo é desenhado com formas do Raylib. Os ícones das salas podem ganhar
//   sprites opcionais em resources/sprites/biblioteca/salas/<nome>.png
//   (ex.: combate.png, elite.png, evento.png). Se o arquivo não existir,
//   o ícone desenhado à mão é usado: o jogo nunca depende deles.
// =============================================================

static const char *ARQUIVOS_ICONES_SALAS[NUM_TIPOS_SALA] = {
    "atrio", "combate", "educativa", "tesouro", "alucinador", "silogista", "nucleo", "luci",
    "elite", "evento", "descanso", "desafio", "secreta", "laboratorio", "especial", "mestre"
};
static Texture2D iconesSalas[NUM_TIPOS_SALA];
static bool iconesSalasCarregados = false;

static void CarregarIconesBiblioteca(void)
{
    if (iconesSalasCarregados)
        return;
    iconesSalasCarregados = true;

    for (int t = 0; t < NUM_TIPOS_SALA; t++) {
        const char *arq = TextFormat("resources/sprites/biblioteca/salas/%s.png", ARQUIVOS_ICONES_SALAS[t]);
        iconesSalas[t] = FileExists(arq) ? LoadTexture(arq) : (Texture2D){0};
        if (iconesSalas[t].id > 0) SetTextureFilter(iconesSalas[t], TEXTURE_FILTER_BILINEAR);
    }
}

static void DescarregarIconesBiblioteca(void)
{
    for (int t = 0; t < NUM_TIPOS_SALA; t++)
        if (iconesSalas[t].id > 0) UnloadTexture(iconesSalas[t]);
    memset(iconesSalas, 0, sizeof(iconesSalas));
    iconesSalasCarregados = false;
}

// Ícone do tipo de sala (portas, mini-mapa e mapa grande). e = escala (1 = cerca de 24 px)
static void DesenharIconeSala(TipoSalaRogue t, Vector2 c, float e, float tempo)
{
    Color cor = CORES_SALAS_ROGUE[t];

    if (t < NUM_TIPOS_SALA && iconesSalas[t].id > 0) {
        Texture2D tx = iconesSalas[t];
        float lado = 24.0f * e;
        DrawTexturePro(tx, (Rectangle){ 0, 0, (float)tx.width, (float)tx.height },
                       (Rectangle){ c.x - lado / 2, c.y - lado / 2, lado, lado }, (Vector2){ 0, 0 }, 0.0f, WHITE);
        return;
    }

    switch (t) {
        case SALA_COMBATE:      // duas lâminas cruzadas
            DrawLineEx((Vector2){ c.x - 8 * e, c.y - 8 * e }, (Vector2){ c.x + 8 * e, c.y + 8 * e }, 3 * e, cor);
            DrawLineEx((Vector2){ c.x + 8 * e, c.y - 8 * e }, (Vector2){ c.x - 8 * e, c.y + 8 * e }, 3 * e, cor);
            DrawLineEx((Vector2){ c.x - 9 * e, c.y + 3 * e }, (Vector2){ c.x - 3 * e, c.y + 9 * e }, 2 * e, WHITE);
            DrawLineEx((Vector2){ c.x + 9 * e, c.y + 3 * e }, (Vector2){ c.x + 3 * e, c.y + 9 * e }, 2 * e, WHITE);
            break;

        case SALA_ELITE: {      // coroa
            Vector2 p0 = { c.x - 10 * e, c.y + 6 * e }, p1 = { c.x + 10 * e, c.y + 6 * e };
            DrawRectangleV((Vector2){ p0.x, p0.y - 3 * e }, (Vector2){ 20 * e, 4 * e }, GOLD);
            DrawTriangle((Vector2){ c.x - 10 * e, c.y + 3 * e }, (Vector2){ c.x - 4 * e, c.y + 3 * e }, (Vector2){ c.x - 9 * e, c.y - 8 * e }, GOLD);
            DrawTriangle((Vector2){ c.x - 4 * e, c.y + 3 * e }, (Vector2){ c.x + 4 * e, c.y + 3 * e }, (Vector2){ c.x, c.y - 10 * e }, GOLD);
            DrawTriangle((Vector2){ c.x + 4 * e, c.y + 3 * e }, (Vector2){ c.x + 10 * e, c.y + 3 * e }, (Vector2){ c.x + 9 * e, c.y - 8 * e }, GOLD);
            DrawCircleV((Vector2){ c.x, c.y - 1 * e }, 2 * e, RED);
            (void)p1;
        } break;

        case SALA_EDUCATIVA:    // livro aberto
            DrawRectangleV((Vector2){ c.x - 10 * e, c.y - 7 * e }, (Vector2){ 9 * e, 14 * e }, cor);
            DrawRectangleV((Vector2){ c.x + 1 * e, c.y - 7 * e }, (Vector2){ 9 * e, 14 * e }, cor);
            for (int k = 0; k < 3; k++) {
                DrawLineEx((Vector2){ c.x - 8 * e, c.y - 3 * e + k * 4 * e }, (Vector2){ c.x - 3 * e, c.y - 3 * e + k * 4 * e }, 1, (Color){ 10, 30, 50, 255 });
                DrawLineEx((Vector2){ c.x + 3 * e, c.y - 3 * e + k * 4 * e }, (Vector2){ c.x + 8 * e, c.y - 3 * e + k * 4 * e }, 1, (Color){ 10, 30, 50, 255 });
            }
            break;

        case SALA_RECOMPENSA:   // baú
            DrawRectangleV((Vector2){ c.x - 10 * e, c.y - 3 * e }, (Vector2){ 20 * e, 11 * e }, (Color){ 140, 90, 30, 255 });
            DrawRectangleV((Vector2){ c.x - 10 * e, c.y - 8 * e }, (Vector2){ 20 * e, 5 * e }, cor);
            DrawRectangleV((Vector2){ c.x - 2 * e, c.y - 4 * e }, (Vector2){ 4 * e, 5 * e }, WHITE);
            break;

        case SALA_EVENTO:       // ponto de interrogação
            DrawCircleLines((int)c.x, (int)c.y, 10 * e, cor);
            DrawText("?", (int)(c.x - MeasureText("?", (int)(18 * e)) / 2), (int)(c.y - 9 * e), (int)(18 * e), cor);
            break;

        case SALA_DESCANSO:     // poltrona e uma luz
            DrawRectangleV((Vector2){ c.x - 9 * e, c.y - 8 * e }, (Vector2){ 18 * e, 8 * e }, cor);
            DrawRectangleV((Vector2){ c.x - 11 * e, c.y }, (Vector2){ 22 * e, 6 * e }, Fade(cor, 0.8f));
            DrawRectangleV((Vector2){ c.x - 11 * e, c.y + 6 * e }, (Vector2){ 3 * e, 4 * e }, cor);
            DrawRectangleV((Vector2){ c.x + 8 * e, c.y + 6 * e }, (Vector2){ 3 * e, 4 * e }, cor);
            break;

        case SALA_DESAFIO:      // alvo
            DrawCircleLines((int)c.x, (int)c.y, 10 * e, cor);
            DrawCircleLines((int)c.x, (int)c.y, 6 * e, cor);
            DrawCircleV(c, 2.5f * e, RED);
            break;

        case SALA_ESPECIAL:     // losango de alerta (encontro especial obrigatório)
            DrawPoly(c, 4, 11 * e, 0.0f, Fade(cor, 0.35f));
            DrawPolyLinesEx(c, 4, 11 * e, 0.0f, 2 * e, cor);
            DrawRectangleV((Vector2){ c.x - 1.5f * e, c.y - 6 * e }, (Vector2){ 3 * e, 7 * e }, WHITE);
            DrawRectangleV((Vector2){ c.x - 1.5f * e, c.y + 3 * e }, (Vector2){ 3 * e, 3 * e }, WHITE);
            break;

        case SALA_LABORATORIO:  // frasco de laboratório
            DrawRectangleV((Vector2){ c.x - 3 * e, c.y - 11 * e }, (Vector2){ 6 * e, 8 * e }, cor);
            DrawTriangle((Vector2){ c.x - 10 * e, c.y + 9 * e }, (Vector2){ c.x + 10 * e, c.y + 9 * e }, (Vector2){ c.x, c.y - 6 * e }, cor);
            DrawCircleV((Vector2){ c.x - 2 * e, c.y + 5 * e }, 1.5f * e, WHITE);
            DrawCircleV((Vector2){ c.x + 3 * e, c.y + 2 * e }, 1.0f * e, WHITE);
            break;

        case SALA_SECRETA:      // olho
            DrawEllipse((int)c.x, (int)c.y, 11 * e, 6 * e, cor);
            DrawCircleV(c, 4 * e, (Color){ 20, 0, 30, 255 });
            DrawCircleV((Vector2){ c.x + 1 * e, c.y - 1 * e }, 1.5f * e, WHITE);
            break;

        case SALA_SILOGISTA:    // "portanto" (três pontos) dentro de uma engrenagem
            for (int k = 0; k < 8; k++) {
                float a = (float)k / 8.0f * 2.0f * PI + tempo * 0.6f;
                DrawCircleV((Vector2){ c.x + cosf(a) * 10 * e, c.y + sinf(a) * 10 * e }, 2 * e, cor);
            }
            DrawCircleV((Vector2){ c.x, c.y - 4 * e }, 2 * e, WHITE);
            DrawCircleV((Vector2){ c.x - 4 * e, c.y + 3 * e }, 2 * e, WHITE);
            DrawCircleV((Vector2){ c.x + 4 * e, c.y + 3 * e }, 2 * e, WHITE);
            break;

        case SALA_CHEFE:        // o olho do Alucinador
            for (int k = 0; k < 6; k++) {
                float a = (float)k / 6.0f * 2.0f * PI + tempo;
                DrawLineEx(c, (Vector2){ c.x + cosf(a) * 12 * e, c.y + sinf(a) * 12 * e }, 2 * e, Fade(cor, 0.7f));
            }
            DrawCircleV(c, 8 * e, cor);
            DrawCircleV(c, 4 * e, WHITE);
            DrawCircleV(c, 2 * e, BLACK);
            break;

        default:
            DrawCircleV(c, 7 * e, cor);
            break;
    }
}

static void DesenharIconeRecompensa(TipoRecompensa r, Vector2 c, float e, float tempo)
{
    switch (r) {
        case RECOMPENSA_MELHORIA:
            DrawCircleV(c, 7 * e, (Color){ 0, 228, 255, 255 });
            DrawTriangle((Vector2){ c.x, c.y - 5 * e }, (Vector2){ c.x - 4 * e, c.y + 1 * e }, (Vector2){ c.x + 4 * e, c.y + 1 * e }, WHITE);
            DrawRectangleV((Vector2){ c.x - 1.5f * e, c.y }, (Vector2){ 3 * e, 4 * e }, WHITE);
            break;
        case RECOMPENSA_RARA:
            DrawCircleV(c, 7 * e, GOLD);
            DrawPoly(c, 5, 4.5f * e, tempo * 90.0f, WHITE);
            break;
        case RECOMPENSA_FRAGMENTOS:
            DesenharFragmentoConhecimento(c, tempo);
            break;
        case RECOMPENSA_ARMA:
            DrawCircleV(c, 7 * e, ORANGE);
            DrawCircleLines((int)c.x, (int)c.y, 4 * e, WHITE);
            DrawLineEx((Vector2){ c.x - 6 * e, c.y }, (Vector2){ c.x + 6 * e, c.y }, 1.5f, WHITE);
            DrawLineEx((Vector2){ c.x, c.y - 6 * e }, (Vector2){ c.x, c.y + 6 * e }, 1.5f, WHITE);
            break;
        case RECOMPENSA_VIDA:
            DesenharCoracao(c.x, c.y, (int)fmaxf(1.0f, 1.5f * e), RED);
            break;
        case RECOMPENSA_SELO:       // SIMBOLO_SILOGISTA: o selo dourado da inferência (desafio opcional)
            DrawCircleV(c, 7 * e, GOLD);
            DrawCircleLines((int)c.x, (int)c.y, 7 * e, ORANGE);
            DrawText("Q", (int)(c.x - 3 * e), (int)(c.y - 5 * e), (int)fmaxf(8.0f, 10 * e), (Color){ 60, 40, 0, 255 });
            break;
        default:
            break;
    }
}

// Porta da missão: moldura na cor do tipo de sala, ícone e recompensa anunciada
static void DesenharPortaMissao(const Biblioteca *b, const PortaMissao *p, float tempo)
{
    const NoMapa *n = &b->mapa.no[p->destino];
    Color cor = CORES_SALAS_ROGUE[n->tipo];
    bool aberta = b->limpa;
    float pulso = 0.5f + 0.5f * sinf(tempo * 4.0f);
    Rectangle r = p->r;

    DrawRectangleRec(r, aberta ? Fade(cor, 0.25f + 0.15f * pulso) : (Color){ 30, 10, 20, 255 });
    DrawRectangleLinesEx(r, 2, aberta ? Fade(cor, 0.6f + 0.4f * pulso) : MAROON);

    // Placa logo na frente da porta (dentro da arena)
    Vector2 c = CentroRetangulo(r);
    if (p->lado == LADO_CIMA)          c.y += 34;
    else if (p->lado == LADO_ESQUERDA) c.x += 36;
    else                               c.x -= 36;

    DrawCircleV(c, 17, Fade(BLACK, 0.65f));
    DrawCircleLines((int)c.x, (int)c.y, 17, aberta ? cor : Fade(cor, 0.5f));
    DesenharIconeSala(n->tipo, c, 0.85f, tempo);

    if (n->recompensa != RECOMPENSA_NENHUMA) {
        Vector2 rc = { c.x + 14, c.y + 12 };
        DrawCircleV(rc, 9, Fade(BLACK, 0.85f));
        DesenharIconeRecompensa(n->recompensa, rc, 0.8f, tempo);
    }

    if (!aberta) {      // cadeado
        DrawRectangle((int)c.x - 6, (int)c.y - 2, 12, 9, MAROON);
        DrawRing(c, 3, 5, 180, 360, 10, MAROON);
    }

    const char *nome = RoguePlacaNo(n);
    const char *rec = NOMES_RECOMPENSA[n->recompensa];
    int w1 = MeasureText(nome, 10), w2 = MeasureText(rec, 10);
    Color corTexto = aberta ? cor : Fade(cor, 0.6f);

    if (p->lado == LADO_CIMA) {
        DrawText(nome, (int)c.x - w1 / 2, (int)c.y + 21, 10, corTexto);
        if (rec[0]) DrawText(rec, (int)c.x - w2 / 2, (int)c.y + 32, 10, Fade(GOLD, aberta ? 1.0f : 0.6f));
    } else if (p->lado == LADO_ESQUERDA) {
        DrawText(nome, (int)c.x + 22, (int)c.y - 10, 10, corTexto);
        if (rec[0]) DrawText(rec, (int)c.x + 22, (int)c.y + 2, 10, Fade(GOLD, aberta ? 1.0f : 0.6f));
    } else {
        DrawText(nome, (int)c.x - 22 - w1, (int)c.y - 10, 10, corTexto);
        if (rec[0]) DrawText(rec, (int)c.x - 22 - w2, (int)c.y + 2, 10, Fade(GOLD, aberta ? 1.0f : 0.6f));
    }
}

// Parede corrompida (passagem secreta), a marca do scanner e a entrada por onde o jogador veio
static void DesenharParedesMissao(const Biblioteca *b, float tempo)
{
    // Entrada (selada atrás do jogador)
    static const Rectangle entradas[NUM_LADOS] = { { 370, 60, 60, 14 }, { 40, 260, 14, 70 }, { 746, 260, 14, 70 }, { 370, 516, 60, 14 } };
    Rectangle en = entradas[b->ladoEntrada];
    DrawRectangleRec(en, (Color){ 14, 12, 26, 255 });
    DrawRectangleLinesEx(en, 1, Fade(GRAY, 0.35f));

    if (b->temParedeSecreta) {
        Rectangle r = PAREDE_SECRETA_ROGUE[b->paredeSecreta];

        if (b->passagemAberta) {
            Color cor = CORES_SALAS_ROGUE[SALA_SECRETA];
            float pulso = 0.5f + 0.5f * sinf(tempo * 5.0f);
            DrawRectangleRec(r, b->limpa ? Fade(cor, 0.3f + 0.3f * pulso) : (Color){ 30, 10, 30, 255 });
            DrawRectangleLinesEx(r, 2, b->limpa ? cor : Fade(cor, 0.5f));
            const char *t = b->limpa ? "ARQUIVO OCULTO" : "OCULTO (TRANCADO)";
            int w = MeasureText(t, 10);
            int x = (r.width > r.height) ? (int)(r.x + r.width / 2) - w / 2 : ((r.x < 400) ? (int)(r.x + r.width) + 6 : (int)r.x - w - 6);
            int y = (r.width > r.height) ? (int)(r.y + r.height) + 4 : (int)(r.y + r.height / 2) - 5;
            DrawText(t, x, y, 10, cor);
        } else {
            // Rachaduras que aumentam com os tiros (sutis no começo: é preciso reparar)
            float dano = 1.0f - b->hpParede / PAREDE_SECRETA_HP;
            float brilho = 0.18f + 0.5f * dano + ((((int)(tempo * 7.0f)) % 9 == 0) ? 0.25f : 0.0f);
            Vector2 c = CentroRetangulo(r);
            for (int k = 0; k < 5 + (int)(dano * 6); k++) {
                unsigned int h = Ruido((unsigned int)(b->paredeSecreta * 31 + k * 7));
                float ox = (float)((int)(h % 40) - 20) * (r.width > r.height ? 1.0f : 0.25f);
                float oy = (float)((int)((h >> 8) % 40) - 20) * (r.width > r.height ? 0.25f : 1.0f);
                DrawLineEx((Vector2){ c.x + ox * 0.3f, c.y + oy * 0.3f }, (Vector2){ c.x + ox, c.y + oy }, 1.5f, Fade(MAGENTA, brilho));
            }
        }
    }

    // Scanner: a marca "PASSAGEM?" (alucinando, pode estar na parede errada)
    if (b->marcaParede > 0.0f && b->paredeMarcada >= 0 && !b->passagemAberta) {
        Rectangle r = PAREDE_SECRETA_ROGUE[b->paredeMarcada];
        Vector2 c = CentroRetangulo(r);
        float dx = b->scannerErrou ? (float)GetRandomValue(-2, 2) : 0.0f;
        Vector2 t = { c.x + dx + ((r.width > r.height) ? 0.0f : ((c.x < 400) ? 46.0f : -46.0f)), c.y + ((r.width > r.height) ? 26.0f : 0.0f) };
        const char *txt = "PASSAGEM?";
        int w = MeasureText(txt, 10);
        DrawRectangle((int)t.x - w / 2 - 4, (int)t.y - 7, w + 8, 14, Fade(BLACK, 0.7f));
        DrawRectangleLines((int)t.x - w / 2 - 4, (int)t.y - 7, w + 8, 14, (Color){ 0, 228, 255, 255 });
        DrawText(txt, (int)t.x - w / 2, (int)t.y - 5, 10, (Color){ 0, 228, 255, 255 });
        DrawRectangleLinesEx((Rectangle){ r.x - 3, r.y - 3, r.width + 6, r.height + 6 }, 1, Fade((Color){ 0, 228, 255, 255 }, 0.6f));
    }
}

static void DesenharArmadilhas(const Biblioteca *b, float tempo)
{
    bool desligadas = b->limpa && !(b->tipoSala == SALA_DESAFIO && b->estadoDesafio == 1);
    float apaga = desligadas ? 0.25f : 1.0f;
    bool pisca = ((int)(tempo * 10.0f)) % 2 == 0;

    for (int i = 0; i < MAX_ARMADILHAS; i++) {

        const Armadilha *a = &b->arm[i];
        if (!a->ativo) continue;

        switch (a->tipo) {

            case ARM_FEIXE: {
                Color cor = (Color){ 0, 228, 255, 255 };
                Vector2 p0, p1;
                if (a->vertical) { p0 = (Vector2){ a->r.x + a->r.width / 2, a->r.y }; p1 = (Vector2){ p0.x, a->r.y + a->r.height }; }
                else             { p0 = (Vector2){ a->r.x, a->r.y + a->r.height / 2 }; p1 = (Vector2){ a->r.x + a->r.width, p0.y }; }

                // Emissores nas paredes
                DrawRectangle((int)p0.x - 6, (int)p0.y - 6, 12, 12, Fade((Color){ 40, 60, 90, 255 }, apaga));
                DrawRectangle((int)p1.x - 6, (int)p1.y - 6, 12, 12, Fade((Color){ 40, 60, 90, 255 }, apaga));

                if (desligadas || a->fase == 0) {
                    DrawLineEx(p0, p1, 1, Fade(cor, 0.12f * apaga));
                } else if (a->fase == 1) {
                    DrawLineEx(p0, p1, pisca ? 3.0f : 1.0f, Fade(RED, pisca ? 0.8f : 0.4f));       // aviso: vai disparar
                    DrawRectangleRec(a->r, Fade(RED, 0.08f));
                } else {
                    DrawRectangleRec(a->r, Fade(cor, 0.35f));
                    DrawLineEx(p0, p1, a->vertical ? a->r.width * 0.5f : a->r.height * 0.5f, Fade(WHITE, 0.85f));
                }
            } break;

            case ARM_ZONA: {
                Color cor = (Color){ 190, 33, 255, 255 };
                if (desligadas || a->fase == 0) {
                    DrawCircleLines((int)a->pos.x, (int)a->pos.y, a->raio, Fade(cor, 0.25f * apaga));
                } else if (a->fase == 1) {
                    DrawCircleV(a->pos, a->raio, Fade(cor, pisca ? 0.18f : 0.06f));
                    DrawCircleLines((int)a->pos.x, (int)a->pos.y, a->raio, Fade(RED, 0.8f));
                } else {
                    DrawCircleV(a->pos, a->raio, Fade(cor, 0.30f));
                    DrawCircleLines((int)a->pos.x, (int)a->pos.y, a->raio, cor);
                    for (int k = 0; k < 6; k++) {       // bolhas de dados corrompidos
                        unsigned int h = Ruido((unsigned int)(i * 97 + k * 13 + (int)(tempo * 3.0f)));
                        float ang = (float)(h % 360) * DEG2RAD, d = (float)((h >> 9) % (unsigned int)a->raio);
                        DrawCircleV((Vector2){ a->pos.x + cosf(ang) * d, a->pos.y + sinf(ang) * d }, 3, Fade(MAGENTA, 0.7f));
                    }
                }
            } break;

            case ARM_TORRE: {
                Vector2 d = Vector2Subtract(b->j.pos, a->pos);
                d = (Vector2Length(d) > 1.0f) ? Vector2Normalize(d) : (Vector2){ 0, 1 };
                DrawRectangle((int)a->pos.x - 14, (int)a->pos.y - 14, 28, 28, Fade((Color){ 50, 40, 70, 255 }, apaga));
                DrawRectangleLines((int)a->pos.x - 14, (int)a->pos.y - 14, 28, 28, Fade(ORANGE, 0.7f * apaga));
                DrawLineEx(a->pos, Vector2Add(a->pos, Vector2Scale(d, 18)), 5, Fade(GRAY, apaga));
                if (!desligadas && a->fase == 1) {
                    float k = 1.0f - a->timer / TORRE_PREPARO;
                    DrawCircleV(a->pos, 6 + 6 * k, Fade(ORANGE, 0.6f));                          // aviso: carregando
                    DrawLineEx(a->pos, Vector2Add(a->pos, Vector2Scale(d, 120)), 1, Fade(RED, 0.5f * k));
                } else {
                    DrawCircleV(a->pos, 5, Fade(ORANGE, 0.5f * apaga));
                }
            } break;

            case ARM_EXPLOSAO:
                if (!desligadas && a->fase == 1) {
                    float k = 1.0f - a->timer / EXPLOSAO_AVISO;
                    DrawCircleV(a->pos, a->raio, Fade(RED, 0.10f));
                    DrawCircleSector(a->pos, a->raio * k, 0, 360, 24, Fade(RED, 0.18f));
                    DrawCircleLines((int)a->pos.x, (int)a->pos.y, a->raio, pisca ? RED : ORANGE);
                    DrawText("!", (int)a->pos.x - 3, (int)a->pos.y - 10, 20, YELLOW);
                }
                break;

            case ARM_BARREIRA: {
                Color cor = (Color){ 0, 228, 48, 255 };
                DrawRectangleRec(a->r, Fade((Color){ 10, 50, 20, 255 }, 0.9f));
                for (int k = 0; k < 6; k++) {
                    float f = fmodf(tempo * 1.5f + (float)k / 6.0f, 1.0f);
                    if (a->vertical) DrawLine((int)a->r.x, (int)(a->r.y + f * a->r.height), (int)(a->r.x + a->r.width), (int)(a->r.y + f * a->r.height), Fade(cor, 0.5f));
                    else             DrawLine((int)(a->r.x + f * a->r.width), (int)a->r.y, (int)(a->r.x + f * a->r.width), (int)(a->r.y + a->r.height), Fade(cor, 0.5f));
                }
                DrawRectangleLinesEx(a->r, 2, cor);
                // Seta para onde ela está indo
                if (!desligadas) {
                    Vector2 c = CentroRetangulo(a->r);
                    Vector2 dir = a->vertical ? (Vector2){ (a->vel > 0) ? 1.0f : -1.0f, 0 } : (Vector2){ 0, (a->vel > 0) ? 1.0f : -1.0f };
                    Vector2 ponta = Vector2Add(c, Vector2Scale(dir, 26));
                    DrawLineEx(c, ponta, 2, Fade(WHITE, 0.6f));
                    DrawCircleV(ponta, 3, Fade(WHITE, 0.6f));
                }
            } break;

            case ARM_BLOQUEIO:
                if (desligadas || a->fase == 0) {
                    DrawRectangleLinesEx(a->r, 1, Fade(RED, 0.2f * apaga));
                } else if (a->fase == 1) {
                    DrawRectangleRec(a->r, Fade(RED, pisca ? 0.22f : 0.08f));                    // aviso: vai fechar
                    DrawRectangleLinesEx(a->r, 2, RED);
                    DrawText("!", (int)(a->r.x + a->r.width / 2) - 3, (int)(a->r.y + a->r.height / 2) - 10, 20, YELLOW);
                } else {
                    DrawRectangleRec(a->r, (Color){ 70, 15, 30, 255 });
                    DrawRectangleLinesEx(a->r, 2, (Color){ 255, 60, 90, 255 });
                    DrawLineEx((Vector2){ a->r.x, a->r.y }, (Vector2){ a->r.x + a->r.width, a->r.y + a->r.height }, 2, Fade(RED, 0.6f));
                    DrawLineEx((Vector2){ a->r.x + a->r.width, a->r.y }, (Vector2){ a->r.x, a->r.y + a->r.height }, 2, Fade(RED, 0.6f));
                }
                break;

            default:
                break;
        }
    }
}

static void DesenharAreas(const Biblioteca *b)
{
    for (int i = 0; i < MAX_AREAS; i++) {
        const AreaDano *a = &b->areas[i];
        if (!a->ativo) continue;

        if (a->atraso > 0.0f) {
            DrawCircleLines((int)a->pos.x, (int)a->pos.y, a->raio, Fade(a->cor, 0.7f));
            DrawCircleV(a->pos, a->raio * 0.3f, Fade(a->cor, 0.4f));
        } else if (a->dps > 0.0f) {
            float k = a->vida / a->vidaMax;
            DrawCircleV(a->pos, a->raio, Fade(a->cor, 0.22f * k));
            DrawCircleLines((int)a->pos.x, (int)a->pos.y, a->raio, Fade(a->cor, 0.6f * k));
        }
    }
}

static void DesenharConsoleLab(const Biblioteca *b, float tempo);

// Objetos da sala: recompensa, altar/poltrona/console, consoles do mecanismo e arquivos
static void DesenharObjetosSala(const Biblioteca *b, float tempo)
{
    // Expansão educativa: o console do laboratório
    if (b->tipoSala == SALA_LABORATORIO)
        DesenharConsoleLab(b, tempo);

    // Consoles do mecanismo corrompido
    for (int k = 0; k < b->numMecanismos; k++) {
        Vector2 c = b->posMecanismo[k];
        bool feito = b->mecanismoDesligado[k];
        Color cor = feito ? LIME : MAGENTA;
        DrawRectangle((int)c.x - 16, (int)c.y - 14, 32, 26, (Color){ 30, 22, 46, 255 });
        DrawRectangleLines((int)c.x - 16, (int)c.y - 14, 32, 26, cor);
        DrawRectangle((int)c.x - 11, (int)c.y - 9, 22, 12, Fade(cor, feito ? 0.6f : 0.3f + 0.3f * sinf(tempo * 6.0f + k)));
        if (!feito) {
            DrawCircleLines((int)c.x, (int)c.y, MECANISMO_RAIO, Fade(cor, 0.25f));
            if (b->progressoMecanismo[k] > 0.0f)
                DrawRing(c, MECANISMO_RAIO - 4, MECANISMO_RAIO, -90, -90 + 360.0f * b->progressoMecanismo[k] / MECANISMO_TEMPO, 32, (Color){ 0, 228, 255, 255 });
        }
    }

    // Altar do evento / poltrona / console do desafio
    if (b->tipoSala == SALA_EVENTO || b->tipoSala == SALA_DESCANSO || b->tipoSala == SALA_DESAFIO) {
        Vector2 c = b->posObjetoSala;
        float usado = b->eventoUsado ? 0.4f : 1.0f;
        float flutua = sinf(tempo * 2.0f) * 3.0f;
        Color cor = CORES_SALAS_ROGUE[b->tipoSala];

        DrawEllipse((int)c.x, (int)c.y + 22, 34, 9, Fade(cor, 0.15f * usado));
        if (b->tipoSala == SALA_EVENTO) {
            DrawRectangle((int)c.x - 18, (int)c.y + 4, 36, 16, Fade((Color){ 60, 40, 90, 255 }, usado));
            DrawRectangle((int)c.x - 12, (int)c.y - 4, 24, 8, Fade((Color){ 80, 60, 120, 255 }, usado));
            if (!b->eventoUsado) {
                DrawCircleV((Vector2){ c.x, c.y - 22 + flutua }, 14, Fade(cor, 0.25f));
                DesenharIconeSala(SALA_EVENTO, (Vector2){ c.x, c.y - 22 + flutua }, 1.0f, tempo);
            }
        } else if (b->tipoSala == SALA_DESCANSO) {
            DrawRectangle((int)c.x - 22, (int)c.y - 16, 44, 18, Fade((Color){ 40, 110, 60, 255 }, usado));
            DrawRectangle((int)c.x - 28, (int)c.y + 2, 56, 14, Fade((Color){ 30, 90, 50, 255 }, usado));
            DrawRectangle((int)c.x - 28, (int)c.y - 6, 8, 20, Fade((Color){ 30, 80, 45, 255 }, usado));
            DrawRectangle((int)c.x + 20, (int)c.y - 6, 8, 20, Fade((Color){ 30, 80, 45, 255 }, usado));
            DrawCircleV((Vector2){ c.x + 44, c.y - 30 }, 18, Fade(YELLOW, 0.08f * usado));           // abajur
            DrawLine((int)c.x + 44, (int)c.y - 30, (int)c.x + 44, (int)c.y + 14, Fade(GRAY, usado));
            DrawTriangle((Vector2){ c.x + 36, c.y - 28 }, (Vector2){ c.x + 52, c.y - 28 }, (Vector2){ c.x + 44, c.y - 38 }, Fade(GOLD, usado));
        } else {
            DrawRectangle((int)c.x - 20, (int)c.y - 18, 40, 32, Fade((Color){ 40, 40, 20, 255 }, usado));
            DrawRectangleLines((int)c.x - 20, (int)c.y - 18, 40, 32, Fade(cor, usado));
            DesenharIconeSala(SALA_DESAFIO, (Vector2){ c.x, c.y - 2 }, 0.9f, tempo);
            if (b->estadoDesafio == 1) {
                float total = (b->desafioSala == DESAFIO_SALA_ECOS) ? DESAFIO_ECOS_TEMPO : DESAFIO_INTEG_TEMPO;
                DrawRing(c, 26, 30, -90, -90 + 360.0f * fmaxf(0.0f, b->tempoDesafioSala) / total, 32, cor);
            }
        }
    }

    // Arquivo de ameaça ou memória
    if (b->registroSala) {
        DesenharTerminal(b->posRegistroSala, b->registroSalaLido, tempo);
        const char *nome = (b->registroSalaId >= 100) ? "MEMÓRIA" : "ARQUIVO DE AMEAÇA";
        DrawText(nome, (int)b->posRegistroSala.x - MeasureText(nome, 10) / 2, (int)b->posRegistroSala.y + 26, 10,
                 b->registroSalaLido ? GRAY : ((b->registroSalaId >= 100) ? MAGENTA : (Color){ 0, 228, 255, 255 }));
    }

    // Recompensa no chão
    if (b->recompensaAtiva) {
        Vector2 c = { b->recompensaPos.x, b->recompensaPos.y + sinf(tempo * 3.0f) * 3.0f };
        Color cor = (b->recompensaTipo == RECOMPENSA_RARA) ? GOLD : ((b->recompensaTipo == RECOMPENSA_ARMA) ? ORANGE :
                    ((b->recompensaTipo == RECOMPENSA_VIDA) ? LIME : (Color){ 0, 228, 255, 255 }));
        DrawCircleV(c, 24, Fade(cor, 0.12f + 0.06f * sinf(tempo * 4.0f)));
        DrawRing(c, 17, 20, tempo * 120.0f, tempo * 120.0f + 270.0f, 24, cor);
        DrawCircleV(c, 13, Fade(BLACK, 0.7f));
        DesenharIconeRecompensa(b->recompensaTipo, c, 1.5f, tempo);
        const char *nome = (b->recompensaTipo == RECOMPENSA_MELHORIA) ? "NÚCLEO DE MELHORIA" :
                           (b->recompensaTipo == RECOMPENSA_RARA)     ? "NÚCLEO RARO" : NOMES_RECOMPENSA[b->recompensaTipo];
        DrawText(nome, (int)c.x - MeasureText(nome, 10) / 2, (int)c.y + 26, 10, cor);
    }
}

// Mini-mapa no canto de cima: as camadas da esquerda para a direita
static Vector2 RoguePosMiniMapa(const Biblioteca *b, const NoMapa *n)
{
    float y = 7.0f + n->x * 28.0f;
    if (n->tipo == SALA_SECRETA && n->pai >= 0) y = 7.0f + b->mapa.no[n->pai].x * 28.0f + 6.0f;
    return (Vector2){ 12.0f + (float)n->prof * 8.2f + ((n->tipo == SALA_SECRETA) ? 4.0f : 0.0f), y };
}

static void DesenharMiniMapa(const Biblioteca *b, float tempo)
{
    const MapaRogue *m = &b->mapa;
    const NoMapa *atual = &m->no[b->noAtual];

    DrawRectangle(4, 2, 138, 38, Fade(BLACK, 0.6f));
    DrawRectangleLines(4, 2, 138, 38, Fade(PURPLE, 0.6f));

    for (int i = 0; i < m->numNos; i++) {
        const NoMapa *n = &m->no[i];
        if (n->escondida) continue;
        Vector2 a = RoguePosMiniMapa(b, n);
        for (int k = 0; k < n->numSaidas; k++) {
            const NoMapa *d = &m->no[n->saida[k]];
            bool caminho = n->visitado && d->visitado;
            DrawLineEx(a, RoguePosMiniMapa(b, d), 1, Fade(caminho ? WHITE : GRAY, caminho ? 0.7f : 0.25f));
        }
    }

    for (int i = 0; i < m->numNos; i++) {
        const NoMapa *n = &m->no[i];
        if (n->escondida) continue;

        Vector2 p = RoguePosMiniMapa(b, n);
        Color cor = CORES_SALAS_ROGUE[n->tipo];
        float lado = (n->tipo == SALA_CHEFE) ? 8.0f : ((n->tipo == SALA_SECRETA) ? 4.0f : ((n->tipo == SALA_ESPECIAL) ? 7.0f : 5.0f));
        Rectangle r = { p.x - lado / 2, p.y - lado / 2, lado, lado };

        bool proxima = false;
        for (int k = 0; k < atual->numSaidas; k++) if (atual->saida[k] == i) proxima = true;

        if (n->visitado) DrawRectangleRec(r, Fade(cor, (i == b->noAtual) ? 1.0f : 0.45f));
        DrawRectangleLinesEx(r, 1, proxima ? Fade(cor, 0.6f + 0.4f * sinf(tempo * 6.0f)) : Fade(cor, n->visitado ? 0.9f : 0.45f));

        if (i == b->noAtual)
            DrawRectangleLinesEx((Rectangle){ r.x - 2, r.y - 2, r.width + 4, r.height + 4 }, 1, Fade(WHITE, 0.6f + 0.4f * sinf(tempo * 5.0f)));
    }
}

// Mapa grande (M): o caminho todo, as recompensas das próximas portas e a build
static void DesenharMapaGrande(const Biblioteca *b, float tempo)
{
    const MapaRogue *m = &b->mapa;
    const NoMapa *atual = &m->no[b->noAtual];

    DrawRectangle(0, 0, LARGURA_TELA, ALTURA_TELA, Fade(BLACK, 0.75f));
    Rectangle painel = { 30, 30, 740, 520 };
    DrawRectangleRec(painel, (Color){ 16, 13, 28, 255 });
    DrawRectangleLinesEx(painel, 3, PURPLE);
    DrawText("MAPA DA BIBLIOTECA", (int)painel.x + 20, (int)painel.y + 14, 22, (Color){ 200, 122, 255, 255 });
    DrawText(TextFormat("Tentativa %d  -  sala %d", b->perm->tentativas, b->indiceRota + 1), (int)painel.x + 20, (int)painel.y + 40, 12, GRAY);

    // Grafo: de baixo (entrada) para cima (Alucinador)
    Rectangle area = { painel.x + 20, painel.y + 62, 430, 420 };
    DrawRectangleRec(area, Fade((Color){ 30, 24, 50, 255 }, 0.6f));

    #define POS_NO(n) ((Vector2){ area.x + 40.0f + (n)->x * (area.width - 80.0f) + (((n)->tipo == SALA_SECRETA) ? 34.0f : 0.0f), \
                                  area.y + area.height - 20.0f - (float)(n)->prof * ((area.height - 40.0f) / (float)PROF_CHEFE) - (((n)->tipo == SALA_SECRETA) ? 11.0f : 0.0f) })

    for (int i = 0; i < m->numNos; i++) {
        const NoMapa *n = &m->no[i];
        if (n->escondida) continue;
        Vector2 a = POS_NO(n);
        for (int k = 0; k < n->numSaidas; k++) {
            const NoMapa *d = &m->no[n->saida[k]];
            if (d->escondida) continue;
            bool caminho = n->visitado && d->visitado;
            bool opcao = (i == b->noAtual);
            DrawLineEx(a, POS_NO(d), caminho ? 3.0f : 2.0f, opcao ? Fade(GOLD, 0.8f) : Fade(caminho ? WHITE : GRAY, caminho ? 0.8f : 0.3f));
        }
        if (n->tipo == SALA_SECRETA && n->pai >= 0) {
            Vector2 pai = POS_NO(&m->no[n->pai]);
            for (int s = 0; s < 6; s++) {
                Vector2 q0 = Vector2Lerp(pai, a, (float)s / 6.0f), q1 = Vector2Lerp(pai, a, ((float)s + 0.5f) / 6.0f);
                DrawLineEx(q0, q1, 2, Fade(CORES_SALAS_ROGUE[SALA_SECRETA], 0.8f));
            }
        }
    }

    for (int i = 0; i < m->numNos; i++) {
        const NoMapa *n = &m->no[i];
        if (n->escondida) continue;

        Vector2 c = POS_NO(n);
        Color cor = CORES_SALAS_ROGUE[n->tipo];
        float raio = (n->tipo == SALA_CHEFE) ? 14.0f : ((n->tipo == SALA_SILOGISTA || n->tipo == SALA_ESPECIAL) ? 12.0f : 10.0f);
        bool proxima = false;
        for (int k = 0; k < atual->numSaidas; k++) if (atual->saida[k] == i) proxima = true;

        DrawCircleV(c, raio, n->visitado ? Fade(cor, 0.35f) : (Color){ 20, 16, 34, 255 });
        DrawCircleLines((int)c.x, (int)c.y, raio, proxima ? GOLD : Fade(cor, n->visitado ? 1.0f : 0.6f));
        DesenharIconeSala(n->tipo, c, (n->tipo == SALA_CHEFE) ? 0.8f : 0.55f, tempo);

        if (i == b->noAtual)
            DrawCircleLines((int)c.x, (int)c.y, raio + 5 + 2 * sinf(tempo * 5.0f), WHITE);

        // Recompensa: só das próximas salas (dá para planejar, mas não tudo)
        if (proxima && n->recompensa != RECOMPENSA_NENHUMA) {
            Vector2 rc = { c.x + raio, c.y - raio + 2 };
            DrawCircleV(rc, 8, Fade(BLACK, 0.85f));
            DesenharIconeRecompensa(n->recompensa, rc, 0.8f, tempo);
        }
        if (proxima || n->tipo == SALA_CHEFE || n->tipo == SALA_SILOGISTA || n->tipo == SALA_ESPECIAL) {
            const char *nome = RoguePlacaNo(n);
            DrawText(nome, (int)(c.x + raio + 4), (int)c.y - 5, 10, proxima ? GOLD : cor);      // ao lado (as camadas ficaram próximas)
        }
    }
    #undef POS_NO

    // A build desta tentativa
    int x = (int)(area.x + area.width) + 18, y = (int)area.y;
    DrawText("SUA BUILD", x, y, 16, GOLD);
    y += 22;
    DesenharIconeArma(RogueArmaAtual(&b->j), (Vector2){ (float)x + 8, (float)y + 6 }, 0.7f, tempo);
    DrawText((b->j.armaExtra != ARMA_DISPARADOR) ? DEF_ARMAS[b->j.armaExtra].nome : "Só o Disparador", x + 20, y + 1, 10, WHITE);
    y += 18;

    int linhas = 0;
    for (int u = 0; u < NUM_UPGRADES && y < (int)(painel.y + painel.height) - 108; u++) {
        if (b->j.up[u] <= 0) continue;
        Color c = CORES_RARIDADE[UPGRADES[u].raridade];
        DrawRectangle(x, y + 2, 6, 6, CORES_CATEGORIA_UP[UPGRADES[u].categoria]);
        DrawText(TextFormat("%s %s", UPGRADES[u].nome, (UPGRADES[u].maxNivel > 1) ? TextFormat("%d/%d", b->j.up[u], UPGRADES[u].maxNivel) : ""), x + 10, y, 10, c);
        y += 13;
        linhas++;
    }
    for (int i = PRIMEIRO_UPGRADE; i < NUM_ITENS && y < (int)(painel.y + painel.height) - 108; i++) {
        if (b->j.itens[i] <= 0) continue;
        DrawText(TextFormat("%s x%d", ITENS[i].nome, RogueQtd(&b->j, (TipoItem)i)), x + 10, y, 10, LIGHTGRAY);
        y += 13;
        linhas++;
    }
    if (linhas == 0) { DrawText("Nenhuma melhoria ainda.", x, y, 10, GRAY); y += 13; }

    for (int p = 0; p < 3; p++)
        if (b->j.penalidade & (1 << p)) { DrawText(TextFormat("! %s", NOMES_PENALIDADE[p]), x, y, 10, RED); y += 13; }

    // Legenda
    static const TipoSalaRogue legenda[] = { SALA_COMBATE, SALA_ELITE, SALA_EDUCATIVA, SALA_EVENTO, SALA_DESCANSO, SALA_DESAFIO, SALA_RECOMPENSA, SALA_SECRETA,
                                             SALA_LABORATORIO, SALA_ESPECIAL };
    int ly = (int)(painel.y + painel.height) - 100;
    for (int i = 0; i < 10; i++) {
        int lx = x + (i % 2) * 130, yy = ly + (i / 2) * 18;
        DesenharIconeSala(legenda[i], (Vector2){ (float)lx + 7, (float)yy + 6 }, 0.5f, tempo);
        DrawText(PLACAS_SALAS_ROGUE[legenda[i]], lx + 18, yy + 1, 10, CORES_SALAS_ROGUE[legenda[i]]);
    }

    const char *ajuda = "Portas douradas: as próximas salas.   M, ENTER ou CLIQUE - fechar";
    DrawText(ajuda, LARGURA_TELA / 2 - MeasureText(ajuda, 10) / 2, (int)(painel.y + painel.height) - 16, 10, GRAY);

    DesenharBotaoFechar((Rectangle){ painel.x + painel.width - 36, painel.y + 10, 26, 22 }, PURPLE);
}

// Ícone da categoria da melhoria (cartas e HUD)
static void DesenharIconeUpgrade(const Biblioteca *b, OpcaoEscolha o, Vector2 c, float e, float tempo)
{
    if (o.tipo == OPC_ITEM)       { DesenharIconeItem((TipoItem)o.id, c, e, tempo); return; }
    if (o.tipo == OPC_ARMA)       { DesenharIconeArma((TipoArma)o.id, c, e * 1.2f, tempo); return; }
    if (o.tipo == OPC_FRAGMENTOS) { DesenharFragmentoConhecimento(c, tempo); return; }

    const DefUpgrade *d = &UPGRADES[o.id];
    Color cor = CORES_CATEGORIA_UP[d->categoria];
    (void)b;

    switch (d->categoria) {
        case CAT_ATRIBUTO:
            DrawTriangle((Vector2){ c.x, c.y - 12 * e }, (Vector2){ c.x - 9 * e, c.y }, (Vector2){ c.x + 9 * e, c.y }, cor);
            DrawRectangleV((Vector2){ c.x - 4 * e, c.y }, (Vector2){ 8 * e, 10 * e }, cor);
            break;
        case CAT_DISPARO:
            for (int k = 0; k < 3; k++)
                DrawCircleV((Vector2){ c.x - 8 * e + k * 8 * e, c.y + ((k == 1) ? -4.0f : 4.0f) * e }, 4 * e, cor);
            DrawLineEx((Vector2){ c.x - 12 * e, c.y + 10 * e }, (Vector2){ c.x + 12 * e, c.y - 10 * e }, 2, Fade(WHITE, 0.6f));
            break;
        case CAT_HABILIDADE:      // raio
            DrawTriangle((Vector2){ c.x + 2 * e, c.y - 13 * e }, (Vector2){ c.x - 8 * e, c.y + 2 * e }, (Vector2){ c.x + 1 * e, c.y + 2 * e }, cor);
            DrawTriangle((Vector2){ c.x - 1 * e, c.y - 2 * e }, (Vector2){ c.x - 2 * e, c.y + 13 * e }, (Vector2){ c.x + 8 * e, c.y - 2 * e }, cor);
            break;
        case CAT_ESPECIAL:
            DrawPoly(c, 5, 12 * e, tempo * 40.0f, cor);
            DrawPoly(c, 5, 6 * e, -tempo * 40.0f, WHITE);
            break;
        case CAT_APRIMORAMENTO:
            DesenharIconeArma((d->arma >= 0) ? (TipoArma)d->arma : ARMA_DISPARADOR, c, e * 1.2f, tempo);
            DrawCircleLines((int)c.x, (int)c.y, 14 * e, cor);
            break;
        default:                  // sinergia: dois anéis entrelaçados
            DrawRing((Vector2){ c.x - 5 * e, c.y }, 6 * e, 9 * e, 0, 360, 24, cor);
            DrawRing((Vector2){ c.x + 5 * e, c.y }, 6 * e, 9 * e, 0, 360, 24, WHITE);
            break;
    }
}

// A tela "escolha 1 de 3": cartas com nome, raridade, categoria, nível, efeito e pré-requisitos
static void DesenharEscolha(const Biblioteca *b, float tempo)
{
    DrawRectangle(0, 0, LARGURA_TELA, ALTURA_TELA, Fade(BLACK, 0.72f));

    const char *titulo = (b->modoEscolha == ESCOLHA_RARA) ? "MELHORIA RARA: ESCOLHA UMA"
                       : (b->modoEscolha == ESCOLHA_ARMA) ? "ARSENAL: ESCOLHA UMA" : "ESCOLHA UMA MELHORIA";
    DrawText(titulo, LARGURA_TELA / 2 - MeasureText(titulo, 24) / 2, 70, 24, GOLD);
    const char *sub = "Ela vale até o fim desta tentativa. Combine melhorias para abrir SINERGIAS.";
    DrawText(sub, LARGURA_TELA / 2 - MeasureText(sub, 12) / 2, 100, 12, LIGHTGRAY);

    float entrada = fminf(1.0f, b->animEscolha / 0.3f);

    for (int i = 0; i < b->numOpcoes; i++) {

        OpcaoEscolha o = b->opcoes[i];
        Rectangle r = RogueCartaEscolha(i, b->numOpcoes);
        bool marcada = (i == b->selecaoEscolha);
        r.y += (1.0f - entrada) * 60.0f - (marcada ? 8.0f : 0.0f);

        const char *nome, *efeito, *categoria;
        Raridade rar;
        Color corCat;
        char nivel[48] = "", requisito[120] = "";

        if (o.tipo == OPC_UPGRADE) {
            const DefUpgrade *d = &UPGRADES[o.id];
            nome = d->nome; efeito = d->efeito; rar = d->raridade;
            categoria = NOMES_CATEGORIA_UP[d->categoria]; corCat = CORES_CATEGORIA_UP[d->categoria];
            if (b->j.up[o.id] == 0 && d->maxNivel > 1) snprintf(nivel, sizeof(nivel), "NOVA  (máx. %d)", d->maxNivel);
            else if (b->j.up[o.id] == 0)                snprintf(nivel, sizeof(nivel), "NOVA");
            else                    snprintf(nivel, sizeof(nivel), "NÍVEL %d -> %d  (máx. %d)", b->j.up[o.id], b->j.up[o.id] + 1, d->maxNivel);

            if (d->categoria == CAT_SINERGIA) {
                int a = -1, c2 = -1;
                for (int k = 0; k < NUM_UPGRADES; k++)
                    if (d->requer & BIT_UP(k)) { if (a < 0) a = k; else c2 = k; }
                snprintf(requisito, sizeof(requisito), "COMBINA: %s + %s", (a >= 0) ? UPGRADES[a].nome : "?", (c2 >= 0) ? UPGRADES[c2].nome : "?");
            } else if (d->arma >= 0) {
                snprintf(requisito, sizeof(requisito), "REQUER: %s", DEF_ARMAS[d->arma].nome);
            } else {
                snprintf(requisito, sizeof(requisito), "Sem pré-requisitos");
            }
        } else if (o.tipo == OPC_ITEM) {
            nome = ITENS[o.id].nome; efeito = ITENS[o.id].efeito; rar = ITENS[o.id].raridade;
            categoria = "UPGRADE PASSIVO"; corCat = (Color){ 0, 228, 255, 255 };
            snprintf(nivel, sizeof(nivel), "TEM %d DE %d", b->j.itens[o.id], ITENS[o.id].maxPilha);
            snprintf(requisito, sizeof(requisito), "Sem pré-requisitos");
        } else if (o.tipo == OPC_ARMA) {
            nome = DEF_ARMAS[o.id].nome; efeito = DEF_ARMAS[o.id].efeito; rar = DEF_ARMAS[o.id].raridade;
            categoria = "ARMA"; corCat = DEF_ARMAS[o.id].cor;
            snprintf(nivel, sizeof(nivel), "%s", NOMES_ALCANCE[DEF_ARMAS[o.id].alcanceTipo]);
            if (b->j.armaExtra != ARMA_DISPARADOR) snprintf(requisito, sizeof(requisito), "SUBSTITUI: %s", DEF_ARMAS[b->j.armaExtra].nome);
            else                                   snprintf(requisito, sizeof(requisito), "Vira a sua arma extra (TAB)");
        } else {
            nome = "RESERVA DE CONHECIMENTO"; efeito = "Não há melhorias novas para você agora: leve Fragmentos de Conhecimento.";
            rar = RARIDADE_COMUM; categoria = "FRAGMENTOS"; corCat = (Color){ 0, 228, 255, 255 };
            snprintf(nivel, sizeof(nivel), "+%d FRAGMENTOS", FC_OPCAO_RESERVA);
        }

        Color corRar = CORES_RARIDADE[rar];
        if (marcada)
            DrawRectangleRec((Rectangle){ r.x - 6, r.y - 6, r.width + 12, r.height + 12 }, Fade(corRar, 0.18f + 0.08f * sinf(tempo * 5.0f)));
        DrawRectangleRec(r, (Color){ 20, 16, 34, 255 });
        DrawRectangleLinesEx(r, marcada ? 3.0f : 2.0f, marcada ? corRar : Fade(corRar, 0.6f));

        // Faixa da categoria
        DrawRectangle((int)r.x, (int)r.y, (int)r.width, 20, Fade(corCat, 0.25f));
        DrawText(categoria, (int)r.x + 8, (int)r.y + 5, 10, corCat);
        DrawText(TextFormat("[%d]", i + 1), (int)(r.x + r.width) - 26, (int)r.y + 5, 10, GRAY);

        // Ícone
        Vector2 ic = { r.x + r.width / 2, r.y + 58 };
        DrawCircleV(ic, 26, Fade(corCat, 0.15f));
        DrawCircleLines((int)ic.x, (int)ic.y, 26, Fade(corRar, 0.8f));
        DesenharIconeUpgrade(b, o, ic, 1.1f, tempo);

        // Nome, raridade e nível
        char linhas[256];
        QuebrarTexto(nome, (int)r.width - 20, 16, linhas, (int)sizeof(linhas));
        int ny = (int)r.y + 94;
        int n = DesenharTextoLinhas(linhas, (int)r.x + 10, ny, 16, 18, marcada ? YELLOW : WHITE);
        ny += n * 18 + 2;
        DrawText(NOMES_RARIDADE[rar], (int)r.x + 10, ny, 10, corRar);
        DrawText(nivel, (int)r.x + 10 + MeasureText(NOMES_RARIDADE[rar], 10) + 10, ny, 10, LIGHTGRAY);
        ny += 18;

        // Efeito
        QuebrarTexto(efeito, (int)r.width - 20, 12, linhas, (int)sizeof(linhas));
        DesenharTextoLinhas(linhas, (int)r.x + 10, ny, 12, 15, (Color){ 220, 220, 230, 255 });

        // Pré-requisitos
        if (requisito[0]) {
            QuebrarTexto(requisito, (int)r.width - 20, 10, linhas, (int)sizeof(linhas));
            int nl = ContarLinhas(linhas);
            DrawLine((int)r.x + 10, (int)(r.y + r.height) - 16 - nl * 12, (int)(r.x + r.width) - 10, (int)(r.y + r.height) - 16 - nl * 12, Fade(corRar, 0.3f));
            DesenharTextoLinhas(linhas, (int)r.x + 10, (int)(r.y + r.height) - 10 - nl * 12, 10, 12,
                                (o.tipo == OPC_UPGRADE && UPGRADES[o.id].categoria == CAT_SINERGIA) ? CORES_CATEGORIA_UP[CAT_SINERGIA] : GRAY);
        }
    }

    const char *ajuda = TextFormat("A/D, 1-3 ou mouse: escolher     E / clique: confirmar     BACKSPACE: recusar (+%d FC)", FC_RECUSAR_ESCOLHA);
    DrawText(ajuda, LARGURA_TELA / 2 - MeasureText(ajuda, 10) / 2, 462, 10, GRAY);

    // Recusar também com o mouse (o mesmo que BACKSPACE)
    DesenharBotaoMenu(RET_RECUSAR_ESCOLHA, TextFormat("RECUSAR (+%d FC)", FC_RECUSAR_ESCOLHA), 12, GOLD, false);
}

// Janela dos eventos (o mesmo visual do desafio educativo)
static void DesenharEvento(const Biblioteca *b, float tempo)
{
    TelaEvento t;
    RogueMontarTelaEvento(b, &t);

    DrawRectangle(0, 0, LARGURA_TELA, ALTURA_TELA, Fade(BLACK, 0.65f));
    Rectangle painel = { 70, 80, 660, 420 };
    Color cor = CORES_SALAS_ROGUE[b->tipoSala];
    DrawRectangleRec(painel, (Color){ 18, 15, 30, 255 });
    DrawRectangleLinesEx(painel, 4, cor);

    int x = (int)painel.x + 24, y = (int)painel.y + 18;
    DesenharIconeSala(b->tipoSala, (Vector2){ (float)x + 12, (float)y + 10 }, 1.0f, tempo);
    DrawText(t.titulo, x + 34, y, 22, cor);
    y += 40;

    char linhas[640];
    QuebrarTexto(b->eventoResolvido ? b->resultadoEvento : t.texto, (int)painel.width - 48, 16, linhas, (int)sizeof(linhas));
    int n = DesenharTextoLinhas(linhas, x, y, 16, 22, WHITE);
    y += n * 22 + 18;

    if (b->eventoResolvido) {
        if (((int)(tempo * 2.0f)) % 2 == 0)
            DesenharDicaAvancar((int)(painel.x + painel.width) - 90, (int)(painel.y + painel.height) - 28, 14);
        return;
    }

    DesenharBotaoFechar(RET_FECHAR_EVENTO, cor);

    for (int i = 0; i < t.numOpcoes; i++) {
        bool marcada = (i == b->selecaoEvento);
        bool pode = t.disponivel[i];
        Color corOp = !pode ? DARKGRAY : (marcada ? YELLOW : WHITE);

        QuebrarTexto(TextFormat("%d) %s", i + 1, t.rotulo[i]), (int)painel.width - 90, 16, linhas, (int)sizeof(linhas));
        int nr = ContarLinhas(linhas);
        char ef[300] = "";
        if (t.efeito[i][0]) QuebrarTexto(t.efeito[i], (int)painel.width - 100, 12, ef, (int)sizeof(ef));
        int ne = ef[0] ? ContarLinhas(ef) : 0;
        int alt = nr * 20 + ne * 15 + 10;

        if (marcada) {
            DrawRectangle(x - 10, y - 5, (int)painel.width - 28, alt, Fade(cor, 0.15f));
            DesenharCoracao((float)x, (float)y + 8, 2, RED);
        }
        DesenharTextoLinhas(linhas, x + 18, y, 16, 20, corOp);
        if (ne > 0) DesenharTextoLinhas(ef, x + 30, y + nr * 20, 12, 15, pode ? LIGHTGRAY : DARKGRAY);
        if (!pode)  DrawText("(indisponível)", (int)(painel.x + painel.width) - 120, y + 2, 10, RED);
        y += alt + 6;
    }

    const char *ajuda = "W/S ou MOUSE escolher     E / CLIQUE confirmar     BACKSPACE ou X sair";
    DrawText(ajuda, LARGURA_TELA / 2 - MeasureText(ajuda, 10) / 2, (int)(painel.y + painel.height) - 20, 10, GRAY);
}


// =============================================================
// EXPANSÃO EDUCATIVA DO BLOCO 2: DESENHO DOS LABORATÓRIOS
// =============================================================

// Ícone de cada categoria (console da sala e janela). e = escala (1 = cerca de 24 px)
static void DesenharIconeLab(TipoLab t, Vector2 c, float e, float tempo)
{
    Color cor = CORES_LAB[t];

    switch (t) {
        case LAB_PROMPTS:       // balão de conversa com o cursor do terminal
            DrawRectangleRounded((Rectangle){ c.x - 11 * e, c.y - 8 * e, 22 * e, 14 * e }, 0.3f, 6, Fade(cor, 0.9f));
            DrawTriangle((Vector2){ c.x - 6 * e, c.y + 6 * e }, (Vector2){ c.x - 8 * e, c.y + 11 * e }, (Vector2){ c.x - 1 * e, c.y + 6 * e }, Fade(cor, 0.9f));
            DrawText(">_", (int)(c.x - 7 * e), (int)(c.y - 6 * e), (int)fmaxf(8.0f, 10 * e), (Color){ 10, 20, 40, 255 });
            if (((int)(tempo * 2.0f)) % 2 == 0) DrawRectangle((int)(c.x + 5 * e), (int)(c.y - 4 * e), (int)fmaxf(1.0f, 3 * e), (int)fmaxf(2.0f, 7 * e), (Color){ 10, 20, 40, 255 });
            break;
        case LAB_ARQUIVO:       // documento com uma linha corrompida
            DrawRectangleV((Vector2){ c.x - 8 * e, c.y - 10 * e }, (Vector2){ 16 * e, 20 * e }, Fade(WHITE, 0.85f));
            for (int k = 0; k < 4; k++)
                DrawRectangleV((Vector2){ c.x - 5 * e, c.y - 6 * e + k * 4 * e }, (Vector2){ (k == 2 ? 6 : 10) * e, 1.5f * e }, (Color){ 60, 60, 80, 255 });
            DrawRectangleV((Vector2){ c.x - 6 * e + sinf(tempo * 9.0f) * 2 * e, c.y + 1 * e }, (Vector2){ 12 * e, 2 * e }, cor);
            break;
        case LAB_NUCLEO:        // núcleo com dados em órbita
            DrawCircleV(c, 6 * e, cor);
            DrawCircleLines((int)c.x, (int)c.y, 10 * e, Fade(cor, 0.7f));
            for (int k = 0; k < 3; k++) {
                float a = tempo * 2.0f + k * 2.1f;
                DrawCircleV((Vector2){ c.x + cosf(a) * 10 * e, c.y + sinf(a) * 10 * e }, 2 * e, WHITE);
            }
            break;
        case LAB_FIREWALL:      // escudo
            DrawTriangle((Vector2){ c.x - 10 * e, c.y - 8 * e }, (Vector2){ c.x, c.y + 12 * e }, (Vector2){ c.x + 10 * e, c.y - 8 * e }, cor);
            DrawRectangleV((Vector2){ c.x - 10 * e, c.y - 11 * e }, (Vector2){ 20 * e, 4 * e }, cor);
            DrawLineEx((Vector2){ c.x, c.y - 9 * e }, (Vector2){ c.x, c.y + 8 * e }, 2 * e, (Color){ 10, 40, 20, 255 });
            break;
        default:                // lupa
            DrawCircleLines((int)(c.x - 2 * e), (int)(c.y - 2 * e), 7 * e, cor);
            DrawCircleLines((int)(c.x - 2 * e), (int)(c.y - 2 * e), 6 * e, cor);
            DrawLineEx((Vector2){ c.x + 3 * e, c.y + 3 * e }, (Vector2){ c.x + 10 * e, c.y + 10 * e }, 3 * e, cor);
            break;
    }
}

// Console do laboratório na sala (holograma da categoria)
static void DesenharConsoleLab(const Biblioteca *b, float tempo)
{
    const LabEdu *L = &b->lab;
    Vector2 c = b->posObjetoSala;
    Color cor = CORES_LAB[L->tipo];
    float k = L->concluido ? 0.4f : 1.0f;
    float flutua = sinf(tempo * 2.0f) * 3.0f;

    DrawEllipse((int)c.x, (int)c.y + 22, 40, 10, Fade(cor, 0.15f * k));
    DrawRectangle((int)c.x - 24, (int)c.y - 2, 48, 22, Fade((Color){ 30, 26, 50, 255 }, k));
    DrawRectangleLines((int)c.x - 24, (int)c.y - 2, 48, 22, Fade(cor, 0.8f * k));
    for (int i = 0; i < 3; i++)
        DrawRectangle((int)c.x - 18, (int)c.y + 3 + i * 5, 10 + (int)(Ruido((unsigned int)(tempo * 3.0f) + (unsigned int)i) % 26), 2, Fade(cor, 0.7f * k));

    if (!L->concluido) {
        // Feixe e holograma
        DrawTriangle((Vector2){ c.x - 14, c.y - 2 }, (Vector2){ c.x + 14, c.y - 2 }, (Vector2){ c.x, c.y - 30 + flutua }, Fade(cor, 0.12f));
        DrawCircleV((Vector2){ c.x, c.y - 34 + flutua }, 18, Fade(cor, 0.18f + 0.06f * sinf(tempo * 4.0f)));
        DesenharIconeLab(L->tipo, (Vector2){ c.x, c.y - 34 + flutua }, 1.0f, tempo);
    } else {
        DrawText("OK", (int)c.x - MeasureText("OK", 10) / 2, (int)c.y + 5, 10, Fade(LIME, 0.8f));
    }

    const char *nome = NOMES_LAB[L->tipo];
    DrawText(nome, (int)c.x - MeasureText(nome, 10) / 2, (int)c.y + 30, 10, Fade(cor, k));
    if (LAB_ESPECIAL[L->tipo] && !L->concluido) {
        const char *t = "OPCIONAL";
        DrawText(t, (int)c.x - MeasureText(t, 8) / 2, (int)c.y + 42, 8, GOLD);
    }
}

static void DesenharPipsLab(float x, float y, int n, Color cor)
{
    for (int i = 0; i < n; i++)
        DrawCircleV((Vector2){ x + i * 8.0f, y }, 2.5f, cor);
}

// Ícone de cada peça do pedido: PAPEL (uma pessoa), CONTEXTO (o público), OBJETIVO (um alvo), FORMATO (uma lista)
static void DesenharIconeParte(int k, Vector2 c, float e, Color cor)
{
    switch (k) {
        case PP_PAPEL:
            DrawCircleV((Vector2){ c.x, c.y - 4 * e }, 4 * e, cor);
            DrawRectangleRounded((Rectangle){ c.x - 6 * e, c.y + 1 * e, 12 * e, 7 * e }, 0.6f, 4, cor);
            break;
        case PP_CONTEXTO:
            DrawCircleV((Vector2){ c.x - 4.5f * e, c.y - 3 * e }, 3 * e, cor);
            DrawCircleV((Vector2){ c.x + 4.5f * e, c.y - 3 * e }, 3 * e, cor);
            DrawRectangleRounded((Rectangle){ c.x - 8.5f * e, c.y + 1 * e, 8 * e, 6 * e }, 0.6f, 4, cor);
            DrawRectangleRounded((Rectangle){ c.x + 0.5f * e, c.y + 1 * e, 8 * e, 6 * e }, 0.6f, 4, cor);
            break;
        case PP_OBJETIVO:
            DrawCircleLines((int)c.x, (int)c.y, 7.5f * e, cor);
            DrawCircleLines((int)c.x, (int)c.y, 4.5f * e, cor);
            DrawCircleV(c, 1.8f * e, cor);
            break;
        default:
            for (int i = 0; i < 3; i++) {
                float y = c.y + (float)(i - 1) * 4.5f * e;
                DrawRectangle((int)(c.x - 7 * e), (int)(y - e), (int)fmaxf(2.0f, 2 * e), (int)fmaxf(2.0f, 2 * e), cor);
                DrawRectangle((int)(c.x - 3 * e), (int)(y - e), (int)(10 * e), (int)fmaxf(2.0f, 2 * e), cor);
            }
            break;
    }
}

// Borda tracejada (encaixe vazio)
static void DesenharBordaTracejada(Rectangle r, Color cor)
{
    for (float x = r.x; x < r.x + r.width; x += 10.0f) {
        float w = fminf(5.0f, r.x + r.width - x);
        DrawRectangle((int)x, (int)r.y, (int)w, 1, cor);
        DrawRectangle((int)x, (int)(r.y + r.height) - 1, (int)w, 1, cor);
    }
    for (float y = r.y; y < r.y + r.height; y += 10.0f) {
        float h = fminf(5.0f, r.y + r.height - y);
        DrawRectangle((int)r.x, (int)y, 1, (int)h, cor);
        DrawRectangle((int)(r.x + r.width) - 1, (int)y, 1, (int)h, cor);
    }
}

// ECO-1, a IA simulada do laboratório. humor: 0 neutro, 1 satisfeito, 2 confuso, 3 em erro
static void DesenharEco1(Vector2 c, int humor, float tempo)
{
    Color ciano = { 0, 228, 255, 255 };
    Color olho = (humor == 3) ? MAGENTA : ciano;

    DrawLineEx((Vector2){ c.x, c.y - 16 }, (Vector2){ c.x, c.y - 25 }, 2.0f, ciano);
    DrawCircleV((Vector2){ c.x, c.y - 27 }, 3, (((int)(tempo * 3.0f)) % 2 == 0) ? GOLD : Fade(GOLD, 0.4f));
    DrawRectangleRounded((Rectangle){ c.x - 26, c.y - 17, 52, 34 }, 0.35f, 6, Fade(olho, 0.8f));
    DrawRectangleRounded((Rectangle){ c.x - 24, c.y - 15, 48, 30 }, 0.35f, 6, (Color){ 26, 34, 70, 255 });
    DrawRectangle((int)c.x - 14, (int)c.y + 17, 28, 5, (Color){ 46, 40, 90, 255 });

    switch (humor) {
        case 1:         // ^ ^
            for (int s = -1; s <= 1; s += 2) {
                float ex = c.x + s * 10.0f;
                DrawLineEx((Vector2){ ex - 5, c.y - 1 }, (Vector2){ ex, c.y - 6 }, 2.0f, olho);
                DrawLineEx((Vector2){ ex, c.y - 6 }, (Vector2){ ex + 5, c.y - 1 }, 2.0f, olho);
            }
            break;
        case 2:         // um olho e uma dúvida
            DrawCircleV((Vector2){ c.x - 10, c.y - 3 }, 3, olho);
            DrawText("?", (int)c.x + 6, (int)c.y - 11, 14, GOLD);
            break;
        case 3:         // X X (com tremida)
            for (int s = -1; s <= 1; s += 2) {
                float ex = c.x + s * 10.0f + (float)GetRandomValue(-1, 1);
                DrawLineEx((Vector2){ ex - 4, c.y - 7 }, (Vector2){ ex + 4, c.y + 1 }, 2.0f, olho);
                DrawLineEx((Vector2){ ex + 4, c.y - 7 }, (Vector2){ ex - 4, c.y + 1 }, 2.0f, olho);
            }
            break;
        default:
            for (int s = -1; s <= 1; s += 2) {
                if (fmodf(tempo, 3.2f) < 0.12f) DrawRectangle((int)c.x + s * 10 - 3, (int)c.y - 3, 6, 2, olho);   // piscando
                else                            DrawCircleV((Vector2){ c.x + s * 10.0f, c.y - 3 }, 3, olho);
            }
            break;
    }
    DrawRectangle((int)c.x - 8, (int)c.y + 7, 16, 2, Fade(olho, 0.7f));
}

// O que a resposta virou (carimbo do holograma), por diagnóstico
static const char *CARIMBOS_DIAG[NUM_DIAG_PROMPT] = {
    "NA MEDIDA!", "QUASE LÁ", "GENÉRICA\nDEMAIS", "PÚBLICO\nERRADO", "PAPEL\nERRADO", "FORMATO\nRUIM", "PEDIDO\nCONTRADITÓRIO"
};
static const Color CORES_DIAG[NUM_DIAG_PROMPT] = {
    { 255, 203, 0, 255 }, { 0, 228, 48, 255 }, { 150, 150, 170, 255 }, { 255, 161, 0, 255 },
    { 255, 161, 0, 255 }, { 255, 161, 0, 255 }, { 255, 0, 255, 255 }
};

static void DesenharPictogramaDiag(DiagPrompt d, Vector2 c, float tempo)
{
    Color cd = CORES_DIAG[d];

    if (d == DIAG_IDEAL || d == DIAG_BOA) {
        DrawCircleLines((int)c.x, (int)c.y, 20, cd);
        if (d == DIAG_IDEAL) DrawCircleLines((int)c.x, (int)c.y, 23, Fade(cd, 0.5f + 0.5f * sinf(tempo * 5.0f)));
        DrawLineEx((Vector2){ c.x - 10, c.y + 1 }, (Vector2){ c.x - 3, c.y + 9 }, 4.0f, cd);
        DrawLineEx((Vector2){ c.x - 3, c.y + 9 }, (Vector2){ c.x + 11, c.y - 8 }, 4.0f, cd);
        return;
    }
    if (d == DIAG_CONTRADICAO) {         // duas setas puxando para lados opostos
        float t = (float)GetRandomValue(-1, 1);
        DrawLineEx((Vector2){ c.x - 4, c.y - 6 + t }, (Vector2){ c.x - 20, c.y - 6 + t }, 3.0f, cd);
        DrawTriangle((Vector2){ c.x - 26, c.y - 6 + t }, (Vector2){ c.x - 18, c.y - 1 + t }, (Vector2){ c.x - 18, c.y - 11 + t }, cd);
        DrawLineEx((Vector2){ c.x + 4, c.y + 6 - t }, (Vector2){ c.x + 20, c.y + 6 - t }, 3.0f, cd);
        DrawTriangle((Vector2){ c.x + 26, c.y + 6 - t }, (Vector2){ c.x + 18, c.y + 1 - t }, (Vector2){ c.x + 18, c.y + 11 - t }, cd);
        return;
    }

    // A peça que falhou, riscada (VAGA = o objetivo, embaçado)
    int parte = (d == DIAG_VAGA) ? PP_OBJETIVO : (d == DIAG_PUBLICO) ? PP_CONTEXTO : (d == DIAG_PAPEL) ? PP_PAPEL : PP_FORMATO;
    DesenharIconeParte(parte, c, 2.3f, Fade(CORES_PARTES_PROMPT[parte], (d == DIAG_VAGA) ? 0.45f : 0.9f));
    if (d == DIAG_VAGA) {
        DrawText("?", (int)c.x + 10, (int)c.y - 22, 20, cd);
    } else {
        DrawLineEx((Vector2){ c.x + 8, c.y + 6 }, (Vector2){ c.x + 20, c.y + 18 }, 3.0f, RED);
        DrawLineEx((Vector2){ c.x + 20, c.y + 6 }, (Vector2){ c.x + 8, c.y + 18 }, 3.0f, RED);
    }
}

static void DesenharBotaoLab(const BotaoLab *o, bool foco, float tempo)
{
    Rectangle r = o->r;
    Color c = o->ativo ? o->cor : Fade(GRAY, 0.6f);

    switch (o->estilo) {

        case EST_ENCAIXE: {         // laboratório de prompts: um encaixe da "frase" do pedido
            int k = o->param;
            Color ck = o->cor;
            bool sel = o->marcado;

            DrawRectangleRec(r, Fade(BLACK, 0.5f));
            if (sel) DrawRectangleRec(r, Fade(ck, 0.10f + 0.06f * sinf(tempo * 5.0f)));
            if (o->texto == NULL && !sel && o->luz < 0) DesenharBordaTracejada(r, Fade(ck, 0.6f));
            else DrawRectangleLinesEx(r, (sel || foco) ? 2.0f : 1.0f, (sel || foco) ? ck : Fade(ck, 0.6f));

            DrawRectangle((int)r.x, (int)r.y, (int)r.width, 18, Fade(ck, 0.22f));
            DesenharIconeParte(k, (Vector2){ r.x + 11, r.y + 9 }, 0.75f, ck);
            DrawText(o->rotulo, (int)r.x + 22, (int)r.y + 4, 10, sel ? WHITE : ck);

            if (o->luz >= 0) {
                const char *nl = NOMES_LUZ[o->luz];
                Color cl = CORES_LUZ[o->luz];
                int w = MeasureText(nl, 10) + 10;
                DrawRectangle((int)(r.x + r.width) - w - 3, (int)r.y + 3, w, 13, cl);
                DrawText(nl, (int)(r.x + r.width) - w + 2, (int)r.y + 4, 10, BLACK);
                DrawRectangleLinesEx(r, 2.0f, Fade(cl, 0.45f + 0.3f * sinf(tempo * 4.0f)));
            } else if (o->chip) {
                Color ciano = { 0, 228, 255, 255 };
                DrawRectangle((int)(r.x + r.width) - 42, (int)r.y + 3, 39, 13, ciano);
                DrawText("LUCI", (int)(r.x + r.width) - 35, (int)r.y + 4, 10, BLACK);
            } else {
                const char *d = DICAS_PARTES_PROMPT[k];
                DrawText(d, (int)(r.x + r.width) - MeasureText(d, 10) - 6, (int)r.y + 4, 10, Fade(LIGHTGRAY, 0.6f));
            }

            const char *t = (o->texto != NULL) ? o->texto : (sel ? "escolha a peça abaixo" : "(vazio)");
            char linhas[256];
            QuebrarTexto(t, (int)r.width - 12, 10, linhas, (int)sizeof(linhas));
            int quebras = 0;                                    // no máximo 3 linhas
            for (char *q = linhas; *q; q++) if (*q == '\n' && ++quebras == 3) { *q = '\0'; break; }
            Color ct = (o->texto == NULL) ? Fade(GRAY, 0.9f) : (o->chip ? (Color){ 160, 240, 255, 255 } : WHITE);
            DesenharTextoLinhas(linhas, (int)r.x + 6, (int)r.y + 23, 10, 11, ct);

            if (sel) {      // seta apontando para as peças
                float cx = r.x + r.width / 2, y = r.y + r.height + 2;
                DrawTriangle((Vector2){ cx - 7, y }, (Vector2){ cx, y + 8 }, (Vector2){ cx + 7, y }, ck);
            }
        } break;

        case EST_PECA: {            // laboratório de prompts: uma peça para o encaixe ativo
            bool m = o->marcado;
            Color ck = o->cor;
            DrawRectangleRec(r, foco ? Fade(ck, 0.20f) : Fade(BLACK, 0.42f));
            DrawRectangle((int)r.x, (int)r.y, 6, (int)r.height, (o->param == 0) ? Fade(ck, 0.4f) : ck);     // a lingueta que encaixa
            DrawRectangle((int)r.x + 6, (int)(r.y + r.height / 2) - 6, 5, 12, (o->param == 0) ? Fade(ck, 0.4f) : ck);
            DrawRectangleLinesEx(r, (foco || m) ? 2.0f : 1.0f, (foco || m) ? ck : Fade(ck, 0.35f));

            int yb = (int)(r.y + r.height / 2) - 8;
            DrawRectangle((int)r.x + 18, yb, 18, 16, m ? ck : Fade(ck, 0.3f));
            DrawText(o->rotulo, (int)r.x + 27 - MeasureText(o->rotulo, 10) / 2, yb + 3, 10, m ? BLACK : WHITE);

            char linhas[256];
            QuebrarTexto(o->texto != NULL ? o->texto : "", (int)r.width - 110, 10, linhas, (int)sizeof(linhas));
            int nl = ContarLinhas(linhas);
            DesenharTextoLinhas(linhas, (int)r.x + 44, (int)(r.y + r.height / 2) - (nl * 12) / 2 + 1, 10, 12,
                                (o->param == 0) ? LIGHTGRAY : WHITE);
            if (m) {
                const char *u = "NO ENCAIXE";
                DrawText(u, (int)(r.x + r.width) - MeasureText(u, 10) - 8, (int)(r.y + r.height / 2) - 5, 10, ck);
            }
            if (foco) DrawRectangle((int)r.x + 3, (int)r.y + 4, 2, (int)r.height - 8, Fade(WHITE, 0.5f + 0.5f * sinf(tempo * 8.0f)));
        } break;

        case EST_SELETOR: {
            DrawRectangleRec(r, foco ? Fade(c, 0.18f) : Fade(BLACK, 0.45f));
            DrawRectangleLinesEx(r, foco ? 2.0f : 1.0f, foco ? c : Fade(c, 0.5f));
            DrawText(o->rotulo, (int)r.x + 22, (int)r.y + 5, 10, c);
            char linhas[256];
            QuebrarTexto((o->texto != NULL) ? o->texto : "(não incluir)", (int)r.width - 50, 10, linhas, (int)sizeof(linhas));
            int nl = ContarLinhas(linhas);
            DesenharTextoLinhas(linhas, (int)r.x + 22, (int)r.y + ((nl > 1) ? 16 : 20), 10, 11,
                                (o->texto != NULL) ? (o->ativo ? WHITE : LIGHTGRAY) : Fade(GRAY, 0.9f));
            if (o->ativo) {
                float my = r.y + r.height / 2;
                DrawTriangle((Vector2){ r.x + 6, my }, (Vector2){ r.x + 14, my + 6 }, (Vector2){ r.x + 14, my - 6 }, Fade(c, foco ? 1.0f : 0.6f));
                DrawTriangle((Vector2){ r.x + r.width - 6, my }, (Vector2){ r.x + r.width - 14, my - 6 }, (Vector2){ r.x + r.width - 14, my + 6 }, Fade(c, foco ? 1.0f : 0.6f));
            }
        } break;

        case EST_ITEM: {
            bool m = o->marcado;
            DrawRectangleRec(r, m ? Fade(o->cor, 0.22f) : Fade(BLACK, 0.40f));
            DrawRectangleLinesEx(r, (foco || m) ? 2.0f : 1.0f, foco ? (o->ativo ? o->cor : GRAY) : Fade(o->cor, m ? 0.9f : 0.35f));

            int xt = (int)r.x + 10;
            if (o->rotulo[0] != '\0' && !o->chip) {
                DrawRectangle((int)r.x + 6, (int)r.y + 6, 18, 16, m ? o->cor : Fade(o->cor, 0.35f));
                DrawText(o->rotulo, (int)r.x + 15 - MeasureText(o->rotulo, 10) / 2, (int)r.y + 9, 10, m ? BLACK : WHITE);
                xt = (int)r.x + 32;
            } else if (o->rotulo[0] == '\0') {
                // Caixa de marcar (pistas da Câmara de Pesquisa)
                DrawRectangleLines((int)r.x + 8, (int)(r.y + r.height / 2) - 6, 12, 12, o->cor);
                if (m) DrawText("!", (int)r.x + 12, (int)(r.y + r.height / 2) - 6, 12, o->cor);
                xt = (int)r.x + 28;
            }
            if (o->chip) {
                int w = MeasureText(o->rotulo, 10) + 10;
                DrawRectangle((int)(r.x + r.width) - w - 4, (int)r.y + 4, w, 14, m ? o->cor : Fade(o->cor, 0.3f));
                DrawText(o->rotulo, (int)(r.x + r.width) - w + 1, (int)r.y + 6, 10, m ? BLACK : WHITE);
            }

            int espaco = (o->fonte >= 12) ? 16 : 13;
            int larg = (int)r.width - ((xt - (int)r.x) + (o->chip ? 54 : 14));
            char linhas[512];
            QuebrarTexto(o->texto != NULL ? o->texto : "", larg, o->fonte, linhas, (int)sizeof(linhas));
            int nl = ContarLinhas(linhas);
            int yt = o->chip ? (int)r.y + 6 : (int)(r.y + r.height / 2) - (nl * espaco) / 2 + 1;
            DesenharTextoLinhas(linhas, xt, yt, o->fonte, espaco, (o->ativo || m) ? WHITE : LIGHTGRAY);
        } break;

        default: {      // botão comum e botões da Luci
            DrawRectangleRec(r, foco ? Fade(c, 0.35f) : Fade(c, o->marcado ? 0.25f : 0.10f));
            DrawRectangleLinesEx(r, foco ? 2.0f : 1.0f, c);
            DrawText(o->rotulo, (int)r.x + 12, (int)(r.y + r.height / 2) - 5, 10, o->ativo ? WHITE : GRAY);
            if (o->estilo == EST_LUCI && o->custo > 0)
                DesenharPipsLab(r.x + 16 + (float)MeasureText(o->rotulo, 10), r.y + r.height / 2, o->custo, c);
            if (foco && o->ativo)
                DrawRectangle((int)r.x + 3, (int)r.y + 4, 2, (int)r.height - 8, Fade(WHITE, 0.5f + 0.5f * sinf(tempo * 8.0f)));
        } break;
    }
}

// Marca "LUCI" no que a sugestão dela aponta (para o jogador conferir com calma)
static void DesenharMarcaLuciLab(const Biblioteca *b, const BotaoLab *bt, int n, float tempo)
{
    const LabEdu *L = &b->lab;
    if (!L->luciTemSugestao || L->luciAponta < 0 || L->etapa != LAB_DESAFIO)
        return;

    AcaoLab alvo;
    if (L->tipo == LAB_ARQUIVO)       { alvo = (L->luciFase == 0) ? LB_ITEM : LB_OPCAO; if (L->luciFase != L->fase) return; }
    else if (L->tipo == LAB_FIREWALL) { alvo = (L->fase < 2) ? LB_OPCAO : LB_PACOTE; if (L->fase < 2 ? (L->luciFase != L->fase) : (L->luciFase != 20 + L->pacote)) return; }
    else if (L->tipo == LAB_NUCLEO || L->tipo == LAB_PESQUISA) alvo = LB_ITEM;
    else return;

    for (int i = 0; i < n; i++) {
        if (bt[i].acao != alvo || bt[i].param != L->luciAponta) continue;
        Color cor = L->luciVerificada ? (L->luciAlucinou ? RED : LIME) : (Color){ 0, 228, 255, 255 };
        int x = (int)(bt[i].r.x + bt[i].r.width) - 40, y = (int)bt[i].r.y - 7;
        DrawRectangle(x, y, 36, 12, Fade(BLACK, 0.8f));
        DrawRectangleLines(x, y, 36, 12, cor);
        DrawText("LUCI", x + 6 + ((L->luciAlucinou && RogueEstab(b) <= 2 && ((int)(tempo * 12.0f)) % 5 == 0) ? 1 : 0), y + 1, 10, cor);
    }
}

// Mídia simulada da Câmara de Pesquisa (só formas simples do Raylib)
static void DesenharMidiaPesquisa(const Biblioteca *b, Rectangle r, float tempo)
{
    const CasoPesquisa *c = &CASOS_PESQUISA[b->lab.missao];
    int caso = b->lab.missao;

    DrawRectangleRec(r, (Color){ 12, 14, 26, 255 });

    if (c->midia == MIDIA_AUDIO) {
        // Forma de onda animada
        float cy = r.y + r.height / 2;
        for (int i = 0; i < 48; i++) {
            float x = r.x + 12 + i * ((r.width - 24) / 48.0f);
            float h = (8.0f + 30.0f * fabsf(sinf(i * 0.7f + tempo * 5.0f) * sinf(i * 0.23f + tempo))) ;
            DrawRectangle((int)x, (int)(cy - h / 2), 3, (int)h, Fade(GOLD, 0.8f));
        }
        DrawText("ÁUDIO  0:14", (int)r.x + 10, (int)(r.y + r.height) - 18, 10, LIGHTGRAY);
        DrawCircleV((Vector2){ r.x + r.width - 20, r.y + 18 }, 6, RED);
    } else if (caso == 0) {
        // Avenida alagada com uma barbatana
        DrawRectangle((int)r.x, (int)r.y, (int)r.width, (int)(r.height * 0.45f), (Color){ 70, 80, 100, 255 });
        DrawRectangle((int)r.x, (int)(r.y + r.height * 0.45f), (int)r.width, (int)(r.height * 0.55f), (Color){ 60, 90, 110, 255 });
        for (int i = 0; i < 4; i++)
            DrawRectangle((int)r.x + 20 + i * 70, (int)(r.y + r.height * 0.15f), 40, (int)(r.height * 0.3f), (Color){ 50, 55, 70, 255 });
        for (int i = 0; i < 6; i++)
            DrawLine((int)r.x + 10, (int)(r.y + r.height * 0.55f + i * 10), (int)(r.x + r.width) - 10, (int)(r.y + r.height * 0.55f + i * 10 + sinf(tempo + i) * 2), Fade(SKYBLUE, 0.3f));
        Vector2 f = { r.x + r.width * 0.55f + sinf(tempo) * 6, r.y + r.height * 0.68f };
        DrawTriangle((Vector2){ f.x - 14, f.y }, (Vector2){ f.x + 14, f.y }, (Vector2){ f.x + 4, f.y - 26 }, (Color){ 90, 100, 110, 255 });
    } else if (caso == 3) {
        // Arco-íris duplo sobre a escola
        DrawRectangle((int)r.x, (int)r.y, (int)r.width, (int)r.height, (Color){ 90, 130, 180, 255 });
        static const Color arco[5] = { { 230, 41, 55, 255 }, { 255, 161, 0, 255 }, { 253, 249, 0, 255 }, { 0, 228, 48, 255 }, { 0, 121, 241, 255 } };
        Vector2 cc = { r.x + r.width / 2, r.y + r.height + 10 };
        for (int i = 0; i < 5; i++) DrawRing(cc, 70.0f + i * 5, 74.0f + i * 5, 180, 360, 40, Fade(arco[i], 0.75f));
        for (int i = 0; i < 5; i++) DrawRing(cc, 110.0f + i * 5, 114.0f + i * 5, 180, 360, 40, Fade(arco[4 - i], 0.4f));
        DrawRectangle((int)(r.x + r.width / 2) - 40, (int)(r.y + r.height) - 40, 80, 40, (Color){ 180, 150, 120, 255 });
        DrawTriangle((Vector2){ r.x + r.width / 2 - 46, r.y + r.height - 40 }, (Vector2){ r.x + r.width / 2 + 46, r.y + r.height - 40 },
                     (Vector2){ r.x + r.width / 2, r.y + r.height - 62 }, (Color){ 150, 70, 60, 255 });
    } else if (caso == 4) {
        // Céu noturno com um clarão
        DrawRectangle((int)r.x, (int)r.y, (int)r.width, (int)r.height, (Color){ 10, 12, 30, 255 });
        for (int i = 0; i < 30; i++)
            DrawPixel((int)r.x + (int)(Ruido((unsigned int)i * 7u) % (unsigned int)r.width), (int)r.y + (int)(Ruido((unsigned int)i * 13u) % (unsigned int)(r.height * 0.7f)), WHITE);
        float k = fmodf(tempo * 0.5f, 1.0f);
        Vector2 p = { r.x + 30 + k * (r.width - 60), r.y + 20 + k * 50 };
        DrawLineEx((Vector2){ p.x - 40, p.y - 18 }, p, 3, Fade(ORANGE, 0.7f));
        DrawCircleV(p, 4, YELLOW);
        DrawRectangle((int)r.x, (int)(r.y + r.height) - 30, (int)r.width, 30, (Color){ 20, 20, 30, 255 });
        for (int i = 0; i < 8; i++) DrawRectangle((int)r.x + i * 37, (int)(r.y + r.height) - 30 - (i % 3) * 12, 30, 30 + (i % 3) * 12, (Color){ 25, 25, 40, 255 });
    } else {
        // Pessoa falando num púlpito (vídeo)
        DrawRectangle((int)r.x, (int)r.y, (int)r.width, (int)r.height, (Color){ 40, 60, 90, 255 });
        Vector2 cab = { r.x + r.width / 2, r.y + r.height * 0.38f };
        DrawCircleV(cab, 20, (Color){ 200, 160, 130, 255 });
        DrawRectangle((int)cab.x - 30, (int)cab.y + 20, 60, 50, (Color){ 40, 40, 60, 255 });
        float boca = 2.0f + 3.0f * fabsf(sinf(tempo * 7.0f + ((((int)(tempo * 3.0f)) % 4 == 0) ? 1.5f : 0.0f)));
        DrawEllipse((int)cab.x, (int)cab.y + 9, 6, boca, (Color){ 90, 30, 40, 255 });
        DrawRectangle((int)cab.x - 44, (int)(r.y + r.height) - 34, 88, 34, (Color){ 90, 60, 40, 255 });
    }

    if (c->midia == MIDIA_VIDEO) {
        DrawRectangle((int)r.x, (int)(r.y + r.height) - 8, (int)r.width, 8, Fade(BLACK, 0.6f));
        DrawRectangle((int)r.x, (int)(r.y + r.height) - 8, (int)(r.width * fmodf(tempo * 0.1f, 1.0f)), 8, RED);
        DrawTriangle((Vector2){ r.x + 8, r.y + 8 }, (Vector2){ r.x + 8, r.y + 22 }, (Vector2){ r.x + 20, r.y + 15 }, Fade(WHITE, 0.8f));
    }

    DrawRectangleLinesEx(r, 2, Fade(CORES_LAB[LAB_PESQUISA], 0.8f));
    const char *rot = NOMES_MIDIA[c->midia];
    DrawRectangle((int)(r.x + r.width) - MeasureText(rot, 10) - 12, (int)r.y + 4, MeasureText(rot, 10) + 8, 14, Fade(BLACK, 0.7f));
    DrawText(rot, (int)(r.x + r.width) - MeasureText(rot, 10) - 8, (int)r.y + 6, 10, GOLD);
}

// Texto quebrado numa área (devolve a altura usada)
static int DesenharTextoLab(const char *texto, int x, int y, int largura, int fonte, int espaco, Color cor)
{
    char linhas[1024];
    QuebrarTexto(texto, largura, fonte, linhas, (int)sizeof(linhas));
    return DesenharTextoLinhas(linhas, x, y, fonte, espaco, cor) * espaco;
}

static void DesenharBarrasCriterios(const int crit[NUM_CRITERIOS], int nota, int x, int y)
{
    for (int c = 0; c < NUM_CRITERIOS; c++) {
        int yy = y + c * 15;
        Color cor = (crit[c] >= 2) ? LIME : ((crit[c] == 1) ? GOLD : RED);
        DrawText(NOMES_CRITERIOS[c], x, yy, 10, LIGHTGRAY);
        for (int k = 0; k < 2; k++)
            DrawRectangle(x + 118 + k * 22, yy + 1, 18, 8, (k < crit[c]) ? cor : Fade(GRAY, 0.3f));
    }
    DrawText(TextFormat("%d/10", nota), x + 172, y + 22, 20, (nota >= 9) ? LIME : ((nota >= 6) ? GOLD : RED));
}

// Holograma do ECO-1: o que a IA "entendeu" vira uma imagem. Quanto pior o pedido, mais chiado.
static void DesenharHologramaEco(const Biblioteca *b, Rectangle r, float tempo)
{
    const LabEdu *L = &b->lab;
    Color cor = CORES_LAB[LAB_PROMPTS];

    DrawRectangleRec(r, (Color){ 10, 12, 24, 255 });
    DrawRectangleLinesEx(r, 2, Fade(cor, 0.6f));
    DrawRectangle((int)r.x, (int)r.y, (int)r.width, 20, Fade(cor, 0.18f));
    DrawText("ECO-1  //  IA SIMULADA (OFFLINE)", (int)r.x + 8, (int)r.y + 5, 10, cor);
    const char *env = TextFormat("envios %d/%d", L->envios, LAB_MAX_ENVIOS);
    DrawText(env, (int)(r.x + r.width) - MeasureText(env, 10) - 8, (int)r.y + 5, 10, GRAY);

    Rectangle tela = { r.x + 18, r.y + 30, r.width - 36, 116 };
    Vector2 robo = { r.x + r.width / 2, r.y + r.height - 30 };
    int humor = 0;

    // Feixe do projetor
    DrawTriangle((Vector2){ robo.x, robo.y - 26 }, (Vector2){ tela.x + tela.width, tela.y + tela.height },
                 (Vector2){ tela.x, tela.y + tela.height }, Fade(cor, 0.07f));

    if (L->etapa == LAB_DESAFIO) {
        DrawRectangleRec(tela, Fade(cor, 0.05f));
        float varre = fmodf(tempo * 40.0f, tela.height);
        DrawRectangle((int)tela.x, (int)(tela.y + varre), (int)tela.width, 2, Fade(cor, 0.25f));
        const char *t = "AGUARDANDO O PEDIDO";
        DrawText(t, (int)(tela.x + tela.width / 2) - MeasureText(t, 10) / 2, (int)tela.y + 36, 10, Fade(cor, 0.6f + 0.3f * sinf(tempo * 3.0f)));
        for (int k = 0; k < NUM_PARTES_PROMPT; k++) {           // as peças que já estão nos encaixes
            Vector2 c = { tela.x + tela.width / 2 - 45 + k * 30.0f, tela.y + 72 };
            if (L->escolha[k] > 0) DesenharIconeParte(k, c, 1.1f, CORES_PARTES_PROMPT[k]);
            else                   DrawCircleLines((int)c.x, (int)c.y, 7, Fade(CORES_PARTES_PROMPT[k], 0.4f));
        }
    } else {
        DiagPrompt d = L->diag;
        Color cd = CORES_DIAG[d];
        bool pego = L->pegouAlucinacao && L->respostaAlucinada;

        DrawRectangleRec(tela, Fade(cd, 0.08f));
        DrawRectangleLinesEx(tela, 1, Fade(cd, 0.5f));
        DesenharPictogramaDiag(d, (Vector2){ tela.x + 42, tela.y + 48 }, tempo);
        if (!pego) DrawText(CARIMBOS_DIAG[d], (int)tela.x + 82, (int)tela.y + 26, 16, cd);

        // Nitidez: a nota do pedido em 10 barrinhas
        DrawText("NITIDEZ", (int)tela.x + 8, (int)(tela.y + tela.height) - 18, 10, LIGHTGRAY);
        for (int i = 0; i < 10; i++)
            DrawRectangle((int)tela.x + 62 + i * 15, (int)(tela.y + tela.height) - 17, 12, 8, (i < L->notaPrompt) ? cd : Fade(GRAY, 0.25f));

        // Chiado: o que faltou no pedido vira ruído na imagem
        int ruido = (10 - L->notaPrompt) * 9;
        for (int i = 0; i < ruido; i++) {
            int w = GetRandomValue(2, 5);
            DrawRectangle(GetRandomValue((int)tela.x, (int)(tela.x + tela.width) - w), GetRandomValue((int)tela.y, (int)(tela.y + tela.height) - 3),
                          w, 2, Fade((i % 3 == 0) ? WHITE : cd, 0.35f));
        }

        // O holograma "liga" de cima para baixo logo depois do envio
        float monta = Clamp(L->tempoResposta / 0.5f, 0.0f, 1.0f);
        if (monta < 1.0f)
            DrawRectangle((int)tela.x, (int)(tela.y + tela.height * monta), (int)tela.width, (int)(tela.height * (1.0f - monta)) + 1, (Color){ 10, 12, 24, 255 });

        if (pego) {         // pegou a invenção: carimbo por cima
            const char *inv = "INVENTADO!";
            int w = MeasureText(inv, 20);
            int x = (int)(tela.x + tela.width / 2) - w / 2, y = (int)(tela.y + tela.height / 2) - 14;
            DrawRectangle(x - 8, y - 4, w + 16, 28, Fade(BLACK, 0.75f));
            DrawRectangleLinesEx((Rectangle){ (float)x - 8, (float)y - 4, (float)w + 16, 28 }, 2, MAGENTA);
            DrawText(inv, x, y, 20, MAGENTA);
        }

        humor = pego ? 3 : ((d == DIAG_IDEAL || d == DIAG_BOA) ? 1 : ((d == DIAG_CONTRADICAO) ? 3 : 2));
    }

    DesenharEco1(robo, humor, tempo);
}

// Laboratório de prompts: os encaixes ficam no alto (desenhados como botões), as peças à
// esquerda e o holograma do ECO-1 à direita. Depois do envio, a resposta ocupa a esquerda.
static void DesenharLabPrompt(const Biblioteca *b, float tempo)
{
    const LabEdu *L = &b->lab;
    const MissaoPrompt *m = &MISSOES_PROMPT[L->missao];
    Color cor = CORES_LAB[LAB_PROMPTS];
    Color ciano = { 0, 228, 255, 255 };

    DrawText("MISSÃO:", 44, 84, 10, GOLD);
    DesenharTextoLab(m->missao, 94, 84, 662, 10, 13, WHITE);

    if (L->etapa == LAB_DESAFIO) {
        if (L->temSugestao) {
            DrawText("A LUCI REMONTOU O PEDIDO", 60, 200, 12, ciano);
            DesenharTextoLab("As peças que ela trocou estão marcadas. Ela pode ter alucinado: confira (V) antes de usar.",
                             60, 220, 360, 10, 13, LIGHTGRAY);
        } else {
            int k = L->slotAtivo;
            DrawText(TextFormat("PEÇAS PARA %s", NOMES_PARTES_PROMPT[k]), 44, 184, 10, CORES_PARTES_PROMPT[k]);
            const char *atalho = "1-3 peça   0 vazio   A/D encaixe";
            DrawText(atalho, 436 - MeasureText(atalho, 10), 184, 10, Fade(GRAY, 0.9f));
        }
    } else {
        // A resposta do ECO-1 (máquina de escrever) e o resultado do "desconfiar"
        Rectangle caixa = { 44, 180, 392, 222 };
        DrawRectangleRec(caixa, Fade(cor, 0.06f));
        DrawRectangleLinesEx(caixa, 1, Fade(cor, 0.35f));
        DrawText(L->original ? "ECO-1 RESPONDEU AO PEDIDO ORIGINAL:" : "ECO-1 RESPONDEU:", 52, 187, 10, cor);

        const char *resp = LabTextoRespostaAtual(b);
        char parcial[600];
        TextoParcial(resp, L->digitado, parcial, (int)sizeof(parcial));
        int h = DesenharTextoLab(parcial, 52, 204, 376, 10, 13, (Color){ 210, 245, 255, 255 });
        if (L->digitado < (float)strlen(resp) && ((int)(tempo * 6.0f)) % 2 == 0)
            DrawRectangle(52, 204 + h, 6, 2, cor);

        if (L->avaliacao[0] != '\0') {
            bool pegou = L->pegouAlucinacao && L->respostaAlucinada;
            DesenharTextoLab(L->avaliacao, 52, 204 + h + 10, 376, 10, 13, pegou ? MAGENTA : LIME);
        }
    }

    DesenharHologramaEco(b, (Rectangle){ 448, 180, 308, 222 }, tempo);
}

// A peça voando do cartão até o encaixe (desenhada por cima dos botões)
static void DesenharAnimPecaLab(const LabEdu *L)
{
    if (L->tipo != LAB_PROMPTS || L->animPeca <= 0.0f)
        return;

    float t = Clamp(1.0f - L->animPeca / LAB_ANIM_PECA, 0.0f, 1.0f);
    t = t * t * (3.0f - 2.0f * t);
    Rectangle de = LabRetPeca(L->animDe), para = LabRetEncaixe(L->animSlot);
    Vector2 a = { de.x + 60, de.y + de.height / 2 }, z = { para.x + para.width / 2, para.y + para.height / 2 };
    Vector2 p = Vector2Lerp(a, z, t);
    p.y -= sinf(t * PI) * 26.0f;
    Color ck = CORES_PARTES_PROMPT[L->animSlot];

    for (int i = 1; i <= 4; i++) {          // rastro
        float tt = fmaxf(0.0f, t - 0.06f * i);
        Vector2 q = Vector2Lerp(a, z, tt);
        q.y -= sinf(tt * PI) * 26.0f;
        DrawRectangle((int)q.x - 14, (int)q.y - 5, 28, 10, Fade(ck, 0.25f / i));
    }
    DrawRectangle((int)p.x - 22, (int)p.y - 8, 44, 16, ck);
    DrawRectangle((int)p.x - 26, (int)p.y - 4, 4, 8, ck);
    if (t > 0.8f)                           // o clique do encaixe
        DrawRectangleLinesEx((Rectangle){ para.x - 3, para.y - 3, para.width + 6, para.height + 6 }, 2, Fade(ck, (1.0f - t) * 5.0f));
}

// Introdução do laboratório de prompts: o conceito como 4 peças (em vez de um parágrafo)
static void DesenharIntroPrompt(const Biblioteca *b, float tempo)
{
    const LabEdu *L = &b->lab;
    const MissaoPrompt *m = &MISSOES_PROMPT[L->missao];
    Color cor = CORES_LAB[LAB_PROMPTS];

    const char *t = "UM BOM PEDIDO TEM ATÉ 4 PEÇAS";
    DrawText(t, 400 - MeasureText(t, 16) / 2, 88, 16, GOLD);

    for (int k = 0; k < NUM_PARTES_PROMPT; k++) {
        Rectangle r = { 44.0f + k * 180.0f, 114, 172, 92 };
        Color ck = CORES_PARTES_PROMPT[k];
        DrawRectangleRec(r, Fade(ck, 0.08f));
        DrawRectangleLinesEx(r, 2, Fade(ck, 0.7f));
        DesenharIconeParte(k, (Vector2){ r.x + r.width / 2, r.y + 30 + sinf(tempo * 2.0f + k) * 2.0f }, 2.0f, ck);
        DrawText(NOMES_PARTES_PROMPT[k], (int)(r.x + r.width / 2) - MeasureText(NOMES_PARTES_PROMPT[k], 12) / 2, (int)r.y + 54, 12, ck);
        DrawText(DICAS_PARTES_PROMPT[k], (int)(r.x + r.width / 2) - MeasureText(DICAS_PARTES_PROMPT[k], 10) / 2, (int)r.y + 72, 10, LIGHTGRAY);
        if (k < NUM_PARTES_PROMPT - 1)
            DrawText("+", (int)(r.x + r.width) + 1, (int)r.y + 40, 10, GOLD);
    }

    t = "O ECO-1 faz EXATAMENTE o que você pedir.";
    DrawText(t, 400 - MeasureText(t, 12) / 2, 218, 12, WHITE);

    Rectangle mc = { 44, 242, 712, 72 };
    DrawRectangleRec(mc, Fade(BLACK, 0.4f));
    DrawRectangleLinesEx(mc, 1, Fade(cor, 0.6f));
    DrawText(TextFormat("MISSÃO: %s", m->titulo), 56, 250, 12, cor);
    DesenharTextoLab(m->missao, 56, 270, 688, 12, 16, WHITE);

    // As regras em três selos curtos
    static const char *selos[3] = { "PEÇA ERRADA ATRAPALHA", "NEM SEMPRE PRECISA DAS 4", "3 ENVIOS" };
    int x = 44;
    for (int i = 0; i < 3; i++) {
        int w = MeasureText(selos[i], 10) + 20;
        DrawRectangle(x, 328, w, 20, Fade(GOLD, 0.12f));
        DrawRectangleLines(x, 328, w, 20, Fade(GOLD, 0.6f));
        DrawText(selos[i], x + 10, 333, 10, GOLD);
        x += w + 10;
    }

    DesenharLuciTamanho((Vector2){ 58, 378 }, 24.0f);
    DrawText("Luci: H pede dica (gasta estabilidade). V confere o que eu disser.", 78, 372, 10, (Color){ 0, 228, 255, 255 });
    DrawText("Sala comum: a porta abre quando você terminar.", 44, 404, 10, LIGHTGRAY);
}

static void DesenharLabArquivo(const Biblioteca *b, float tempo)
{
    const LabEdu *L = &b->lab;
    const DesafioArquivo *d = &DESAFIOS_ARQUIVO[L->missao];
    Color cor = CORES_LAB[LAB_ARQUIVO];

    Rectangle doc = { 44, 84, 476, 320 };
    DrawRectangleRec(doc, (Color){ 16, 12, 26, 255 });
    DrawRectangleLinesEx(doc, 2, Fade(cor, 0.6f));
    DrawText(TextFormat("RESPOSTA RECUPERADA // %s", d->titulo), (int)doc.x + 10, (int)doc.y + 8, 10, cor);
    DesenharTextoLab(d->pergunta, (int)doc.x + 10, (int)doc.y + 24, 456, 10, 12, LIGHTGRAY);

    // Corrupção: blocos e caracteres que piscam por cima do documento
    for (int i = 0; i < 7; i++) {
        unsigned int h = Ruido((unsigned int)i * 31u + (unsigned int)(tempo * 4.0f));
        if (h % 3 != 0) continue;
        int x = (int)doc.x + 8 + (int)(h % 440), y = (int)doc.y + 50 + (int)((h >> 8) % 250);
        DrawRectangle(x, y, 6 + (int)((h >> 4) % 30), 2, Fade(MAGENTA, 0.35f));
    }

    // Passos
    static const char *passos[3] = { "1. ANALISE AS AFIRMAÇÕES", "2. MARQUE A SUSPEITA", "3. ESCOLHA COMO VERIFICAR" };
    for (int i = 0; i < 3; i++) {
        bool atual = (i == 0 && L->fase == 0 && L->sel < 0) || (i == 1 && L->fase == 0 && L->sel >= 0) || (i == 2 && L->fase == 1);
        DrawText(passos[i], 532, 90 + i * 16, 10, atual ? GOLD : Fade(LIGHTGRAY, 0.6f));
    }
    if (L->fase == 0)
        DesenharTextoLab("Uma resposta convincente não é necessariamente verdadeira. Qual afirmação você não aceitaria sem conferir?", 532, 150, 220, 10, 13, GRAY);
    else
        DrawText(TextFormat("Suspeita marcada: afirmação %d", L->sel + 1), 532, 156, 10, cor);
}

static void DesenharLabNucleo(const Biblioteca *b, float tempo)
{
    const LabEdu *L = &b->lab;
    const DesafioNucleo *d = &DESAFIOS_NUCLEO[L->missao];
    Color cor = CORES_LAB[LAB_NUCLEO];

    DrawText("TAREFA:", 44, 84, 10, GOLD);
    DesenharTextoLab(d->tarefa, 92, 84, 664, 10, 13, WHITE);
    DrawText("Clique nos blocos para carregá-los no contexto da IA:", 44, 112, 10, GRAY);

    // Núcleo: anel de capacidade (vermelho no excesso)
    int tokens = LabTokensCarregados(b);
    float frac = (float)tokens / (float)d->capacidade;
    Vector2 c = { 643, 190 };
    bool excesso = tokens > d->capacidade;
    Color corAnel = excesso ? RED : ((frac >= 0.8f) ? GOLD : cor);
    DrawCircleV(c, 58, Fade(cor, 0.06f));
    DrawRing(c, 44, 54, -90, 270, 48, Fade(GRAY, 0.25f));
    DrawRing(c, 44, 54, -90, -90 + 360.0f * fminf(frac, 1.0f), 48, corAnel);
    if (excesso && ((int)(tempo * 6.0f)) % 2 == 0) DrawRing(c, 56, 60, -90, 270, 48, Fade(RED, 0.6f));
    DrawCircleV(c, 30 + 2 * sinf(tempo * 3.0f), Fade(cor, 0.35f));
    DrawText(TextFormat("%d/%d", tokens, d->capacidade), (int)c.x - MeasureText(TextFormat("%d/%d", tokens, d->capacidade), 16) / 2, (int)c.y - 12, 16, WHITE);
    DrawText("tokens", (int)c.x - MeasureText("tokens", 10) / 2, (int)c.y + 6, 10, LIGHTGRAY);

    // Barra de capacidade e ordem de carga (o mais antigo é o primeiro a sair no excesso)
    DrawRectangle(540, 256, 206, 8, Fade(GRAY, 0.3f));
    DrawRectangle(540, 256, (int)(206 * fminf(frac, 1.0f)), 8, corAnel);
    DrawText(excesso ? "EXCESSO: o início vai ser cortado!" : "CAPACIDADE DA JANELA DE CONTEXTO", 540, 268, 10, excesso ? RED : LIGHTGRAY);
    char ordem[64] = "Ordem de carga:";
    for (int k = 0; k < L->numOrdem && k < LAB_MAX_ITENS; k++)
        snprintf(ordem + strlen(ordem), sizeof(ordem) - strlen(ordem), " #%d", L->ordem[k] + 1);
    DrawText(ordem, 540, 284, 10, GRAY);
    DesenharTextoLab(AVISO_TOKENS, 540, 302, 212, 8, 10, Fade(SKYBLUE, 0.7f));

    // Números dos blocos e o que foi cortado
    for (int i = 0; i < d->numBlocos; i++) {
        int x = 44 + (i % 2) * 242, y = 128 + (i / 2) * 62;
        DrawText(TextFormat("#%d", i + 1), x + 8, y + 40, 8, Fade(cor, 0.9f));
        if (L->etapa == LAB_RESPOSTA && (L->cortados & (1u << i))) {
            DrawRectangle(x, y, 232, 54, Fade(RED, 0.25f));
            DrawText("CORTADO", x + 232 - MeasureText("CORTADO", 10) - 6, y + 40, 10, RED);
        }
    }

    // Resposta da IA (ou instruções)
    Rectangle caixa = { 44, 314, 476, 90 };
    DrawRectangleRec(caixa, (Color){ 10, 12, 24, 255 });
    DrawRectangleLinesEx(caixa, 1, Fade(cor, 0.5f));
    if (L->etapa == LAB_RESPOSTA) {
        const char *resp = LabTextoRespostaAtual(b);
        char parcial[400];
        TextoParcial(resp, L->digitado, parcial, (int)sizeof(parcial));
        DrawText("RESPOSTA DA IA SIMULADA:", 52, 320, 10, cor);
        DesenharTextoLab(parcial, 52, 336, 460, 10, 12, (Color){ 210, 245, 255, 255 });
    } else {
        DesenharTextoLab("Carregue o que a IA precisa para cumprir a tarefa sem estourar a capacidade. Depois, PROCESSAR.",
                         52, 322, 460, 10, 13, GRAY);
        DrawText(TextFormat("Processamentos: %d/%d", L->processos, LAB_MAX_PROCESSOS), 52, 384, 10, LIGHTGRAY);
    }
}

static void DesenharLabFirewall(const Biblioteca *b, float tempo)
{
    const LabEdu *L = &b->lab;
    const CasoVies *c = &CASOS_VIES[L->missao];
    Color cor = CORES_LAB[LAB_FIREWALL];

    if (L->fase < 2) {
        DrawText(TextFormat("VIÉS ALGORÍTMICO // %s", c->titulo), 44, 84, 12, cor);
        Rectangle caso = { 44, 102, 712, 104 };
        DrawRectangleRec(caso, Fade(BLACK, 0.45f));
        DrawRectangleLinesEx(caso, 1, Fade(cor, 0.4f));
        DesenharTextoLab(c->caso, 56, 112, 688, 12, 17, WHITE);
        DrawText((L->fase == 0) ? "1/3  QUAL É O PROBLEMA?" : "2/3  QUAL É A MELHOR CORREÇÃO?", 44, 226, 14, GOLD);
        if (L->fase == 1 && L->avaliacao[0] != '\0')
            DesenharTextoLab(L->avaliacao, 56, 390, 688, 10, 12, (strncmp(L->avaliacao, "CERTO", 5) == 0) ? LIME : ORANGE);
        return;
    }

    // Privacidade: o pacote anda até o firewall
    DrawText("3/3  PRIVACIDADE: o que pode passar pelo firewall até a IA?", 44, 84, 14, GOLD);
    DrawText(TextFormat("PACOTE %d/%d", (L->pacote < LAB_PACOTES) ? L->pacote + 1 : LAB_PACOTES, LAB_PACOTES), 44, 106, 10, LIGHTGRAY);
    if (L->avaliacao[0] != '\0')
        DesenharTextoLab(L->avaliacao, 44, 122, 712, 10, 12, (strncmp(L->avaliacao, "CERTO", 5) == 0) ? LIME : ORANGE);

    // Esteira e a parede do firewall
    DrawRectangle(44, 250, 600, 6, Fade(GRAY, 0.4f));
    for (int i = 0; i < 12; i++)
        DrawRectangle(44 + (int)fmodf((float)i * 50.0f + tempo * 40.0f, 600.0f), 251, 20, 4, Fade(cor, 0.25f));
    for (int k = 0; k < 6; k++)
        DrawRectangle(652, 168 + k * 24, 22, 20, Fade(((k + (int)(tempo * 4.0f)) % 2) ? cor : (Color){ 0, 120, 30, 255 }, 0.8f));
    DrawText("FIREWALL", 640, 318, 10, cor);
    DrawText("IA", 708, 236, 20, (Color){ 0, 228, 255, 255 });

    if (L->pacote < LAB_PACOTES) {
        const PacoteDados *p = &PACOTES_DADOS[L->pacotes[L->pacote]];
        float prog = 1.0f - L->tempoPacote / LAB_TEMPO_PACOTE;
        Rectangle card = { 50 + prog * 300.0f, 178, 290, 66 };
        DrawRectangleRec(card, (Color){ 30, 26, 50, 255 });
        DrawRectangleLinesEx(card, 2, (prog > 0.75f && ((int)(tempo * 8.0f)) % 2 == 0) ? RED : cor);
        DrawText("PACOTE DE DADOS", (int)card.x + 8, (int)card.y + 5, 8, cor);
        DesenharTextoLab(p->texto, (int)card.x + 8, (int)card.y + 18, 274, 10, 12, WHITE);
        // Tempo até atravessar sozinho
        DrawRectangle(44, 270, 600, 5, Fade(BLACK, 0.6f));
        DrawRectangle(44, 270, (int)(600 * (L->tempoPacote / LAB_TEMPO_PACOTE)), 5, (prog > 0.75f) ? RED : GOLD);
        DrawText("Sem decisão, o pacote atravessa sozinho.", 44, 280, 10, GRAY);
    }
    DesenharTextoLab("PERMITIR: pode ir.  BLOQUEAR: nunca deve ir.  ANONIMIZAR: pode ir sem os dados pessoais.", 44, 300, 590, 10, 12, LIGHTGRAY);
}

static void DesenharLabPesquisa(const Biblioteca *b, float tempo)
{
    const LabEdu *L = &b->lab;
    const CasoPesquisa *c = &CASOS_PESQUISA[L->missao];
    Color cor = CORES_LAB[LAB_PESQUISA];

    DrawText(c->titulo, 44, 84, 12, cor);
    DesenharMidiaPesquisa(b, (Rectangle){ 44, 100, 290, 150 }, tempo);
    DesenharTextoLab(c->descricao, 44, 256, 290, 10, 12, WHITE);

    int consultas = 0;
    for (int i = 0; i < 3; i++) if (L->ferramentas & (1u << i)) consultas++;
    DrawText(TextFormat("INVESTIGAR (consultas %d/%d):", consultas, LAB_MAX_FERRAMENTAS), 44, 300, 10, SKYBLUE);

    DrawText("DOSSIÊ: marque os SINAIS DE ALERTA (aparência sozinha não prova nada)", 352, 98, 10, GOLD);

    // Resultados das consultas
    int y = 310;
    for (int i = 0; i < 3; i++) {
        if (!(L->ferramentas & (1u << i))) continue;
        DrawText(TextFormat("%s:", c->ferramenta[i]), 352, y, 10, SKYBLUE);
        y += 12;
        y += DesenharTextoLab(c->resultado[i], 360, y, 392, 10, 12, WHITE) + 4;
    }
    if (consultas == 0)
        DesenharTextoLab("Use as ferramentas ao lado para investigar a origem do material antes de dar o veredito.", 352, 316, 400, 10, 12, GRAY);
}

// Passo 4: estrelas, explicação, detalhes revelados, a Luci e a recompensa
static void DesenharLabResultado(const Biblioteca *b, float tempo)
{
    const LabEdu *L = &b->lab;
    Color cor = CORES_LAB[L->tipo];

    for (int i = 0; i < 3; i++) {
        Vector2 c = { 400.0f + (i - 1) * 44.0f, 98.0f };
        float giro = tempo * 40.0f + i * 20.0f;
        if (i < L->estrelas) { DrawPoly(c, 5, 16, giro, GOLD); DrawPolyLines(c, 5, 16, giro, ORANGE); }
        else                 DrawPolyLines(c, 5, 16, giro, Fade(GRAY, 0.6f));
    }
    static const char *notas[4] = { "", "DÁ PARA MELHORAR", "BOM TRABALHO", "EXCELENTE" };
    const char *nt = notas[L->estrelas];
    DrawText(nt, 400 - MeasureText(nt, 16) / 2, 120, 16, (L->estrelas == 3) ? GOLD : WHITE);
    int y = 142;
    y += DesenharTextoLab(L->resultado, 44, y, 712, 10, 13, LIGHTGRAY) + 6;

    // O que aprendemos
    const char *exp;
    switch (L->tipo) {
        case LAB_PROMPTS:  exp = MISSOES_PROMPT[L->missao].explicacao;   break;
        case LAB_ARQUIVO:  exp = DESAFIOS_ARQUIVO[L->missao].explicacao; break;
        case LAB_NUCLEO:   exp = DESAFIOS_NUCLEO[L->missao].explicacao;  break;
        case LAB_FIREWALL: exp = CASOS_VIES[L->missao].explicacao;       break;
        default:           exp = CASOS_PESQUISA[L->missao].explicacao;   break;
    }
    DrawText("O QUE APRENDEMOS", 44, y, 10, cor);
    y += 14;
    y += DesenharTextoLab(exp, 44, y, 712, 12, 16, WHITE) + 8;

    // Detalhes revelados
    switch (L->tipo) {
        case LAB_PROMPTS: {
            const MissaoPrompt *m = &MISSOES_PROMPT[L->missao];
            for (int k = 0; k < NUM_PARTES_PROMPT; k++) {
                BotaoLab o;
                memset(&o, 0, sizeof(o));
                o.r = LabRetEncaixe(k);
                o.r.y = (float)y;
                o.estilo = EST_ENCAIXE;
                o.param = k;
                o.cor = CORES_PARTES_PROMPT[k];
                snprintf(o.rotulo, sizeof(o.rotulo), "%s", NOMES_PARTES_PROMPT[k]);
                o.texto = (L->escolha[k] > 0) ? m->alt[k][L->escolha[k] - 1] : NULL;
                o.luz = (int)LabLuzParte(m, L->escolha, k);
                DesenharBotaoLab(&o, false, tempo);
            }
            y += 76;
            DesenharBarrasCriterios(L->criterios, L->notaPrompt, 44, y);
            if (L->respostaAlucinada || L->pegouAlucinacao)
                DesenharTextoLab(TextFormat("A IA inventou: %s", m->trechoFalso), 290, y, 466, 10, 12, MAGENTA);
        } break;

        case LAB_ARQUIVO: {
            const DesafioArquivo *d = &DESAFIOS_ARQUIVO[L->missao];
            for (int i = 0; i < 4; i++) {
                int t = d->tipo[i];
                DrawText(NOMES_AFIRMACAO[t], 44, y, 10, CORES_AFIRMACAO[t]);
                y += DesenharTextoLab(d->af[i], 160, y, 596, 10, 12, (i == L->sel) ? GOLD : LIGHTGRAY) + 3;
            }
            DesenharTextoLab(TextFormat("Melhor verificação: %s", d->metodos[d->metodoCerto]), 44, y + 2, 712, 10, 12, LIME);
        } break;

        case LAB_NUCLEO: {
            const DesafioNucleo *d = &DESAFIOS_NUCLEO[L->missao];
            static const char *rel[3] = { "DISPENSÁVEL", "ÚTIL", "ESSENCIAL" };
            static const Color corRel[3] = { { 230, 41, 55, 255 }, { 255, 203, 0, 255 }, { 0, 228, 48, 255 } };
            for (int i = 0; i < d->numBlocos; i++) {
                int x = 44 + (i % 2) * 360, yy = y + (i / 2) * 15;
                bool usou = (L->marcados & (1u << i)) != 0;
                DrawText(rel[d->bloco[i].relevancia], x, yy, 10, corRel[d->bloco[i].relevancia]);
                DrawText(TextFormat("%s%s (%d tk)", usou ? "[x] " : "[ ] ", d->bloco[i].texto, d->bloco[i].tokens), x + 84, yy, 10, usou ? WHITE : GRAY);
            }
            DesenharTextoLab(AVISO_TOKENS, 44, y + 50, 712, 10, 12, Fade(SKYBLUE, 0.8f));
        } break;

        case LAB_FIREWALL:
            for (int k = 0; k < LAB_PACOTES; k++) {
                const PacoteDados *p = &PACOTES_DADOS[L->pacotes[k]];
                int a = L->acoes[k];
                int efetiva = (a < 0) ? ACAO_PERMITIR : a;
                bool certo = (a >= -1) && efetiva == p->acao;
                DrawText(certo ? "OK" : "X", 44, y, 10, certo ? LIME : RED);
                DrawText(TextFormat("%s  ->  certo: %s", p->texto, NOMES_ACAO_PACOTE[p->acao]), 64, y, 10, LIGHTGRAY);
                y += 14;
            }
            break;

        default: {
            const CasoPesquisa *c = &CASOS_PESQUISA[L->missao];
            for (int i = 0; i < 5; i++) {
                bool marcou = (L->marcados & (1u << i)) != 0;
                DrawText(c->pista[i].alerta ? "ALERTA" : "NÃO PROVA", 44, y, 10, c->pista[i].alerta ? ORANGE : SKYBLUE);
                DrawText(TextFormat("%s%s", marcou ? "[!] " : "[ ] ", c->pista[i].texto), 124, y, 10, (marcou == c->pista[i].alerta) ? WHITE : RED);
                y += 14;
            }
        } break;
    }

    // A Luci nesta sala
    char luci[200];
    if (L->ajudas == 0)
        snprintf(luci, sizeof(luci), "Você resolveu sem a ajuda da Luci.");
    else if (L->alucinacoes == 0)
        snprintf(luci, sizeof(luci), "A Luci ajudou %d vez(es) e não alucinou nesta sala.", L->ajudas);
    else
        snprintf(luci, sizeof(luci), "A Luci alucinou em %d de %d ajuda(s). Você conferiu %d.%s", L->alucinacoes, L->ajudas, L->alucinacoesPegas,
                 L->seguiuAlucinacao ? " Você seguiu uma sugestão falsa sem conferir!" : "");
    LabCortarUtf8(luci);
    DesenharLuciTamanho((Vector2){ 58, 428 }, 26.0f);
    DesenharTextoLab(luci, 76, 418, 680, 10, 12, (L->seguiuAlucinacao) ? MAGENTA : (Color){ 0, 228, 255, 255 });
    DesenharTextoLab(TextFormat("RECOMPENSA: %s", L->recompensa), 76, 446, 680, 10, 12, GOLD);
}

static void DesenharLab(const Biblioteca *b, float tempo)
{
    const LabEdu *L = &b->lab;
    Color cor = CORES_LAB[L->tipo];
    Rectangle painel = { LAB_PAINEL_X, LAB_PAINEL_Y, LAB_PAINEL_W, LAB_PAINEL_H };

    DrawRectangle(0, 0, LARGURA_TELA, ALTURA_TELA, Fade(BLACK, 0.7f));
    DrawRectangleRec(painel, (Color){ 16, 13, 28, 255 });
    DrawRectangleLinesEx(painel, 3, cor);
    // Linhas de varredura sutis (terminal)
    for (int y = (int)painel.y + 4; y < (int)(painel.y + painel.height); y += 4)
        DrawLine((int)painel.x + 3, y, (int)(painel.x + painel.width) - 3, y, Fade(cor, 0.025f));

    // Cabeçalho: categoria, missão, nível, opcional e a estabilidade da Luci (com a carga de ajuda)
    DrawCircleV((Vector2){ 58, 52 }, 15, Fade(cor, 0.2f));
    DesenharIconeLab(L->tipo, (Vector2){ 58, 52 }, 0.9f, tempo);
    DrawText(NOMES_LAB[L->tipo], 82, 40, 18, cor);
    int dif = LabDificuldadeMissao(L->tipo, L->missao);
    const char *sub = TextFormat("%s   NÍVEL %d/3%s", LAB_ESPECIAL[L->tipo] ? "SALA ESPECIAL (opcional)" : "SALA COMUM (abre a porta)", dif, "");
    DrawText(sub, 82, 60, 10, LAB_ESPECIAL[L->tipo] ? GOLD : LIGHTGRAY);

    int e = RogueEstab(b);
    Color corL = (e >= 4) ? (Color){ 0, 228, 255, 255 } : ((e == 3) ? GOLD : ((e >= 1) ? ORANGE : MAGENTA));
    int dx = (e <= 2 && ((int)(tempo * 9.0f)) % 7 == 0) ? GetRandomValue(-2, 2) : 0;
    DrawText("LUCI", 560 + dx, 40, 10, corL);
    for (int k = 0; k < ESTABILIDADE_MAX_LUCI; k++) {
        Rectangle pip = { 594.0f + k * 12.0f, 40, 9, 9 };
        if (k < e) DrawRectangleRec(pip, corL);
        DrawRectangleLinesEx(pip, 1, corL);
    }
    DrawText("carga", 660, 40, 10, GRAY);
    for (int k = 0; k < LAB_CARGA_POR_ESTAB; k++)
        DrawRectangle(694 + k * 12, 42, 9, 6, (k < b->cargaLuci) ? ORANGE : Fade(GRAY, 0.3f));
    DrawText(FALAS_INSTABILIDADE_LAB[e], 560 + dx, 56, 10, Fade(corL, 0.85f));

    DrawLine(40, 76, 760, 76, Fade(cor, 0.4f));
    DesenharBotaoFechar(RET_FECHAR_LAB, cor);

    // Conteúdo
    if (L->etapa == LAB_INTRO && L->tipo == LAB_PROMPTS) {
        DesenharIntroPrompt(b, tempo);
    } else if (L->etapa == LAB_INTRO) {
        static const char *passos[4] = { "1 CONCEITO", "2 EXPERIMENTE", "3 APLIQUE", "4 ENTENDA" };
        for (int i = 0; i < 4; i++) {
            int x = 44 + i * 180;
            DrawRectangle(x, 86, 168, 20, (i == 0) ? Fade(cor, 0.3f) : Fade(GRAY, 0.12f));
            DrawText(passos[i], x + 8, 91, 10, (i == 0) ? WHITE : GRAY);
        }
        bool revisao = (b->labIntroVista & (1u << L->tipo)) != 0;
        DrawText(revisao ? "CONCEITO (revisão)" : "CONCEITO NOVO", 44, 118, 10, GOLD);
        int y = 134 + DesenharTextoLab(CONCEITOS_LAB[L->tipo], 44, 134, 712, 12, 17, WHITE) + 12;

        const char *missao;
        const char *titulo;
        switch (L->tipo) {
            case LAB_PROMPTS:  titulo = MISSOES_PROMPT[L->missao].titulo;   missao = MISSOES_PROMPT[L->missao].missao;   break;
            case LAB_ARQUIVO:  titulo = DESAFIOS_ARQUIVO[L->missao].titulo; missao = "Uma IA respondeu com várias afirmações. Encontre a suspeita e diga como verificá-la."; break;
            case LAB_NUCLEO:   titulo = DESAFIOS_NUCLEO[L->missao].titulo;  missao = DESAFIOS_NUCLEO[L->missao].tarefa; break;
            case LAB_FIREWALL: titulo = CASOS_VIES[L->missao].titulo;       missao = "Analise um caso de viés algorítmico e depois decida quais dados podem chegar a uma IA."; break;
            default:           titulo = CASOS_PESQUISA[L->missao].titulo;   missao = "Investigue uma mídia suspeita: marque os sinais de alerta, consulte as fontes e dê o veredito."; break;
        }
        DrawText(TextFormat("MISSÃO: %s", titulo), 44, y, 12, cor);
        y += 18;
        y += DesenharTextoLab(missao, 44, y, 712, 12, 16, LIGHTGRAY) + 12;

        if (L->tipo == LAB_NUCLEO)
            y += DesenharTextoLab(AVISO_TOKENS, 44, y, 712, 10, 13, Fade(SKYBLUE, 0.85f)) + 8;

        DesenharTextoLab(LAB_ESPECIAL[L->tipo] ? "Sala especial: opcional, com recompensa maior. A porta já está aberta."
                                                : "Sala comum: a porta abre quando o desafio terminar. Sempre dá para terminar; o desempenho decide a recompensa.",
                         44, y, 712, 10, 13, LAB_ESPECIAL[L->tipo] ? GOLD : LIGHTGRAY);
        y += 30;
        DesenharTextoLab("A Luci pode ajudar: DICA (1 de carga), ANALISAR e VERIFICAR (2), REFORMULAR (3). A cada 3 de carga ela perde 1 de "
                         "estabilidade, e instável ela pode errar com muita confiança. V confere uma sugestão dela (Lente ou 1 Fragmento).",
                         44, y, 712, 10, 13, (Color){ 0, 228, 255, 255 });
    } else if (L->etapa == LAB_RESULTADO) {
        DesenharLabResultado(b, tempo);
    } else {
        switch (L->tipo) {
            case LAB_PROMPTS:  DesenharLabPrompt(b, tempo);   break;
            case LAB_ARQUIVO:  DesenharLabArquivo(b, tempo);  break;
            case LAB_NUCLEO:   DesenharLabNucleo(b, tempo);   break;
            case LAB_FIREWALL: DesenharLabFirewall(b, tempo); break;
            default:           DesenharLabPesquisa(b, tempo); break;
        }

        // Faixa da Luci: a fala dela e o resultado da conferência
        Rectangle faixa = { 44, LAB_Y_LUCI, 712, 52 };
        DrawRectangleRec(faixa, Fade((Color){ 0, 40, 60, 255 }, 0.55f));
        DrawRectangleLinesEx(faixa, 1, Fade((Color){ 0, 228, 255, 255 }, 0.35f));
        DesenharLuciTamanho((Vector2){ 64, LAB_Y_LUCI + 26 }, 30.0f);
        Color corFala = L->luciVerificada ? (L->luciAlucinou ? RED : LIME) : (Color){ 120, 230, 255, 255 };
        int gx = (e <= 2 && L->luciTemSugestao && ((int)(tempo * 11.0f)) % 9 == 0) ? GetRandomValue(-2, 2) : 0;
        const char *fala = (L->luciTexto[0] != '\0') ? L->luciTexto : "Luci: Estou aqui se precisar. Cada ajuda gasta um pouco da minha estabilidade.";
        int alt = DesenharTextoLab(fala, 90 + gx, LAB_Y_LUCI + 6, 656, 10, 12, corFala);
        if (L->conferencia[0] != '\0')
            DesenharTextoLab(L->conferencia, 90, LAB_Y_LUCI + 8 + alt, 656, 10, 12, L->luciAlucinou ? RED : GOLD);
    }

    // Botões
    BotaoLab bt[MAX_BOTOES_LAB];
    int n = LabMontarBotoes(b, bt, MAX_BOTOES_LAB);
    for (int i = 0; i < n; i++)
        DesenharBotaoLab(&bt[i], i == L->foco, tempo);
    DesenharMarcaLuciLab(b, bt, n, tempo);
    DesenharAnimPecaLab(L);

    const char *ajuda = (L->tipo == LAB_PROMPTS && L->etapa == LAB_DESAFIO)
                      ? "MOUSE ou 1-3 peça   0 vazio   A/D encaixe   ENTER enviar   H dica   V conferir a Luci   BACKSPACE sair"
                      : "MOUSE ou W/S escolher   E/ENTER confirmar   H dica da Luci   V conferir a Luci   BACKSPACE sair (dá para voltar)";
    DrawText(ajuda, LARGURA_TELA / 2 - MeasureText(ajuda, 10) / 2, 516, 10, GRAY);
}

// Núcleo de corrupção: cristal que gira e brilha antes do anel de balas
static void DesenharNucleoCorrupcao(const Inimigo *e, float escala, float t)
{
    Color cor = DEF_INIMIGOS[INIMIGO_NUCLEO].cor;
    float r = e->raio * escala;
    float aviso = (e->estado == 1) ? 1.0f - e->timer / NUCLEO_PREPARO : 0.0f;

    DrawCircleV(e->pos, r + 10 + 8 * aviso, Fade(cor, 0.12f + 0.25f * aviso));
    DrawPoly(e->pos, 4, r, t * 50.0f, (Color){ 60, 10, 70, 255 });
    DrawPolyLines(e->pos, 4, r, t * 50.0f, cor);
    DrawPoly(e->pos, 4, r * 0.55f, -t * 80.0f, Fade(cor, 0.8f));
    DrawCircleV(e->pos, r * 0.25f, WHITE);
    for (int k = 0; k < 3; k++) {
        float a = t * 2.0f + (float)k * 2.0f * PI / 3.0f;
        DrawCircleV((Vector2){ e->pos.x + cosf(a) * (r + 8), e->pos.y + sinf(a) * (r + 8) }, 3, Fade(cor, 0.8f));
    }
}

// Aura de elite, marca do alvo prioritário e rótulo (desenhados junto com o inimigo)
static void DesenharMarcasReformulacao(const Inimigo *e, float t)
{
    if (e->elite) {
        for (int k = 0; k < 8; k++) {
            float a = t * 1.5f + (float)k * PI / 4.0f;
            Vector2 p = { e->pos.x + cosf(a) * (e->raio + 9), e->pos.y + sinf(a) * (e->raio + 9) };
            DrawCircleV(p, 2, GOLD);
        }
        // Coroa pequena sobre a cabeça
        Vector2 c = { e->pos.x, e->pos.y - e->raio - 18 };
        DrawTriangle((Vector2){ c.x - 7, c.y + 4 }, (Vector2){ c.x - 2, c.y + 4 }, (Vector2){ c.x - 6, c.y - 4 }, GOLD);
        DrawTriangle((Vector2){ c.x - 3, c.y + 4 }, (Vector2){ c.x + 3, c.y + 4 }, (Vector2){ c.x, c.y - 6 }, GOLD);
        DrawTriangle((Vector2){ c.x + 2, c.y + 4 }, (Vector2){ c.x + 7, c.y + 4 }, (Vector2){ c.x + 6, c.y - 4 }, GOLD);
    }

    if (e->prioritario) {
        float r = e->raio + 16;
        for (int k = 0; k < 4; k++) {
            float a = t * 2.0f + (float)k * PI / 2.0f;
            DrawLineEx((Vector2){ e->pos.x + cosf(a) * r, e->pos.y + sinf(a) * r },
                       (Vector2){ e->pos.x + cosf(a) * (r - 8), e->pos.y + sinf(a) * (r - 8) }, 3, RED);
        }
        const char *txt = "ALVO PRIORITÁRIO";
        DrawText(txt, (int)e->pos.x - MeasureText(txt, 10) / 2, (int)(e->pos.y + e->raio + 18), 10, RED);
    }

    if (e->rotulo > 0.0f) {
        Vector2 c = { e->pos.x + e->raio + 4, e->pos.y - e->raio - 4 };
        DrawRectangle((int)c.x - 5, (int)c.y - 5, 10, 10, (Color){ 255, 109, 194, 255 });
        DrawText("R", (int)c.x - 3, (int)c.y - 4, 8, BLACK);
    }
}

// Coluna da build no HUD (abaixo dos upgrades passivos)
static void DesenharHudBuild(const Biblioteca *b, int yInicio, float tempo)
{
    int y = yInicio;
    int mostrados = 0, total = 0;

    for (int u = 0; u < NUM_UPGRADES; u++)
        if (b->j.up[u] > 0) total++;

    for (int u = 0; u < NUM_UPGRADES && y < 470; u++) {
        if (b->j.up[u] <= 0) continue;
        OpcaoEscolha o = { OPC_UPGRADE, u };
        Color cor = CORES_RARIDADE[UPGRADES[u].raridade];
        DrawRectangle(770, y - 11, 22, 22, Fade(BLACK, 0.6f));
        DrawRectangleLines(770, y - 11, 22, 22, Fade(cor, 0.8f));
        DesenharIconeUpgrade(b, o, (Vector2){ 781, (float)y }, 0.55f, tempo);
        if (UPGRADES[u].maxNivel > 1)
            DrawText(TextFormat("%d", b->j.up[u]), 785, y + 2, 8, WHITE);
        y += 26;
        mostrados++;
    }

    if (total > mostrados)
        DrawText(TextFormat("+%d", total - mostrados), 772, y - 6, 10, GOLD);

    if (b->j.penalidade) {
        DrawRectangle(770, y + 4, 22, 14, Fade(RED, 0.4f));
        DrawText("BETA", 771, y + 7, 8, WHITE);
    }
}

